impl<Source, Store, CheckpointSource, const N: usize>
    WalRetentionAnalyzedTransactionPageStorageRestartCheckpointReplay<
        Source,
        Store,
        CheckpointSource,
        N,
    >
where
    Source: DurableTransactionRestartAnalysisSource<N>
        + DurableTransactionRestartRetentionMetadataSource
        + DurableTransactionRestartPrunedGenerationSource<N>
        + DurableTransactionRestartWalReclamationSource<N>,
    Store: DurablePageStoreInventorySource<N>,
    CheckpointSource: DurableTransactionRestartCheckpointCompletenessBaselineSource
        + DurableTransactionRestartCheckpointCompletenessBaselinePublisher,
{
    /// Consumes this owner, revalidates every frozen input, and invokes one
    /// permit-bound atomic reclamation effect.
    pub fn reclaim_wal_prefix(
        self,
    ) -> Result<
        ReclaimedTransactionPageStorageRestartCheckpointReplay<Source, Store, CheckpointSource, N>,
        FailedTransactionPageStorageRestartCheckpointWalReclamation<
            Source,
            Store,
            CheckpointSource,
            N,
        >,
    > {
        reclaim_analyzed_transaction_restart_wal_prefix(self)
    }
}

/// Exact replay-window materialization failure inside one stable WAL callback.
#[derive(Clone, Debug, Eq, PartialEq)]
pub enum DurableTransactionRestartCheckpointReplayWindowError {
    /// The exact replay window could not reserve its complete record count.
    CapacityExhausted {
        /// Number of records selected for owned materialization.
        record_count: usize,
    },
    /// An inclusive replay position rederived from the selected checkpoint was absent.
    InclusiveStartNotRecordBoundary {
        /// Missing inclusive numeric record position.
        position: u64,
    },
    /// A selected checkpoint frontier was absent from the validated current stream.
    CheckpointFrontierNotRecordBoundary {
        /// Missing checkpoint frontier.
        frontier: u64,
    },
}

impl fmt::Display for DurableTransactionRestartCheckpointReplayWindowError {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::CapacityExhausted { record_count } => write!(
                formatter,
                "restart checkpoint replay window capacity is exhausted for {record_count} records"
            ),
            Self::InclusiveStartNotRecordBoundary { position } => write!(
                formatter,
                "restart checkpoint replay start {position} is not a current logical record boundary"
            ),
            Self::CheckpointFrontierNotRecordBoundary { frontier } => write!(
                formatter,
                "restart checkpoint frontier {frontier} is not a current logical record boundary"
            ),
        }
    }
}

impl Error for DurableTransactionRestartCheckpointReplayWindowError {}

/// Opaque exact baseline rederived when a retained selected baseline changed.
///
/// The complete rederived baseline remains private so a failed plan cannot
/// release page, replay, or checkpoint evidence. Identifying metadata is exposed
/// only for diagnosis; the failed owner separately retains the original baseline.
#[derive(Debug)]
pub struct DurableTransactionRestartCheckpointReplayBaselineMismatch {
    rederived: Box<DurableTransactionRestartCheckpointCompletenessBaseline>,
}

impl DurableTransactionRestartCheckpointReplayBaselineMismatch {
    /// Returns the persistent lineage identity of the rederived baseline.
    #[must_use]
    pub const fn persistent_log_id(&self) -> PersistentLogId {
        self.rederived.persistent_log_id()
    }

    /// Returns the rederived checkpoint frontier.
    #[must_use]
    pub const fn durable_frontier(&self) -> Option<u64> {
        self.rederived.durable_frontier()
    }

    /// Returns the rederived transaction-entry count.
    #[must_use]
    pub fn transaction_count(&self) -> usize {
        self.rederived.transactions().len()
    }

    /// Returns the rederived page-entry count.
    #[must_use]
    pub fn page_count(&self) -> usize {
        self.rederived.pages().len()
    }

    /// Returns the rederived inclusive replay position, when present.
    #[must_use]
    pub const fn inclusive_replay_start(&self) -> Option<u64> {
        self.rederived.replay_start().position()
    }
}

impl fmt::Display for DurableTransactionRestartCheckpointReplayBaselineMismatch {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(
            formatter,
            "rederived selected checkpoint baseline at frontier {:?} with {} transactions and {} pages differs from retained selection",
            self.durable_frontier(),
            self.transaction_count(),
            self.page_count()
        )
    }
}

impl Error for DurableTransactionRestartCheckpointReplayBaselineMismatch {}

/// Exact contradiction in one stable retained logical WAL suffix.
#[derive(Clone, Debug)]
pub enum DurableTransactionRestartRetainedSuffixEvidenceError {
    /// Metadata omitted a retained boundary for nonempty observations.
    RetainedBoundaryMissing {
        /// Number of retained observations.
        record_count: usize,
    },
    /// Metadata supplied a retained boundary for an empty suffix.
    RetainedBoundaryWithoutObservations {
        /// Unexpected retained boundary.
        retained_first: u64,
    },
    /// The first retained observation differs from metadata.
    RetainedFirstMismatch {
        /// Metadata boundary.
        expected: u64,
        /// First retained observation.
        actual: u64,
    },
    /// A nonempty retained suffix has no logical high-water.
    LogicalHighWaterMissing {
        /// Number of retained observations.
        record_count: usize,
    },
    /// The retained tail differs from independent logical high-water.
    RetainedTailMismatch {
        /// Independent logical high-water.
        expected: u64,
        /// Retained tail.
        actual: u64,
    },
    /// One retained observation belongs to another lineage.
    ForeignRecordLineage {
        /// Retained observation index.
        index: usize,
        /// Observation kind.
        kind: DurableTransactionRestartObservationKind,
        /// Foreign position.
        position: LogSequenceNumber,
    },
    /// One retained observation uses reserved position zero.
    ZeroRecordPosition {
        /// Retained observation index.
        index: usize,
        /// Observation kind.
        kind: DurableTransactionRestartObservationKind,
    },
    /// Two retained observations claim one position.
    DuplicateRecordPosition {
        /// Earlier retained observation index.
        previous_index: usize,
        /// Later retained observation index.
        actual_index: usize,
        /// Duplicated position.
        position: u64,
    },
    /// Retained positions are not strictly increasing.
    NonAdvancingRecordPosition {
        /// Earlier retained observation index.
        previous_index: usize,
        /// Earlier position.
        previous: u64,
        /// Later retained observation index.
        actual_index: usize,
        /// Rejected position.
        actual: u64,
    },
    /// The selected nonempty checkpoint frontier is absent from retained evidence.
    CheckpointFrontierNotRetained {
        /// Selected checkpoint frontier.
        checkpoint_frontier: u64,
    },
    /// Allocator metadata is below a retained transaction identity.
    AllocatorHighWaterBelowTransaction {
        /// Persisted transaction identity.
        transaction: DurableTransactionIdentityObservation,
        /// Durable allocator epoch high-water.
        allocated_epoch_high_water: u64,
    },
    /// A pre-frontier transaction page is not summarized by the checkpoint.
    CheckpointTransactionPageMismatch {
        /// Persisted owner.
        transaction: DurableTransactionIdentityObservation,
        /// Retained page position.
        page_position: u64,
    },
    /// A pre-frontier commit is not summarized exactly by the checkpoint.
    CheckpointCommitMismatch {
        /// Persisted transaction.
        transaction: DurableTransactionIdentityObservation,
        /// Retained commit position.
        commit_position: u64,
    },
    /// A checkpoint count cannot fit the in-memory analysis width.
    OwnedPageCountWidthExceeded {
        /// Persisted transaction.
        transaction: DurableTransactionIdentityObservation,
        /// Portable checkpoint count.
        record_count: u64,
    },
    /// The synthesized transaction table could not reserve exact capacity.
    TransactionCapacityExhausted {
        /// Checkpoint transaction count.
        transaction_count: usize,
    },
    /// A post-frontier page occurs after its transaction commit.
    PageAfterCommit {
        /// Persisted owner.
        transaction: DurableTransactionIdentityObservation,
        /// Earlier commit position.
        commit_position: u64,
        /// Invalid later page position.
        page_position: u64,
    },
    /// A post-frontier commit duplicates an existing commit.
    DuplicateCommit {
        /// Persisted transaction.
        transaction: DurableTransactionIdentityObservation,
        /// Earlier commit position.
        first_commit_position: u64,
        /// Duplicate commit position.
        duplicate_commit_position: u64,
    },
    /// Counting a transaction-owned page exceeded `usize`.
    OwnedPageCountExhausted {
        /// Persisted transaction.
        transaction: DurableTransactionIdentityObservation,
    },
    /// Replay lower bound cannot be selected from retained observations.
    ReplayWindow(DurableTransactionRestartCheckpointReplayWindowError),
}

impl fmt::Display for DurableTransactionRestartRetainedSuffixEvidenceError {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::RetainedBoundaryMissing { .. } => {
                formatter.write_str("nonempty retained WAL suffix has no retained boundary")
            }
            Self::RetainedBoundaryWithoutObservations { .. } => {
                formatter.write_str("empty retained WAL suffix has a retained boundary")
            }
            Self::RetainedFirstMismatch { .. } => {
                formatter.write_str("retained WAL suffix does not start at its metadata boundary")
            }
            Self::LogicalHighWaterMissing { .. } => {
                formatter.write_str("nonempty retained WAL suffix has no logical high-water")
            }
            Self::RetainedTailMismatch { .. } => {
                formatter.write_str("retained WAL suffix does not end at logical high-water")
            }
            Self::ForeignRecordLineage { .. } => {
                formatter.write_str("retained WAL suffix contains a foreign record")
            }
            Self::ZeroRecordPosition { .. } => {
                formatter.write_str("retained WAL suffix contains position zero")
            }
            Self::DuplicateRecordPosition { .. } => {
                formatter.write_str("retained WAL suffix contains a duplicate position")
            }
            Self::NonAdvancingRecordPosition { .. } => {
                formatter.write_str("retained WAL suffix positions are not strictly increasing")
            }
            Self::CheckpointFrontierNotRetained { .. } => formatter
                .write_str("selected checkpoint frontier is not retained in the WAL suffix"),
            Self::AllocatorHighWaterBelowTransaction { .. } => formatter
                .write_str("WAL allocator high-water is below a retained transaction identity"),
            Self::CheckpointTransactionPageMismatch { .. } => formatter
                .write_str("retained pre-frontier transaction page contradicts the checkpoint"),
            Self::CheckpointCommitMismatch { .. } => {
                formatter.write_str("retained pre-frontier commit contradicts the checkpoint")
            }
            Self::OwnedPageCountWidthExceeded { .. } => {
                formatter.write_str("checkpoint owned-page count exceeds the analysis width")
            }
            Self::TransactionCapacityExhausted { .. } => {
                formatter.write_str("retained WAL transaction capacity is exhausted")
            }
            Self::PageAfterCommit { .. } => {
                formatter.write_str("retained WAL transaction page occurs after commit")
            }
            Self::DuplicateCommit { .. } => {
                formatter.write_str("retained WAL suffix contains a duplicate commit")
            }
            Self::OwnedPageCountExhausted { .. } => {
                formatter.write_str("retained WAL transaction page count is exhausted")
            }
            Self::ReplayWindow(source) => source.fmt(formatter),
        }
    }
}

impl Error for DurableTransactionRestartRetainedSuffixEvidenceError {
    fn source(&self) -> Option<&(dyn Error + 'static)> {
        match self {
            Self::ReplayWindow(source) => Some(source),
            Self::RetainedBoundaryMissing { .. }
            | Self::RetainedBoundaryWithoutObservations { .. }
            | Self::RetainedFirstMismatch { .. }
            | Self::LogicalHighWaterMissing { .. }
            | Self::RetainedTailMismatch { .. }
            | Self::ForeignRecordLineage { .. }
            | Self::ZeroRecordPosition { .. }
            | Self::DuplicateRecordPosition { .. }
            | Self::NonAdvancingRecordPosition { .. }
            | Self::CheckpointFrontierNotRetained { .. }
            | Self::AllocatorHighWaterBelowTransaction { .. }
            | Self::CheckpointTransactionPageMismatch { .. }
            | Self::CheckpointCommitMismatch { .. }
            | Self::OwnedPageCountWidthExceeded { .. }
            | Self::TransactionCapacityExhausted { .. }
            | Self::PageAfterCommit { .. }
            | Self::DuplicateCommit { .. }
            | Self::OwnedPageCountExhausted { .. } => None,
        }
    }
}

/// Evidence failure while planning one selected checkpoint replay window.
#[derive(Debug)]
pub enum DurableTransactionRestartCheckpointReplayPlanningEvidenceError<SourceError, StoreError> {
    /// The privately retained selected baseline no longer matched current evidence.
    CheckpointRevalidation(
        Box<
            DurableTransactionRestartCheckpointCompletenessBaselineValidationEvidenceError<
                SourceError,
                StoreError,
            >,
        >,
    ),
    /// Valid current selected-prefix evidence no longer equals the retained baseline.
    SelectedBaselineMismatch(DurableTransactionRestartCheckpointReplayBaselineMismatch),
    /// The complete current durable logical stream was invalid.
    CurrentAnalysis(Box<DurableTransactionRestartAnalysisEvidenceError>),
    /// The validated current stream could not form the exact owned replay window.
    ReplayWindow(DurableTransactionRestartCheckpointReplayWindowError),
    /// Current pruned-generation metadata or checkpoint anchoring was invalid.
    PrunedGeneration(Box<DurableTransactionRestartPrunedGenerationSelectionEvidenceError>),
    /// Retained-suffix ordering, transaction, or replay evidence was invalid.
    RetainedSuffix(Box<DurableTransactionRestartRetainedSuffixEvidenceError>),
    /// Generation metadata changed across the stable retained-suffix callback.
    PrunedGenerationMetadataChanged {
        /// Metadata observed before the callback.
        expected: Box<DurableTransactionRestartWalReclamationSourceObservation>,
        /// Metadata observed after the callback.
        actual: Box<DurableTransactionRestartWalReclamationSourceObservation>,
    },
}

impl<SourceError: fmt::Display, StoreError: fmt::Display> fmt::Display
    for DurableTransactionRestartCheckpointReplayPlanningEvidenceError<SourceError, StoreError>
{
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::CheckpointRevalidation(source) => {
                write!(
                    formatter,
                    "selected restart checkpoint revalidation failed: {source}"
                )
            }
            Self::SelectedBaselineMismatch(source) => source.fmt(formatter),
            Self::CurrentAnalysis(source) => {
                write!(
                    formatter,
                    "complete current restart analysis failed: {source}"
                )
            }
            Self::ReplayWindow(source) => source.fmt(formatter),
            Self::PrunedGeneration(source) => {
                write!(formatter, "pruned restart generation is invalid: {source}")
            }
            Self::RetainedSuffix(source) => {
                write!(
                    formatter,
                    "retained restart WAL suffix is invalid: {source}"
                )
            }
            Self::PrunedGenerationMetadataChanged { .. } => formatter
                .write_str("pruned restart generation metadata changed during replay planning"),
        }
    }
}

impl<SourceError, StoreError> Error
    for DurableTransactionRestartCheckpointReplayPlanningEvidenceError<SourceError, StoreError>
where
    SourceError: Error + 'static,
    StoreError: Error + 'static,
{
    fn source(&self) -> Option<&(dyn Error + 'static)> {
        match self {
            Self::CheckpointRevalidation(source) => Some(source.as_ref()),
            Self::SelectedBaselineMismatch(source) => Some(source),
            Self::CurrentAnalysis(source) => Some(source.as_ref()),
            Self::ReplayWindow(source) => Some(source),
            Self::PrunedGeneration(source) => Some(source.as_ref()),
            Self::RetainedSuffix(source) => Some(source.as_ref()),
            Self::PrunedGenerationMetadataChanged { .. } => None,
        }
    }
}

/// Failure to obtain one exact owned replay plan from selected startup storage.
#[derive(Debug)]
pub enum DurableTransactionRestartCheckpointReplayPlanningError<SourceError, StoreError> {
    /// The retained WAL and page store no longer identify one lineage.
    LineageMismatch {
        /// Durable restart source lineage.
        source_lineage: LogLineage,
        /// Page-store lineage.
        store_lineage: LogLineage,
    },
    /// The WAL source failed before or after its stable callback.
    Source(SourceError),
    /// Stable callback evidence failed validation or materialization.
    Evidence(
        Box<
            DurableTransactionRestartCheckpointReplayPlanningEvidenceError<SourceError, StoreError>,
        >,
    ),
}

impl<SourceError: fmt::Display, StoreError: fmt::Display> fmt::Display
    for DurableTransactionRestartCheckpointReplayPlanningError<SourceError, StoreError>
{
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::LineageMismatch { .. } => formatter.write_str(
                "restart replay source and page snapshot source belong to different lineages",
            ),
            Self::Source(source) => {
                write!(formatter, "restart replay planning source failed: {source}")
            }
            Self::Evidence(source) => {
                write!(formatter, "restart replay planning failed: {source}")
            }
        }
    }
}

impl<SourceError, StoreError> Error
    for DurableTransactionRestartCheckpointReplayPlanningError<SourceError, StoreError>
where
    SourceError: Error + 'static,
    StoreError: Error + 'static,
{
    fn source(&self) -> Option<&(dyn Error + 'static)> {
        match self {
            Self::Source(source) => Some(source),
            Self::Evidence(source) => Some(source.as_ref()),
            Self::LineageMismatch { .. } => None,
        }
    }
}

/// Exact planning error retained by an owning failed replay-planning state.
pub type TransactionPageStorageRestartCheckpointReplayPlanningError<Source, Store, const N: usize> =
    DurableTransactionRestartCheckpointReplayPlanningError<
        <Source as DurableTransactionRestartAnalysisSource<N>>::Error,
        <Store as DurablePageStoreSnapshotSource<N>>::ObservationError,
    >;

/// Owning selected-checkpoint state with one private exact current replay plan.
///
/// The plan exposes identifying counts and frontiers only. Its selected baseline,
/// complete-current analysis, full-image replay observations, adapters, and
/// checkpoint source remain private.
///
/// ```compile_fail
/// use ntsql_transaction::{
///     DurableTransactionRestartAnalysis,
///     PlannedTransactionPageStorageRestartCheckpointReplay,
///     SelectedTransactionPageStorageRestartCheckpointCompleteness,
/// };
///
/// fn cannot_forge_plan<Source, Store, CheckpointSource, const N: usize>(
///     selected: SelectedTransactionPageStorageRestartCheckpointCompleteness<
///         Source,
///         Store,
///         CheckpointSource,
///         N,
///     >,
///     current_analysis: DurableTransactionRestartAnalysis,
/// ) -> PlannedTransactionPageStorageRestartCheckpointReplay<
///     Source,
///     Store,
///     CheckpointSource,
///     N,
/// > {
///     PlannedTransactionPageStorageRestartCheckpointReplay {
///         selected,
///         current_analysis,
///         replay_observations: Vec::new(),
///     }
/// }
/// ```
///
/// ```compile_fail
/// use ntsql_transaction::PlannedTransactionPageStorageRestartCheckpointReplay;
///
/// fn cannot_extract_plan<Source, Store, CheckpointSource, const N: usize>(
///     planned: PlannedTransactionPageStorageRestartCheckpointReplay<
///         Source,
///         Store,
///         CheckpointSource,
///         N,
///     >,
/// ) {
///     let _ = planned.replay_observations;
/// }
/// ```
///
/// ```compile_fail
/// use ntsql_transaction::{
///     DurableTransactionRestartAnalysis,
///     PlannedTransactionPageStorageRestartCheckpointReplay,
/// };
///
/// fn cannot_extract_analysis<Source, Store, CheckpointSource, const N: usize>(
///     planned: PlannedTransactionPageStorageRestartCheckpointReplay<
///         Source,
///         Store,
///         CheckpointSource,
///         N,
///     >,
/// ) -> DurableTransactionRestartAnalysis {
///     planned.current_analysis
/// }
/// ```
///
/// ```compile_fail
/// use ntsql_transaction::{
///     PlannedTransactionPageStorageRestartCheckpointReplay,
///     UnrecoveredTransactionPageStorage,
/// };
///
/// fn cannot_substitute_storage<Source, Store, CheckpointSource, const N: usize>(
///     planned: PlannedTransactionPageStorageRestartCheckpointReplay<
///         Source,
///         Store,
///         CheckpointSource,
///         N,
///     >,
/// ) -> UnrecoveredTransactionPageStorage<Source, Store, N> {
///     planned
/// }
/// ```
///
/// ```compile_fail
/// use ntsql_page::PageWritePermit;
/// use ntsql_transaction::PlannedTransactionPageStorageRestartCheckpointReplay;
///
/// fn cannot_authorize_page_write<
///     'attempt,
///     Source,
///     Store,
///     CheckpointSource,
///     const N: usize,
/// >(
///     planned: PlannedTransactionPageStorageRestartCheckpointReplay<
///         Source,
///         Store,
///         CheckpointSource,
///         N,
///     >,
/// ) -> PageWritePermit<'attempt> {
///     planned.into()
/// }
/// ```
///
/// ```compile_fail
/// use ntsql_transaction::{
///     DurableTransactionRestartCheckpointCompletenessBaselinePublicationPermit,
///     PlannedTransactionPageStorageRestartCheckpointReplay,
/// };
///
/// fn cannot_authorize_publication<
///     'attempt,
///     Source,
///     Store,
///     CheckpointSource,
///     const N: usize,
/// >(
///     planned: PlannedTransactionPageStorageRestartCheckpointReplay<
///         Source,
///         Store,
///         CheckpointSource,
///         N,
///     >,
/// ) -> DurableTransactionRestartCheckpointCompletenessBaselinePublicationPermit<'attempt> {
///     planned.into()
/// }
/// ```
///
/// ```compile_fail
/// use ntsql_transaction::{
///     ActiveTransaction, PlannedTransactionPageStorageRestartCheckpointReplay,
/// };
///
/// fn cannot_restore_transaction<Source, Store, CheckpointSource, const N: usize>(
///     planned: PlannedTransactionPageStorageRestartCheckpointReplay<
///         Source,
///         Store,
///         CheckpointSource,
///         N,
///     >,
/// ) -> ActiveTransaction {
///     planned.into()
/// }
/// ```
///
/// ```compile_fail
/// use ntsql_transaction::PlannedTransactionPageStorageRestartCheckpointReplay;
/// use ntsql_wal::LogDurability;
///
/// fn cannot_retain_or_reclaim_log<
///     Log,
///     Source,
///     Store,
///     CheckpointSource,
///     const N: usize,
/// >(
///     log: &mut Log,
///     planned: &PlannedTransactionPageStorageRestartCheckpointReplay<
///         Source,
///         Store,
///         CheckpointSource,
///         N,
///     >,
/// )
/// where
///     Log: LogDurability,
/// {
///     let _ = log.flush_through(planned);
/// }
/// ```
#[must_use = "planned replay must be retained, explicitly declined, or dropped"]
pub struct PlannedTransactionPageStorageRestartCheckpointReplay<
    Source,
    Store,
    CheckpointSource,
    const N: usize,
> where
    Source: DurableTransactionRestartAnalysisSource<N>,
    Store: DurablePageStoreSnapshotSource<N>,
{
    selected: SelectedTransactionPageStorageRestartCheckpointCompleteness<
        Source,
        Store,
        CheckpointSource,
        N,
    >,
    current_analysis: DurableTransactionRestartAnalysis,
    replay_observations: Vec<OwnedDurableTransactionRestartReplayObservation<N>>,
}

/// Owning outcome of declining one selected-checkpoint replay plan.
pub type TransactionPageStorageRestartCheckpointReplayPlanDecline<
    Source,
    Store,
    CheckpointSource,
    const N: usize,
> = Result<
    UncheckpointedTransactionPageStorage<Source, Store, CheckpointSource, N>,
    Box<PlannedTransactionPageStorageRestartCheckpointReplay<Source, Store, CheckpointSource, N>>,
>;

impl<Source, Store, CheckpointSource, const N: usize>
    PlannedTransactionPageStorageRestartCheckpointReplay<Source, Store, CheckpointSource, N>
where
    Source: DurableTransactionRestartAnalysisSource<N>,
    Store: DurablePageStoreSnapshotSource<N>,
{
    /// Returns the persistent lineage identity retained by the selected checkpoint.
    #[must_use]
    pub const fn persistent_log_id(&self) -> PersistentLogId {
        self.selected.persistent_log_id()
    }

    /// Returns the selected checkpoint frontier, or `None` for its empty prefix.
    #[must_use]
    pub const fn checkpoint_frontier(&self) -> Option<u64> {
        self.selected.durable_frontier()
    }

    /// Returns the complete current durable frontier covered by this replay plan.
    #[must_use]
    pub fn current_frontier(&self) -> Option<u64> {
        self.current_analysis
            .durable_frontier()
            .map(LogSequenceNumber::get)
    }

    /// Returns the inclusive replay position when the selected plan requires one.
    #[must_use]
    pub const fn inclusive_replay_start(&self) -> Option<u64> {
        self.selected.baseline.replay_start().position()
    }

    /// Returns the exact number of owned logical records in the replay window.
    #[must_use]
    pub const fn replay_record_count(&self) -> usize {
        self.replay_observations.len()
    }

    /// Returns the number of transactions in the complete-current analysis.
    #[must_use]
    pub fn current_transaction_count(&self) -> usize {
        self.current_analysis.transactions().len()
    }

    /// Discards a complete-prefix plan before granting full recovery.
    ///
    /// An anchored plan is returned unchanged and can only continue through its
    /// selected-checkpoint path.
    pub fn decline_replay_plan(
        self,
    ) -> TransactionPageStorageRestartCheckpointReplayPlanDecline<Source, Store, CheckpointSource, N>
    {
        if matches!(
            self.selected.validation,
            SelectedRestartCheckpointValidation::Anchored { .. }
        ) {
            return Err(Box::new(self));
        }
        let Self {
            selected,
            current_analysis: _,
            replay_observations: _,
        } = self;
        let SelectedTransactionPageStorageRestartCheckpointCompleteness {
            storage,
            checkpoint_source,
            baseline: _,
            validation: _,
        } = selected;
        Ok(UncheckpointedTransactionPageStorage {
            storage,
            checkpoint_source,
        })
    }
}

impl<Source, Store, CheckpointSource, const N: usize>
    PlannedTransactionPageStorageRestartCheckpointReplay<Source, Store, CheckpointSource, N>
where
    Source: DurableTransactionRestartAnalysisSource<N>,
    Store: DurablePageStoreSnapshotSource<N>,
{
    /// Consumes the owned replay window into ordered read-only page-repair decisions.
    ///
    /// This transition does not re-enter the WAL source or invoke a page-store
    /// write. All retained-evidence checks and allocations complete before the
    /// first page snapshot is observed.
    pub fn prepare_page_repairs(
        self,
    ) -> TransactionPageStorageRestartCheckpointRepairPreparation<Source, Store, CheckpointSource, N>
    {
        match prepare_transaction_restart_checkpoint_page_repairs(&self) {
            Ok(page_repairs) => TransactionPageStorageRestartCheckpointRepairPreparation::Prepared(
                PreparedTransactionPageStorageRestartCheckpointRepairs {
                    planned: self,
                    page_repairs,
                },
            ),
            Err(error) => TransactionPageStorageRestartCheckpointRepairPreparation::Failed(
                FailedTransactionPageStorageRestartCheckpointRepairPreparation {
                    planned: self,
                    error,
                },
            ),
        }
    }
}

impl<Source, Store, CheckpointSource, const N: usize> fmt::Debug
    for PlannedTransactionPageStorageRestartCheckpointReplay<Source, Store, CheckpointSource, N>
where
    Source: DurableTransactionRestartAnalysisSource<N>,
    Store: DurablePageStoreSnapshotSource<N>,
{
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        formatter
            .debug_struct("PlannedTransactionPageStorageRestartCheckpointReplay")
            .field("persistent_log_id", &self.persistent_log_id())
            .field("checkpoint_frontier", &self.checkpoint_frontier())
            .field("current_frontier", &self.current_frontier())
            .field("inclusive_replay_start", &self.inclusive_replay_start())
            .field("replay_record_count", &self.replay_record_count())
            .field(
                "current_transaction_count",
                &self.current_transaction_count(),
            )
            .finish_non_exhaustive()
    }
}

/// Retained-evidence contradiction while preparing selected replay page repairs.
#[derive(Clone, Debug, Eq, PartialEq)]
pub enum DurableTransactionRestartCheckpointRepairPreparationEvidenceError {
    /// The distinct replay-page inventory could not reserve its record-count bound.
    PageInventoryCapacityExhausted {
        /// Replay-record count used as the inventory upper bound.
        record_count: usize,
    },
    /// The ordered repair-decision table could not reserve its exact page count.
    DecisionCapacityExhausted {
        /// Number of distinct replay pages requiring one decision each.
        page_count: usize,
    },
    /// A replay page was absent from the inventory derived from the same window.
    ReplayPageInventoryMissing {
        /// Page omitted from the private sorted inventory.
        page_number: PageNumber,
        /// Exact owned replay position for the omitted page.
        page_position: LogSequenceNumber,
    },
    /// A replay transaction-page owner was absent from complete-current analysis.
    CurrentTransactionMissing {
        /// Persisted owner missing from the retained transaction table.
        transaction: DurableTransactionIdentityObservation,
        /// Exact transaction-page position.
        page_position: LogSequenceNumber,
    },
    /// A committed replay page had no exact later commit in the owned window.
    CommittedReplayRecordMissing {
        /// Persisted committed owner.
        transaction: DurableTransactionIdentityObservation,
        /// Exact transaction-page position.
        page_position: LogSequenceNumber,
        /// Commit position retained by complete-current analysis.
        commit_position: LogSequenceNumber,
    },
    /// A dirty selected-checkpoint image was absent from the owned replay window.
    DirtyCheckpointRequiredImageMissing {
        /// Dirty selected-checkpoint page.
        page_number: PageNumber,
        /// Required full-image position that the replay floor should retain.
        page_position: u64,
    },
    /// A store observation described another page.
    UnexpectedSnapshotPage {
        /// Requested replay page.
        expected: PageNumber,
        /// Page returned by the store.
        actual: PageNumber,
        /// Returned snapshot position.
        position: LogSequenceNumber,
    },
    /// A store observation belonged to another WAL lineage.
    ForeignSnapshotLineage {
        /// Replay page whose snapshot was rejected.
        page_number: PageNumber,
        /// Foreign snapshot position.
        position: LogSequenceNumber,
    },
    /// A selected-checkpoint page no longer had its exact retained source state.
    CheckpointSourceChanged {
        /// Selected-checkpoint page.
        page_number: PageNumber,
        /// Expected stored position, or absence.
        expected_position: Option<u64>,
        /// Newly observed stored position, or absence.
        actual_position: Option<u64>,
    },
    /// A suffix-only snapshot position had no owned replay page record.
    SuffixSnapshotRecordMissing {
        /// Suffix-only replay page.
        page_number: PageNumber,
        /// Unbacked snapshot position.
        position: LogSequenceNumber,
    },
    /// An eligible backing replay record was absent from the derived target.
    EligibleReplayTargetMissing {
        /// Replay page whose target derivation contradicted its backing record.
        page_number: PageNumber,
        /// Eligible full-image position omitted from the target.
        position: LogSequenceNumber,
    },
    /// A snapshot contradicted the full image at its owned replay position.
    SnapshotPayloadContradiction {
        /// Replay page whose bytes or version contradicted the owned record.
        page_number: PageNumber,
        /// Contradictory snapshot position.
        position: LogSequenceNumber,
    },
    /// A store snapshot was backed by a currently uncommitted replay page.
    SnapshotBackedByUncommittedTransaction {
        /// Replay page whose snapshot was rejected.
        page_number: PageNumber,
        /// Persisted uncommitted owner.
        transaction: DurableTransactionIdentityObservation,
        /// Uncommitted transaction-page position.
        page_position: LogSequenceNumber,
    },
    /// A store snapshot was physically later than the derived repair target.
    SnapshotAfterTarget {
        /// Replay page whose source was later than its target.
        page_number: PageNumber,
        /// Newly observed source position.
        snapshot_position: LogSequenceNumber,
        /// Latest eligible target position.
        target_position: LogSequenceNumber,
    },
}

impl fmt::Display for DurableTransactionRestartCheckpointRepairPreparationEvidenceError {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::PageInventoryCapacityExhausted { record_count } => write!(
                formatter,
                "restart checkpoint repair page inventory capacity is exhausted for {record_count} replay records"
            ),
            Self::DecisionCapacityExhausted { page_count } => write!(
                formatter,
                "restart checkpoint repair decision capacity is exhausted for {page_count} pages"
            ),
            Self::ReplayPageInventoryMissing {
                page_number,
                page_position,
            } => write!(
                formatter,
                "restart checkpoint repair page {} at position {} is absent from its derived inventory",
                page_number.get(),
                page_position.get()
            ),
            Self::CurrentTransactionMissing {
                transaction,
                page_position,
            } => write!(
                formatter,
                "restart checkpoint repair page at position {} has transaction {} absent from complete-current analysis",
                page_position.get(),
                transaction
            ),
            Self::CommittedReplayRecordMissing {
                transaction,
                page_position,
                commit_position,
            } => write!(
                formatter,
                "restart checkpoint repair page for transaction {} at position {} has no owned commit record at position {}",
                transaction,
                page_position.get(),
                commit_position.get()
            ),
            Self::DirtyCheckpointRequiredImageMissing {
                page_number,
                page_position,
            } => write!(
                formatter,
                "dirty restart checkpoint page {} requires image position {page_position} outside the owned replay window",
                page_number.get()
            ),
            Self::UnexpectedSnapshotPage {
                expected,
                actual,
                position,
            } => write!(
                formatter,
                "restart checkpoint repair for page {} observed page {} at position {}",
                expected.get(),
                actual.get(),
                position.get()
            ),
            Self::ForeignSnapshotLineage {
                page_number,
                position,
            } => write!(
                formatter,
                "restart checkpoint repair page {} observed foreign snapshot position {}",
                page_number.get(),
                position.get()
            ),
            Self::CheckpointSourceChanged {
                page_number,
                expected_position,
                actual_position,
            } => write!(
                formatter,
                "restart checkpoint repair page {} changed from selected source position {:?} to {:?}",
                page_number.get(),
                expected_position,
                actual_position
            ),
            Self::SuffixSnapshotRecordMissing {
                page_number,
                position,
            } => write!(
                formatter,
                "suffix-only restart checkpoint repair page {} has snapshot position {} absent from the owned replay window",
                page_number.get(),
                position.get()
            ),
            Self::EligibleReplayTargetMissing {
                page_number,
                position,
            } => write!(
                formatter,
                "restart checkpoint repair page {} has eligible replay position {} absent from its derived target",
                page_number.get(),
                position.get()
            ),
            Self::SnapshotPayloadContradiction {
                page_number,
                position,
            } => write!(
                formatter,
                "restart checkpoint repair page {} snapshot contradicts replay payload at position {}",
                page_number.get(),
                position.get()
            ),
            Self::SnapshotBackedByUncommittedTransaction {
                page_number,
                transaction,
                page_position,
            } => write!(
                formatter,
                "restart checkpoint repair page {} snapshot is backed by uncommitted transaction {} at position {}",
                page_number.get(),
                transaction,
                page_position.get()
            ),
            Self::SnapshotAfterTarget {
                page_number,
                snapshot_position,
                target_position,
            } => write!(
                formatter,
                "restart checkpoint repair page {} snapshot position {} is after target position {}",
                page_number.get(),
                snapshot_position.get(),
                target_position.get()
            ),
        }
    }
}

impl Error for DurableTransactionRestartCheckpointRepairPreparationEvidenceError {}

/// Exact failure while preparing page repairs from one owned replay plan.
#[derive(Debug)]
pub enum DurableTransactionRestartCheckpointRepairPreparationError<StoreError> {
    /// Retained replay evidence and the page store belonged to different lineages.
    LineageMismatch {
        /// Lineage retained by complete-current analysis.
        replay_lineage: LogLineage,
        /// Lineage currently declared by the retained page store.
        store_lineage: LogLineage,
    },
    /// The read-only page-store observation port failed for one ordered page.
    StoreObservation {
        /// Page whose source snapshot could not be observed.
        page_number: PageNumber,
        /// Exact adapter observation failure.
        source: StoreError,
    },
    /// Retained evidence or a returned snapshot was contradictory.
    Evidence(Box<DurableTransactionRestartCheckpointRepairPreparationEvidenceError>),
}

impl<StoreError: fmt::Display> fmt::Display
    for DurableTransactionRestartCheckpointRepairPreparationError<StoreError>
{
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::LineageMismatch { .. } => formatter.write_str(
                "restart checkpoint replay plan and page snapshot source belong to different lineages",
            ),
            Self::StoreObservation {
                page_number,
                source,
            } => write!(
                formatter,
                "restart checkpoint repair source observation failed for page {}: {source}",
                page_number.get()
            ),
            Self::Evidence(source) => {
                write!(formatter, "restart checkpoint repair preparation failed: {source}")
            }
        }
    }
}

impl<StoreError> Error for DurableTransactionRestartCheckpointRepairPreparationError<StoreError>
where
    StoreError: Error + 'static,
{
    fn source(&self) -> Option<&(dyn Error + 'static)> {
        match self {
            Self::StoreObservation { source, .. } => Some(source),
            Self::Evidence(source) => Some(source.as_ref()),
            Self::LineageMismatch { .. } => None,
        }
    }
}

/// Exact preparation error retained by an owning failed state.
pub type TransactionPageStorageRestartCheckpointRepairPreparationError<Store, const N: usize> =
    DurableTransactionRestartCheckpointRepairPreparationError<
        <Store as DurablePageStoreSnapshotSource<N>>::ObservationError,
    >;

/// Result of consuming one replay plan into prepared page-repair decisions.
#[must_use = "repair preparation must be matched to retain its owning state"]
pub enum TransactionPageStorageRestartCheckpointRepairPreparation<
    Source,
    Store,
    CheckpointSource,
    const N: usize,
> where
    Source: DurableTransactionRestartAnalysisSource<N>,
    Store: DurablePageStoreSnapshotSource<N>,
{
    /// Every replay page has one privately retained read-only decision.
    Prepared(
        PreparedTransactionPageStorageRestartCheckpointRepairs<Source, Store, CheckpointSource, N>,
    ),
    /// Preparation failed without invoking a page-store write.
    Failed(
        FailedTransactionPageStorageRestartCheckpointRepairPreparation<
            Source,
            Store,
            CheckpointSource,
            N,
        >,
    ),
}

/// Owning replay state with one ordered private page-repair decision table.
///
/// Callers cannot forge a prepared state:
///
/// ```compile_fail
/// use ntsql_transaction::{
///     PlannedTransactionPageStorageRestartCheckpointReplay,
///     PreparedTransactionPageStorageRestartCheckpointRepairs,
/// };
///
/// fn cannot_forge_prepared<Source, Store, CheckpointSource, const N: usize>(
///     planned: PlannedTransactionPageStorageRestartCheckpointReplay<
///         Source,
///         Store,
///         CheckpointSource,
///         N,
///     >,
/// ) -> PreparedTransactionPageStorageRestartCheckpointRepairs<
///     Source,
///     Store,
///     CheckpointSource,
///     N,
/// > {
///     PreparedTransactionPageStorageRestartCheckpointRepairs {
///         planned,
///         page_repairs: Vec::new(),
///     }
/// }
/// ```
///
/// Exact source snapshots, target images, and replay records remain private:
///
/// ```compile_fail
/// use ntsql_transaction::PreparedTransactionPageStorageRestartCheckpointRepairs;
///
/// fn cannot_extract_page_repairs<Source, Store, CheckpointSource, const N: usize>(
///     prepared: PreparedTransactionPageStorageRestartCheckpointRepairs<
///         Source,
///         Store,
///         CheckpointSource,
///         N,
///     >,
/// ) {
///     let _ = prepared.page_repairs;
/// }
/// ```
///
/// The selected baseline, complete-current analysis, and adapters remain
/// inseparable from the private plan:
///
/// ```compile_fail
/// use ntsql_transaction::PreparedTransactionPageStorageRestartCheckpointRepairs;
///
/// fn cannot_extract_plan<Source, Store, CheckpointSource, const N: usize>(
///     prepared: PreparedTransactionPageStorageRestartCheckpointRepairs<
///         Source,
///         Store,
///         CheckpointSource,
///         N,
///     >,
/// ) {
///     let _ = prepared.planned;
/// }
/// ```
///
/// ```compile_fail
/// use ntsql_transaction::PreparedTransactionPageStorageRestartCheckpointRepairs;
///
/// fn cannot_extract_adapters<Source, Store, CheckpointSource, const N: usize>(
///     prepared: PreparedTransactionPageStorageRestartCheckpointRepairs<
///         Source,
///         Store,
///         CheckpointSource,
///         N,
///     >,
/// ) {
///     let _ = prepared.into_parts();
/// }
/// ```
///
/// Prepared metadata cannot bypass the explicit full-recovery fallback:
///
/// ```compile_fail
/// use ntsql_transaction::PreparedTransactionPageStorageRestartCheckpointRepairs;
///
/// fn cannot_recover_directly<Source, Store, CheckpointSource, const N: usize>(
///     prepared: PreparedTransactionPageStorageRestartCheckpointRepairs<
///         Source,
///         Store,
///         CheckpointSource,
///         N,
///     >,
/// ) {
///     let _ = prepared.recover();
/// }
/// ```
///
/// It grants no ordinary page-write, recovery-write, or checkpoint-publication
/// permit:
///
/// ```compile_fail
/// use ntsql_page::PageWritePermit;
/// use ntsql_transaction::PreparedTransactionPageStorageRestartCheckpointRepairs;
///
/// fn cannot_authorize_page_write<
///     'attempt,
///     Source,
///     Store,
///     CheckpointSource,
///     const N: usize,
/// >(
///     prepared: PreparedTransactionPageStorageRestartCheckpointRepairs<
///         Source,
///         Store,
///         CheckpointSource,
///         N,
///     >,
/// ) -> PageWritePermit<'attempt> {
///     prepared.into()
/// }
/// ```
///
/// ```compile_fail
/// use ntsql_transaction::{
///     CommittedTransactionPageRecoveryWritePermit,
///     PreparedTransactionPageStorageRestartCheckpointRepairs,
/// };
///
/// fn cannot_authorize_recovery_write<
///     'attempt,
///     Source,
///     Store,
///     CheckpointSource,
///     const N: usize,
/// >(
///     prepared: PreparedTransactionPageStorageRestartCheckpointRepairs<
///         Source,
///         Store,
///         CheckpointSource,
///         N,
///     >,
/// ) -> CommittedTransactionPageRecoveryWritePermit<'attempt> {
///     prepared.into()
/// }
/// ```
///
/// ```compile_fail
/// use ntsql_transaction::{
///     DurableTransactionRestartCheckpointCompletenessBaselinePublicationPermit,
///     PreparedTransactionPageStorageRestartCheckpointRepairs,
/// };
///
/// fn cannot_authorize_publication<
///     'attempt,
///     Source,
///     Store,
///     CheckpointSource,
///     const N: usize,
/// >(
///     prepared: PreparedTransactionPageStorageRestartCheckpointRepairs<
///         Source,
///         Store,
///         CheckpointSource,
///         N,
///     >,
/// ) -> DurableTransactionRestartCheckpointCompletenessBaselinePublicationPermit<'attempt> {
///     prepared.into()
/// }
/// ```
///
/// It cannot restore a live transaction or authorize WAL retention/reclamation:
///
/// ```compile_fail
/// use ntsql_transaction::{
///     ActiveTransaction, PreparedTransactionPageStorageRestartCheckpointRepairs,
/// };
///
/// fn cannot_restore_transaction<Source, Store, CheckpointSource, const N: usize>(
///     prepared: PreparedTransactionPageStorageRestartCheckpointRepairs<
///         Source,
///         Store,
///         CheckpointSource,
///         N,
///     >,
/// ) -> ActiveTransaction {
///     prepared.into()
/// }
/// ```
///
/// ```compile_fail
/// use ntsql_transaction::PreparedTransactionPageStorageRestartCheckpointRepairs;
/// use ntsql_wal::LogDurability;
///
/// fn cannot_retain_or_reclaim_log<
///     Log,
///     Source,
///     Store,
///     CheckpointSource,
///     const N: usize,
/// >(
///     log: &mut Log,
///     prepared: &PreparedTransactionPageStorageRestartCheckpointRepairs<
///         Source,
///         Store,
///         CheckpointSource,
///         N,
///     >,
/// )
/// where
///     Log: LogDurability,
/// {
///     let _ = log.flush_through(prepared);
/// }
/// ```
#[must_use = "prepared repairs must be retained, explicitly declined, or dropped"]
pub struct PreparedTransactionPageStorageRestartCheckpointRepairs<
    Source,
    Store,
    CheckpointSource,
    const N: usize,
> where
    Source: DurableTransactionRestartAnalysisSource<N>,
    Store: DurablePageStoreSnapshotSource<N>,
{
    planned:
        PlannedTransactionPageStorageRestartCheckpointReplay<Source, Store, CheckpointSource, N>,
    page_repairs: Vec<PreparedTransactionRestartCheckpointPageRepair<N>>,
}

/// Owning outcome of declining prepared selected-checkpoint page repairs.
pub type TransactionPageStorageRestartCheckpointPageRepairsDecline<
    Source,
    Store,
    CheckpointSource,
    const N: usize,
> = Result<
    UncheckpointedTransactionPageStorage<Source, Store, CheckpointSource, N>,
    Box<PreparedTransactionPageStorageRestartCheckpointRepairs<Source, Store, CheckpointSource, N>>,
>;

impl<Source, Store, CheckpointSource, const N: usize>
    PreparedTransactionPageStorageRestartCheckpointRepairs<Source, Store, CheckpointSource, N>
where
    Source: DurableTransactionRestartAnalysisSource<N>,
    Store: DurablePageStoreSnapshotSource<N>,
{
    /// Returns the persistent lineage identity retained by the selected checkpoint.
    #[must_use]
    pub const fn persistent_log_id(&self) -> PersistentLogId {
        self.planned.persistent_log_id()
    }

    /// Returns the selected checkpoint frontier.
    #[must_use]
    pub const fn checkpoint_frontier(&self) -> Option<u64> {
        self.planned.checkpoint_frontier()
    }

    /// Returns the complete current frontier covered by the repair preparation.
    #[must_use]
    pub fn current_frontier(&self) -> Option<u64> {
        self.planned.current_frontier()
    }

    /// Returns the number of distinct replay pages with one ordered decision.
    #[must_use]
    pub const fn page_count(&self) -> usize {
        self.page_repairs.len()
    }

    /// Returns the number of pages with no currently required durable image.
    #[must_use]
    pub fn no_required_image_count(&self) -> usize {
        self.page_repairs
            .iter()
            .filter(|repair| {
                matches!(
                    repair.resolution,
                    PreparedTransactionRestartCheckpointPageRepairResolution::NoRequiredImage
                )
            })
            .count()
    }

    /// Returns checkpoint-current pages unaffected by an eligible replay image.
    #[must_use]
    pub fn unchanged_checkpoint_current_count(&self) -> usize {
        self.page_repairs
            .iter()
            .filter(|repair| {
                matches!(
                    repair.resolution,
                    PreparedTransactionRestartCheckpointPageRepairResolution::CheckpointCurrent(_)
                )
            })
            .count()
    }

    /// Returns replay targets already present exactly in the current page store.
    #[must_use]
    pub fn already_current_count(&self) -> usize {
        self.page_repairs
            .iter()
            .filter(|repair| {
                matches!(
                    repair.resolution,
                    PreparedTransactionRestartCheckpointPageRepairResolution::AlreadyCurrent(_)
                )
            })
            .count()
    }

    /// Returns exact source/target candidates requiring a later write executor.
    #[must_use]
    pub fn repair_candidate_count(&self) -> usize {
        self.page_repairs
            .iter()
            .filter(|repair| {
                matches!(
                    repair.resolution,
                    PreparedTransactionRestartCheckpointPageRepairResolution::Candidate(_)
                )
            })
            .count()
    }

    /// Discards complete-prefix decisions before granting full recovery.
    ///
    /// Anchored decisions are returned unchanged.
    pub fn decline_page_repairs(
        self,
    ) -> TransactionPageStorageRestartCheckpointPageRepairsDecline<Source, Store, CheckpointSource, N>
    {
        let Self {
            planned,
            page_repairs,
        } = self;
        match planned.decline_replay_plan() {
            Ok(storage) => Ok(storage),
            Err(planned) => Err(Box::new(Self {
                planned: *planned,
                page_repairs,
            })),
        }
    }
}

impl<Source, Store, CheckpointSource, const N: usize> fmt::Debug
    for PreparedTransactionPageStorageRestartCheckpointRepairs<Source, Store, CheckpointSource, N>
where
    Source: DurableTransactionRestartAnalysisSource<N>,
    Store: DurablePageStoreSnapshotSource<N>,
{
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        formatter
            .debug_struct("PreparedTransactionPageStorageRestartCheckpointRepairs")
            .field("persistent_log_id", &self.persistent_log_id())
            .field("checkpoint_frontier", &self.checkpoint_frontier())
            .field("current_frontier", &self.current_frontier())
            .field("page_count", &self.page_count())
            .field("no_required_image_count", &self.no_required_image_count())
            .field(
                "unchanged_checkpoint_current_count",
                &self.unchanged_checkpoint_current_count(),
            )
            .field("already_current_count", &self.already_current_count())
            .field("repair_candidate_count", &self.repair_candidate_count())
            .finish_non_exhaustive()
    }
}

/// Inert per-page evidence retained for one complete or failed repair attempt.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum TransactionRestartCheckpointPageRepairOutcome {
    /// Replay requires no durable image and prepared absence remains exact.
    NoRequiredImage {
        /// Page whose absence was revalidated.
        page_number: PageNumber,
    },
    /// The selected checkpoint's exact current snapshot remains present.
    CheckpointCurrent {
        /// Revalidated page.
        page_number: PageNumber,
    },
    /// Preparation already observed the exact target and it remains present.
    AlreadyCurrent {
        /// Revalidated page.
        page_number: PageNumber,
    },
    /// A fresh attempt observed an exact target left by an earlier attempt.
    TargetAlreadyPresent {
        /// Revalidated page.
        page_number: PageNumber,
    },
    /// The store reported that it durably replaced source with the exact target.
    Repaired {
        /// Repaired page.
        page_number: PageNumber,
    },
}

impl TransactionRestartCheckpointPageRepairOutcome {
    /// Returns the page resolved by this attempt outcome.
    #[must_use]
    pub const fn page_number(&self) -> PageNumber {
        match self {
            Self::NoRequiredImage { page_number }
            | Self::CheckpointCurrent { page_number }
            | Self::AlreadyCurrent { page_number }
            | Self::TargetAlreadyPresent { page_number }
            | Self::Repaired { page_number } => *page_number,
        }
    }
}

/// Exact failure reported by one whole prepared page-repair attempt.
#[derive(Debug)]
pub enum TransactionRestartCheckpointPageRepairFailureCause<ObservationError, WriteError> {
    /// The complete result vector could not reserve capacity before any effect.
    OutcomeCapacityExhausted {
        /// Number of page outcomes required by the immutable plan.
        page_count: usize,
    },
    /// The replay analysis and privately held store no longer share a lineage.
    LineageMismatch {
        /// Exact replay-analysis lineage.
        replay_lineage: LogLineage,
        /// Exact page-store lineage.
        store_lineage: LogLineage,
    },
    /// An internal prepared decision remained unresolved.
    UnresolvedDecision {
        /// Page with the unresolved decision.
        page_number: PageNumber,
    },
    /// An effectful candidate lost its privately retained target.
    CandidateTargetMissing {
        /// Page with the contradictory candidate.
        page_number: PageNumber,
    },
    /// Current store observation failed before invoking this page's write port.
    StoreObservation {
        /// Page being re-observed.
        page_number: PageNumber,
        /// Exact adapter observation failure.
        source: ObservationError,
    },
    /// Current state matched neither the exact source nor the exact target.
    SourceComparison {
        /// Page whose source changed.
        page_number: PageNumber,
        /// Exact comparison contradiction.
        source: DurableTransactionRestartCheckpointPageRepairComparisonError,
    },
    /// The atomic store method was invoked and returned an indeterminate result.
    StoreWrite {
        /// Page whose replacement was invoked.
        page_number: PageNumber,
        /// Exact adapter write failure.
        source: WriteError,
    },
}

impl<ObservationError, WriteError>
    TransactionRestartCheckpointPageRepairFailureCause<ObservationError, WriteError>
{
    /// Returns whether this attempt invoked a store method that returned an error.
    #[must_use]
    pub const fn current_attempt_is_indeterminate(&self) -> bool {
        matches!(self, Self::StoreWrite { .. })
    }

    /// Returns the page directly associated with this failure, when any.
    #[must_use]
    pub const fn page_number(&self) -> Option<PageNumber> {
        match self {
            Self::OutcomeCapacityExhausted { .. } | Self::LineageMismatch { .. } => None,
            Self::UnresolvedDecision { page_number }
            | Self::CandidateTargetMissing { page_number }
            | Self::StoreObservation { page_number, .. }
            | Self::SourceComparison { page_number, .. }
            | Self::StoreWrite { page_number, .. } => Some(*page_number),
        }
    }
}

impl<ObservationError, WriteError> fmt::Display
    for TransactionRestartCheckpointPageRepairFailureCause<ObservationError, WriteError>
where
    ObservationError: fmt::Display,
    WriteError: fmt::Display,
{
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::OutcomeCapacityExhausted { page_count } => write!(
                formatter,
                "repair outcome capacity is exhausted for {page_count} pages"
            ),
            Self::LineageMismatch { .. } => formatter
                .write_str("replay analysis and repair page store belong to different lineages"),
            Self::UnresolvedDecision { page_number } => write!(
                formatter,
                "repair page {} retained an unresolved prepared decision",
                page_number.get()
            ),
            Self::CandidateTargetMissing { page_number } => write!(
                formatter,
                "repair page {} retained a candidate without a target",
                page_number.get()
            ),
            Self::StoreObservation {
                page_number,
                source,
            } => write!(
                formatter,
                "repair page {} observation failed: {source}",
                page_number.get()
            ),
            Self::SourceComparison {
                page_number,
                source,
            } => write!(
                formatter,
                "repair page {} source comparison failed: {source}",
                page_number.get()
            ),
            Self::StoreWrite {
                page_number,
                source,
            } => write!(
                formatter,
                "repair page {} atomic replacement returned an indeterminate error: {source}",
                page_number.get()
            ),
        }
    }
}

impl<ObservationError, WriteError> Error
    for TransactionRestartCheckpointPageRepairFailureCause<ObservationError, WriteError>
where
    ObservationError: Error + 'static,
    WriteError: Error + 'static,
{
    fn source(&self) -> Option<&(dyn Error + 'static)> {
        match self {
            Self::StoreObservation { source, .. } => Some(source),
            Self::SourceComparison { source, .. } => Some(source),
            Self::StoreWrite { source, .. } => Some(source),
            Self::OutcomeCapacityExhausted { .. }
            | Self::LineageMismatch { .. }
            | Self::UnresolvedDecision { .. }
            | Self::CandidateTargetMissing { .. } => None,
        }
    }
}

/// Successful owner after every prepared page was re-observed and resolved.
///
/// This state exposes no adapters, page images, write permits, transaction
/// restoration authority, publication authority, or live transaction owner.
///
/// ```compile_fail
/// fn cannot_fallback<Source, Store, CheckpointSource, const N: usize>(
///     repaired: ntsql_transaction::RepairedTransactionPageStorageRestartCheckpointReplay<
///         Source,
///         Store,
///         CheckpointSource,
///         N,
///     >,
/// ) {
///     let _ = repaired.decline_page_repairs();
/// }
/// ```
#[derive(Debug)]
#[must_use = "repaired restart state must be retained for transaction restoration"]
pub struct RepairedTransactionPageStorageRestartCheckpointReplay<
    Source,
    Store,
    CheckpointSource,
    const N: usize,
> where
    Source: DurableTransactionRestartAnalysisSource<N>,
    Store: DurablePageStoreSnapshotSource<N>,
{
    prepared:
        PreparedTransactionPageStorageRestartCheckpointRepairs<Source, Store, CheckpointSource, N>,
    page_outcomes: Vec<TransactionRestartCheckpointPageRepairOutcome>,
}

impl<Source, Store, CheckpointSource, const N: usize>
    RepairedTransactionPageStorageRestartCheckpointReplay<Source, Store, CheckpointSource, N>
where
    Source: DurableTransactionRestartAnalysisSource<N>,
    Store: DurablePageStoreSnapshotSource<N>,
{
    /// Returns the persistent identity shared by the held recovery resources.
    #[must_use]
    pub const fn persistent_log_id(&self) -> PersistentLogId {
        self.prepared.persistent_log_id()
    }

    /// Returns the selected checkpoint frontier.
    #[must_use]
    pub const fn checkpoint_frontier(&self) -> Option<u64> {
        self.prepared.checkpoint_frontier()
    }

    /// Returns the complete current durable frontier.
    #[must_use]
    pub fn current_frontier(&self) -> Option<u64> {
        self.prepared.current_frontier()
    }

    /// Returns one complete strictly increasing outcome per prepared page.
    #[must_use]
    pub fn page_outcomes(&self) -> &[TransactionRestartCheckpointPageRepairOutcome] {
        &self.page_outcomes
    }
}

/// Inert summary of the transaction state retained by one restored restart owner.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
#[must_use]
pub struct TransactionRestartRestorationSummary {
    transaction_count: usize,
    committed_count: usize,
    unresolved_count: usize,
    highest_persisted_transaction: Option<DurableTransactionIdentityObservation>,
    coordinator_epoch: TransactionEpoch,
    indeterminate_allocation_attempt_count: usize,
}

impl TransactionRestartRestorationSummary {
    /// Returns the number of exact complete-current transaction entries retained.
    #[must_use]
    pub const fn transaction_count(self) -> usize {
        self.transaction_count
    }

    /// Returns the number of entries with one exact durable commit position.
    #[must_use]
    pub const fn committed_count(self) -> usize {
        self.committed_count
    }

    /// Returns the number of unresolved entries retained for later reviewed work.
    #[must_use]
    pub const fn unresolved_count(self) -> usize {
        self.unresolved_count
    }

    /// Returns the greatest persisted identity represented by retained evidence.
    #[must_use]
    pub const fn highest_persisted_transaction(
        self,
    ) -> Option<DurableTransactionIdentityObservation> {
        self.highest_persisted_transaction
    }

    /// Returns the fresh private coordinator epoch allocated above retained evidence.
    #[must_use]
    pub const fn coordinator_epoch(self) -> TransactionEpoch {
        self.coordinator_epoch
    }

    /// Returns earlier allocation calls whose physical result remained unknown.
    #[must_use]
    pub const fn indeterminate_allocation_attempt_count(self) -> usize {
        self.indeterminate_allocation_attempt_count
    }
}

/// Contradictory selected-checkpoint and complete-current transaction evidence.
#[derive(Clone, Debug, Eq, PartialEq)]
pub enum TransactionRestartRestorationEvidenceError {
    /// The complete-current analysis no longer has a persistent lineage identity.
    CurrentPersistentLineageRequired,
    /// Selected and complete-current evidence name different persistent lineages.
    PersistentLineageMismatch {
        /// Persistent identity retained by the selected checkpoint.
        selected: PersistentLogId,
        /// Persistent identity retained by complete-current analysis.
        current: PersistentLogId,
    },
    /// A nonempty selected frontier has no complete-current durable frontier.
    CurrentFrontierMissing {
        /// Selected checkpoint frontier.
        selected_frontier: u64,
    },
    /// The selected checkpoint frontier is after the complete-current frontier.
    SelectedFrontierAfterCurrent {
        /// Selected checkpoint frontier.
        selected_frontier: u64,
        /// Complete-current frontier.
        current_frontier: u64,
    },
    /// An empty selected prefix retained an impossible transaction entry.
    TransactionInEmptySelectedPrefix {
        /// Unexpected selected transaction.
        transaction: DurableTransactionIdentityObservation,
    },
    /// A selected transaction is absent from complete-current analysis.
    SelectedTransactionMissing {
        /// Missing transaction.
        transaction: DurableTransactionIdentityObservation,
    },
    /// A complete-current transaction begins inside the selected prefix but is absent there.
    CurrentTransactionMissingFromSelectedPrefix {
        /// Missing selected-prefix transaction.
        transaction: DurableTransactionIdentityObservation,
        /// First complete-current position for that identity.
        first_position: u64,
    },
    /// A selected transaction's first owned-page position changed.
    FirstOwnedPagePositionMismatch {
        /// Contradictory transaction.
        transaction: DurableTransactionIdentityObservation,
        /// Selected first owned-page position.
        selected: Option<u64>,
        /// Complete-current first owned-page position.
        current: Option<u64>,
    },
    /// An unresolved selected transaction's aggregate page evidence is not a suffix extension.
    SelectedUnresolvedOwnedPageEvidenceContradiction {
        /// Contradictory transaction.
        transaction: DurableTransactionIdentityObservation,
        /// Selected checkpoint frontier.
        selected_frontier: u64,
        /// Selected last owned-page position.
        selected_last_position: Option<u64>,
        /// Complete-current last owned-page position.
        current_last_position: Option<u64>,
        /// Selected durable owned-page count.
        selected_record_count: u64,
        /// Complete-current durable owned-page count.
        current_record_count: u64,
    },
    /// An unresolved selected transaction lost durable owned-page records.
    OwnedPageRecordCountRegressed {
        /// Contradictory transaction.
        transaction: DurableTransactionIdentityObservation,
        /// Selected durable owned-page count.
        selected: u64,
        /// Complete-current durable owned-page count.
        current: u64,
    },
    /// A terminal selected committed entry changed in the complete-current table.
    SelectedCommittedTransactionChanged {
        /// Contradictory transaction.
        transaction: DurableTransactionIdentityObservation,
        /// Selected commit position.
        selected_commit_position: u64,
        /// Complete-current commit position, absent when it became unresolved.
        current_commit_position: Option<u64>,
    },
    /// A selected unresolved entry was already committed inside its selected prefix.
    SelectedUnresolvedTransactionCommittedInsidePrefix {
        /// Contradictory transaction.
        transaction: DurableTransactionIdentityObservation,
        /// Selected checkpoint frontier.
        selected_frontier: u64,
        /// Complete-current commit position at or before that frontier.
        commit_position: u64,
    },
    /// One selected transaction field lies beyond the selected frontier.
    SelectedTransactionPositionAfterFrontier {
        /// Contradictory transaction.
        transaction: DurableTransactionIdentityObservation,
        /// Selected checkpoint frontier.
        selected_frontier: u64,
        /// Out-of-range selected position.
        position: u64,
    },
    /// A complete-current entry has no page or commit position.
    CurrentTransactionHasNoRecordPosition {
        /// Contradictory transaction.
        transaction: DurableTransactionIdentityObservation,
    },
    /// A platform-width page count cannot be represented in checkpoint-width evidence.
    CurrentOwnedPageCountWidthExceeded {
        /// Contradictory transaction.
        transaction: DurableTransactionIdentityObservation,
        /// Complete-current platform-width count.
        record_count: usize,
    },
    /// Restoration summary counters cannot represent another retained entry.
    SummaryCountExhausted,
}

impl fmt::Display for TransactionRestartRestorationEvidenceError {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::CurrentPersistentLineageRequired => formatter
                .write_str("complete-current transaction evidence requires persistent lineage"),
            Self::PersistentLineageMismatch { .. } => {
                formatter.write_str("selected and complete-current transaction lineages differ")
            }
            Self::CurrentFrontierMissing { selected_frontier } => write!(
                formatter,
                "selected transaction frontier {selected_frontier} has no complete-current frontier"
            ),
            Self::SelectedFrontierAfterCurrent {
                selected_frontier,
                current_frontier,
            } => write!(
                formatter,
                "selected transaction frontier {selected_frontier} is after complete-current frontier {current_frontier}"
            ),
            Self::TransactionInEmptySelectedPrefix { transaction } => write!(
                formatter,
                "empty selected transaction prefix contains {transaction}"
            ),
            Self::SelectedTransactionMissing { transaction } => write!(
                formatter,
                "selected transaction {transaction} is absent from complete-current evidence"
            ),
            Self::CurrentTransactionMissingFromSelectedPrefix {
                transaction,
                first_position,
            } => write!(
                formatter,
                "complete-current transaction {transaction} begins at {first_position} inside the selected prefix but is absent there"
            ),
            Self::FirstOwnedPagePositionMismatch { transaction, .. } => write!(
                formatter,
                "selected transaction {transaction} changed its first owned-page position"
            ),
            Self::SelectedUnresolvedOwnedPageEvidenceContradiction { transaction, .. } => write!(
                formatter,
                "selected unresolved transaction {transaction} has page evidence that is not a post-frontier suffix extension"
            ),
            Self::OwnedPageRecordCountRegressed { transaction, .. } => write!(
                formatter,
                "selected transaction {transaction} lost durable owned-page records"
            ),
            Self::SelectedCommittedTransactionChanged { transaction, .. } => write!(
                formatter,
                "selected committed transaction {transaction} changed in complete-current evidence"
            ),
            Self::SelectedUnresolvedTransactionCommittedInsidePrefix { transaction, .. } => write!(
                formatter,
                "selected unresolved transaction {transaction} is committed inside the selected prefix"
            ),
            Self::SelectedTransactionPositionAfterFrontier {
                transaction,
                position,
                ..
            } => write!(
                formatter,
                "selected transaction {transaction} retains position {position} after its checkpoint frontier"
            ),
            Self::CurrentTransactionHasNoRecordPosition { transaction } => write!(
                formatter,
                "complete-current transaction {transaction} has no durable record position"
            ),
            Self::CurrentOwnedPageCountWidthExceeded {
                transaction,
                record_count,
            } => write!(
                formatter,
                "complete-current transaction {transaction} owned-page count {record_count} exceeds checkpoint width"
            ),
            Self::SummaryCountExhausted => {
                formatter.write_str("transaction restoration summary count is exhausted")
            }
        }
    }
}

impl Error for TransactionRestartRestorationEvidenceError {}

/// Deterministic rejection that cannot change within the retained startup attempt.
#[derive(Clone, Debug)]
pub enum TransactionRestartRestorationRejection {
    /// Selected and complete-current transaction evidence is contradictory.
    Evidence(Box<TransactionRestartRestorationEvidenceError>),
    /// No numeric epoch remains above retained persisted evidence.
    IdentitySpaceExhausted {
        /// Highest persisted epoch, absent only for an empty transaction table.
        persisted_epoch_high_water: Option<u64>,
    },
    /// The adapter reported that its next epoch is stale.
    PersistedEpochHighWaterNotAdvanced {
        /// Highest retained persisted epoch.
        persisted_epoch_high_water: u64,
        /// Stale adapter epoch.
        next_epoch: u64,
    },
    /// A successful source result still failed the domain's defensive high-water check.
    AllocatedEpochNotAbovePersistedHighWater {
        /// Highest retained persisted epoch.
        persisted_epoch_high_water: u64,
        /// Invalid allocated epoch.
        allocated_epoch: u64,
    },
    /// A successful source result paired the new epoch with another lineage.
    AllocatedEpochLineageMismatch {
        /// Complete-current transaction lineage.
        expected: LogLineage,
        /// Lineage paired with the allocated epoch.
        actual: LogLineage,
        /// Allocated but intentionally unreleased epoch.
        allocated_epoch: u64,
    },
    /// Another indeterminate allocation attempt cannot be counted exactly.
    AllocationAttemptCountExhausted,
}

impl fmt::Display for TransactionRestartRestorationRejection {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::Evidence(source) => write!(
                formatter,
                "transaction restoration evidence is contradictory: {source}"
            ),
            Self::IdentitySpaceExhausted {
                persisted_epoch_high_water,
            } => write!(
                formatter,
                "transaction identity space is exhausted above persisted epoch {:?}",
                persisted_epoch_high_water
            ),
            Self::PersistedEpochHighWaterNotAdvanced {
                persisted_epoch_high_water,
                next_epoch,
            } => write!(
                formatter,
                "next transaction epoch {next_epoch} does not advance beyond persisted epoch {persisted_epoch_high_water}"
            ),
            Self::AllocatedEpochNotAbovePersistedHighWater {
                persisted_epoch_high_water,
                allocated_epoch,
            } => write!(
                formatter,
                "allocated transaction epoch {allocated_epoch} does not advance beyond persisted epoch {persisted_epoch_high_water}"
            ),
            Self::AllocatedEpochLineageMismatch {
                allocated_epoch, ..
            } => write!(
                formatter,
                "allocated transaction epoch {allocated_epoch} belongs to another lineage"
            ),
            Self::AllocationAttemptCountExhausted => formatter
                .write_str("indeterminate transaction epoch allocation attempt count is exhausted"),
        }
    }
}

impl Error for TransactionRestartRestorationRejection {
    fn source(&self) -> Option<&(dyn Error + 'static)> {
        match self {
            Self::Evidence(source) => Some(source.as_ref()),
            Self::IdentitySpaceExhausted { .. }
            | Self::PersistedEpochHighWaterNotAdvanced { .. }
            | Self::AllocatedEpochNotAbovePersistedHighWater { .. }
            | Self::AllocatedEpochLineageMismatch { .. }
            | Self::AllocationAttemptCountExhausted => None,
        }
    }
}

/// Successful non-live owner after transaction state and a fresh coordinator exist.
///
/// Exact persisted entries remain private inside the retained repaired owner.
/// The coordinator is also private, so no active token or ordinary mutation
/// authority can escape before the final startup transition.
///
/// ```compile_fail
/// use ntsql_transaction::{
///     ActiveTransaction, RestoredTransactionPageStorageRestartCheckpointReplay,
/// };
///
/// fn cannot_extract_active<Source, Store, CheckpointSource, const N: usize>(
///     restored: RestoredTransactionPageStorageRestartCheckpointReplay<
///         Source,
///         Store,
///         CheckpointSource,
///         N,
///     >,
/// ) -> ActiveTransaction {
///     restored.into()
/// }
/// ```
///
/// ```compile_fail
/// use ntsql_transaction::RestoredTransactionPageStorageRestartCheckpointReplay;
///
/// fn cannot_activate_coordinator<Source, Store, CheckpointSource, const N: usize>(
///     mut restored: RestoredTransactionPageStorageRestartCheckpointReplay<
///         Source,
///         Store,
///         CheckpointSource,
///         N,
///     >,
/// ) {
///     let _ = restored.coordinator_mut().begin();
/// }
/// ```
///
/// ```compile_fail
/// use ntsql_transaction::{
///     RepairedTransactionPageStorageRestartCheckpointReplay,
///     RestoredTransactionPageStorageRestartCheckpointReplay, TransactionCoordinator,
///     TransactionRestartRestorationSummary,
/// };
///
/// fn cannot_forge<Source, Store, CheckpointSource, const N: usize>(
///     repaired: RepairedTransactionPageStorageRestartCheckpointReplay<
///         Source,
///         Store,
///         CheckpointSource,
///         N,
///     >,
///     coordinator: TransactionCoordinator,
///     summary: TransactionRestartRestorationSummary,
/// ) -> RestoredTransactionPageStorageRestartCheckpointReplay<
///     Source,
///     Store,
///     CheckpointSource,
///     N,
/// > {
///     RestoredTransactionPageStorageRestartCheckpointReplay {
///         repaired,
///         coordinator,
///         summary,
///     }
/// }
/// ```
///
/// ```compile_fail
/// use ntsql_transaction::RestoredTransactionPageStorageRestartCheckpointReplay;
///
/// fn cannot_extract_adapters<Source, Store, CheckpointSource, const N: usize>(
///     restored: RestoredTransactionPageStorageRestartCheckpointReplay<
///         Source,
///         Store,
///         CheckpointSource,
///         N,
///     >,
/// ) -> (Source, Store, CheckpointSource) {
///     restored.into_parts()
/// }
/// ```
///
/// ```compile_fail
/// use ntsql_transaction::RestoredTransactionPageStorageRestartCheckpointReplay;
///
/// fn cannot_publish_checkpoint<Source, Store, CheckpointSource, const N: usize>(
///     restored: &mut RestoredTransactionPageStorageRestartCheckpointReplay<
///         Source,
///         Store,
///         CheckpointSource,
///         N,
///     >,
/// ) {
///     let _ = restored.publish_restart_checkpoint_completeness_baseline_from_current_prefix();
/// }
/// ```
///
/// ```compile_fail
/// use ntsql_transaction::RestoredTransactionPageStorageRestartCheckpointReplay;
/// use ntsql_wal::LogDurability;
///
/// fn cannot_reclaim_wal<
///     Log: LogDurability,
///     Source,
///     Store,
///     CheckpointSource,
///     const N: usize,
/// >(
///     log: &mut Log,
///     restored: &RestoredTransactionPageStorageRestartCheckpointReplay<
///         Source,
///         Store,
///         CheckpointSource,
///         N,
///     >,
/// ) {
///     let _ = log.flush_through(restored);
/// }
/// ```
#[must_use = "restored restart state must be retained for final startup validation"]
pub struct RestoredTransactionPageStorageRestartCheckpointReplay<
    Source,
    Store,
    CheckpointSource,
    const N: usize,
> where
    Source: DurableTransactionRestartAnalysisSource<N>,
    Store: DurablePageStoreSnapshotSource<N>,
{
    repaired:
        RepairedTransactionPageStorageRestartCheckpointReplay<Source, Store, CheckpointSource, N>,
    coordinator: TransactionCoordinator,
    summary: TransactionRestartRestorationSummary,
}

impl<Source, Store, CheckpointSource, const N: usize>
    RestoredTransactionPageStorageRestartCheckpointReplay<Source, Store, CheckpointSource, N>
where
    Source: DurableTransactionRestartAnalysisSource<N>,
    Store: DurablePageStoreSnapshotSource<N>,
{
    /// Returns the persistent identity shared by all retained restart resources.
    #[must_use]
    pub const fn persistent_log_id(&self) -> PersistentLogId {
        self.repaired.persistent_log_id()
    }

    /// Returns the selected checkpoint frontier.
    #[must_use]
    pub const fn checkpoint_frontier(&self) -> Option<u64> {
        self.repaired.checkpoint_frontier()
    }

    /// Returns the complete-current durable frontier.
    #[must_use]
    pub fn current_frontier(&self) -> Option<u64> {
        self.repaired.current_frontier()
    }

    /// Returns inert aggregate restoration evidence.
    pub const fn transaction_summary(&self) -> TransactionRestartRestorationSummary {
        TransactionRestartRestorationSummary {
            coordinator_epoch: self.coordinator.epoch(),
            ..self.summary
        }
    }

    /// Returns the already completed ordered page-repair outcomes.
    #[must_use]
    pub fn page_outcomes(&self) -> &[TransactionRestartCheckpointPageRepairOutcome] {
        self.repaired.page_outcomes()
    }
}

impl<Source, Store, CheckpointSource, const N: usize> fmt::Debug
    for RestoredTransactionPageStorageRestartCheckpointReplay<Source, Store, CheckpointSource, N>
where
    Source: DurableTransactionRestartAnalysisSource<N>,
    Store: DurablePageStoreSnapshotSource<N>,
{
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        formatter
            .debug_struct("RestoredTransactionPageStorageRestartCheckpointReplay")
            .field("persistent_log_id", &self.persistent_log_id())
            .field("checkpoint_frontier", &self.checkpoint_frontier())
            .field("current_frontier", &self.current_frontier())
            .field("summary", &self.summary)
            .field("page_outcome_count", &self.page_outcomes().len())
            .finish_non_exhaustive()
    }
}

/// Contradiction found while completing one restored selected-checkpoint restart.
#[derive(Clone, Debug)]
pub enum DurableTransactionRestartCheckpointCompletionEvidenceError {
    /// The retained selected/current transaction relationship no longer validates.
    RestorationEvidence(Box<TransactionRestartRestorationEvidenceError>),
    /// Fresh logical WAL analysis described another lineage.
    CurrentLineageChanged {
        /// Lineage retained by the selected restart plan.
        expected: LogLineage,
        /// Lineage returned by final logical WAL analysis.
        actual: LogLineage,
    },
    /// Fresh logical WAL analysis described another durable frontier.
    CurrentFrontierChanged {
        /// Frontier retained by the selected restart plan.
        expected: Option<u64>,
        /// Frontier returned by final logical WAL analysis.
        actual: Option<u64>,
    },
    /// Fresh logical WAL analysis returned another transaction-table length.
    CurrentTransactionCountChanged {
        /// Number of retained complete-current transaction entries.
        expected: usize,
        /// Number of freshly analyzed transaction entries.
        actual: usize,
    },
    /// One freshly analyzed transaction-table entry changed or moved.
    CurrentTransactionEntryChanged {
        /// Strict persisted-identity index of the changed entry.
        index: usize,
        /// Retained transaction identity at this index.
        expected: DurableTransactionIdentityObservation,
        /// Freshly analyzed transaction identity at this index.
        actual: DurableTransactionIdentityObservation,
    },
    /// The retained page store no longer belongs to the logical WAL lineage.
    StoreLineageMismatch {
        /// Freshly validated logical WAL lineage.
        expected: LogLineage,
        /// Lineage declared by the retained page store.
        actual: LogLineage,
    },
    /// The restored coordinator no longer belongs to the logical WAL lineage.
    CoordinatorLineageMismatch {
        /// Freshly validated logical WAL lineage.
        expected: LogLineage,
        /// Lineage retained by the restored coordinator.
        actual: LogLineage,
    },
    /// The coordinator epoch no longer equals its immutable restoration summary.
    CoordinatorEpochChanged {
        /// Epoch recorded when restoration succeeded.
        expected: u64,
        /// Epoch retained by the exact coordinator.
        actual: u64,
    },
    /// The coordinator epoch no longer advances beyond retained persisted identity.
    CoordinatorEpochNotAbovePersistedHighWater {
        /// Highest epoch represented by retained transaction evidence.
        persisted_epoch_high_water: u64,
        /// Epoch retained by the restored coordinator.
        coordinator_epoch: u64,
    },
    /// Aggregate restoration evidence no longer matches the retained transaction table.
    RestorationSummaryChanged {
        /// Summary derived again from exact retained evidence.
        expected: TransactionRestartRestorationSummary,
        /// Summary retained by the restored owner.
        actual: TransactionRestartRestorationSummary,
    },
    /// The private restored coordinator was used before final live release.
    CoordinatorStateChanged {
        /// Next sequence the coordinator would issue.
        next_sequence: Option<u64>,
        /// Number of in-process transaction lifecycle entries.
        lifecycle_count: usize,
        /// Number of staged transaction/page pairs.
        staged_page_count: usize,
    },
    /// The retained ordered page outcomes no longer cover every prepared page.
    PageOutcomeCountChanged {
        /// Number of privately prepared page decisions.
        expected: usize,
        /// Number of retained execution outcomes.
        actual: usize,
    },
    /// One retained historical outcome does not match its prepared page decision.
    PageOutcomeChanged {
        /// Strict page-order index of the contradictory outcome.
        index: usize,
        /// Page owned by the prepared decision.
        expected_page: PageNumber,
        /// Contradictory retained outcome.
        actual: TransactionRestartCheckpointPageRepairOutcome,
    },
    /// A supposedly completed page still has no prepared resolution.
    PendingPageRepair {
        /// Page whose decision remains pending.
        page_number: PageNumber,
    },
    /// A target-bearing prepared resolution lost its exact replay target.
    PageRepairTargetMissing {
        /// Page whose target is absent.
        page_number: PageNumber,
    },
    /// A final page observation contradicted its exact terminal state.
    FinalPageComparison {
        /// Page whose final state was rejected.
        page_number: PageNumber,
        /// Exact source/target comparison contradiction.
        source: Box<DurableTransactionRestartCheckpointPageRepairComparisonError>,
    },
    /// A candidate page remained at its old source rather than its exact target.
    FinalPageTargetMissing {
        /// Page whose exact target was not present.
        page_number: PageNumber,
    },
}

impl fmt::Display for DurableTransactionRestartCheckpointCompletionEvidenceError {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::RestorationEvidence(source) => {
                write!(
                    formatter,
                    "retained transaction restoration evidence changed: {source}"
                )
            }
            Self::CurrentLineageChanged { .. } => {
                formatter.write_str("final logical WAL analysis belongs to another lineage")
            }
            Self::CurrentFrontierChanged { expected, actual } => write!(
                formatter,
                "final logical WAL frontier {actual:?} differs from retained frontier {expected:?}"
            ),
            Self::CurrentTransactionCountChanged { expected, actual } => write!(
                formatter,
                "final transaction count {actual} differs from retained count {expected}"
            ),
            Self::CurrentTransactionEntryChanged {
                index,
                expected,
                actual,
            } => write!(
                formatter,
                "final transaction entry {index} changed from {expected} to {actual}"
            ),
            Self::StoreLineageMismatch { .. } => {
                formatter.write_str("final page store and logical WAL lineages differ")
            }
            Self::CoordinatorLineageMismatch { .. } => {
                formatter.write_str("restored coordinator and logical WAL lineages differ")
            }
            Self::CoordinatorEpochChanged { expected, actual } => write!(
                formatter,
                "restored coordinator epoch {actual} differs from summary epoch {expected}"
            ),
            Self::CoordinatorEpochNotAbovePersistedHighWater {
                persisted_epoch_high_water,
                coordinator_epoch,
            } => write!(
                formatter,
                "restored coordinator epoch {coordinator_epoch} does not advance beyond persisted epoch {persisted_epoch_high_water}"
            ),
            Self::RestorationSummaryChanged { .. } => formatter.write_str(
                "restored transaction summary differs from retained transaction evidence",
            ),
            Self::CoordinatorStateChanged { .. } => {
                formatter.write_str("restored coordinator was used before final live release")
            }
            Self::PageOutcomeCountChanged { expected, actual } => write!(
                formatter,
                "completed page outcome count {actual} differs from prepared count {expected}"
            ),
            Self::PageOutcomeChanged {
                index,
                expected_page,
                ..
            } => write!(
                formatter,
                "completed page outcome {index} does not match prepared page {}",
                expected_page.get()
            ),
            Self::PendingPageRepair { page_number } => write!(
                formatter,
                "completed restart retains pending page {}",
                page_number.get()
            ),
            Self::PageRepairTargetMissing { page_number } => write!(
                formatter,
                "completed restart page {} has no exact repair target",
                page_number.get()
            ),
            Self::FinalPageComparison {
                page_number,
                source,
            } => write!(
                formatter,
                "final state for page {} is contradictory: {source}",
                page_number.get()
            ),
            Self::FinalPageTargetMissing { page_number } => write!(
                formatter,
                "final state for page {} still contains its prepared source",
                page_number.get()
            ),
        }
    }
}

impl Error for DurableTransactionRestartCheckpointCompletionEvidenceError {
    fn source(&self) -> Option<&(dyn Error + 'static)> {
        match self {
            Self::RestorationEvidence(source) => Some(source.as_ref()),
            Self::FinalPageComparison { source, .. } => Some(source.as_ref()),
            Self::CurrentLineageChanged { .. }
            | Self::CurrentFrontierChanged { .. }
            | Self::CurrentTransactionCountChanged { .. }
            | Self::CurrentTransactionEntryChanged { .. }
            | Self::StoreLineageMismatch { .. }
            | Self::CoordinatorLineageMismatch { .. }
            | Self::CoordinatorEpochChanged { .. }
            | Self::CoordinatorEpochNotAbovePersistedHighWater { .. }
            | Self::RestorationSummaryChanged { .. }
            | Self::CoordinatorStateChanged { .. }
            | Self::PageOutcomeCountChanged { .. }
            | Self::PageOutcomeChanged { .. }
            | Self::PendingPageRepair { .. }
            | Self::PageRepairTargetMissing { .. }
            | Self::FinalPageTargetMissing { .. } => None,
        }
    }
}

/// Exact typed failure from the final read-only selected-restart validation.
#[derive(Debug)]
pub enum DurableTransactionRestartCheckpointCompletionError<SourceError, StoreError> {
    /// Fresh logical WAL analysis failed.
    RestartAnalysis(DurableTransactionRestartAnalysisError<SourceError>),
    /// Fresh anchored retained-suffix replay planning failed.
    ReplayPlanning(
        Box<DurableTransactionRestartCheckpointReplayPlanningError<SourceError, StoreError>>,
    ),
    /// Final observation of one prepared page failed.
    StoreObservation {
        /// Page whose exact terminal state could not be observed.
        page_number: PageNumber,
        /// Exact page-store observation failure.
        source: StoreError,
    },
    /// Retained or freshly observed evidence was contradictory.
    Evidence(Box<DurableTransactionRestartCheckpointCompletionEvidenceError>),
}

impl<SourceError: fmt::Display, StoreError: fmt::Display> fmt::Display
    for DurableTransactionRestartCheckpointCompletionError<SourceError, StoreError>
{
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::RestartAnalysis(source) => {
                write!(formatter, "final logical WAL validation failed: {source}")
            }
            Self::ReplayPlanning(source) => {
                write!(
                    formatter,
                    "final anchored retained-suffix validation failed: {source}"
                )
            }
            Self::StoreObservation {
                page_number,
                source,
            } => write!(
                formatter,
                "final observation of page {} failed: {source}",
                page_number.get()
            ),
            Self::Evidence(source) => write!(
                formatter,
                "selected-checkpoint restart completion was rejected: {source}"
            ),
        }
    }
}

impl<SourceError, StoreError> Error
    for DurableTransactionRestartCheckpointCompletionError<SourceError, StoreError>
where
    SourceError: Error + 'static,
    StoreError: Error + 'static,
{
    fn source(&self) -> Option<&(dyn Error + 'static)> {
        match self {
            Self::RestartAnalysis(source) => Some(source),
            Self::ReplayPlanning(source) => Some(source.as_ref()),
            Self::StoreObservation { source, .. } => Some(source),
            Self::Evidence(source) => Some(source.as_ref()),
        }
    }
}

/// Finalization error specialized to one retained WAL source and page store.
pub type TransactionPageStorageRestartCheckpointCompletionError<Source, Store, const N: usize> =
    DurableTransactionRestartCheckpointCompletionError<
        <Source as DurableTransactionRestartAnalysisSource<N>>::Error,
        <Store as DurablePageStoreSnapshotSource<N>>::ObservationError,
    >;

/// Immutable evidence retained by one completed selected-checkpoint restart.
///
/// Exact replay observations, repair decisions, and selected checkpoint fields
/// remain private for the later retention analysis. Public accessors expose only
/// inert identifying and aggregate startup evidence.
///
/// ```compile_fail
/// use ntsql_transaction::TransactionPageStorageRestartCheckpointCompletionEvidence;
///
/// fn cannot_forge<const N: usize>() -> TransactionPageStorageRestartCheckpointCompletionEvidence<N> {
///     TransactionPageStorageRestartCheckpointCompletionEvidence {
///         selected_baseline: todo!(),
///         current_analysis: todo!(),
///         replay_observations: Vec::new(),
///         page_repairs: Vec::new(),
///         page_outcomes: Vec::new(),
///         transaction_summary: todo!(),
///     }
/// }
/// ```
#[must_use]
pub struct TransactionPageStorageRestartCheckpointCompletionEvidence<const N: usize> {
    selected_baseline: Box<DurableTransactionRestartCheckpointCompletenessBaseline>,
    current_analysis: DurableTransactionRestartAnalysis,
    replay_observations: Vec<OwnedDurableTransactionRestartReplayObservation<N>>,
    page_repairs: Vec<PreparedTransactionRestartCheckpointPageRepair<N>>,
    page_outcomes: Vec<TransactionRestartCheckpointPageRepairOutcome>,
    transaction_summary: TransactionRestartRestorationSummary,
}

impl<const N: usize> TransactionPageStorageRestartCheckpointCompletionEvidence<N> {
    /// Returns the persistent identity shared by the completed startup resources.
    #[must_use]
    pub const fn persistent_log_id(&self) -> PersistentLogId {
        self.selected_baseline.persistent_log_id()
    }

    /// Returns the exact selected checkpoint frontier.
    #[must_use]
    pub const fn checkpoint_frontier(&self) -> Option<u64> {
        self.selected_baseline.durable_frontier()
    }

    /// Returns the exact complete-current logical WAL frontier validated at release.
    #[must_use]
    pub fn current_frontier(&self) -> Option<u64> {
        self.current_analysis
            .durable_frontier()
            .map(LogSequenceNumber::get)
    }

    /// Returns the original ordered outcomes of the successful repair attempt.
    #[must_use]
    pub fn page_outcomes(&self) -> &[TransactionRestartCheckpointPageRepairOutcome] {
        &self.page_outcomes
    }

    /// Returns inert aggregate transaction-restoration evidence.
    pub const fn transaction_summary(&self) -> TransactionRestartRestorationSummary {
        self.transaction_summary
    }
}

impl<const N: usize> fmt::Debug for TransactionPageStorageRestartCheckpointCompletionEvidence<N> {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        formatter
            .debug_struct("TransactionPageStorageRestartCheckpointCompletionEvidence")
            .field("persistent_log_id", &self.persistent_log_id())
            .field("checkpoint_frontier", &self.checkpoint_frontier())
            .field("current_frontier", &self.current_frontier())
            .field("replay_record_count", &self.replay_observations.len())
            .field("page_repair_count", &self.page_repairs.len())
            .field("page_outcome_count", &self.page_outcomes.len())
            .field("transaction_summary", &self.transaction_summary)
            .finish_non_exhaustive()
    }
}

/// Live selected-checkpoint owner released only after final exact revalidation.
///
/// This is an explicit sibling of the complete-recovery live owner. It preserves
/// selected replay evidence rather than fabricating a complete-recovery report.
///
/// ```compile_fail
/// use ntsql_transaction::{
///     CompletedTransactionPageStorageRestartCheckpointReplay,
///     TransactionCoordinator, TransactionPageStorageRestartCheckpointCompletionEvidence,
/// };
///
/// fn cannot_forge<Source, Store, CheckpointSource, const N: usize>(
///     coordinator: TransactionCoordinator,
///     source: Source,
///     store: Store,
///     checkpoint_source: CheckpointSource,
///     evidence: TransactionPageStorageRestartCheckpointCompletionEvidence<N>,
/// ) -> CompletedTransactionPageStorageRestartCheckpointReplay<
///     Source,
///     Store,
///     CheckpointSource,
///     N,
/// > {
///     CompletedTransactionPageStorageRestartCheckpointReplay {
///         coordinator,
///         source,
///         store,
///         checkpoint_source,
///         evidence,
///     }
/// }
/// ```
///
/// ```compile_fail
/// use ntsql_transaction::{
///     CompletedTransactionPageStorageRestartCheckpointReplay,
///     RestartAnalyzedTransactionPageStorage,
/// };
///
/// fn cannot_substitute_complete_recovery<Source, Store, CheckpointSource, const N: usize>(
///     completed: CompletedTransactionPageStorageRestartCheckpointReplay<
///         Source,
///         Store,
///         CheckpointSource,
///         N,
///     >,
/// ) -> RestartAnalyzedTransactionPageStorage<Source, Store, N> {
///     completed.into()
/// }
/// ```
///
/// ```compile_fail
/// use ntsql_transaction::TransactionPageStorageRestartCheckpointCompletionEvidence;
/// use ntsql_wal::LogDurability;
///
/// fn cannot_reclaim_wal<Log: LogDurability, const N: usize>(
///     log: &mut Log,
///     evidence: &TransactionPageStorageRestartCheckpointCompletionEvidence<N>,
/// ) {
///     let _ = log.flush_through(evidence);
/// }
/// ```
///
/// ```compile_fail
/// use ntsql_transaction::CompletedTransactionPageStorageRestartCheckpointReplay;
///
/// fn cannot_borrow_checkpoint_source<Source, Store, CheckpointSource, const N: usize>(
///     completed: &CompletedTransactionPageStorageRestartCheckpointReplay<
///         Source,
///         Store,
///         CheckpointSource,
///         N,
///     >,
/// ) -> &CheckpointSource {
///     completed.checkpoint_source()
/// }
/// ```
#[must_use = "completed selected restart owns all live adapters and startup evidence"]
pub struct CompletedTransactionPageStorageRestartCheckpointReplay<
    Source,
    Store,
    CheckpointSource,
    const N: usize,
> where
    Source: DurableTransactionRestartAnalysisSource<N>,
    Store: DurablePageStoreSnapshotSource<N>,
{
    coordinator: TransactionCoordinator,
    source: Source,
    store: Store,
    checkpoint_source: CheckpointSource,
    evidence: TransactionPageStorageRestartCheckpointCompletionEvidence<N>,
    validation: SelectedRestartCheckpointValidation<Source, Store, N>,
}

impl<Source, Store, CheckpointSource, const N: usize>
    CompletedTransactionPageStorageRestartCheckpointReplay<Source, Store, CheckpointSource, N>
where
    Source: DurableTransactionRestartAnalysisSource<N>,
    Store: DurablePageStoreSnapshotSource<N>,
{
    /// Returns the immutable selected-restart completion evidence.
    pub const fn completion_evidence(
        &self,
    ) -> &TransactionPageStorageRestartCheckpointCompletionEvidence<N> {
        &self.evidence
    }

    /// Borrows the exact coordinator, WAL source, and page store for inspection.
    #[must_use]
    pub const fn parts(&self) -> (&TransactionCoordinator, &Source, &Store) {
        (&self.coordinator, &self.source, &self.store)
    }

    /// Borrows the exact coordinator, WAL source, and page store for live work.
    pub const fn parts_mut(&mut self) -> (&mut TransactionCoordinator, &mut Source, &mut Store) {
        (&mut self.coordinator, &mut self.source, &mut self.store)
    }

    /// Releases all exact owners together with immutable selected-startup evidence.
    pub fn into_parts(
        self,
    ) -> (
        TransactionCoordinator,
        Source,
        Store,
        TransactionPageStorageRestartCheckpointCompletionEvidence<N>,
        CheckpointSource,
    ) {
        (
            self.coordinator,
            self.source,
            self.store,
            self.evidence,
            self.checkpoint_source,
        )
    }
}

impl<Source, Store, CheckpointSource, const N: usize>
    CompletedTransactionPageStorageRestartCheckpointReplay<Source, Store, CheckpointSource, N>
where
    Source: DurableTransactionRestartAnalysisSource<N>,
    Store: DurablePageStoreSnapshotSource<N>,
    CheckpointSource: DurableTransactionRestartCheckpointCompletenessBaselinePublisher,
{
    /// Publishes fresh current completeness through the retained checkpoint source.
    ///
    /// Publication is explicit and uses current live source/store state. It does
    /// not reuse or mutate the immutable selected-startup completion evidence.
    pub fn publish_restart_checkpoint_completeness_baseline_from_current_prefix(
        &mut self,
    ) -> DurableTransactionRestartCheckpointCompletenessBaselineCurrentPublicationResult<
        Source::Error,
        Store::ObservationError,
        CheckpointSource::Error,
    > {
        publish_restart_checkpoint_completeness_baseline_from_parts(
            &mut self.source,
            &self.store,
            &mut self.checkpoint_source,
        )
    }
}

impl<Source, Store, CheckpointSource, const N: usize> fmt::Debug
    for CompletedTransactionPageStorageRestartCheckpointReplay<Source, Store, CheckpointSource, N>
where
    Source: DurableTransactionRestartAnalysisSource<N>,
    Store: DurablePageStoreSnapshotSource<N>,
{
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        formatter
            .debug_struct("CompletedTransactionPageStorageRestartCheckpointReplay")
            .field("coordinator_epoch", &self.coordinator.epoch())
            .field("evidence", &self.evidence)
            .finish_non_exhaustive()
    }
}

/// Fail-closed finalization owner retaining the restored state and exact cause.
///
/// Finalization performs no write or allocation, so this state has no retry or
/// fallback. Drop and a complete reopen are required before another attempt.
///
/// ```compile_fail
/// use ntsql_transaction::{
///     DurablePageStoreSnapshotSource, DurableTransactionRestartAnalysisSource,
///     FailedTransactionPageStorageRestartCheckpointCompletion,
/// };
///
/// fn cannot_release_failed<Source, Store, CheckpointSource, const N: usize>(
///     failed: FailedTransactionPageStorageRestartCheckpointCompletion<
///         Source,
///         Store,
///         CheckpointSource,
///         N,
///     >,
/// )
/// where
///     Source: DurableTransactionRestartAnalysisSource<N>,
///     Store: DurablePageStoreSnapshotSource<N>,
/// {
///     let _ = failed.into_parts();
/// }
/// ```
///
/// ```compile_fail
/// use ntsql_transaction::{
///     DurablePageStoreSnapshotSource, DurableTransactionRestartAnalysisSource,
///     FailedTransactionPageStorageRestartCheckpointCompletion,
/// };
///
/// fn cannot_retry_failed<Source, Store, CheckpointSource, const N: usize>(
///     failed: FailedTransactionPageStorageRestartCheckpointCompletion<
///         Source,
///         Store,
///         CheckpointSource,
///         N,
///     >,
/// )
/// where
///     Source: DurableTransactionRestartAnalysisSource<N>,
///     Store: DurablePageStoreSnapshotSource<N>,
/// {
///     let _ = failed.retry();
/// }
/// ```
#[must_use = "failed selected restart completion retains all owners until dropped"]
pub struct FailedTransactionPageStorageRestartCheckpointCompletion<
    Source,
    Store,
    CheckpointSource,
    const N: usize,
> where
    Source: DurableTransactionRestartAnalysisSource<N>,
    Store: DurablePageStoreSnapshotSource<N>,
{
    restored: Box<
        RestoredTransactionPageStorageRestartCheckpointReplay<Source, Store, CheckpointSource, N>,
    >,
    error: TransactionPageStorageRestartCheckpointCompletionError<Source, Store, N>,
}

impl<Source, Store, CheckpointSource, const N: usize>
    FailedTransactionPageStorageRestartCheckpointCompletion<Source, Store, CheckpointSource, N>
where
    Source: DurableTransactionRestartAnalysisSource<N>,
    Store: DurablePageStoreSnapshotSource<N>,
{
    /// Returns the exact final validation failure without exposing any owner.
    #[must_use]
    pub const fn error(
        &self,
    ) -> &TransactionPageStorageRestartCheckpointCompletionError<Source, Store, N> {
        &self.error
    }

    /// Returns inert aggregate restoration evidence retained by the failed owner.
    pub const fn transaction_summary(&self) -> TransactionRestartRestorationSummary {
        self.restored.transaction_summary()
    }
}

impl<Source, Store, CheckpointSource, const N: usize> fmt::Debug
    for FailedTransactionPageStorageRestartCheckpointCompletion<Source, Store, CheckpointSource, N>
where
    Source: DurableTransactionRestartAnalysisSource<N>,
    Store: DurablePageStoreSnapshotSource<N>,
    TransactionPageStorageRestartCheckpointCompletionError<Source, Store, N>: fmt::Debug,
{
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        formatter
            .debug_struct("FailedTransactionPageStorageRestartCheckpointCompletion")
            .field("persistent_log_id", &self.restored.persistent_log_id())
            .field("error", &self.error)
            .finish_non_exhaustive()
    }
}

impl<Source, Store, CheckpointSource, const N: usize> fmt::Display
    for FailedTransactionPageStorageRestartCheckpointCompletion<Source, Store, CheckpointSource, N>
where
    Source: DurableTransactionRestartAnalysisSource<N>,
    Store: DurablePageStoreSnapshotSource<N>,
    TransactionPageStorageRestartCheckpointCompletionError<Source, Store, N>: fmt::Display,
{
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(
            formatter,
            "selected-checkpoint restart completion failed: {}",
            self.error
        )
    }
}

impl<Source, Store, CheckpointSource, const N: usize> Error
    for FailedTransactionPageStorageRestartCheckpointCompletion<Source, Store, CheckpointSource, N>
where
    Source: DurableTransactionRestartAnalysisSource<N> + 'static,
    Store: DurablePageStoreSnapshotSource<N> + 'static,
    CheckpointSource: 'static,
    TransactionPageStorageRestartCheckpointCompletionError<Source, Store, N>: Error + 'static,
{
    fn source(&self) -> Option<&(dyn Error + 'static)> {
        Some(&self.error)
    }
}

impl<Source, Store, CheckpointSource, const N: usize>
    RestoredTransactionPageStorageRestartCheckpointReplay<Source, Store, CheckpointSource, N>
where
    Source: DurableTransactionRestartAnalysisSource<N>,
    Store: DurablePageStoreSnapshotSource<N>,
{
    /// Revalidates logical WAL and every repaired page before releasing live access.
    ///
    /// The durable restart-epoch allocation frame is intentionally absent from the
    /// logical WAL projection. Finalization allocates no replacement coordinator,
    /// performs no write, and retains the complete restored owner on any failure.
    pub fn complete_restart(
        self,
    ) -> Result<
        CompletedTransactionPageStorageRestartCheckpointReplay<Source, Store, CheckpointSource, N>,
        FailedTransactionPageStorageRestartCheckpointCompletion<Source, Store, CheckpointSource, N>,
    > {
        complete_transaction_page_storage_restart_checkpoint_replay(self)
    }
}

/// Inert reason one logical WAL record remains required after selected restart.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum DurableTransactionRestartWalRetentionRequirementCause {
    /// The active selected checkpoint retains its exact frontier boundary.
    SelectedCheckpointFrontier,
    /// The selected checkpoint retains its inclusive replay lower bound.
    SelectedReplayStart {
        /// Evidence that established the selected replay lower bound.
        cause: DurableTransactionRestartReplayStartCause,
    },
    /// One exact current page-store snapshot requires its backing page record.
    StoredPage {
        /// Page whose current snapshot requires the record.
        page_number: PageNumber,
    },
    /// An unresolved durable transaction requires its first owned-page record.
    UnresolvedTransaction {
        /// Persisted unresolved transaction identity.
        transaction: DurableTransactionIdentityObservation,
    },
    /// Adapter format or migration metadata requires this logical record.
    SourceConstraint,
}

/// One exact inclusive logical-record requirement in a retention analysis.
#[derive(Debug)]
#[must_use]
pub struct DurableTransactionRestartWalRetentionRequirement {
    position: LogSequenceNumber,
    cause: DurableTransactionRestartWalRetentionRequirementCause,
}

impl DurableTransactionRestartWalRetentionRequirement {
    /// Returns the inert numeric position of the required logical record.
    #[must_use]
    pub const fn position(&self) -> u64 {
        self.position.get()
    }

    /// Returns the reason this record remains required.
    #[must_use]
    pub const fn cause(&self) -> DurableTransactionRestartWalRetentionRequirementCause {
        self.cause
    }
}

/// Opaque inclusive WAL retention floor, or an explicit no-record requirement.
///
/// ```compile_fail
/// use ntsql_transaction::DurableTransactionRestartWalRetentionFloor;
///
/// let forged = DurableTransactionRestartWalRetentionFloor {
///     retained_first_record: None,
/// };
/// ```
#[derive(Debug)]
#[must_use]
pub struct DurableTransactionRestartWalRetentionFloor {
    retained_first_record: Option<LogSequenceNumber>,
}

impl DurableTransactionRestartWalRetentionFloor {
    /// Returns the first logical record that must remain, or `None` when no
    /// logical record in the analyzed prefix is required.
    #[must_use]
    pub const fn retained_first_record(&self) -> Option<u64> {
        match &self.retained_first_record {
            Some(position) => Some(position.get()),
            None => None,
        }
    }
}

/// Immutable non-authorizing retention analysis for one completed restart.
///
/// The exact lineage-bound floor remains private. This value cannot become a
/// durability, truncation, replacement, page, checkpoint, or transaction
/// authority.
///
/// ```compile_fail
/// use ntsql_transaction::{
///     DurableTransactionRestartWalRetentionAnalysis,
///     DurableTransactionRestartWalRetentionFloor,
/// };
///
/// fn cannot_forge(
///     floor: DurableTransactionRestartWalRetentionFloor,
