fn restart_checkpoint_entry_matches_observation(
    expected: &DurableTransactionRestartCheckpointBaselineEntry,
    actual: DurableTransactionRestartCheckpointBaselineEntryObservation,
) -> bool {
    let expected_state_matches = match (expected.state(), actual.state()) {
        (
            DurableTransactionRestartCheckpointBaselineState::Uncommitted,
            DurableTransactionRestartCheckpointBaselineStateObservation::Uncommitted,
        ) => true,
        (
            DurableTransactionRestartCheckpointBaselineState::Committed {
                commit_position: expected,
            },
            DurableTransactionRestartCheckpointBaselineStateObservation::Committed {
                commit_position: actual,
            },
        ) => expected == actual,
        (
            DurableTransactionRestartCheckpointBaselineState::Uncommitted,
            DurableTransactionRestartCheckpointBaselineStateObservation::Committed { .. },
        )
        | (
            DurableTransactionRestartCheckpointBaselineState::Committed { .. },
            DurableTransactionRestartCheckpointBaselineStateObservation::Uncommitted,
        ) => false,
    };
    let expected_transaction = expected.transaction();
    expected_transaction.epoch() == actual.epoch()
        && expected_transaction.sequence() == actual.sequence()
        && expected.first_owned_page_position() == actual.first_owned_page_position()
        && expected.last_owned_page_position() == actual.last_owned_page_position()
        && expected.owned_page_record_count() == actual.owned_page_record_count()
        && expected_state_matches
}

fn compare_restart_checkpoint_baseline_observation(
    expected: DurableTransactionRestartCheckpointBaseline,
    actual: &DurableTransactionRestartCheckpointBaselineObservation<'_>,
) -> Result<
    DurableTransactionRestartCheckpointBaseline,
    DurableTransactionRestartCheckpointBaselineValidationEvidenceError,
> {
    if expected.durable_frontier() != actual.durable_frontier() {
        return Err(
            DurableTransactionRestartCheckpointBaselineValidationEvidenceError::DurableFrontierMismatch {
                expected: expected.durable_frontier(),
                actual: actual.durable_frontier(),
            },
        );
    }
    if expected.transactions().len() != actual.transactions().len() {
        return Err(
            DurableTransactionRestartCheckpointBaselineValidationEvidenceError::TransactionCountMismatch {
                expected: expected.transactions().len(),
                actual: actual.transactions().len(),
            },
        );
    }
    for (index, (expected_entry, actual_entry)) in expected
        .transactions()
        .iter()
        .zip(actual.transactions())
        .enumerate()
    {
        if !restart_checkpoint_entry_matches_observation(expected_entry, *actual_entry) {
            return Err(
                DurableTransactionRestartCheckpointBaselineValidationEvidenceError::TransactionEntryMismatch {
                    index,
                    expected: Box::new(expected_entry.clone()),
                    actual: *actual_entry,
                },
            );
        }
    }
    Ok(expected)
}

fn current_restart_prefix_error(
    source: DurableTransactionRestartAnalysisEvidenceError,
) -> DurableTransactionRestartCheckpointBaselineValidationEvidenceError {
    DurableTransactionRestartCheckpointBaselineValidationEvidenceError::CurrentPrefix(Box::new(
        source,
    ))
}

/// Exact selected WAL frontier and slice shared by both ADR 0039 validators.
///
/// `frontier`/`observations` are the exact window a decoded checkpoint claims,
/// independent of which validator (transaction-only or completeness) analyzes
/// it next. An empty decoded frontier always selects the canonical empty
/// window `(None, &[])`, regardless of the current WAL's actual length.
struct SelectedRestartCheckpointPrefix<'observations, const N: usize> {
    frontier: Option<LogSequenceNumber>,
    observations: &'observations [DurableTransactionRestartObservation<N>],
}

/// Selects the exact current-WAL window claimed by a decoded checkpoint frontier.
///
/// This is the shared ADR 0039 boundary logic: empty selection, current
/// absent/malformed rejection, future-frontier rejection, numeric-gap
/// detection (with full-current validation to distinguish a valid gap from a
/// malformed current stream), and exact-boundary selection. It performs no
/// transaction, page, or store analysis; callers analyze the returned window
/// with whichever authoritative analysis their validator requires.
fn select_restart_checkpoint_prefix<'observations, const N: usize>(
    lineage: &LogLineage,
    current_frontier: Option<&LogSequenceNumber>,
    observations: &'observations [DurableTransactionRestartObservation<N>],
    checkpoint_frontier: Option<u64>,
) -> Result<
    SelectedRestartCheckpointPrefix<'observations, N>,
    DurableTransactionRestartCheckpointBaselineValidationEvidenceError,
> {
    let Some(checkpoint_frontier) = checkpoint_frontier else {
        return Ok(SelectedRestartCheckpointPrefix {
            frontier: None,
            observations: &[],
        });
    };

    let current_frontier_value = match current_frontier {
        None if observations.is_empty() => {
            return Err(
                DurableTransactionRestartCheckpointBaselineValidationEvidenceError::CheckpointBeyondDurableFrontier {
                    checkpoint_frontier,
                    durable_frontier: None,
                },
            );
        }
        None => {
            let source = analyze_durable_transaction_restart_evidence(lineage, None, observations)
                .err()
                .ok_or(
                    DurableTransactionRestartCheckpointBaselineValidationEvidenceError::CheckpointBeyondDurableFrontier {
                        checkpoint_frontier,
                        durable_frontier: None,
                    },
                )?;
            return Err(current_restart_prefix_error(source));
        }
        Some(frontier) if !lineage.same_lineage(frontier.lineage()) => {
            return Err(current_restart_prefix_error(
                DurableTransactionRestartAnalysisEvidenceError::ForeignFrontier {
                    frontier: frontier.clone(),
                },
            ));
        }
        Some(frontier) if frontier.get() == 0 => {
            return Err(current_restart_prefix_error(
                DurableTransactionRestartAnalysisEvidenceError::ZeroFrontier {
                    frontier: frontier.clone(),
                },
            ));
        }
        Some(frontier) if observations.is_empty() => {
            return Err(current_restart_prefix_error(
                DurableTransactionRestartAnalysisEvidenceError::FrontierWithoutRecords {
                    frontier: frontier.clone(),
                },
            ));
        }
        Some(frontier) => frontier.get(),
    };

    if checkpoint_frontier > current_frontier_value {
        return Err(
            DurableTransactionRestartCheckpointBaselineValidationEvidenceError::CheckpointBeyondDurableFrontier {
                checkpoint_frontier,
                durable_frontier: Some(current_frontier_value),
            },
        );
    }

    let Some(boundary_index) = observations
        .iter()
        .position(|observation| observation.position().get() == checkpoint_frontier)
    else {
        match analyze_durable_transaction_restart_evidence(lineage, current_frontier, observations)
        {
            Ok(_) => {
                return Err(
                    DurableTransactionRestartCheckpointBaselineValidationEvidenceError::CheckpointFrontierNotRecordBoundary {
                        checkpoint_frontier,
                        durable_frontier: current_frontier_value,
                    },
                );
            }
            Err(source) => return Err(current_restart_prefix_error(source)),
        }
    };
    let selected_frontier = lineage.position(checkpoint_frontier);
    let selected = &observations[..=boundary_index];
    Ok(SelectedRestartCheckpointPrefix {
        frontier: Some(selected_frontier),
        observations: selected,
    })
}

fn validate_restart_checkpoint_baseline_evidence<const N: usize>(
    lineage: &LogLineage,
    current_frontier: Option<&LogSequenceNumber>,
    observations: &[DurableTransactionRestartObservation<N>],
    checkpoint: &DurableTransactionRestartCheckpointBaselineObservation<'_>,
) -> Result<
    DurableTransactionRestartCheckpointBaseline,
    DurableTransactionRestartCheckpointBaselineValidationEvidenceError,
> {
    let selected = select_restart_checkpoint_prefix(
        lineage,
        current_frontier,
        observations,
        checkpoint.durable_frontier(),
    )?;
    let analysis = analyze_durable_transaction_restart_evidence(
        lineage,
        selected.frontier.as_ref(),
        selected.observations,
    )
    .map_err(|source| {
        DurableTransactionRestartCheckpointBaselineValidationEvidenceError::SelectedPrefix(
            Box::new(source),
        )
    })?;
    let expected = prepare_restart_checkpoint_baseline(&analysis).map_err(
        DurableTransactionRestartCheckpointBaselineValidationEvidenceError::ExpectedBaselinePreparation,
    )?;
    compare_restart_checkpoint_baseline_observation(expected, checkpoint)
}

fn validate_restart_checkpoint_baseline_against_current_prefix<Source, const N: usize>(
    source: &mut Source,
    checkpoint: &DurableTransactionRestartCheckpointBaselineObservation<'_>,
) -> Result<
    DurableTransactionRestartCheckpointBaseline,
    DurableTransactionRestartCheckpointBaselineValidationError<Source::Error>,
>
where
    Source: DurableTransactionRestartAnalysisSource<N>,
{
    let lineage = source.lineage().clone();
    let Some(expected_id) = lineage.persistent_id() else {
        return Err(
            DurableTransactionRestartCheckpointBaselineValidationError::Evidence(Box::new(
                DurableTransactionRestartCheckpointBaselineValidationEvidenceError::CurrentPersistentLineageRequired,
            )),
        );
    };
    let Some(actual_id) = PersistentLogId::new(checkpoint.persistent_log_id()) else {
        return Err(
            DurableTransactionRestartCheckpointBaselineValidationError::Evidence(Box::new(
                DurableTransactionRestartCheckpointBaselineValidationEvidenceError::ZeroPersistentLogId {
                    persistent_log_id: checkpoint.persistent_log_id(),
                },
            )),
        );
    };
    if actual_id != expected_id {
        return Err(
            DurableTransactionRestartCheckpointBaselineValidationError::Evidence(Box::new(
                DurableTransactionRestartCheckpointBaselineValidationEvidenceError::ForeignPersistentLogId {
                    expected: expected_id,
                    actual: actual_id,
                },
            )),
        );
    }
    if checkpoint.durable_frontier() == Some(0) {
        return Err(
            DurableTransactionRestartCheckpointBaselineValidationError::Evidence(Box::new(
                DurableTransactionRestartCheckpointBaselineValidationEvidenceError::ZeroCheckpointFrontier {
                    checkpoint_frontier: 0,
                },
            )),
        );
    }

    match source.with_durable_transaction_restart_observations(|current_frontier, observations| {
        validate_restart_checkpoint_baseline_evidence(
            &lineage,
            current_frontier,
            observations,
            checkpoint,
        )
    }) {
        Ok(Ok(baseline)) => Ok(baseline),
        Ok(Err(source)) => Err(
            DurableTransactionRestartCheckpointBaselineValidationError::Evidence(Box::new(source)),
        ),
        Err(source) => {
            Err(DurableTransactionRestartCheckpointBaselineValidationError::Source(source))
        }
    }
}

fn restart_checkpoint_page_state_matches_observation(
    state: &DurableTransactionRestartPageState,
    observation: DurableTransactionRestartCheckpointCompletenessBaselinePageStateObservation,
) -> bool {
    matches!(
        (state, observation),
        (
            DurableTransactionRestartPageState::NoRequiredImage,
            DurableTransactionRestartCheckpointCompletenessBaselinePageStateObservation::NoRequiredImage,
        ) | (
            DurableTransactionRestartPageState::StoreMissing { .. },
            DurableTransactionRestartCheckpointCompletenessBaselinePageStateObservation::StoreMissing,
        ) | (
            DurableTransactionRestartPageState::StoreCurrent { .. },
            DurableTransactionRestartCheckpointCompletenessBaselinePageStateObservation::StoreCurrent,
        ) | (
            DurableTransactionRestartPageState::StoreBehind { .. },
            DurableTransactionRestartCheckpointCompletenessBaselinePageStateObservation::StoreBehind,
        )
    )
}

fn restart_checkpoint_required_image_matches_observation(
    expected: Option<&DurableTransactionRestartRequiredPageImage>,
    actual: Option<DurableTransactionRestartCheckpointCompletenessBaselineRequiredImageObservation>,
) -> bool {
    match (expected, actual) {
        (None, None) => true,
        (
            Some(DurableTransactionRestartRequiredPageImage::Raw { page_position }),
            Some(
                DurableTransactionRestartCheckpointCompletenessBaselineRequiredImageObservation::Raw {
                    page_position: actual_page_position,
                },
            ),
        ) => *page_position == actual_page_position,
        (
            Some(DurableTransactionRestartRequiredPageImage::CommittedTransaction {
                transaction,
                page_position,
                commit_position,
            }),
            Some(
                DurableTransactionRestartCheckpointCompletenessBaselineRequiredImageObservation::CommittedTransaction {
                    epoch,
                    sequence,
                    page_position: actual_page_position,
                    commit_position: actual_commit_position,
                },
            ),
        ) => {
            transaction.epoch() == epoch
                && transaction.sequence() == sequence
                && *page_position == actual_page_position
                && *commit_position == actual_commit_position
        }
        (None, Some(_))
        | (Some(DurableTransactionRestartRequiredPageImage::Raw { .. }), _)
        | (Some(DurableTransactionRestartRequiredPageImage::CommittedTransaction { .. }), _) => {
            false
        }
    }
}

fn restart_checkpoint_page_entry_matches_observation(
    expected: &DurableTransactionRestartPageEntry,
    actual: DurableTransactionRestartCheckpointCompletenessBaselinePageObservation,
) -> bool {
    expected.page_number().get() == actual.page_number()
        && restart_checkpoint_page_state_matches_observation(expected.state(), actual.state())
        && restart_checkpoint_required_image_matches_observation(
            expected.state().required_image(),
            actual.required_image(),
        )
        && expected.state().stored_position() == actual.stored_position()
}

fn restart_checkpoint_replay_cause_matches_observation(
    expected: Option<DurableTransactionRestartReplayStartCause>,
    actual: Option<DurableTransactionRestartCheckpointCompletenessBaselineReplayCauseObservation>,
) -> bool {
    match (expected, actual) {
        (None, None) => true,
        (
            Some(DurableTransactionRestartReplayStartCause::StoreMissing { page_number }),
            Some(
                DurableTransactionRestartCheckpointCompletenessBaselineReplayCauseObservation::StoreMissingPage {
                    page_number: actual_page_number,
                },
            ),
        ) => page_number.get() == actual_page_number,
        (
            Some(DurableTransactionRestartReplayStartCause::StoreBehind { page_number }),
            Some(
                DurableTransactionRestartCheckpointCompletenessBaselineReplayCauseObservation::StoreBehindPage {
                    page_number: actual_page_number,
                },
            ),
        ) => page_number.get() == actual_page_number,
        (
            Some(DurableTransactionRestartReplayStartCause::UncommittedTransaction {
                transaction,
            }),
            Some(
                DurableTransactionRestartCheckpointCompletenessBaselineReplayCauseObservation::UncommittedTransaction {
                    epoch,
                    sequence,
                },
            ),
        ) => transaction.epoch() == epoch && transaction.sequence() == sequence,
        (None, Some(_))
        | (Some(DurableTransactionRestartReplayStartCause::StoreMissing { .. }), _)
        | (Some(DurableTransactionRestartReplayStartCause::StoreBehind { .. }), _)
        | (Some(DurableTransactionRestartReplayStartCause::UncommittedTransaction { .. }), _) => {
            false
        }
    }
}

fn restart_checkpoint_replay_matches_observation(
    expected: &DurableTransactionRestartReplayStart,
    actual: DurableTransactionRestartCheckpointCompletenessBaselineReplayObservation,
) -> bool {
    let kind_matches = matches!(
        (expected, actual.kind()),
        (
            DurableTransactionRestartReplayStart::AfterFrontier { .. },
            DurableTransactionRestartCheckpointCompletenessBaselineReplayKindObservation::AfterFrontier,
        ) | (
            DurableTransactionRestartReplayStart::AtPosition { .. },
            DurableTransactionRestartCheckpointCompletenessBaselineReplayKindObservation::AtPosition,
        )
    );
    kind_matches
        && expected.frontier() == actual.frontier()
        && expected.position() == actual.position()
        && restart_checkpoint_replay_cause_matches_observation(expected.cause(), actual.cause())
}

fn compare_restart_checkpoint_completeness_baseline_observation<SourceError, StoreError>(
    expected: DurableTransactionRestartCheckpointCompletenessBaseline,
    actual: &DurableTransactionRestartCheckpointCompletenessBaselineObservation<'_>,
) -> Result<
    DurableTransactionRestartCheckpointCompletenessBaseline,
    DurableTransactionRestartCheckpointCompletenessBaselineValidationEvidenceError<
        SourceError,
        StoreError,
    >,
> {
    let _: DurableTransactionRestartCheckpointBaseline = compare_restart_checkpoint_baseline_observation(
        expected.transaction_baseline().clone(),
        &actual.transactions(),
    )
    .map_err(|source| {
        DurableTransactionRestartCheckpointCompletenessBaselineValidationEvidenceError::NestedTransaction(
            Box::new(source),
        )
    })?;

    if expected.pages().len() != actual.pages().len() {
        return Err(
            DurableTransactionRestartCheckpointCompletenessBaselineValidationEvidenceError::PageCountMismatch {
                expected: expected.pages().len(),
                actual: actual.pages().len(),
            },
        );
    }
    for (index, (expected_entry, actual_entry)) in
        expected.pages().iter().zip(actual.pages()).enumerate()
    {
        if !restart_checkpoint_page_entry_matches_observation(expected_entry, *actual_entry) {
            return Err(
                DurableTransactionRestartCheckpointCompletenessBaselineValidationEvidenceError::PageEntryMismatch {
                    index,
                    expected: Box::new(expected_entry.clone()),
                    actual: *actual_entry,
                },
            );
        }
    }

    if !restart_checkpoint_replay_matches_observation(expected.replay_start(), actual.replay()) {
        return Err(
            DurableTransactionRestartCheckpointCompletenessBaselineValidationEvidenceError::ReplayMismatch {
                expected: Box::new(expected.replay_start().clone()),
                actual: actual.replay(),
            },
        );
    }

    Ok(expected)
}

fn validate_restart_pruned_generation_metadata(
    lineage: &LogLineage,
    store_lineage: &LogLineage,
    metadata: &DurableTransactionRestartWalReclamationSourceObservation,
    checkpoint_frontier: Option<u64>,
) -> Result<(), DurableTransactionRestartPrunedGenerationSelectionEvidenceError> {
    if !lineage.same_lineage(store_lineage) {
        return Err(
            DurableTransactionRestartPrunedGenerationSelectionEvidenceError::StoreLineageMismatch {
                source_lineage: lineage.clone(),
                store_lineage: store_lineage.clone(),
            },
        );
    }
    if !lineage.same_lineage(metadata.lineage()) {
        return Err(
            DurableTransactionRestartPrunedGenerationSelectionEvidenceError::MetadataLineageMismatch {
                expected: lineage.clone(),
                actual: metadata.lineage().clone(),
            },
        );
    }
    if metadata.physical_format_version() == 0 {
        return Err(
            DurableTransactionRestartPrunedGenerationSelectionEvidenceError::ZeroPhysicalFormatVersion,
        );
    }
    for position in [
        metadata.retained_first_logical_record(),
        metadata.logical_position_high_water(),
    ]
    .into_iter()
    .flatten()
    {
        if !lineage.same_lineage(position.lineage()) {
            return Err(
                DurableTransactionRestartPrunedGenerationSelectionEvidenceError::ForeignMetadataPosition {
                    position: position.clone(),
                },
            );
        }
        if position.get() == 0 {
            return Err(
                DurableTransactionRestartPrunedGenerationSelectionEvidenceError::ZeroMetadataPosition {
                    position: position.clone(),
                },
            );
        }
    }
    let retained_first = metadata
        .retained_first_logical_record()
        .map(LogSequenceNumber::get);
    let logical_high_water = metadata
        .logical_position_high_water()
        .map(LogSequenceNumber::get);
    match (retained_first, logical_high_water) {
        (Some(retained_first), None) => {
            return Err(
                DurableTransactionRestartPrunedGenerationSelectionEvidenceError::RetainedBoundaryWithoutHighWater {
                    retained_first,
                },
            );
        }
        (Some(retained_first), Some(logical_high_water)) if retained_first > logical_high_water => {
            return Err(
                DurableTransactionRestartPrunedGenerationSelectionEvidenceError::RetainedBoundaryBeyondHighWater {
                    retained_first,
                    logical_high_water,
                },
            );
        }
        (None, None) | (None, Some(_)) | (Some(_), Some(_)) => {}
    }
    match (
        metadata.source_generation(),
        metadata.selected_checkpoint_anchor,
    ) {
        (0, Some(actual)) => {
            return Err(
                DurableTransactionRestartPrunedGenerationSelectionEvidenceError::LegacyGenerationHasAnchor {
                    actual,
                },
            );
        }
        (0, None) | (_, Some(_)) => {}
        (generation, None) => {
            return Err(
                DurableTransactionRestartPrunedGenerationSelectionEvidenceError::PrunedGenerationMissingAnchor {
                    generation,
                },
            );
        }
    }
    if let Some(checkpoint_frontier) = checkpoint_frontier {
        if checkpoint_frontier == 0 {
            return Err(
                DurableTransactionRestartPrunedGenerationSelectionEvidenceError::ZeroCheckpointFrontier,
            );
        }
        if logical_high_water.is_none_or(|high_water| checkpoint_frontier > high_water) {
            return Err(
                DurableTransactionRestartPrunedGenerationSelectionEvidenceError::CheckpointBeyondLogicalHighWater {
                    checkpoint_frontier,
                    logical_high_water,
                },
            );
        }
        if let Some(retained_first) = retained_first
            && retained_first > checkpoint_frontier
        {
            return Err(
                DurableTransactionRestartPrunedGenerationSelectionEvidenceError::RetainedBoundaryAfterCheckpointFrontier {
                    retained_first,
                    checkpoint_frontier,
                },
            );
        }
    }
    Ok(())
}

fn anchored_checkpoint_position_is_bounded(position: u64, frontier: Option<u64>) -> bool {
    position != 0 && frontier.is_some_and(|frontier| position <= frontier)
}

fn materialize_anchored_restart_checkpoint_required_image(
    index: usize,
    checkpoint_frontier: Option<u64>,
    transactions: &[DurableTransactionRestartCheckpointBaselineEntry],
    observation: DurableTransactionRestartCheckpointCompletenessBaselineRequiredImageObservation,
) -> Result<
    DurableTransactionRestartRequiredPageImage,
    DurableTransactionRestartPrunedGenerationSelectionEvidenceError,
> {
    let page_position = observation.page_position();
    if !anchored_checkpoint_position_is_bounded(page_position, checkpoint_frontier) {
        return Err(
            DurableTransactionRestartPrunedGenerationSelectionEvidenceError::PagePositionOutOfBounds {
                index,
                field: DurableTransactionRestartAnchoredCheckpointPagePositionField::RequiredImage,
                position: page_position,
                checkpoint_frontier,
            },
        );
    }
    match observation {
        DurableTransactionRestartCheckpointCompletenessBaselineRequiredImageObservation::Raw {
            page_position,
        } => Ok(DurableTransactionRestartRequiredPageImage::Raw { page_position }),
        DurableTransactionRestartCheckpointCompletenessBaselineRequiredImageObservation::CommittedTransaction {
            epoch,
            sequence,
            page_position,
            commit_position,
        } => {
            if !anchored_checkpoint_position_is_bounded(commit_position, checkpoint_frontier) {
                return Err(
                    DurableTransactionRestartPrunedGenerationSelectionEvidenceError::PagePositionOutOfBounds {
                        index,
                        field: DurableTransactionRestartAnchoredCheckpointPagePositionField::RequiredImageCommit,
                        position: commit_position,
                        checkpoint_frontier,
                    },
                );
            }
            let transaction =
                DurableTransactionIdentityObservation::new(epoch, sequence).map_err(|source| {
                    DurableTransactionRestartPrunedGenerationSelectionEvidenceError::InvalidTransactionIdentity {
                        index,
                        source,
                    }
                })?;
            let Ok(transaction_index) = transactions
                .binary_search_by_key(&transaction, DurableTransactionRestartCheckpointBaselineEntry::transaction)
            else {
                return Err(
                    DurableTransactionRestartPrunedGenerationSelectionEvidenceError::CommittedImageTransactionMissing {
                        index,
                        transaction,
                    },
                );
            };
            let transaction_entry = &transactions[transaction_index];
            let range_contains_page = match (
                transaction_entry.first_owned_page_position(),
                transaction_entry.last_owned_page_position(),
            ) {
                (Some(first), Some(last)) => first <= page_position && page_position <= last,
                (None, None) | (None, Some(_)) | (Some(_), None) => false,
            };
            if transaction_entry.state().commit_position() != Some(commit_position)
                || !range_contains_page
                || page_position >= commit_position
            {
                return Err(
                    DurableTransactionRestartPrunedGenerationSelectionEvidenceError::CommittedImageTransactionMismatch {
                        index,
                        transaction,
                        page_position,
                        commit_position,
                    },
                );
            }
            Ok(
                DurableTransactionRestartRequiredPageImage::CommittedTransaction {
                    transaction,
                    page_position,
                    commit_position,
                },
            )
        }
    }
}

fn materialize_anchored_restart_checkpoint(
    lineage: &LogLineage,
    metadata: &DurableTransactionRestartWalReclamationSourceObservation,
    checkpoint: &DurableTransactionRestartCheckpointCompletenessBaselineObservation<'_>,
) -> Result<
    DurableTransactionRestartCheckpointCompletenessBaseline,
    DurableTransactionRestartPrunedGenerationSelectionEvidenceError,
> {
    let expected_id = lineage.persistent_id().ok_or(
        DurableTransactionRestartPrunedGenerationSelectionEvidenceError::PersistentLineageRequired,
    )?;
    let transaction_observation = checkpoint.transactions();
    let Some(actual_id) = PersistentLogId::new(transaction_observation.persistent_log_id()) else {
        return Err(
            DurableTransactionRestartPrunedGenerationSelectionEvidenceError::ZeroPersistentLogId {
                persistent_log_id: transaction_observation.persistent_log_id(),
            },
        );
    };
    if actual_id != expected_id {
        return Err(
            DurableTransactionRestartPrunedGenerationSelectionEvidenceError::ForeignPersistentLogId {
                expected: expected_id,
                actual: actual_id,
            },
        );
    }
    let checkpoint_frontier = transaction_observation.durable_frontier();
    if checkpoint_frontier == Some(0) {
        return Err(
            DurableTransactionRestartPrunedGenerationSelectionEvidenceError::ZeroCheckpointFrontier,
        );
    }

    let mut transactions = Vec::new();
    transactions
        .try_reserve_exact(transaction_observation.transactions().len())
        .map_err(|_| {
            DurableTransactionRestartPrunedGenerationSelectionEvidenceError::TransactionCapacityExhausted {
                transaction_count: transaction_observation.transactions().len(),
            }
        })?;
    let mut previous_transaction = None;
    for (index, observation) in transaction_observation
        .transactions()
        .iter()
        .copied()
        .enumerate()
    {
        let transaction =
            DurableTransactionIdentityObservation::new(observation.epoch(), observation.sequence())
                .map_err(|source| {
                    DurableTransactionRestartPrunedGenerationSelectionEvidenceError::InvalidTransactionIdentity {
                        index,
                        source,
                    }
                })?;
        if let Some(previous) = previous_transaction
            && transaction <= previous
        {
            return Err(
                DurableTransactionRestartPrunedGenerationSelectionEvidenceError::TransactionIdentityNotIncreasing {
                    index,
                    previous,
                    actual: transaction,
                },
            );
        }
        if transaction.epoch() > metadata.allocated_epoch_high_water().get() {
            return Err(
                DurableTransactionRestartPrunedGenerationSelectionEvidenceError::AllocatorHighWaterBelowTransaction {
                    transaction,
                    allocated_epoch_high_water: metadata.allocated_epoch_high_water().get(),
                },
            );
        }
        previous_transaction = Some(transaction);

        let first = observation.first_owned_page_position();
        let last = observation.last_owned_page_position();
        let count = observation.owned_page_record_count();
        let range_count_is_possible = match (first, last, count) {
            (None, None, 0) => true,
            (Some(first), Some(last), 1) => first == last,
            (Some(first), Some(last), count) if count > 1 => {
                first < last && u128::from(count) <= u128::from(last) - u128::from(first) + 1
            }
            (None, None, _) | (None, Some(_), _) | (Some(_), None, _) | (Some(_), Some(_), _) => {
                false
            }
        };
        if !range_count_is_possible {
            return Err(
                DurableTransactionRestartPrunedGenerationSelectionEvidenceError::TransactionOwnedPageShape {
                    index,
                    first,
                    last,
                    count,
                },
            );
        }
        for (field, position) in [
            (
                DurableTransactionRestartAnchoredCheckpointTransactionPositionField::FirstOwnedPage,
                first,
            ),
            (
                DurableTransactionRestartAnchoredCheckpointTransactionPositionField::LastOwnedPage,
                last,
            ),
        ] {
            if let Some(position) = position
                && !anchored_checkpoint_position_is_bounded(position, checkpoint_frontier)
            {
                return Err(
                    DurableTransactionRestartPrunedGenerationSelectionEvidenceError::TransactionPositionOutOfBounds {
                        index,
                        field,
                        position,
                        checkpoint_frontier,
                    },
                );
            }
        }
        let state = match observation.state() {
            DurableTransactionRestartCheckpointBaselineStateObservation::Uncommitted => {
                if count == 0 {
                    return Err(
                        DurableTransactionRestartPrunedGenerationSelectionEvidenceError::UncommittedTransactionWithoutOwnedPage {
                            index,
                            transaction,
                        },
                    );
                }
                DurableTransactionRestartCheckpointBaselineState::Uncommitted
            }
            DurableTransactionRestartCheckpointBaselineStateObservation::Committed {
                commit_position,
            } => {
                if !anchored_checkpoint_position_is_bounded(commit_position, checkpoint_frontier) {
                    return Err(
                        DurableTransactionRestartPrunedGenerationSelectionEvidenceError::TransactionPositionOutOfBounds {
                            index,
                            field: DurableTransactionRestartAnchoredCheckpointTransactionPositionField::Commit,
                            position: commit_position,
                            checkpoint_frontier,
                        },
                    );
                }
                if let Some(last_owned_page_position) = last
                    && commit_position <= last_owned_page_position
                {
                    return Err(
                        DurableTransactionRestartPrunedGenerationSelectionEvidenceError::TransactionCommitNotAfterOwnedPages {
                            index,
                            last_owned_page_position,
                            commit_position,
                        },
                    );
                }
                DurableTransactionRestartCheckpointBaselineState::Committed { commit_position }
            }
        };
        transactions.push(DurableTransactionRestartCheckpointBaselineEntry {
            transaction,
            first_owned_page_position: first,
            last_owned_page_position: last,
            owned_page_record_count: count,
            state,
        });
    }

    let mut pages = Vec::new();
    pages
        .try_reserve_exact(checkpoint.pages().len())
        .map_err(|_| {
            DurableTransactionRestartPrunedGenerationSelectionEvidenceError::PageCapacityExhausted {
                page_count: checkpoint.pages().len(),
            }
        })?;
    let mut previous_page = None;
    for (index, observation) in checkpoint.pages().iter().copied().enumerate() {
        let Some(page_number) = PageNumber::new(observation.page_number()) else {
            return Err(
                DurableTransactionRestartPrunedGenerationSelectionEvidenceError::ZeroPageNumber {
                    index,
                },
            );
        };
        if let Some(previous) = previous_page
            && page_number <= previous
        {
            return Err(
                DurableTransactionRestartPrunedGenerationSelectionEvidenceError::PageNumberNotIncreasing {
                    index,
                    previous,
                    actual: page_number,
                },
            );
        }
        previous_page = Some(page_number);

        let required_observation = observation.required_image();
        let stored_position = observation.stored_position();
        let valid_shape = matches!(
            (
                observation.state(),
                required_observation,
                stored_position,
            ),
            (
                DurableTransactionRestartCheckpointCompletenessBaselinePageStateObservation::NoRequiredImage,
                None,
                None,
            ) | (
                DurableTransactionRestartCheckpointCompletenessBaselinePageStateObservation::StoreMissing,
                Some(_),
                None,
            ) | (
                DurableTransactionRestartCheckpointCompletenessBaselinePageStateObservation::StoreCurrent
                    | DurableTransactionRestartCheckpointCompletenessBaselinePageStateObservation::StoreBehind,
                Some(_),
                Some(_),
            )
        );
        if !valid_shape {
            return Err(
                DurableTransactionRestartPrunedGenerationSelectionEvidenceError::PageStateShape {
                    index,
                    actual: observation,
                },
            );
        }
        let required = required_observation
            .map(|required| {
                materialize_anchored_restart_checkpoint_required_image(
                    index,
                    checkpoint_frontier,
                    &transactions,
                    required,
                )
            })
            .transpose()?;
        if let Some(stored_position) = stored_position
            && !anchored_checkpoint_position_is_bounded(stored_position, checkpoint_frontier)
        {
            return Err(
                DurableTransactionRestartPrunedGenerationSelectionEvidenceError::PagePositionOutOfBounds {
                    index,
                    field: DurableTransactionRestartAnchoredCheckpointPagePositionField::StoredImage,
                    position: stored_position,
                    checkpoint_frontier,
                },
            );
        }
        let state = match (observation.state(), required, stored_position) {
            (
                DurableTransactionRestartCheckpointCompletenessBaselinePageStateObservation::NoRequiredImage,
                None,
                None,
            ) => DurableTransactionRestartPageState::NoRequiredImage,
            (
                DurableTransactionRestartCheckpointCompletenessBaselinePageStateObservation::StoreMissing,
                Some(required),
                None,
            ) => DurableTransactionRestartPageState::StoreMissing { required },
            (
                DurableTransactionRestartCheckpointCompletenessBaselinePageStateObservation::StoreCurrent,
                Some(required),
                Some(stored_position),
            ) if stored_position == required.page_position() => {
                DurableTransactionRestartPageState::StoreCurrent {
                    required,
                    stored_position,
                }
            }
            (
                DurableTransactionRestartCheckpointCompletenessBaselinePageStateObservation::StoreBehind,
                Some(required),
                Some(stored_position),
            ) if stored_position < required.page_position() => {
                DurableTransactionRestartPageState::StoreBehind {
                    stored_position,
                    required,
                }
            }
            (
                DurableTransactionRestartCheckpointCompletenessBaselinePageStateObservation::StoreBehind,
                Some(required),
                Some(stored_position),
            ) => {
                return Err(
                    DurableTransactionRestartPrunedGenerationSelectionEvidenceError::StoreBehindNotBeforeRequiredImage {
                        index,
                        stored_position,
                        required_position: required.page_position(),
                    },
                );
            }
            (
                DurableTransactionRestartCheckpointCompletenessBaselinePageStateObservation::StoreCurrent,
                _,
                _,
            )
            | (
                DurableTransactionRestartCheckpointCompletenessBaselinePageStateObservation::NoRequiredImage,
                _,
                _,
            )
            | (
                DurableTransactionRestartCheckpointCompletenessBaselinePageStateObservation::StoreMissing,
                _,
                _,
            )
            | (
                DurableTransactionRestartCheckpointCompletenessBaselinePageStateObservation::StoreBehind,
                _,
                _,
            ) => {
                return Err(
                    DurableTransactionRestartPrunedGenerationSelectionEvidenceError::PageStateShape {
                        index,
                        actual: observation,
                    },
                );
            }
        };
        pages.push(DurableTransactionRestartPageEntry { page_number, state });
    }

    let mut replay_floor = None;
    for transaction in &transactions {
        if matches!(
            transaction.state(),
            DurableTransactionRestartCheckpointBaselineState::Uncommitted
        ) {
            let Some(position) = transaction.first_owned_page_position() else {
                return Err(
                    DurableTransactionRestartPrunedGenerationSelectionEvidenceError::UncommittedTransactionWithoutOwnedPage {
                        index: 0,
                        transaction: transaction.transaction(),
                    },
                );
            };
            lower_restart_replay_start(
                &mut replay_floor,
                position,
                DurableTransactionRestartReplayStartCause::UncommittedTransaction {
                    transaction: transaction.transaction(),
                },
            );
        }
    }
    for page in &pages {
        match page.state() {
            DurableTransactionRestartPageState::StoreMissing { required } => {
                lower_restart_replay_start(
                    &mut replay_floor,
                    required.page_position(),
                    DurableTransactionRestartReplayStartCause::StoreMissing {
                        page_number: page.page_number(),
                    },
                );
            }
            DurableTransactionRestartPageState::StoreBehind { required, .. } => {
                lower_restart_replay_start(
                    &mut replay_floor,
                    required.page_position(),
                    DurableTransactionRestartReplayStartCause::StoreBehind {
                        page_number: page.page_number(),
                    },
                );
            }
            DurableTransactionRestartPageState::NoRequiredImage
            | DurableTransactionRestartPageState::StoreCurrent { .. } => {}
        }
    }
    let replay_start = match replay_floor {
        Some((position, cause)) => {
            DurableTransactionRestartReplayStart::AtPosition { position, cause }
        }
        None => DurableTransactionRestartReplayStart::AfterFrontier {
            frontier: checkpoint_frontier,
        },
    };
    if !restart_checkpoint_replay_matches_observation(&replay_start, checkpoint.replay()) {
        return Err(
            DurableTransactionRestartPrunedGenerationSelectionEvidenceError::ReplayShapeMismatch {
                expected: Box::new(replay_start),
                actual: checkpoint.replay(),
            },
        );
    }
    let baseline = DurableTransactionRestartCheckpointCompletenessBaseline {
        transaction_baseline: DurableTransactionRestartCheckpointBaseline {
            persistent_log_id: expected_id,
            durable_frontier: checkpoint_frontier,
            transactions,
        },
        pages,
        replay_start,
    };
    let expected_anchor = selected_restart_checkpoint_anchor(&baseline);
    if metadata.selected_checkpoint_anchor != Some(expected_anchor) {
        return Err(
            DurableTransactionRestartPrunedGenerationSelectionEvidenceError::SelectedCheckpointAnchorMismatch {
                expected: expected_anchor,
                actual: metadata.selected_checkpoint_anchor,
            },
        );
    }
    Ok(baseline)
}

fn derive_restart_checkpoint_completeness_baseline_evidence<SourceError, Store, const N: usize>(
    lineage: &LogLineage,
    current_frontier: Option<&LogSequenceNumber>,
    observations: &[DurableTransactionRestartObservation<N>],
    store: &Store,
    checkpoint_frontier: Option<u64>,
) -> Result<
    DurableTransactionRestartCheckpointCompletenessBaseline,
    DurableTransactionRestartCheckpointCompletenessBaselineValidationEvidenceError<
        SourceError,
        Store::ObservationError,
    >,
>
where
    Store: DurablePageStoreSnapshotSource<N>,
{
    let selected = select_restart_checkpoint_prefix(
        lineage,
        current_frontier,
        observations,
        checkpoint_frontier,
    )
    .map_err(|source| {
        DurableTransactionRestartCheckpointCompletenessBaselineValidationEvidenceError::Baseline(
            Box::new(source),
        )
    })?;

    let analysis = analyze_durable_transaction_restart_completeness_evidence::<SourceError, Store, N>(
        lineage,
        selected.frontier.as_ref(),
        selected.observations,
        store,
    )
    .map_err(|source| {
        DurableTransactionRestartCheckpointCompletenessBaselineValidationEvidenceError::CompletenessEvidence(
            Box::new(source),
        )
    })?;

    let expected = prepare_restart_checkpoint_completeness_baseline(analysis).map_err(
        DurableTransactionRestartCheckpointCompletenessBaselineValidationEvidenceError::BaselinePreparation,
    )?;

    Ok(expected)
}

fn validate_restart_checkpoint_completeness_baseline_evidence<SourceError, Store, const N: usize>(
    lineage: &LogLineage,
    current_frontier: Option<&LogSequenceNumber>,
    observations: &[DurableTransactionRestartObservation<N>],
    store: &Store,
    checkpoint: &DurableTransactionRestartCheckpointCompletenessBaselineObservation<'_>,
) -> Result<
    DurableTransactionRestartCheckpointCompletenessBaseline,
    DurableTransactionRestartCheckpointCompletenessBaselineValidationEvidenceError<
        SourceError,
        Store::ObservationError,
    >,
>
where
    Store: DurablePageStoreSnapshotSource<N>,
{
    let expected = derive_restart_checkpoint_completeness_baseline_evidence::<SourceError, Store, N>(
        lineage,
        current_frontier,
        observations,
        store,
        checkpoint.transactions().durable_frontier(),
    )?;

    compare_restart_checkpoint_completeness_baseline_observation(expected, checkpoint)
}

struct MaterializedTransactionRestartCheckpointReplay<const N: usize> {
    current_analysis: DurableTransactionRestartAnalysis,
    replay_observations: Vec<OwnedDurableTransactionRestartReplayObservation<N>>,
    retained_observations: Vec<OwnedDurableTransactionRestartReplayObservation<N>>,
}

fn select_restart_checkpoint_replay_window<'observations, const N: usize>(
    observations: &'observations [DurableTransactionRestartObservation<N>],
    replay_start: &DurableTransactionRestartReplayStart,
) -> Result<
    &'observations [DurableTransactionRestartObservation<N>],
    DurableTransactionRestartCheckpointReplayWindowError,
> {
    match replay_start {
        DurableTransactionRestartReplayStart::AtPosition { position, .. } => {
            let Some(index) = observations
                .iter()
                .position(|observation| observation.position().get() == *position)
            else {
                return Err(
                    DurableTransactionRestartCheckpointReplayWindowError::InclusiveStartNotRecordBoundary {
                        position: *position,
                    },
                );
            };
            observations.get(index..).ok_or(
                DurableTransactionRestartCheckpointReplayWindowError::InclusiveStartNotRecordBoundary {
                    position: *position,
                },
            )
        }
        DurableTransactionRestartReplayStart::AfterFrontier { frontier: None } => Ok(observations),
        DurableTransactionRestartReplayStart::AfterFrontier {
            frontier: Some(frontier),
        } => {
            let Some(index) = observations
                .iter()
                .position(|observation| observation.position().get() == *frontier)
            else {
                return Err(
                    DurableTransactionRestartCheckpointReplayWindowError::CheckpointFrontierNotRecordBoundary {
                        frontier: *frontier,
                    },
                );
            };
            let Some(start_index) = index.checked_add(1) else {
                return Err(
                    DurableTransactionRestartCheckpointReplayWindowError::CheckpointFrontierNotRecordBoundary {
                        frontier: *frontier,
                    },
                );
            };
            observations.get(start_index..).ok_or(
                DurableTransactionRestartCheckpointReplayWindowError::CheckpointFrontierNotRecordBoundary {
                    frontier: *frontier,
                },
            )
        }
    }
}

fn reserve_restart_checkpoint_replay_observations<const N: usize>(
    replay_observations: &mut Vec<OwnedDurableTransactionRestartReplayObservation<N>>,
    record_count: usize,
) -> Result<(), DurableTransactionRestartCheckpointReplayWindowError> {
    replay_observations
        .try_reserve_exact(record_count)
        .map_err(
            |_| DurableTransactionRestartCheckpointReplayWindowError::CapacityExhausted {
                record_count,
            },
        )
}

fn plan_selected_restart_checkpoint_replay_evidence<SourceError, Store, const N: usize>(
    lineage: &LogLineage,
    current_frontier: Option<&LogSequenceNumber>,
    observations: &[DurableTransactionRestartObservation<N>],
    store: &Store,
    baseline: &DurableTransactionRestartCheckpointCompletenessBaseline,
) -> Result<
    MaterializedTransactionRestartCheckpointReplay<N>,
    DurableTransactionRestartCheckpointReplayPlanningEvidenceError<
        SourceError,
        Store::ObservationError,
    >,
>
where
    Store: DurablePageStoreSnapshotSource<N>,
{
    let rederived =
        derive_restart_checkpoint_completeness_baseline_evidence::<SourceError, Store, N>(
            lineage,
            current_frontier,
            observations,
            store,
            baseline.durable_frontier(),
        )
        .map_err(|source| {
            DurableTransactionRestartCheckpointReplayPlanningEvidenceError::CheckpointRevalidation(
                Box::new(source),
            )
        })?;
    if rederived != *baseline {
        return Err(
            DurableTransactionRestartCheckpointReplayPlanningEvidenceError::SelectedBaselineMismatch(
                DurableTransactionRestartCheckpointReplayBaselineMismatch {
                    rederived: Box::new(rederived),
                },
            ),
        );
    }

    let current_analysis =
        analyze_durable_transaction_restart_evidence(lineage, current_frontier, observations)
            .map_err(|source| {
                DurableTransactionRestartCheckpointReplayPlanningEvidenceError::CurrentAnalysis(
                    Box::new(source),
                )
            })?;

    let replay_window =
        select_restart_checkpoint_replay_window(observations, baseline.replay_start()).map_err(
            DurableTransactionRestartCheckpointReplayPlanningEvidenceError::ReplayWindow,
        )?;
    let mut replay_observations = Vec::new();
    reserve_restart_checkpoint_replay_observations(&mut replay_observations, replay_window.len())
        .map_err(DurableTransactionRestartCheckpointReplayPlanningEvidenceError::ReplayWindow)?;
    replay_observations.extend(
        replay_window
            .iter()
            .map(OwnedDurableTransactionRestartReplayObservation::from),
    );

    Ok(MaterializedTransactionRestartCheckpointReplay {
        current_analysis,
        replay_observations,
        retained_observations: Vec::new(),
    })
}

fn plan_selected_restart_checkpoint_replay<Source, Store, const N: usize>(
    source: &mut Source,
    store: &Store,
    baseline: &DurableTransactionRestartCheckpointCompletenessBaseline,
) -> Result<
    MaterializedTransactionRestartCheckpointReplay<N>,
    DurableTransactionRestartCheckpointReplayPlanningError<Source::Error, Store::ObservationError>,
>
where
    Source: DurableTransactionRestartAnalysisSource<N>,
    Store: DurablePageStoreSnapshotSource<N>,
{
    let lineage = source.lineage().clone();
    let store_lineage = store.lineage().clone();
    if !lineage.same_lineage(&store_lineage) {
        return Err(
            DurableTransactionRestartCheckpointReplayPlanningError::LineageMismatch {
                source_lineage: lineage,
                store_lineage,
            },
        );
    }

    match source.with_durable_transaction_restart_observations(|current_frontier, observations| {
        plan_selected_restart_checkpoint_replay_evidence::<Source::Error, Store, N>(
            &lineage,
            current_frontier,
            observations,
            store,
            baseline,
        )
    }) {
        Ok(Ok(plan)) => Ok(plan),
        Ok(Err(source)) => {
            Err(DurableTransactionRestartCheckpointReplayPlanningError::Evidence(Box::new(source)))
        }
        Err(source) => Err(DurableTransactionRestartCheckpointReplayPlanningError::Source(source)),
    }
}

fn seed_anchored_restart_transaction_analysis(
    lineage: &LogLineage,
    logical_high_water: Option<&LogSequenceNumber>,
    baseline: &DurableTransactionRestartCheckpointCompletenessBaseline,
    retained_record_count: usize,
) -> Result<DurableTransactionRestartAnalysis, DurableTransactionRestartRetainedSuffixEvidenceError>
{
    let mut transactions = Vec::new();
    transactions
        .try_reserve_exact(baseline.transactions().len())
        .map_err(|_| {
            DurableTransactionRestartRetainedSuffixEvidenceError::TransactionCapacityExhausted {
                transaction_count: baseline.transactions().len(),
            }
        })?;
    for entry in baseline.transactions() {
        let transaction = entry.transaction();
        let owned_page_record_count =
            usize::try_from(entry.owned_page_record_count()).map_err(|_| {
                DurableTransactionRestartRetainedSuffixEvidenceError::OwnedPageCountWidthExceeded {
                    transaction,
                    record_count: entry.owned_page_record_count(),
                }
            })?;
        let state = match entry.state() {
            DurableTransactionRestartCheckpointBaselineState::Uncommitted => {
                DurableTransactionRestartState::Uncommitted
            }
            DurableTransactionRestartCheckpointBaselineState::Committed { commit_position } => {
                DurableTransactionRestartState::Committed {
                    commit_position: lineage.position(commit_position),
                }
            }
        };
        transactions.push(DurableTransactionRestartEntry {
            transaction,
            first_owned_page_position: entry
                .first_owned_page_position()
                .map(|position| lineage.position(position)),
            last_owned_page_position: entry
                .last_owned_page_position()
                .map(|position| lineage.position(position)),
            owned_page_record_count,
            state,
        });
    }
    transactions
        .try_reserve(retained_record_count)
        .map_err(|_| {
            DurableTransactionRestartRetainedSuffixEvidenceError::TransactionCapacityExhausted {
                transaction_count: baseline.transactions().len(),
            }
        })?;
    Ok(DurableTransactionRestartAnalysis {
        lineage: lineage.clone(),
        durable_frontier: logical_high_water.cloned(),
        transactions,
    })
}

fn validate_retained_restart_suffix_order<const N: usize>(
    lineage: &LogLineage,
    metadata: &DurableTransactionRestartWalReclamationSourceObservation,
    observations: &[DurableTransactionRestartObservation<N>],
    checkpoint_frontier: Option<u64>,
) -> Result<(), DurableTransactionRestartRetainedSuffixEvidenceError> {
    let retained_first = metadata
        .retained_first_logical_record()
        .map(LogSequenceNumber::get);
    match (retained_first, observations.first()) {
        (None, Some(_)) => {
            return Err(
                DurableTransactionRestartRetainedSuffixEvidenceError::RetainedBoundaryMissing {
                    record_count: observations.len(),
                },
            );
        }
        (Some(retained_first), None) => {
            return Err(
                DurableTransactionRestartRetainedSuffixEvidenceError::RetainedBoundaryWithoutObservations {
                    retained_first,
                },
            );
        }
        (Some(expected), Some(first)) if first.position().get() != expected => {
            return Err(
                DurableTransactionRestartRetainedSuffixEvidenceError::RetainedFirstMismatch {
                    expected,
                    actual: first.position().get(),
                },
            );
        }
        (None, None) | (Some(_), Some(_)) => {}
    }

    let high_water = metadata
        .logical_position_high_water()
        .map(LogSequenceNumber::get);
    match (high_water, observations.last()) {
        (None, Some(_)) => {
            return Err(
                DurableTransactionRestartRetainedSuffixEvidenceError::LogicalHighWaterMissing {
                    record_count: observations.len(),
                },
            );
        }
        (Some(expected), Some(tail)) if tail.position().get() != expected => {
            return Err(
                DurableTransactionRestartRetainedSuffixEvidenceError::RetainedTailMismatch {
                    expected,
                    actual: tail.position().get(),
                },
            );
        }
        (None, None) | (Some(_), None) | (Some(_), Some(_)) => {}
    }

    let mut previous = None;
    for (index, observation) in observations.iter().enumerate() {
        let position = observation.position();
        if !lineage.same_lineage(position.lineage()) {
            return Err(
                DurableTransactionRestartRetainedSuffixEvidenceError::ForeignRecordLineage {
                    index,
                    kind: observation.kind(),
                    position: position.clone(),
                },
            );
        }
        if position.get() == 0 {
            return Err(
                DurableTransactionRestartRetainedSuffixEvidenceError::ZeroRecordPosition {
                    index,
                    kind: observation.kind(),
                },
            );
        }
        let transaction = match observation {
            DurableTransactionRestartObservation::Page(_) => None,
            DurableTransactionRestartObservation::TransactionPage(observation) => {
                Some(observation.owner())
            }
            DurableTransactionRestartObservation::Commit(observation) => {
                Some(observation.transaction())
            }
        };
        if let Some(transaction) = transaction
            && transaction.epoch() > metadata.allocated_epoch_high_water().get()
        {
            return Err(
                DurableTransactionRestartRetainedSuffixEvidenceError::AllocatorHighWaterBelowTransaction {
                    transaction,
                    allocated_epoch_high_water: metadata.allocated_epoch_high_water().get(),
                },
            );
        }
        if let Some((previous_index, previous_position)) = previous {
            if position.get() == previous_position {
                return Err(
                    DurableTransactionRestartRetainedSuffixEvidenceError::DuplicateRecordPosition {
                        previous_index,
                        actual_index: index,
                        position: position.get(),
                    },
                );
            }
            if position.get() < previous_position {
                return Err(
                    DurableTransactionRestartRetainedSuffixEvidenceError::NonAdvancingRecordPosition {
                        previous_index,
                        previous: previous_position,
                        actual_index: index,
                        actual: position.get(),
                    },
                );
            }
        }
        previous = Some((index, position.get()));
    }
    if let Some(checkpoint_frontier) = checkpoint_frontier
        && observations
            .binary_search_by_key(&checkpoint_frontier, |observation| {
                observation.position().get()
            })
            .is_err()
    {
        return Err(
            DurableTransactionRestartRetainedSuffixEvidenceError::CheckpointFrontierNotRetained {
                checkpoint_frontier,
            },
        );
    }
    Ok(())
}

fn validate_retained_checkpoint_transaction_page(
    analysis: &DurableTransactionRestartAnalysis,
    transaction: DurableTransactionIdentityObservation,
    page_position: u64,
) -> Result<(), DurableTransactionRestartRetainedSuffixEvidenceError> {
    let Ok(index) = analysis
        .transactions
        .binary_search_by_key(&transaction, |entry| entry.transaction)
    else {
        return Err(
            DurableTransactionRestartRetainedSuffixEvidenceError::CheckpointTransactionPageMismatch {
                transaction,
                page_position,
            },
        );
    };
    let entry = &analysis.transactions[index];
    let in_range = match (
        entry.first_owned_page_position.as_ref(),
        entry.last_owned_page_position.as_ref(),
    ) {
        (Some(first), Some(last)) => first.get() <= page_position && page_position <= last.get(),
        (None, None) | (None, Some(_)) | (Some(_), None) => false,
    };
    if !in_range {
        return Err(
            DurableTransactionRestartRetainedSuffixEvidenceError::CheckpointTransactionPageMismatch {
                transaction,
                page_position,
            },
        );
    }
    Ok(())
}

fn validate_retained_checkpoint_commit(
    analysis: &DurableTransactionRestartAnalysis,
    transaction: DurableTransactionIdentityObservation,
    commit_position: u64,
) -> Result<(), DurableTransactionRestartRetainedSuffixEvidenceError> {
    let matches = analysis
        .transactions
        .binary_search_by_key(&transaction, |entry| entry.transaction)
        .ok()
        .and_then(|index| analysis.transactions.get(index))
        .and_then(|entry| entry.state().commit_position())
        .is_some_and(|position| position.get() == commit_position);
    if !matches {
        return Err(
            DurableTransactionRestartRetainedSuffixEvidenceError::CheckpointCommitMismatch {
                transaction,
                commit_position,
            },
        );
    }
    Ok(())
}

fn apply_retained_restart_suffix<const N: usize>(
    analysis: &mut DurableTransactionRestartAnalysis,
    baseline: &DurableTransactionRestartCheckpointCompletenessBaseline,
    observations: &[DurableTransactionRestartObservation<N>],
) -> Result<(), DurableTransactionRestartRetainedSuffixEvidenceError> {
    let checkpoint_frontier = baseline.durable_frontier();
    for observation in observations {
        let position = observation.position().get();
        let after_checkpoint = checkpoint_frontier.is_none_or(|frontier| position > frontier);
        match observation {
            DurableTransactionRestartObservation::Page(_) => {}
            DurableTransactionRestartObservation::TransactionPage(observation)
                if !after_checkpoint =>
            {
                validate_retained_checkpoint_transaction_page(
                    analysis,
                    observation.owner(),
                    position,
                )?;
            }
            DurableTransactionRestartObservation::Commit(observation) if !after_checkpoint => {
                validate_retained_checkpoint_commit(analysis, observation.transaction(), position)?;
            }
            DurableTransactionRestartObservation::TransactionPage(observation) => {
                let transaction = observation.owner();
                match analysis
                    .transactions
                    .binary_search_by_key(&transaction, |entry| entry.transaction)
                {
                    Ok(index) => {
                        let entry = &mut analysis.transactions[index];
                        if let DurableTransactionRestartState::Committed { commit_position } =
                            &entry.state
                        {
                            return Err(
                                DurableTransactionRestartRetainedSuffixEvidenceError::PageAfterCommit {
                                    transaction,
                                    commit_position: commit_position.get(),
                                    page_position: position,
                                },
                            );
                        }
                        entry.owned_page_record_count = entry
                            .owned_page_record_count
                            .checked_add(1)
                            .ok_or(
                                DurableTransactionRestartRetainedSuffixEvidenceError::OwnedPageCountExhausted {
                                    transaction,
                                },
                            )?;
                        entry.last_owned_page_position = Some(observation.position().clone());
                    }
                    Err(index) => analysis.transactions.insert(
                        index,
                        DurableTransactionRestartEntry {
                            transaction,
                            first_owned_page_position: Some(observation.position().clone()),
                            last_owned_page_position: Some(observation.position().clone()),
                            owned_page_record_count: 1,
                            state: DurableTransactionRestartState::Uncommitted,
                        },
                    ),
                }
            }
            DurableTransactionRestartObservation::Commit(observation) => {
                let transaction = observation.transaction();
                match analysis
                    .transactions
                    .binary_search_by_key(&transaction, |entry| entry.transaction)
                {
                    Ok(index) => {
                        let entry = &mut analysis.transactions[index];
                        match &entry.state {
                            DurableTransactionRestartState::Uncommitted => {
                                entry.state = DurableTransactionRestartState::Committed {
                                    commit_position: observation.position().clone(),
                                };
                            }
                            DurableTransactionRestartState::Committed {
                                commit_position: first_commit_position,
                            } => {
                                return Err(
                                    DurableTransactionRestartRetainedSuffixEvidenceError::DuplicateCommit {
                                        transaction,
                                        first_commit_position: first_commit_position.get(),
                                        duplicate_commit_position: position,
                                    },
                                );
                            }
                        }
                    }
                    Err(index) => analysis.transactions.insert(
                        index,
                        DurableTransactionRestartEntry {
                            transaction,
                            first_owned_page_position: None,
                            last_owned_page_position: None,
                            owned_page_record_count: 0,
                            state: DurableTransactionRestartState::Committed {
                                commit_position: observation.position().clone(),
                            },
                        },
                    ),
                }
            }
        }
    }
    Ok(())
}

fn plan_anchored_restart_checkpoint_replay_evidence<const N: usize>(
    lineage: &LogLineage,
    metadata: &DurableTransactionRestartWalReclamationSourceObservation,
    observations: &[DurableTransactionRestartObservation<N>],
    baseline: &DurableTransactionRestartCheckpointCompletenessBaseline,
) -> Result<
    MaterializedTransactionRestartCheckpointReplay<N>,
    DurableTransactionRestartRetainedSuffixEvidenceError,
> {
    validate_retained_restart_suffix_order(
        lineage,
        metadata,
        observations,
        baseline.durable_frontier(),
    )?;
    let mut current_analysis = seed_anchored_restart_transaction_analysis(
        lineage,
        metadata.logical_position_high_water(),
        baseline,
        observations.len(),
    )?;
    apply_retained_restart_suffix(&mut current_analysis, baseline, observations)?;

    let replay_window =
        select_restart_checkpoint_replay_window(observations, baseline.replay_start())
            .map_err(DurableTransactionRestartRetainedSuffixEvidenceError::ReplayWindow)?;
    let mut replay_observations = Vec::new();
    reserve_restart_checkpoint_replay_observations(&mut replay_observations, replay_window.len())
        .map_err(DurableTransactionRestartRetainedSuffixEvidenceError::ReplayWindow)?;
    replay_observations.extend(
        replay_window
            .iter()
            .map(OwnedDurableTransactionRestartReplayObservation::from),
    );
    let mut retained_observations = Vec::new();
    reserve_restart_checkpoint_replay_observations(&mut retained_observations, observations.len())
        .map_err(DurableTransactionRestartRetainedSuffixEvidenceError::ReplayWindow)?;
    retained_observations.extend(
        observations
            .iter()
            .map(OwnedDurableTransactionRestartReplayObservation::from),
    );
    Ok(MaterializedTransactionRestartCheckpointReplay {
        current_analysis,
        replay_observations,
        retained_observations,
    })
}

fn validate_anchored_restart_planning_metadata(
    lineage: &LogLineage,
    store_lineage: &LogLineage,
    metadata: &DurableTransactionRestartWalReclamationSourceObservation,
    baseline: &DurableTransactionRestartCheckpointCompletenessBaseline,
) -> Result<(), DurableTransactionRestartPrunedGenerationSelectionEvidenceError> {
    validate_restart_pruned_generation_metadata(
        lineage,
        store_lineage,
        metadata,
        baseline.durable_frontier(),
    )?;
    let expected = selected_restart_checkpoint_anchor(baseline);
    if metadata.source_generation() == 0 || metadata.selected_checkpoint_anchor != Some(expected) {
        return Err(
            DurableTransactionRestartPrunedGenerationSelectionEvidenceError::SelectedCheckpointAnchorMismatch {
                expected,
                actual: metadata.selected_checkpoint_anchor,
            },
        );
    }
    for entry in baseline.transactions() {
        if entry.transaction().epoch() > metadata.allocated_epoch_high_water().get() {
            return Err(
                DurableTransactionRestartPrunedGenerationSelectionEvidenceError::AllocatorHighWaterBelowTransaction {
                    transaction: entry.transaction(),
                    allocated_epoch_high_water: metadata.allocated_epoch_high_water().get(),
                },
            );
        }
    }
    Ok(())
}

fn plan_anchored_restart_checkpoint_replay<Source, Store, const N: usize>(
    source: &mut Source,
    store: &Store,
    baseline: &DurableTransactionRestartCheckpointCompletenessBaseline,
) -> Result<
    MaterializedTransactionRestartCheckpointReplay<N>,
    DurableTransactionRestartCheckpointReplayPlanningError<
        <Source as DurableTransactionRestartAnalysisSource<N>>::Error,
        Store::ObservationError,
    >,
>
where
    Source: DurableTransactionRestartPrunedGenerationSource<N>,
    Store: DurablePageStoreSnapshotSource<N>,
{
    let lineage = source.lineage().clone();
    let store_lineage = store.lineage().clone();
    let metadata = source
        .observe_restart_pruned_generation()
        .map_err(DurableTransactionRestartCheckpointReplayPlanningError::Source)?;
    validate_anchored_restart_planning_metadata(&lineage, &store_lineage, &metadata, baseline)
        .map_err(|source| {
            DurableTransactionRestartCheckpointReplayPlanningError::Evidence(Box::new(
                DurableTransactionRestartCheckpointReplayPlanningEvidenceError::PrunedGeneration(
                    Box::new(source),
                ),
            ))
        })?;

    let planned = source.with_durable_transaction_restart_retained_observations(|observations| {
        plan_anchored_restart_checkpoint_replay_evidence(
            &lineage,
            &metadata,
            observations,
            baseline,
        )
    });
    let planned =
        planned.map_err(DurableTransactionRestartCheckpointReplayPlanningError::Source)?;
    let reobserved = source
        .observe_restart_pruned_generation()
        .map_err(DurableTransactionRestartCheckpointReplayPlanningError::Source)?;
    if !restart_wal_reclamation_source_observations_match(&metadata, &reobserved) {
        return Err(
            DurableTransactionRestartCheckpointReplayPlanningError::Evidence(Box::new(
                DurableTransactionRestartCheckpointReplayPlanningEvidenceError::PrunedGenerationMetadataChanged {
                    expected: Box::new(metadata),
                    actual: Box::new(reobserved),
                },
            )),
        );
    }
    planned.map_err(|source| {
        DurableTransactionRestartCheckpointReplayPlanningError::Evidence(Box::new(
            DurableTransactionRestartCheckpointReplayPlanningEvidenceError::RetainedSuffix(
                Box::new(source),
            ),
        ))
    })
}

fn reserve_restart_checkpoint_repair_page_inventory(
    page_numbers: &mut Vec<PageNumber>,
    record_count: usize,
) -> Result<(), DurableTransactionRestartCheckpointRepairPreparationEvidenceError> {
    page_numbers.try_reserve_exact(record_count).map_err(|_| {
        DurableTransactionRestartCheckpointRepairPreparationEvidenceError::PageInventoryCapacityExhausted {
            record_count,
        }
    })
}

fn reserve_restart_checkpoint_repair_decisions<const N: usize>(
    page_repairs: &mut Vec<PreparedTransactionRestartCheckpointPageRepair<N>>,
    page_count: usize,
) -> Result<(), DurableTransactionRestartCheckpointRepairPreparationEvidenceError> {
    page_repairs.try_reserve_exact(page_count).map_err(|_| {
        DurableTransactionRestartCheckpointRepairPreparationEvidenceError::DecisionCapacityExhausted {
            page_count,
        }
    })
}

fn current_restart_transaction<'analysis>(
    analysis: &'analysis DurableTransactionRestartAnalysis,
    transaction: DurableTransactionIdentityObservation,
    page_position: &LogSequenceNumber,
) -> Result<
    &'analysis DurableTransactionRestartEntry,
    DurableTransactionRestartCheckpointRepairPreparationEvidenceError,
> {
    analysis
        .transactions()
        .binary_search_by_key(&transaction, DurableTransactionRestartEntry::transaction)
        .map(|index| &analysis.transactions()[index])
        .map_err(|_| {
            DurableTransactionRestartCheckpointRepairPreparationEvidenceError::CurrentTransactionMissing {
                transaction,
                page_position: page_position.clone(),
            }
        })
}

fn owned_replay_observation_position<const N: usize>(
    observation: &OwnedDurableTransactionRestartReplayObservation<N>,
) -> &LogSequenceNumber {
    match observation {
        OwnedDurableTransactionRestartReplayObservation::Page { position, .. }
        | OwnedDurableTransactionRestartReplayObservation::TransactionPage { position, .. }
        | OwnedDurableTransactionRestartReplayObservation::Commit { position, .. } => position,
    }
}

fn owned_replay_observation_at_position<const N: usize>(
    replay_observations: &[OwnedDurableTransactionRestartReplayObservation<N>],
    position: u64,
) -> Option<(usize, &OwnedDurableTransactionRestartReplayObservation<N>)> {
    replay_observations
        .binary_search_by_key(&position, |observation| {
            owned_replay_observation_position(observation).get()
        })
        .ok()
        .and_then(|index| {
            replay_observations
                .get(index)
                .map(|observation| (index, observation))
        })
}

fn prepared_replay_page_target<const N: usize>(
    observation_index: usize,
    observation: &OwnedDurableTransactionRestartReplayObservation<N>,
    replay_observations: &[OwnedDurableTransactionRestartReplayObservation<N>],
    analysis: &DurableTransactionRestartAnalysis,
) -> Result<
    Option<DurableTransactionRestartCheckpointPageRepairTarget<N>>,
    DurableTransactionRestartCheckpointRepairPreparationEvidenceError,
> {
    match observation {
        OwnedDurableTransactionRestartReplayObservation::Page {
            page_number,
            page_version,
            bytes,
            position,
        } => Ok(Some(DurableTransactionRestartCheckpointPageRepairTarget {
            kind: DurableTransactionRestartCheckpointPageRepairTargetKind::Raw,
            page_number: *page_number,
            page_version: *page_version,
            bytes: *bytes,
            page_position: position.clone(),
        })),
        OwnedDurableTransactionRestartReplayObservation::TransactionPage {
            transaction,
            page_number,
            page_version,
            bytes,
            position,
        } => {
            let entry = current_restart_transaction(analysis, *transaction, position)?;
            match entry.state() {
                DurableTransactionRestartState::Uncommitted => Ok(None),
                DurableTransactionRestartState::Committed { commit_position } => {
                    let matching_later_commit = matches!(
                        owned_replay_observation_at_position(
                            replay_observations,
                            commit_position.get(),
                        ),
                        Some((
                            commit_index,
                            OwnedDurableTransactionRestartReplayObservation::Commit {
                                transaction: actual_transaction,
                                position: actual_position,
                            },
                        )) if commit_index > observation_index
                            && *actual_transaction == *transaction
                            && actual_position == commit_position
                    );
                    if !matching_later_commit {
                        return Err(
                            DurableTransactionRestartCheckpointRepairPreparationEvidenceError::CommittedReplayRecordMissing {
                                transaction: *transaction,
                                page_position: position.clone(),
                                commit_position: commit_position.clone(),
                            },
                        );
                    }
                    Ok(Some(
                        DurableTransactionRestartCheckpointPageRepairTarget {
                            kind: DurableTransactionRestartCheckpointPageRepairTargetKind::CommittedTransaction {
                                transaction: *transaction,
                                commit_position: commit_position.clone(),
                            },
                            page_number: *page_number,
                            page_version: *page_version,
                            bytes: *bytes,
                            page_position: position.clone(),
                        },
                    ))
                }
            }
        }
        OwnedDurableTransactionRestartReplayObservation::Commit { .. } => Ok(None),
    }
}

fn dirty_checkpoint_required_image_is_owned<const N: usize>(
    page_number: PageNumber,
    required: &DurableTransactionRestartRequiredPageImage,
    replay_observations: &[OwnedDurableTransactionRestartReplayObservation<N>],
    analysis: &DurableTransactionRestartAnalysis,
) -> Result<bool, DurableTransactionRestartCheckpointRepairPreparationEvidenceError> {
    let Some((observation_index, observation)) =
        owned_replay_observation_at_position(replay_observations, required.page_position())
    else {
        return Ok(false);
    };
    match (required, observation) {
        (
            DurableTransactionRestartRequiredPageImage::Raw { .. },
            OwnedDurableTransactionRestartReplayObservation::Page {
                page_number: actual_page,
                ..
            },
        ) => Ok(*actual_page == page_number),
        (
            DurableTransactionRestartRequiredPageImage::CommittedTransaction {
                transaction,
                commit_position,
                ..
            },
            OwnedDurableTransactionRestartReplayObservation::TransactionPage {
                transaction: actual_transaction,
                page_number: actual_page,
                ..
            },
        ) if *actual_transaction == *transaction && *actual_page == page_number => Ok(matches!(
            prepared_replay_page_target(
                observation_index,
                observation,
                replay_observations,
                analysis,
            )?,
            Some(DurableTransactionRestartCheckpointPageRepairTarget {
                kind:
                    DurableTransactionRestartCheckpointPageRepairTargetKind::CommittedTransaction {
                        transaction: target_transaction,
                        commit_position: target_commit,
                    },
                ..
            }) if target_transaction == *transaction
                && target_commit.get() == *commit_position
        )),
        _ => Ok(false),
    }
}

fn selected_checkpoint_page_entry(
    baseline: &DurableTransactionRestartCheckpointCompletenessBaseline,
    page_number: PageNumber,
) -> Option<&DurableTransactionRestartPageEntry> {
    baseline
        .pages()
        .binary_search_by_key(
            &page_number,
            DurableTransactionRestartPageEntry::page_number,
        )
        .ok()
        .map(|index| &baseline.pages()[index])
}

fn validate_owned_dirty_checkpoint_images<const N: usize>(
    baseline: &DurableTransactionRestartCheckpointCompletenessBaseline,
    replay_observations: &[OwnedDurableTransactionRestartReplayObservation<N>],
    analysis: &DurableTransactionRestartAnalysis,
) -> Result<(), DurableTransactionRestartCheckpointRepairPreparationEvidenceError> {
    for entry in baseline.pages() {
        let required = match entry.state() {
            DurableTransactionRestartPageState::StoreMissing { required }
            | DurableTransactionRestartPageState::StoreBehind { required, .. } => required,
            DurableTransactionRestartPageState::NoRequiredImage
            | DurableTransactionRestartPageState::StoreCurrent { .. } => continue,
        };
        if !dirty_checkpoint_required_image_is_owned(
            entry.page_number(),
            required,
            replay_observations,
            analysis,
        )? {
            return Err(
                DurableTransactionRestartCheckpointRepairPreparationEvidenceError::DirtyCheckpointRequiredImageMissing {
                    page_number: entry.page_number(),
                    page_position: required.page_position(),
                },
            );
        }
    }
    Ok(())
}

fn combine_restart_checkpoint_page_repair_evidence<const N: usize>(
    repair: &mut PreparedTransactionRestartCheckpointPageRepair<N>,
    baseline: &DurableTransactionRestartCheckpointCompletenessBaseline,
) {
    let page_number = repair.page_number;
    let mut target = repair.target.take();
    let checkpoint = selected_checkpoint_page_entry(baseline, page_number);

    let (source_expectation, unchanged_checkpoint_current) = match checkpoint
        .map(DurableTransactionRestartPageEntry::state)
    {
        None => (
            PreparedTransactionRestartCheckpointPageSourceExpectation::SuffixOnly,
            false,
        ),
        Some(DurableTransactionRestartPageState::NoRequiredImage) => (
            PreparedTransactionRestartCheckpointPageSourceExpectation::MissingAtCheckpoint,
            false,
        ),
        Some(DurableTransactionRestartPageState::StoreMissing { .. }) => (
            PreparedTransactionRestartCheckpointPageSourceExpectation::MissingAtCheckpoint,
            false,
        ),
        Some(DurableTransactionRestartPageState::StoreCurrent {
            required,
            stored_position,
        }) => {
            let unchanged = target
                .as_ref()
                .is_none_or(|candidate| candidate.page_position.get() <= required.page_position());
            if unchanged {
                target = None;
            }
            (
                PreparedTransactionRestartCheckpointPageSourceExpectation::ExactCheckpointSnapshot {
                    position: *stored_position,
                },
                unchanged,
            )
        }
        Some(DurableTransactionRestartPageState::StoreBehind {
            stored_position, ..
        }) => (
            PreparedTransactionRestartCheckpointPageSourceExpectation::ExactCheckpointSnapshot {
                position: *stored_position,
            },
            false,
        ),
    };

    repair.source_expectation = source_expectation;
    repair.target = target;
    repair.unchanged_checkpoint_current = unchanged_checkpoint_current;
}

fn owned_replay_page_at_position<'replay, const N: usize>(
    page_number: PageNumber,
    position: &LogSequenceNumber,
    replay_observations: &'replay [OwnedDurableTransactionRestartReplayObservation<N>],
) -> Option<(
    usize,
    &'replay OwnedDurableTransactionRestartReplayObservation<N>,
)> {
    owned_replay_observation_at_position(replay_observations, position.get()).and_then(
        |(index, observation)| {
            matches!(
                observation,
                OwnedDurableTransactionRestartReplayObservation::Page {
                    page_number: actual_page,
                    position: actual_position,
                    ..
                }
                    | OwnedDurableTransactionRestartReplayObservation::TransactionPage {
                        page_number: actual_page,
                        position: actual_position,
                        ..
                    } if *actual_page == page_number && actual_position == position
            )
            .then_some((index, observation))
        },
    )
}

fn validate_replay_backed_snapshot<const N: usize>(
    snapshot: &StoredPageSnapshotObservation<N>,
    replay_observations: &[OwnedDurableTransactionRestartReplayObservation<N>],
    analysis: &DurableTransactionRestartAnalysis,
) -> Result<(), DurableTransactionRestartCheckpointRepairPreparationEvidenceError> {
    let page_number = snapshot.page_number();
    let Some((observation_index, observation)) = owned_replay_page_at_position(
        page_number,
        snapshot.required_position(),
        replay_observations,
    ) else {
        return Err(
            DurableTransactionRestartCheckpointRepairPreparationEvidenceError::SuffixSnapshotRecordMissing {
                page_number,
                position: snapshot.required_position().clone(),
            },
        );
    };

    match observation {
        OwnedDurableTransactionRestartReplayObservation::Page {
            page_version,
            bytes,
            ..
        } => {
            if snapshot.page_version() != *page_version || snapshot.image().bytes() != bytes {
                return Err(
                    DurableTransactionRestartCheckpointRepairPreparationEvidenceError::SnapshotPayloadContradiction {
                        page_number,
                        position: snapshot.required_position().clone(),
                    },
                );
            }
        }
        OwnedDurableTransactionRestartReplayObservation::TransactionPage {
            transaction,
            page_version,
            bytes,
            position,
            ..
        } => {
            if snapshot.page_version() != *page_version || snapshot.image().bytes() != bytes {
                return Err(
                    DurableTransactionRestartCheckpointRepairPreparationEvidenceError::SnapshotPayloadContradiction {
                        page_number,
                        position: snapshot.required_position().clone(),
                    },
                );
            }
            if prepared_replay_page_target(
                observation_index,
                observation,
                replay_observations,
                analysis,
            )?
            .is_none()
            {
                return Err(
                    DurableTransactionRestartCheckpointRepairPreparationEvidenceError::SnapshotBackedByUncommittedTransaction {
                        page_number,
                        transaction: *transaction,
                        page_position: position.clone(),
                    },
                );
            }
        }
        OwnedDurableTransactionRestartReplayObservation::Commit { .. } => {
            return Err(
                DurableTransactionRestartCheckpointRepairPreparationEvidenceError::SuffixSnapshotRecordMissing {
                    page_number,
                    position: snapshot.required_position().clone(),
                },
            );
        }
    }
    Ok(())
}

fn snapshot_matches_prepared_repair_target<const N: usize>(
    snapshot: &StoredPageSnapshotObservation<N>,
    target: &DurableTransactionRestartCheckpointPageRepairTarget<N>,
) -> bool {
    snapshot.page_number() == target.page_number
        && snapshot.required_position() == &target.page_position
        && snapshot.page_version() == target.page_version
        && snapshot.image().bytes() == &target.bytes
}

fn validate_prepared_snapshot_identity<const N: usize>(
    lineage: &LogLineage,
    page_number: PageNumber,
    snapshot: &StoredPageSnapshotObservation<N>,
) -> Result<(), DurableTransactionRestartCheckpointRepairPreparationEvidenceError> {
    if snapshot.page_number() != page_number {
        return Err(
            DurableTransactionRestartCheckpointRepairPreparationEvidenceError::UnexpectedSnapshotPage {
                expected: page_number,
                actual: snapshot.page_number(),
                position: snapshot.required_position().clone(),
            },
        );
    }
    if !lineage.same_lineage(snapshot.required_position().lineage()) {
        return Err(
            DurableTransactionRestartCheckpointRepairPreparationEvidenceError::ForeignSnapshotLineage {
                page_number,
                position: snapshot.required_position().clone(),
            },
        );
    }
    Ok(())
}

fn resolve_prepared_restart_checkpoint_page_repair<const N: usize>(
    lineage: &LogLineage,
    repair: &mut PreparedTransactionRestartCheckpointPageRepair<N>,
    snapshot: Option<StoredPageSnapshotObservation<N>>,
    replay_observations: &[OwnedDurableTransactionRestartReplayObservation<N>],
    analysis: &DurableTransactionRestartAnalysis,
) -> Result<(), DurableTransactionRestartCheckpointRepairPreparationEvidenceError> {
    if let Some(snapshot) = snapshot.as_ref() {
        validate_prepared_snapshot_identity(lineage, repair.page_number, snapshot)?;
    }

    match &repair.source_expectation {
        PreparedTransactionRestartCheckpointPageSourceExpectation::MissingAtCheckpoint => {
            if snapshot.is_some() {
                return Err(
                    DurableTransactionRestartCheckpointRepairPreparationEvidenceError::CheckpointSourceChanged {
                        page_number: repair.page_number,
                        expected_position: None,
                        actual_position: snapshot
                            .as_ref()
                            .map(|source| source.required_position().get()),
                    },
                );
            }
        }
        PreparedTransactionRestartCheckpointPageSourceExpectation::ExactCheckpointSnapshot {
            position,
        } => {
            if snapshot
                .as_ref()
                .map(|source| source.required_position().get())
                != Some(*position)
            {
                return Err(
                    DurableTransactionRestartCheckpointRepairPreparationEvidenceError::CheckpointSourceChanged {
                        page_number: repair.page_number,
                        expected_position: Some(*position),
                        actual_position: snapshot
                            .as_ref()
                            .map(|source| source.required_position().get()),
                    },
                );
            }
        }
        PreparedTransactionRestartCheckpointPageSourceExpectation::SuffixOnly => {}
    }

    if repair.unchanged_checkpoint_current {
        let Some(snapshot) = snapshot else {
            return Err(
                DurableTransactionRestartCheckpointRepairPreparationEvidenceError::CheckpointSourceChanged {
                    page_number: repair.page_number,
                    expected_position: match repair.source_expectation {
                        PreparedTransactionRestartCheckpointPageSourceExpectation::ExactCheckpointSnapshot {
                            position,
                        } => Some(position),
                        PreparedTransactionRestartCheckpointPageSourceExpectation::SuffixOnly
                        | PreparedTransactionRestartCheckpointPageSourceExpectation::MissingAtCheckpoint => None,
                    },
                    actual_position: None,
                },
            );
        };
        if owned_replay_page_at_position(
            repair.page_number,
            snapshot.required_position(),
            replay_observations,
        )
        .is_some()
        {
            validate_replay_backed_snapshot(&snapshot, replay_observations, analysis)?;
        }
        repair.resolution =
            PreparedTransactionRestartCheckpointPageRepairResolution::CheckpointCurrent(snapshot);
        return Ok(());
    }

    let Some(target) = repair.target.as_ref() else {
        if let Some(snapshot) = snapshot {
            validate_replay_backed_snapshot(&snapshot, replay_observations, analysis)?;
            return Err(
                DurableTransactionRestartCheckpointRepairPreparationEvidenceError::EligibleReplayTargetMissing {
                    page_number: repair.page_number,
                    position: snapshot.required_position().clone(),
                },
            );
        }
        repair.resolution =
            PreparedTransactionRestartCheckpointPageRepairResolution::NoRequiredImage;
        return Ok(());
    };

    let Some(snapshot) = snapshot else {
        repair.resolution =
            PreparedTransactionRestartCheckpointPageRepairResolution::Candidate(None);
        return Ok(());
    };
    if snapshot.required_position() == &target.page_position {
        if !snapshot_matches_prepared_repair_target(&snapshot, target) {
            return Err(
                DurableTransactionRestartCheckpointRepairPreparationEvidenceError::SnapshotPayloadContradiction {
                    page_number: repair.page_number,
                    position: snapshot.required_position().clone(),
                },
            );
        }
        repair.resolution =
            PreparedTransactionRestartCheckpointPageRepairResolution::AlreadyCurrent(snapshot);
        return Ok(());
    }
    if snapshot.required_position().get() > target.page_position.get() {
        return Err(
            DurableTransactionRestartCheckpointRepairPreparationEvidenceError::SnapshotAfterTarget {
                page_number: repair.page_number,
                snapshot_position: snapshot.required_position().clone(),
                target_position: target.page_position.clone(),
            },
        );
    }

    match repair.source_expectation {
        PreparedTransactionRestartCheckpointPageSourceExpectation::SuffixOnly => {
            validate_replay_backed_snapshot(&snapshot, replay_observations, analysis)?;
        }
        PreparedTransactionRestartCheckpointPageSourceExpectation::ExactCheckpointSnapshot {
            ..
        } => {
            if owned_replay_page_at_position(
                repair.page_number,
                snapshot.required_position(),
                replay_observations,
            )
            .is_some()
            {
                validate_replay_backed_snapshot(&snapshot, replay_observations, analysis)?;
            }
        }
        PreparedTransactionRestartCheckpointPageSourceExpectation::MissingAtCheckpoint => {}
    }
    repair.resolution =
        PreparedTransactionRestartCheckpointPageRepairResolution::Candidate(Some(snapshot));
    Ok(())
}

fn prepare_transaction_restart_checkpoint_page_repairs<
    Source,
    Store,
    CheckpointSource,
    const N: usize,
>(
    planned: &PlannedTransactionPageStorageRestartCheckpointReplay<
        Source,
        Store,
        CheckpointSource,
        N,
    >,
) -> Result<
    Vec<PreparedTransactionRestartCheckpointPageRepair<N>>,
    TransactionPageStorageRestartCheckpointRepairPreparationError<Store, N>,
>
where
    Source: DurableTransactionRestartAnalysisSource<N>,
    Store: DurablePageStoreSnapshotSource<N>,
{
    let replay_lineage = planned.current_analysis.lineage().clone();
    let store_lineage = planned.selected.storage.store.lineage().clone();
    if !replay_lineage.same_lineage(&store_lineage) {
        return Err(
            DurableTransactionRestartCheckpointRepairPreparationError::LineageMismatch {
                replay_lineage,
                store_lineage,
            },
        );
    }

    let mut page_numbers = Vec::new();
    reserve_restart_checkpoint_repair_page_inventory(
        &mut page_numbers,
        planned.replay_observations.len(),
    )
    .map_err(|source| {
        DurableTransactionRestartCheckpointRepairPreparationError::Evidence(Box::new(source))
    })?;
    for observation in &planned.replay_observations {
        match observation {
            OwnedDurableTransactionRestartReplayObservation::Page { page_number, .. }
            | OwnedDurableTransactionRestartReplayObservation::TransactionPage {
                page_number,
                ..
            } => page_numbers.push(*page_number),
            OwnedDurableTransactionRestartReplayObservation::Commit { .. } => {}
        }
    }
    page_numbers.sort_unstable();
    page_numbers.dedup();

    let mut page_repairs = Vec::new();
    reserve_restart_checkpoint_repair_decisions(&mut page_repairs, page_numbers.len()).map_err(
        |source| {
            DurableTransactionRestartCheckpointRepairPreparationError::Evidence(Box::new(source))
        },
    )?;
    page_repairs.extend(page_numbers.into_iter().map(|page_number| {
        PreparedTransactionRestartCheckpointPageRepair {
            page_number,
            source_expectation:
                PreparedTransactionRestartCheckpointPageSourceExpectation::SuffixOnly,
            target: None,
            unchanged_checkpoint_current: false,
            resolution: PreparedTransactionRestartCheckpointPageRepairResolution::Pending,
        }
    }));
    for (observation_index, observation) in planned.replay_observations.iter().enumerate() {
        let (page_number, page_position) = match observation {
            OwnedDurableTransactionRestartReplayObservation::Page {
                page_number,
                position,
                ..
            }
            | OwnedDurableTransactionRestartReplayObservation::TransactionPage {
                page_number,
                position,
                ..
            } => (*page_number, position),
            OwnedDurableTransactionRestartReplayObservation::Commit { .. } => continue,
        };
        let repair_index = page_repairs
            .binary_search_by_key(&page_number, |repair| repair.page_number)
            .map_err(|_| {
                DurableTransactionRestartCheckpointRepairPreparationError::Evidence(Box::new(
                    DurableTransactionRestartCheckpointRepairPreparationEvidenceError::ReplayPageInventoryMissing {
                        page_number,
                        page_position: page_position.clone(),
                    },
                ))
            })?;
        if let Some(target) = prepared_replay_page_target(
            observation_index,
            observation,
            &planned.replay_observations,
            &planned.current_analysis,
        )
        .map_err(|source| {
            DurableTransactionRestartCheckpointRepairPreparationError::Evidence(Box::new(source))
        })? {
            page_repairs[repair_index].target = Some(target);
        }
    }
    validate_owned_dirty_checkpoint_images(
        &planned.selected.baseline,
        &planned.replay_observations,
        &planned.current_analysis,
    )
    .map_err(|source| {
        DurableTransactionRestartCheckpointRepairPreparationError::Evidence(Box::new(source))
    })?;
    for repair in &mut page_repairs {
        combine_restart_checkpoint_page_repair_evidence(repair, &planned.selected.baseline);
    }

    for repair in &mut page_repairs {
        let page_number = repair.page_number;
        let snapshot = planned
            .selected
            .storage
            .store
            .observe_page(page_number)
            .map_err(|source| {
                DurableTransactionRestartCheckpointRepairPreparationError::StoreObservation {
                    page_number,
                    source,
                }
            })?;
        resolve_prepared_restart_checkpoint_page_repair(
            &replay_lineage,
            repair,
            snapshot,
            &planned.replay_observations,
            &planned.current_analysis,
        )
        .map_err(|source| {
            DurableTransactionRestartCheckpointRepairPreparationError::Evidence(Box::new(source))
        })?;
    }
    Ok(page_repairs)
}

fn compare_prepared_restart_checkpoint_page_source<const N: usize>(
    lineage: &LogLineage,
    page_number: PageNumber,
    expected: Option<&StoredPageSnapshotObservation<N>>,
    current: Option<&StoredPageSnapshotObservation<N>>,
) -> Result<(), DurableTransactionRestartCheckpointPageRepairComparisonError> {
    let Some(current) = current else {
        return match expected {
            None => Ok(()),
            Some(expected) => Err(
                DurableTransactionRestartCheckpointPageRepairComparisonError::StoreChanged {
                    page_number,
                    expected_source_position: Some(expected.required_position().clone()),
                    actual_position: None,
                },
            ),
        };
    };
    if current.page_number() != page_number {
        return Err(
            DurableTransactionRestartCheckpointPageRepairComparisonError::UnexpectedCurrentSnapshotPage {
                expected: page_number,
                actual: current.page_number(),
                position: current.required_position().clone(),
            },
        );
    }
    if !lineage.same_lineage(current.required_position().lineage()) {
        return Err(
            DurableTransactionRestartCheckpointPageRepairComparisonError::ForeignCurrentSnapshotLineage {
                page_number,
                position: current.required_position().clone(),
            },
        );
    }
    let Some(expected) = expected else {
        return Err(
            DurableTransactionRestartCheckpointPageRepairComparisonError::StoreChanged {
                page_number,
                expected_source_position: None,
                actual_position: Some(current.required_position().clone()),
            },
        );
    };
    if current.required_position() != expected.required_position() {
        return Err(
            DurableTransactionRestartCheckpointPageRepairComparisonError::StoreChanged {
                page_number,
                expected_source_position: Some(expected.required_position().clone()),
                actual_position: Some(current.required_position().clone()),
            },
        );
    }
    if !snapshots_match(current, expected) {
        return Err(
            DurableTransactionRestartCheckpointPageRepairComparisonError::SourceSnapshotPayloadContradiction {
                page_number,
                position: current.required_position().clone(),
            },
        );
    }
    Ok(())
}

fn attempt_prepared_transaction_restart_checkpoint_page_repairs<
    Source,
    Store,
    CheckpointSource,
    const N: usize,
>(
    prepared: &mut PreparedTransactionPageStorageRestartCheckpointRepairs<
        Source,
        Store,
        CheckpointSource,
        N,
    >,
    completed_prefix: &mut Vec<TransactionRestartCheckpointPageRepairOutcome>,
) -> Result<
    (),
    TransactionRestartCheckpointPageRepairFailureCause<Store::ObservationError, Store::WriteError>,
>
where
    Source: DurableTransactionRestartAnalysisSource<N>,
    Store: TransactionRestartCheckpointPageRepairStore<N>,
{
    let replay_lineage = prepared.planned.current_analysis.lineage().clone();
    let store_lineage = prepared.planned.selected.storage.store.lineage().clone();
    if !replay_lineage.same_lineage(&store_lineage) {
        return Err(
            TransactionRestartCheckpointPageRepairFailureCause::LineageMismatch {
                replay_lineage,
                store_lineage,
            },
        );
    }

    let page_repairs = &prepared.page_repairs;
    let store = &mut prepared.planned.selected.storage.store;
    for repair in page_repairs {
        let page_number = repair.page_number;
        let current = store.observe_page(page_number).map_err(|source| {
            TransactionRestartCheckpointPageRepairFailureCause::StoreObservation {
                page_number,
                source,
            }
        })?;
        let outcome = match &repair.resolution {
            PreparedTransactionRestartCheckpointPageRepairResolution::Pending => {
                return Err(
                    TransactionRestartCheckpointPageRepairFailureCause::UnresolvedDecision {
                        page_number,
                    },
                );
            }
            PreparedTransactionRestartCheckpointPageRepairResolution::NoRequiredImage => {
                compare_prepared_restart_checkpoint_page_source(
                    &replay_lineage,
                    page_number,
                    None,
                    current.as_ref(),
                )
                .map_err(|source| {
                    TransactionRestartCheckpointPageRepairFailureCause::SourceComparison {
                        page_number,
                        source,
                    }
                })?;
                TransactionRestartCheckpointPageRepairOutcome::NoRequiredImage { page_number }
            }
            PreparedTransactionRestartCheckpointPageRepairResolution::CheckpointCurrent(
                expected,
            ) => {
                compare_prepared_restart_checkpoint_page_source(
                    &replay_lineage,
                    page_number,
                    Some(expected),
                    current.as_ref(),
                )
                .map_err(|source| {
                    TransactionRestartCheckpointPageRepairFailureCause::SourceComparison {
                        page_number,
                        source,
                    }
                })?;
                TransactionRestartCheckpointPageRepairOutcome::CheckpointCurrent { page_number }
            }
            PreparedTransactionRestartCheckpointPageRepairResolution::AlreadyCurrent(expected) => {
                compare_prepared_restart_checkpoint_page_source(
                    &replay_lineage,
                    page_number,
                    Some(expected),
                    current.as_ref(),
                )
                .map_err(|source| {
                    TransactionRestartCheckpointPageRepairFailureCause::SourceComparison {
                        page_number,
                        source,
                    }
                })?;
                TransactionRestartCheckpointPageRepairOutcome::AlreadyCurrent { page_number }
            }
            PreparedTransactionRestartCheckpointPageRepairResolution::Candidate(source) => {
                let Some(target) = repair.target.as_ref() else {
                    return Err(
                        TransactionRestartCheckpointPageRepairFailureCause::CandidateTargetMissing {
                            page_number,
                        },
                    );
                };
                let precondition = match source {
                    Some(snapshot) => {
                        DurableTransactionRestartCheckpointPageRepairPrecondition::ExactSnapshot(
                            snapshot,
                        )
                    }
                    None => DurableTransactionRestartCheckpointPageRepairPrecondition::StoreMissing,
                };
                let candidate = DurableTransactionRestartCheckpointPageRepairCandidate {
                    precondition,
                    target,
                };
                match compare_transaction_restart_checkpoint_page_repair_candidate(
                    &candidate,
                    current.as_ref(),
                )
                .map_err(|source| {
                    TransactionRestartCheckpointPageRepairFailureCause::SourceComparison {
                        page_number,
                        source,
                    }
                })? {
                    DurableTransactionRestartCheckpointPageRepairComparison::TargetAlreadyPresent => {
                        TransactionRestartCheckpointPageRepairOutcome::TargetAlreadyPresent {
                            page_number,
                        }
                    }
                    DurableTransactionRestartCheckpointPageRepairComparison::SourceMatches => {
                        with_transaction_restart_checkpoint_page_repair_write_permit(
                            target,
                            |permit| {
                                store.compare_and_replace_replay_page(&candidate, permit)
                            },
                        )
                        .map_err(|source| {
                            TransactionRestartCheckpointPageRepairFailureCause::StoreWrite {
                                page_number,
                                source,
                            }
                        })?;
                        TransactionRestartCheckpointPageRepairOutcome::Repaired { page_number }
                    }
                }
            }
        };
        completed_prefix.push(outcome);
    }
    Ok(())
}

fn execute_prepared_transaction_restart_checkpoint_page_repairs<
    Source,
    Store,
    CheckpointSource,
    const N: usize,
>(
    mut prepared: PreparedTransactionPageStorageRestartCheckpointRepairs<
        Source,
        Store,
        CheckpointSource,
        N,
    >,
    mut completed_prefix: Vec<TransactionRestartCheckpointPageRepairOutcome>,
    prior_indeterminate_result: bool,
) -> TransactionPageStorageRestartCheckpointPageRepairExecution<
    Source,
    Store,
    CheckpointSource,
    Store::ObservationError,
    Store::WriteError,
    N,
>
where
    Source: DurableTransactionRestartAnalysisSource<N>,
    Store: TransactionRestartCheckpointPageRepairStore<N>,
{
    completed_prefix.clear();
    let page_count = prepared.page_count();
    if completed_prefix.capacity() < page_count
        && completed_prefix.try_reserve_exact(page_count).is_err()
    {
        return TransactionPageStorageRestartCheckpointPageRepairExecution::Failed(
            FailedTransactionPageStorageRestartCheckpointPageRepair {
                prepared,
                completed_prefix,
                cause:
                    TransactionRestartCheckpointPageRepairFailureCause::OutcomeCapacityExhausted {
                        page_count,
                    },
                has_indeterminate_result: prior_indeterminate_result,
            },
        );
    }

    match attempt_prepared_transaction_restart_checkpoint_page_repairs(
        &mut prepared,
        &mut completed_prefix,
    ) {
        Ok(()) => TransactionPageStorageRestartCheckpointPageRepairExecution::Repaired(
            RepairedTransactionPageStorageRestartCheckpointReplay {
                prepared,
                page_outcomes: completed_prefix,
            },
        ),
        Err(cause) => {
            let has_indeterminate_result =
                prior_indeterminate_result || cause.current_attempt_is_indeterminate();
            TransactionPageStorageRestartCheckpointPageRepairExecution::Failed(
                FailedTransactionPageStorageRestartCheckpointPageRepair {
                    prepared,
                    completed_prefix,
                    cause,
                    has_indeterminate_result,
                },
            )
        }
    }
}

struct PreparedTransactionRestartRestoration {
    lineage: LogLineage,
    transaction_count: usize,
    committed_count: usize,
    unresolved_count: usize,
    highest_persisted_transaction: Option<DurableTransactionIdentityObservation>,
}

fn validate_selected_transaction_positions(
    transaction: DurableTransactionIdentityObservation,
    selected_frontier: Option<u64>,
    positions: impl IntoIterator<Item = Option<u64>>,
) -> Result<(), TransactionRestartRestorationEvidenceError> {
    for position in positions.into_iter().flatten() {
        let Some(frontier) = selected_frontier else {
            return Err(
                TransactionRestartRestorationEvidenceError::TransactionInEmptySelectedPrefix {
                    transaction,
                },
            );
        };
        if position > frontier {
            return Err(
                TransactionRestartRestorationEvidenceError::SelectedTransactionPositionAfterFrontier {
                    transaction,
                    selected_frontier: frontier,
                    position,
                },
            );
        }
    }
    Ok(())
}

fn current_transaction_first_position(entry: &DurableTransactionRestartEntry) -> Option<u64> {
    match (
        entry
            .first_owned_page_position()
            .map(LogSequenceNumber::get),
        entry.state().commit_position().map(LogSequenceNumber::get),
    ) {
        (Some(page), Some(commit)) => Some(page.min(commit)),
        (Some(page), None) => Some(page),
        (None, Some(commit)) => Some(commit),
        (None, None) => None,
    }
}

fn prepare_transaction_restart_restoration<Source, Store, CheckpointSource, const N: usize>(
    repaired: &RepairedTransactionPageStorageRestartCheckpointReplay<
        Source,
        Store,
        CheckpointSource,
        N,
    >,
) -> Result<PreparedTransactionRestartRestoration, TransactionRestartRestorationEvidenceError>
where
    Source: DurableTransactionRestartAnalysisSource<N>,
    Store: DurablePageStoreSnapshotSource<N>,
{
    let planned = &repaired.prepared.planned;
    prepare_transaction_restart_restoration_evidence(
        &planned.selected.baseline,
        &planned.current_analysis,
    )
}

fn prepare_transaction_restart_restoration_evidence(
    selected_baseline: &DurableTransactionRestartCheckpointCompletenessBaseline,
    current: &DurableTransactionRestartAnalysis,
) -> Result<PreparedTransactionRestartRestoration, TransactionRestartRestorationEvidenceError> {
    let selected = selected_baseline.transaction_baseline();
    let Some(current_persistent_id) = current.lineage().persistent_id() else {
        return Err(TransactionRestartRestorationEvidenceError::CurrentPersistentLineageRequired);
    };
    if selected.persistent_log_id() != current_persistent_id {
        return Err(
            TransactionRestartRestorationEvidenceError::PersistentLineageMismatch {
                selected: selected.persistent_log_id(),
                current: current_persistent_id,
            },
        );
    }

    let selected_frontier = selected.durable_frontier();
    let current_frontier = current.durable_frontier().map(LogSequenceNumber::get);
    match (selected_frontier, current_frontier) {
        (Some(selected_frontier), None) => {
            return Err(
                TransactionRestartRestorationEvidenceError::CurrentFrontierMissing {
                    selected_frontier,
                },
            );
        }
        (Some(selected_frontier), Some(current_frontier))
            if selected_frontier > current_frontier =>
        {
            return Err(
                TransactionRestartRestorationEvidenceError::SelectedFrontierAfterCurrent {
                    selected_frontier,
                    current_frontier,
                },
            );
        }
        (None, _) | (Some(_), Some(_)) => {}
    }

    let mut highest_persisted_transaction: Option<DurableTransactionIdentityObservation> = None;
    for selected_entry in selected.transactions() {
        let transaction = selected_entry.transaction();
        highest_persisted_transaction = Some(
            highest_persisted_transaction.map_or(transaction, |highest| highest.max(transaction)),
        );
        validate_selected_transaction_positions(
            transaction,
            selected_frontier,
            [
                selected_entry.first_owned_page_position(),
                selected_entry.last_owned_page_position(),
                selected_entry.state().commit_position(),
            ],
        )?;

        let Ok(current_index) = current
            .transactions()
            .binary_search_by_key(&transaction, DurableTransactionRestartEntry::transaction)
        else {
            return Err(
                TransactionRestartRestorationEvidenceError::SelectedTransactionMissing {
                    transaction,
                },
            );
        };
        let current_entry = &current.transactions()[current_index];
        let current_first = current_entry
            .first_owned_page_position()
            .map(LogSequenceNumber::get);
        if selected_entry.first_owned_page_position() != current_first {
            return Err(
                TransactionRestartRestorationEvidenceError::FirstOwnedPagePositionMismatch {
                    transaction,
                    selected: selected_entry.first_owned_page_position(),
                    current: current_first,
                },
            );
        }
        let current_last = current_entry
            .last_owned_page_position()
            .map(LogSequenceNumber::get);
        let current_count =
            u64::try_from(current_entry.owned_page_record_count()).map_err(|_| {
                TransactionRestartRestorationEvidenceError::CurrentOwnedPageCountWidthExceeded {
                    transaction,
                    record_count: current_entry.owned_page_record_count(),
                }
            })?;
        match selected_entry.state() {
            DurableTransactionRestartCheckpointBaselineState::Committed { commit_position } => {
                if selected_entry.last_owned_page_position() != current_last
                    || selected_entry.owned_page_record_count() != current_count
                    || current_entry
                        .state()
                        .commit_position()
                        .map(LogSequenceNumber::get)
                        != Some(commit_position)
                {
                    return Err(
                        TransactionRestartRestorationEvidenceError::SelectedCommittedTransactionChanged {
                            transaction,
                            selected_commit_position: commit_position,
                            current_commit_position: current_entry
                                .state()
                                .commit_position()
                                .map(LogSequenceNumber::get),
                        },
                    );
                }
            }
            DurableTransactionRestartCheckpointBaselineState::Uncommitted => {
                let selected_last = selected_entry.last_owned_page_position();
                let selected_count = selected_entry.owned_page_record_count();
                if current_count < selected_count {
                    return Err(
                        TransactionRestartRestorationEvidenceError::OwnedPageRecordCountRegressed {
                            transaction,
                            selected: selected_count,
                            current: current_count,
                        },
                    );
                }
                let Some(selected_frontier) = selected_frontier else {
                    return Err(
                        TransactionRestartRestorationEvidenceError::TransactionInEmptySelectedPrefix {
                            transaction,
                        },
                    );
                };
                let exact_unchanged_page_evidence =
                    current_count == selected_count && current_last == selected_last;
                let post_frontier_page_growth = current_count > selected_count
                    && current_last.is_some_and(|position| position > selected_frontier);
                if !exact_unchanged_page_evidence && !post_frontier_page_growth {
                    return Err(
                        TransactionRestartRestorationEvidenceError::SelectedUnresolvedOwnedPageEvidenceContradiction {
                            transaction,
                            selected_frontier,
                            selected_last_position: selected_last,
                            current_last_position: current_last,
                            selected_record_count: selected_count,
                            current_record_count: current_count,
                        },
                    );
                }
                if let Some(commit_position) = current_entry
                    .state()
                    .commit_position()
                    .map(LogSequenceNumber::get)
                    && commit_position <= selected_frontier
                {
                    return Err(
                        TransactionRestartRestorationEvidenceError::SelectedUnresolvedTransactionCommittedInsidePrefix {
                            transaction,
                            selected_frontier,
                            commit_position,
                        },
                    );
                }
            }
        }
    }

    let mut committed_count = 0_usize;
    let mut unresolved_count = 0_usize;
    for current_entry in current.transactions() {
        let transaction = current_entry.transaction();
        highest_persisted_transaction = Some(
            highest_persisted_transaction.map_or(transaction, |highest| highest.max(transaction)),
        );
        match current_entry.state() {
            DurableTransactionRestartState::Committed { .. } => {
                committed_count = committed_count
                    .checked_add(1)
                    .ok_or(TransactionRestartRestorationEvidenceError::SummaryCountExhausted)?;
            }
            DurableTransactionRestartState::Uncommitted => {
                unresolved_count = unresolved_count
                    .checked_add(1)
                    .ok_or(TransactionRestartRestorationEvidenceError::SummaryCountExhausted)?;
            }
        }

        let first_position = current_transaction_first_position(current_entry).ok_or(
            TransactionRestartRestorationEvidenceError::CurrentTransactionHasNoRecordPosition {
                transaction,
            },
        )?;
        if selected_frontier.is_some_and(|frontier| first_position <= frontier)
            && selected
                .transactions()
                .binary_search_by_key(
                    &transaction,
                    DurableTransactionRestartCheckpointBaselineEntry::transaction,
                )
                .is_err()
        {
            return Err(
                TransactionRestartRestorationEvidenceError::CurrentTransactionMissingFromSelectedPrefix {
                    transaction,
                    first_position,
                },
            );
        }
    }

    let transaction_count = committed_count
        .checked_add(unresolved_count)
        .ok_or(TransactionRestartRestorationEvidenceError::SummaryCountExhausted)?;
    Ok(PreparedTransactionRestartRestoration {
        lineage: current.lineage().clone(),
        transaction_count,
        committed_count,
        unresolved_count,
        highest_persisted_transaction,
    })
}

fn rejected_transaction_restart_restoration<Source, Store, CheckpointSource, const N: usize>(
    repaired: RepairedTransactionPageStorageRestartCheckpointReplay<
        Source,
        Store,
        CheckpointSource,
        N,
    >,
    cause: TransactionRestartRestorationRejection,
    indeterminate_allocation_attempt_count: usize,
) -> TransactionPageStorageRestartCheckpointRestoration<
    Source,
    Store,
    CheckpointSource,
    <Source as TransactionRestartCoordinatorEpochSource>::Error,
    N,
>
where
    Source: TransactionRestartCoordinatorEpochSource + DurableTransactionRestartAnalysisSource<N>,
    Store: DurablePageStoreSnapshotSource<N>,
{
    TransactionPageStorageRestartCheckpointRestoration::Rejected(
        RejectedTransactionPageStorageRestartCheckpointRestoration {
            repaired,
            cause,
            indeterminate_allocation_attempt_count,
        },
    )
}

fn restore_transaction_restart_state<Source, Store, CheckpointSource, const N: usize>(
    mut repaired: RepairedTransactionPageStorageRestartCheckpointReplay<
        Source,
        Store,
        CheckpointSource,
        N,
    >,
    indeterminate_allocation_attempt_count: usize,
) -> TransactionPageStorageRestartCheckpointRestoration<
    Source,
    Store,
    CheckpointSource,
    <Source as TransactionRestartCoordinatorEpochSource>::Error,
    N,
>
where
    Source: TransactionRestartCoordinatorEpochSource + DurableTransactionRestartAnalysisSource<N>,
    Store: DurablePageStoreSnapshotSource<N>,
{
    let prepared = match prepare_transaction_restart_restoration(&repaired) {
        Ok(prepared) => prepared,
        Err(source) => {
            return rejected_transaction_restart_restoration(
                repaired,
                TransactionRestartRestorationRejection::Evidence(Box::new(source)),
                indeterminate_allocation_attempt_count,
            );
        }
    };
    let epoch_high_water = prepared
        .highest_persisted_transaction
        .map(|transaction| transaction.epoch);
    let Some(next_indeterminate_allocation_attempt_count) =
        indeterminate_allocation_attempt_count.checked_add(1)
    else {
        return rejected_transaction_restart_restoration(
            repaired,
            TransactionRestartRestorationRejection::AllocationAttemptCountExhausted,
            indeterminate_allocation_attempt_count,
        );
    };
    let source = &mut repaired.prepared.planned.selected.storage.source;
    let (epoch, lineage) = match source.allocate_restart_transaction_epoch(epoch_high_water) {
        Ok(allocation) => allocation,
        Err(TransactionRestartCoordinatorEpochAllocationError::Source(source)) => {
            return TransactionPageStorageRestartCheckpointRestoration::Failed(
                FailedTransactionPageStorageRestartCheckpointRestoration {
                    repaired,
                    cause: source,
                    indeterminate_allocation_attempt_count:
                        next_indeterminate_allocation_attempt_count,
                },
            );
        }
        Err(TransactionRestartCoordinatorEpochAllocationError::IdentitySpaceExhausted {
            persisted_epoch_high_water,
        }) => {
            return rejected_transaction_restart_restoration(
                repaired,
                TransactionRestartRestorationRejection::IdentitySpaceExhausted {
                    persisted_epoch_high_water,
                },
                indeterminate_allocation_attempt_count,
            );
        }
        Err(
            TransactionRestartCoordinatorEpochAllocationError::PersistedEpochHighWaterNotAdvanced {
                persisted_epoch_high_water,
                next_epoch,
            },
        ) => {
            return rejected_transaction_restart_restoration(
                repaired,
                TransactionRestartRestorationRejection::PersistedEpochHighWaterNotAdvanced {
                    persisted_epoch_high_water,
                    next_epoch,
                },
                indeterminate_allocation_attempt_count,
            );
        }
    };

    if let Some(high_water) = epoch_high_water
        && epoch <= high_water
    {
        return rejected_transaction_restart_restoration(
            repaired,
            TransactionRestartRestorationRejection::AllocatedEpochNotAbovePersistedHighWater {
                persisted_epoch_high_water: high_water.get(),
                allocated_epoch: epoch.get(),
            },
            indeterminate_allocation_attempt_count,
        );
    }
    if !prepared.lineage.same_lineage(&lineage) {
        return rejected_transaction_restart_restoration(
            repaired,
            TransactionRestartRestorationRejection::AllocatedEpochLineageMismatch {
                expected: prepared.lineage,
                actual: lineage,
                allocated_epoch: epoch.get(),
            },
            indeterminate_allocation_attempt_count,
        );
    }

    let coordinator = TransactionCoordinator::from_allocated_epoch(epoch, lineage);
    let summary = TransactionRestartRestorationSummary {
        transaction_count: prepared.transaction_count,
        committed_count: prepared.committed_count,
        unresolved_count: prepared.unresolved_count,
        highest_persisted_transaction: prepared.highest_persisted_transaction,
        coordinator_epoch: coordinator.epoch(),
        indeterminate_allocation_attempt_count,
    };
    TransactionPageStorageRestartCheckpointRestoration::Restored(
        RestoredTransactionPageStorageRestartCheckpointReplay {
            repaired,
            coordinator,
            summary,
        },
    )
}

fn completion_evidence_error<SourceError, StoreError>(
    source: DurableTransactionRestartCheckpointCompletionEvidenceError,
) -> DurableTransactionRestartCheckpointCompletionError<SourceError, StoreError> {
    DurableTransactionRestartCheckpointCompletionError::Evidence(Box::new(source))
}

fn validate_completed_transaction_restart_evidence<
    Source,
    Store,
    CheckpointSource,
    const N: usize,
>(
    restored: &RestoredTransactionPageStorageRestartCheckpointReplay<
        Source,
        Store,
        CheckpointSource,
        N,
    >,
    fresh_analysis: &DurableTransactionRestartAnalysis,
) -> Result<(), DurableTransactionRestartCheckpointCompletionEvidenceError>
where
    Source: DurableTransactionRestartAnalysisSource<N>,
    Store: DurablePageStoreSnapshotSource<N>,
{
    validate_completed_transaction_restart_evidence_parts(
        &restored.repaired.prepared.planned.selected.baseline,
        &restored.repaired.prepared.planned.current_analysis,
        &restored.coordinator,
        restored.summary,
        fresh_analysis,
    )
}

fn validate_completed_transaction_restart_evidence_parts(
    selected_baseline: &DurableTransactionRestartCheckpointCompletenessBaseline,
    retained: &DurableTransactionRestartAnalysis,
    coordinator: &TransactionCoordinator,
    summary: TransactionRestartRestorationSummary,
    fresh_analysis: &DurableTransactionRestartAnalysis,
) -> Result<(), DurableTransactionRestartCheckpointCompletionEvidenceError> {
    let prepared = prepare_transaction_restart_restoration_evidence(selected_baseline, retained)
        .map_err(|source| {
            DurableTransactionRestartCheckpointCompletionEvidenceError::RestorationEvidence(
                Box::new(source),
            )
        })?;
    if !retained.lineage().same_lineage(fresh_analysis.lineage()) {
        return Err(
            DurableTransactionRestartCheckpointCompletionEvidenceError::CurrentLineageChanged {
                expected: retained.lineage().clone(),
                actual: fresh_analysis.lineage().clone(),
            },
        );
    }

    let retained_frontier = retained.durable_frontier().map(LogSequenceNumber::get);
    let fresh_frontier = fresh_analysis
        .durable_frontier()
        .map(LogSequenceNumber::get);
    if retained_frontier != fresh_frontier {
        return Err(
            DurableTransactionRestartCheckpointCompletionEvidenceError::CurrentFrontierChanged {
                expected: retained_frontier,
                actual: fresh_frontier,
            },
        );
    }
    if retained.transactions().len() != fresh_analysis.transactions().len() {
        return Err(
            DurableTransactionRestartCheckpointCompletionEvidenceError::CurrentTransactionCountChanged {
                expected: retained.transactions().len(),
                actual: fresh_analysis.transactions().len(),
            },
        );
    }
    for (index, (expected, actual)) in retained
        .transactions()
        .iter()
        .zip(fresh_analysis.transactions())
        .enumerate()
    {
        if expected != actual {
            return Err(
                DurableTransactionRestartCheckpointCompletionEvidenceError::CurrentTransactionEntryChanged {
                    index,
                    expected: expected.transaction(),
                    actual: actual.transaction(),
                },
            );
        }
    }

    if !fresh_analysis
        .lineage()
        .same_lineage(&coordinator.log_lineage)
    {
        return Err(
            DurableTransactionRestartCheckpointCompletionEvidenceError::CoordinatorLineageMismatch {
                expected: fresh_analysis.lineage().clone(),
                actual: coordinator.log_lineage.clone(),
            },
        );
    }
    let coordinator_epoch = coordinator.epoch();
    if summary.coordinator_epoch != coordinator_epoch {
        return Err(
            DurableTransactionRestartCheckpointCompletionEvidenceError::CoordinatorEpochChanged {
                expected: summary.coordinator_epoch.get(),
                actual: coordinator_epoch.get(),
            },
        );
    }
    if let Some(highest) = prepared.highest_persisted_transaction
        && coordinator_epoch.get() <= highest.epoch()
    {
        return Err(
            DurableTransactionRestartCheckpointCompletionEvidenceError::CoordinatorEpochNotAbovePersistedHighWater {
                persisted_epoch_high_water: highest.epoch(),
                coordinator_epoch: coordinator_epoch.get(),
            },
        );
    }
    let expected_summary = TransactionRestartRestorationSummary {
        transaction_count: prepared.transaction_count,
        committed_count: prepared.committed_count,
        unresolved_count: prepared.unresolved_count,
        highest_persisted_transaction: prepared.highest_persisted_transaction,
        coordinator_epoch,
        indeterminate_allocation_attempt_count: summary.indeterminate_allocation_attempt_count,
    };
    if expected_summary != summary {
        return Err(
            DurableTransactionRestartCheckpointCompletionEvidenceError::RestorationSummaryChanged {
                expected: expected_summary,
                actual: summary,
            },
        );
    }
    if coordinator.next_transaction_id != Some(NonZeroU64::MIN)
        || !coordinator.lifecycles.is_empty()
        || !coordinator.staged_pages.is_empty()
    {
        return Err(
            DurableTransactionRestartCheckpointCompletionEvidenceError::CoordinatorStateChanged {
                next_sequence: coordinator.next_transaction_id.map(NonZeroU64::get),
                lifecycle_count: coordinator.lifecycles.len(),
                staged_page_count: coordinator.staged_pages.len(),
            },
        );
    }
    Ok(())
}

fn page_outcome_matches_prepared_resolution<const N: usize>(
    resolution: &PreparedTransactionRestartCheckpointPageRepairResolution<N>,
    outcome: TransactionRestartCheckpointPageRepairOutcome,
) -> bool {
    matches!(
        (resolution, outcome),
        (
            PreparedTransactionRestartCheckpointPageRepairResolution::NoRequiredImage,
            TransactionRestartCheckpointPageRepairOutcome::NoRequiredImage { .. },
        ) | (
            PreparedTransactionRestartCheckpointPageRepairResolution::CheckpointCurrent(_),
            TransactionRestartCheckpointPageRepairOutcome::CheckpointCurrent { .. },
        ) | (
            PreparedTransactionRestartCheckpointPageRepairResolution::AlreadyCurrent(_),
            TransactionRestartCheckpointPageRepairOutcome::AlreadyCurrent { .. },
        ) | (
            PreparedTransactionRestartCheckpointPageRepairResolution::Candidate(_),
            TransactionRestartCheckpointPageRepairOutcome::TargetAlreadyPresent { .. }
                | TransactionRestartCheckpointPageRepairOutcome::Repaired { .. },
        )
    )
}

fn validate_completed_transaction_restart_pages<Source, Store, CheckpointSource, const N: usize>(
    restored: &RestoredTransactionPageStorageRestartCheckpointReplay<
        Source,
        Store,
        CheckpointSource,
        N,
    >,
) -> Result<
    (),
    DurableTransactionRestartCheckpointCompletionError<
        <Source as DurableTransactionRestartAnalysisSource<N>>::Error,
        Store::ObservationError,
    >,
>
where
    Source: DurableTransactionRestartAnalysisSource<N>,
    Store: DurablePageStoreSnapshotSource<N>,
{
    let prepared = &restored.repaired.prepared;
    let store = &prepared.planned.selected.storage.store;
    let lineage = &prepared.planned.current_analysis.lineage;
    let store_lineage = store.lineage();
    if !lineage.same_lineage(store_lineage) {
        return Err(completion_evidence_error(
            DurableTransactionRestartCheckpointCompletionEvidenceError::StoreLineageMismatch {
                expected: lineage.clone(),
                actual: store_lineage.clone(),
            },
        ));
    }
    if prepared.page_repairs.len() != restored.repaired.page_outcomes.len() {
        return Err(completion_evidence_error(
            DurableTransactionRestartCheckpointCompletionEvidenceError::PageOutcomeCountChanged {
                expected: prepared.page_repairs.len(),
                actual: restored.repaired.page_outcomes.len(),
            },
        ));
    }

    for (index, (repair, outcome)) in prepared
        .page_repairs
        .iter()
        .zip(&restored.repaired.page_outcomes)
        .enumerate()
    {
        let page_number = repair.page_number;
        if outcome.page_number() != page_number
            || !page_outcome_matches_prepared_resolution(&repair.resolution, *outcome)
        {
            return Err(completion_evidence_error(
                DurableTransactionRestartCheckpointCompletionEvidenceError::PageOutcomeChanged {
                    index,
                    expected_page: page_number,
                    actual: *outcome,
                },
            ));
        }
        let current = store.observe_page(page_number).map_err(|source| {
            DurableTransactionRestartCheckpointCompletionError::StoreObservation {
                page_number,
                source,
            }
        })?;

        match &repair.resolution {
            PreparedTransactionRestartCheckpointPageRepairResolution::Pending => {
                return Err(completion_evidence_error(
                    DurableTransactionRestartCheckpointCompletionEvidenceError::PendingPageRepair {
                        page_number,
                    },
                ));
            }
            PreparedTransactionRestartCheckpointPageRepairResolution::NoRequiredImage => {
                compare_prepared_restart_checkpoint_page_source(
                    lineage,
                    page_number,
                    None,
                    current.as_ref(),
                )
                .map_err(|source| {
                    completion_evidence_error(
                        DurableTransactionRestartCheckpointCompletionEvidenceError::FinalPageComparison {
                            page_number,
                            source: Box::new(source),
                        },
                    )
                })?;
            }
            PreparedTransactionRestartCheckpointPageRepairResolution::CheckpointCurrent(
                expected,
            ) => {
                compare_prepared_restart_checkpoint_page_source(
                    lineage,
                    page_number,
                    Some(expected),
                    current.as_ref(),
                )
                .map_err(|source| {
                    completion_evidence_error(
                        DurableTransactionRestartCheckpointCompletionEvidenceError::FinalPageComparison {
                            page_number,
                            source: Box::new(source),
                        },
                    )
                })?;
            }
            PreparedTransactionRestartCheckpointPageRepairResolution::AlreadyCurrent(expected) => {
                let Some(target) = repair.target.as_ref() else {
                    return Err(completion_evidence_error(
                        DurableTransactionRestartCheckpointCompletionEvidenceError::PageRepairTargetMissing {
                            page_number,
                        },
                    ));
                };
                let candidate = DurableTransactionRestartCheckpointPageRepairCandidate {
                    precondition:
                        DurableTransactionRestartCheckpointPageRepairPrecondition::ExactSnapshot(
                            expected,
                        ),
                    target,
                };
                match compare_transaction_restart_checkpoint_page_repair_candidate(
                    &candidate,
                    current.as_ref(),
                )
                .map_err(|source| {
                    completion_evidence_error(
                        DurableTransactionRestartCheckpointCompletionEvidenceError::FinalPageComparison {
                            page_number,
                            source: Box::new(source),
                        },
                    )
                })? {
                    DurableTransactionRestartCheckpointPageRepairComparison::TargetAlreadyPresent => {
                    }
                    DurableTransactionRestartCheckpointPageRepairComparison::SourceMatches => {
                        return Err(completion_evidence_error(
                            DurableTransactionRestartCheckpointCompletionEvidenceError::FinalPageTargetMissing {
                                page_number,
                            },
                        ));
                    }
                }
            }
            PreparedTransactionRestartCheckpointPageRepairResolution::Candidate(source) => {
                let Some(target) = repair.target.as_ref() else {
                    return Err(completion_evidence_error(
                        DurableTransactionRestartCheckpointCompletionEvidenceError::PageRepairTargetMissing {
                            page_number,
                        },
                    ));
                };
                let precondition = match source {
                    Some(snapshot) => {
                        DurableTransactionRestartCheckpointPageRepairPrecondition::ExactSnapshot(
                            snapshot,
                        )
                    }
                    None => DurableTransactionRestartCheckpointPageRepairPrecondition::StoreMissing,
                };
                let candidate = DurableTransactionRestartCheckpointPageRepairCandidate {
                    precondition,
                    target,
                };
                match compare_transaction_restart_checkpoint_page_repair_candidate(
                    &candidate,
                    current.as_ref(),
                )
                .map_err(|source| {
                    completion_evidence_error(
                        DurableTransactionRestartCheckpointCompletionEvidenceError::FinalPageComparison {
                            page_number,
                            source: Box::new(source),
                        },
                    )
                })? {
                    DurableTransactionRestartCheckpointPageRepairComparison::TargetAlreadyPresent => {
                    }
                    DurableTransactionRestartCheckpointPageRepairComparison::SourceMatches => {
                        return Err(completion_evidence_error(
                            DurableTransactionRestartCheckpointCompletionEvidenceError::FinalPageTargetMissing {
                                page_number,
                            },
                        ));
                    }
                }
            }
        }
    }
    Ok(())
}

fn complete_transaction_page_storage_restart_checkpoint_replay<
    Source,
    Store,
    CheckpointSource,
    const N: usize,
>(
    mut restored: RestoredTransactionPageStorageRestartCheckpointReplay<
        Source,
        Store,
        CheckpointSource,
        N,
    >,
) -> Result<
    CompletedTransactionPageStorageRestartCheckpointReplay<Source, Store, CheckpointSource, N>,
    FailedTransactionPageStorageRestartCheckpointCompletion<Source, Store, CheckpointSource, N>,
>
where
    Source: DurableTransactionRestartAnalysisSource<N>,
    Store: DurablePageStoreSnapshotSource<N>,
{
    let selected = &mut restored.repaired.prepared.planned.selected;
    let fresh_analysis = match &selected.validation {
        SelectedRestartCheckpointValidation::CompletePrefix => {
            match analyze_durable_transaction_restart(&mut selected.storage.source) {
                Ok(analysis) => analysis,
                Err(source) => {
                    return Err(FailedTransactionPageStorageRestartCheckpointCompletion {
                        restored: Box::new(restored),
                        error: DurableTransactionRestartCheckpointCompletionError::RestartAnalysis(
                            source,
                        ),
                    });
                }
            }
        }
        SelectedRestartCheckpointValidation::Anchored { planner } => {
            match planner(
                &mut selected.storage.source,
                &selected.storage.store,
                &selected.baseline,
            ) {
                Ok(materialized) => materialized.current_analysis,
                Err(source) => {
                    return Err(FailedTransactionPageStorageRestartCheckpointCompletion {
                        restored: Box::new(restored),
                        error: DurableTransactionRestartCheckpointCompletionError::ReplayPlanning(
                            Box::new(source),
                        ),
                    });
                }
            }
        }
    };
    if let Err(source) = validate_completed_transaction_restart_evidence(&restored, &fresh_analysis)
    {
        return Err(FailedTransactionPageStorageRestartCheckpointCompletion {
            restored: Box::new(restored),
            error: completion_evidence_error(source),
        });
    }
    if let Err(error) = validate_completed_transaction_restart_pages(&restored) {
        return Err(FailedTransactionPageStorageRestartCheckpointCompletion {
            restored: Box::new(restored),
            error,
        });
    }

    let RestoredTransactionPageStorageRestartCheckpointReplay {
        repaired,
        coordinator,
        summary,
    } = restored;
    let RepairedTransactionPageStorageRestartCheckpointReplay {
        prepared,
        page_outcomes,
    } = repaired;
    let PreparedTransactionPageStorageRestartCheckpointRepairs {
        planned,
        page_repairs,
    } = prepared;
    let PlannedTransactionPageStorageRestartCheckpointReplay {
        selected,
        current_analysis,
        replay_observations,
    } = planned;
    let SelectedTransactionPageStorageRestartCheckpointCompleteness {
        storage,
        checkpoint_source,
        baseline,
        validation,
    } = selected;
    let UnrecoveredTransactionPageStorage {
        source,
        store,
        page_width: _,
    } = storage;
    Ok(CompletedTransactionPageStorageRestartCheckpointReplay {
        coordinator,
        source,
        store,
        checkpoint_source,
        evidence: TransactionPageStorageRestartCheckpointCompletionEvidence {
            selected_baseline: baseline,
            current_analysis,
            replay_observations,
            page_repairs,
            page_outcomes,
            transaction_summary: summary,
        },
        validation,
    })
}

fn wal_retention_evidence_error<
    WalSourceError,
    StoreError,
    MetadataError,
    StoreObservationError,
>(
    source: DurableTransactionRestartWalRetentionEvidenceError,
) -> DurableTransactionRestartWalRetentionAnalysisError<
    WalSourceError,
    StoreError,
    MetadataError,
    StoreObservationError,
> {
    DurableTransactionRestartWalRetentionAnalysisError::Evidence(Box::new(source))
}

fn validate_wal_retention_inventory_order<const N: usize>(
    inventory: &[StoredPageSnapshotObservation<N>],
) -> Result<(), DurableTransactionRestartWalRetentionEvidenceError> {
    for (offset, window) in inventory.windows(2).enumerate() {
        let previous = window[0].page_number();
        let actual = window[1].page_number();
        if actual <= previous {
            return Err(
                DurableTransactionRestartWalRetentionEvidenceError::PageInventoryNotStrictlyIncreasing {
                    index: offset + 1,
                    previous,
                    actual,
                },
            );
        }
    }
    Ok(())
}

fn push_wal_retention_requirement<Observation, const N: usize>(
    lineage: &LogLineage,
    durable_frontier: Option<&LogSequenceNumber>,
    observations: &[Observation],
    position: u64,
    cause: DurableTransactionRestartWalRetentionRequirementCause,
    requirements: &mut Vec<DurableTransactionRestartWalRetentionRequirement>,
    retained_first_record: &mut Option<LogSequenceNumber>,
) -> Result<(), DurableTransactionRestartWalRetentionEvidenceError>
where
    Observation: DurableTransactionRestartObservationView<N>,
{
    let Some(frontier) = durable_frontier else {
        return Err(
            DurableTransactionRestartWalRetentionEvidenceError::RequirementInEmptyPrefix {
                cause,
                position,
            },
        );
    };
    if position > frontier.get() {
        return Err(
            DurableTransactionRestartWalRetentionEvidenceError::RequirementAfterFrontier {
                cause,
                position,
                frontier: frontier.get(),
            },
        );
    }
    let Ok(index) = observations.binary_search_by_key(&position, |observation| {
        observation.restart_position().get()
    }) else {
        return Err(
            DurableTransactionRestartWalRetentionEvidenceError::RequirementNotRecordBoundary {
                cause,
                position,
            },
        );
    };
    let actual = observations[index].restart_position().clone();
    if !lineage.same_lineage(actual.lineage()) {
        return Err(
            DurableTransactionRestartWalRetentionEvidenceError::RequirementNotRecordBoundary {
                cause,
                position,
            },
        );
    }
    if retained_first_record
        .as_ref()
        .is_none_or(|retained| actual.get() < retained.get())
    {
        *retained_first_record = Some(actual.clone());
    }
    requirements.push(DurableTransactionRestartWalRetentionRequirement {
        position: actual,
        cause,
    });
    Ok(())
}

struct CompletedTransactionRestartWalRetentionEvidenceInput<'evidence, Observation, const N: usize>
{
    coordinator: &'evidence TransactionCoordinator,
    completion: &'evidence TransactionPageStorageRestartCheckpointCompletionEvidence<N>,
    lineage: &'evidence LogLineage,
    store_lineage: &'evidence LogLineage,
    durable_frontier: Option<&'evidence LogSequenceNumber>,
    observations: &'evidence [Observation],
    inventory: &'evidence [StoredPageSnapshotObservation<N>],
    metadata: &'evidence DurableTransactionRestartRetentionMetadataObservation,
}

fn analyze_completed_transaction_restart_wal_retention_evidence<const N: usize>(
    input: CompletedTransactionRestartWalRetentionEvidenceInput<
        '_,
        DurableTransactionRestartObservation<N>,
        N,
    >,
) -> Result<
    DurableTransactionRestartWalRetentionAnalysis,
    DurableTransactionRestartWalRetentionEvidenceError,
> {
    let fresh_analysis = analyze_durable_transaction_restart_evidence(
        input.lineage,
        input.durable_frontier,
        input.observations,
    )
    .map_err(
        |source| DurableTransactionRestartWalRetentionEvidenceError::RestartAnalysis {
            source: Box::new(source),
        },
    )?;
    derive_completed_transaction_restart_wal_retention_evidence(input, &fresh_analysis)
}

fn derive_completed_transaction_restart_wal_retention_evidence<Observation, const N: usize>(
    input: CompletedTransactionRestartWalRetentionEvidenceInput<'_, Observation, N>,
    fresh_analysis: &DurableTransactionRestartAnalysis,
) -> Result<
    DurableTransactionRestartWalRetentionAnalysis,
    DurableTransactionRestartWalRetentionEvidenceError,
>
where
    Observation: DurableTransactionRestartObservationView<N>,
{
    let CompletedTransactionRestartWalRetentionEvidenceInput {
        coordinator,
        completion,
        lineage,
        store_lineage,
        durable_frontier,
        observations,
        inventory,
        metadata,
    } = input;
    validate_completed_transaction_restart_evidence_parts(
        &completion.selected_baseline,
        &completion.current_analysis,
        coordinator,
        completion.transaction_summary(),
        fresh_analysis,
    )
    .map_err(
        |source| DurableTransactionRestartWalRetentionEvidenceError::Completion {
            source: Box::new(source),
        },
    )?;

    if !lineage.same_lineage(store_lineage) {
        return Err(
            DurableTransactionRestartWalRetentionEvidenceError::StoreLineageMismatch {
                expected: lineage.clone(),
                actual: store_lineage.clone(),
            },
        );
    }
    if !lineage.same_lineage(metadata.lineage()) {
        return Err(
            DurableTransactionRestartWalRetentionEvidenceError::MetadataLineageMismatch {
                expected: lineage.clone(),
                actual: metadata.lineage().clone(),
            },
        );
    }
    if metadata.allocated_epoch_high_water().get() != coordinator.epoch().get() {
        return Err(
            DurableTransactionRestartWalRetentionEvidenceError::AllocatedEpochHighWaterChanged {
                expected: coordinator.epoch().get(),
                actual: metadata.allocated_epoch_high_water().get(),
            },
        );
    }
    if let Some(position) = metadata.oldest_required_log_position()
        && !lineage.same_lineage(position.lineage())
    {
        return Err(
            DurableTransactionRestartWalRetentionEvidenceError::ForeignSourceConstraint {
                position: position.clone(),
            },
        );
    }
    validate_wal_retention_inventory_order(inventory)?;

    let page_number_capacity = observations.len().checked_add(inventory.len()).ok_or(
        DurableTransactionRestartWalRetentionEvidenceError::PageInventoryCountOverflow {
            record_count: observations.len(),
            store_page_count: inventory.len(),
        },
    )?;
    let mut page_numbers = Vec::new();
    page_numbers
        .try_reserve_exact(page_number_capacity)
        .map_err(|_| {
            DurableTransactionRestartWalRetentionEvidenceError::PageInventoryCapacityExhausted {
                capacity: page_number_capacity,
            }
        })?;
    for observation in observations {
        match observation.as_restart_observation_ref() {
            DurableTransactionRestartObservationRef::Page { page_number, .. }
            | DurableTransactionRestartObservationRef::TransactionPage { page_number, .. } => {
                page_numbers.push(page_number);
            }
            DurableTransactionRestartObservationRef::Commit { .. } => {}
        }
    }
    page_numbers.extend(
        inventory
            .iter()
            .map(StoredPageSnapshotObservation::page_number),
    );
    page_numbers.sort_unstable();
    page_numbers.dedup();

    let unresolved_count = fresh_analysis
        .transactions()
        .iter()
        .filter(|entry| matches!(entry.state(), DurableTransactionRestartState::Uncommitted))
        .count();
    let requirement_capacity = 2_usize
        .checked_add(inventory.len())
        .and_then(|capacity| capacity.checked_add(unresolved_count))
        .and_then(|capacity| {
            capacity.checked_add(usize::from(
                metadata.oldest_required_log_position().is_some(),
            ))
        })
        .ok_or(DurableTransactionRestartWalRetentionEvidenceError::RequirementCountOverflow)?;
    let mut requirements = Vec::new();
    requirements
        .try_reserve_exact(requirement_capacity)
        .map_err(|_| {
            DurableTransactionRestartWalRetentionEvidenceError::RequirementCapacityExhausted {
                capacity: requirement_capacity,
            }
        })?;
    let mut retained_first_record = None;

    if let Some(position) = completion.selected_baseline.durable_frontier() {
        push_wal_retention_requirement(
            lineage,
            durable_frontier,
            observations,
            position,
            DurableTransactionRestartWalRetentionRequirementCause::SelectedCheckpointFrontier,
            &mut requirements,
            &mut retained_first_record,
        )?;
    }
    if let Some(position) = completion.selected_baseline.replay_start().position() {
        let Some(cause) = completion.selected_baseline.replay_start().cause() else {
            return Err(
                DurableTransactionRestartWalRetentionEvidenceError::SelectedReplayCauseMissing {
                    position,
                },
            );
        };
        push_wal_retention_requirement(
            lineage,
            durable_frontier,
            observations,
            position,
            DurableTransactionRestartWalRetentionRequirementCause::SelectedReplayStart { cause },
            &mut requirements,
            &mut retained_first_record,
        )?;
    }

    for page_number in page_numbers {
        let required =
            latest_required_restart_page_image(fresh_analysis, page_number, observations).map_err(
                |source| {
                    DurableTransactionRestartWalRetentionEvidenceError::PageInventorySnapshot {
                        page_number,
                        source: Box::new(source),
                    }
                },
            )?;
        let snapshot = inventory
            .binary_search_by_key(&page_number, StoredPageSnapshotObservation::page_number)
            .ok()
            .map(|index| &inventory[index]);
        match (required, snapshot) {
            (None, None) => {}
            (None, Some(snapshot)) => {
                let stored_position = validate_restart_page_snapshot(
                    lineage,
                    fresh_analysis,
                    observations,
                    page_number,
                    snapshot,
                )
                .map_err(|source| {
                    DurableTransactionRestartWalRetentionEvidenceError::PageInventorySnapshot {
                        page_number,
                        source: Box::new(source),
                    }
                })?;
                return Err(
                    DurableTransactionRestartWalRetentionEvidenceError::UnexpectedPageSnapshotWithoutRequiredImage {
                        page_number,
                        stored_position,
                    },
                );
            }
            (Some(required), None) => {
                return Err(
                    DurableTransactionRestartWalRetentionEvidenceError::RequiredPageSnapshotMissing {
                        page_number,
                        required_position: required.page_position(),
                    },
                );
            }
            (Some(required), Some(snapshot)) => {
                let stored_position = validate_restart_page_snapshot(
                    lineage,
                    fresh_analysis,
                    observations,
                    page_number,
                    snapshot,
                )
                .map_err(|source| {
                    DurableTransactionRestartWalRetentionEvidenceError::PageInventorySnapshot {
                        page_number,
                        source: Box::new(source),
                    }
                })?;
                if stored_position != required.page_position() {
                    return Err(
                        DurableTransactionRestartWalRetentionEvidenceError::RequiredPageSnapshotBehind {
                            page_number,
                            stored_position,
                            required_position: required.page_position(),
                        },
                    );
                }
                push_wal_retention_requirement(
                    lineage,
                    durable_frontier,
                    observations,
                    stored_position,
                    DurableTransactionRestartWalRetentionRequirementCause::StoredPage {
                        page_number,
                    },
                    &mut requirements,
                    &mut retained_first_record,
                )?;
            }
        }
    }

    for entry in fresh_analysis.transactions() {
        if matches!(entry.state(), DurableTransactionRestartState::Uncommitted) {
            let transaction = entry.transaction();
            let Some(position) = entry
                .first_owned_page_position()
                .map(LogSequenceNumber::get)
            else {
                return Err(
                    DurableTransactionRestartWalRetentionEvidenceError::UnresolvedTransactionPositionMissing {
                        transaction,
                    },
                );
            };
            push_wal_retention_requirement(
                lineage,
                durable_frontier,
                observations,
                position,
                DurableTransactionRestartWalRetentionRequirementCause::UnresolvedTransaction {
                    transaction,
                },
                &mut requirements,
                &mut retained_first_record,
            )?;
        }
    }
    if let Some(position) = metadata.oldest_required_log_position() {
        push_wal_retention_requirement(
            lineage,
            durable_frontier,
            observations,
            position.get(),
            DurableTransactionRestartWalRetentionRequirementCause::SourceConstraint,
            &mut requirements,
            &mut retained_first_record,
        )?;
    }

    let floor = DurableTransactionRestartWalRetentionFloor {
        retained_first_record,
    };
    Ok(DurableTransactionRestartWalRetentionAnalysis {
        persistent_log_id: completion.persistent_log_id(),
        lineage: lineage.clone(),
        durable_frontier: durable_frontier.cloned(),
        allocated_epoch_high_water: metadata.allocated_epoch_high_water(),
        floor,
        requirements,
        store_page_count: inventory.len(),
        unresolved_transaction_count: unresolved_count,
    })
}

fn analyze_completed_transaction_restart_wal_retention<
    Source,
    Store,
    CheckpointSource,
    const N: usize,
>(
    mut completed: CompletedTransactionPageStorageRestartCheckpointReplay<
        Source,
        Store,
        CheckpointSource,
        N,
    >,
) -> Result<
    WalRetentionAnalyzedTransactionPageStorageRestartCheckpointReplay<
        Source,
        Store,
        CheckpointSource,
        N,
    >,
    FailedTransactionPageStorageRestartCheckpointWalRetentionAnalysis<
        Source,
        Store,
        CheckpointSource,
        N,
    >,
>
where
    Source: DurableTransactionRestartAnalysisSource<N>
        + DurableTransactionRestartRetentionMetadataSource,
    Store: DurablePageStoreInventorySource<N>,
{
    let inventory = match completed.store.durable_page_store_inventory() {
        Ok(inventory) => inventory,
        Err(source) => {
            return Err(
                FailedTransactionPageStorageRestartCheckpointWalRetentionAnalysis {
                    completed: Box::new(completed),
                    error: DurableTransactionRestartWalRetentionAnalysisError::StoreInventory(
                        source,
                    ),
                },
            );
        }
    };
    let store_lineage = completed.store.lineage().clone();
    let metadata = match completed.source.observe_restart_retention_metadata() {
        Ok(metadata) => metadata,
        Err(source) => {
            return Err(
                FailedTransactionPageStorageRestartCheckpointWalRetentionAnalysis {
                    completed: Box::new(completed),
                    error: DurableTransactionRestartWalRetentionAnalysisError::MetadataSource(
                        source,
                    ),
                },
            );
        }
    };
    let lineage = completed.source.lineage().clone();
    let analysis = match &completed.validation {
        SelectedRestartCheckpointValidation::CompletePrefix => {
            match completed
                .source
                .with_durable_transaction_restart_observations(|durable_frontier, observations| {
                    analyze_completed_transaction_restart_wal_retention_evidence(
                        CompletedTransactionRestartWalRetentionEvidenceInput {
                            coordinator: &completed.coordinator,
                            completion: &completed.evidence,
                            lineage: &lineage,
                            store_lineage: &store_lineage,
                            durable_frontier,
                            observations,
                            inventory: &inventory,
                            metadata: &metadata,
                        },
                    )
                }) {
                Ok(Ok(analysis)) => analysis,
                Ok(Err(source)) => {
                    return Err(
                        FailedTransactionPageStorageRestartCheckpointWalRetentionAnalysis {
                            completed: Box::new(completed),
                            error: wal_retention_evidence_error(source),
                        },
                    );
                }
                Err(source) => {
                    return Err(
                        FailedTransactionPageStorageRestartCheckpointWalRetentionAnalysis {
                            completed: Box::new(completed),
                            error: DurableTransactionRestartWalRetentionAnalysisError::WalSource(
                                source,
                            ),
                        },
                    );
                }
            }
        }
        SelectedRestartCheckpointValidation::Anchored { planner } => {
            let materialized = match planner(
                &mut completed.source,
                &completed.store,
                &completed.evidence.selected_baseline,
            ) {
                Ok(materialized) => materialized,
                Err(source) => {
                    return Err(
                        FailedTransactionPageStorageRestartCheckpointWalRetentionAnalysis {
                            completed: Box::new(completed),
                            error:
                                DurableTransactionRestartWalRetentionAnalysisError::ReplayPlanning(
                                    Box::new(source),
                                ),
                        },
                    );
                }
            };
            match derive_completed_transaction_restart_wal_retention_evidence(
                CompletedTransactionRestartWalRetentionEvidenceInput {
                    coordinator: &completed.coordinator,
                    completion: &completed.evidence,
                    lineage: &lineage,
                    store_lineage: &store_lineage,
                    durable_frontier: materialized.current_analysis.durable_frontier(),
                    observations: &materialized.retained_observations,
                    inventory: &inventory,
                    metadata: &metadata,
                },
                &materialized.current_analysis,
            ) {
                Ok(analysis) => analysis,
                Err(source) => {
                    return Err(
                        FailedTransactionPageStorageRestartCheckpointWalRetentionAnalysis {
                            completed: Box::new(completed),
                            error: wal_retention_evidence_error(source),
                        },
                    );
                }
            }
        }
    };
    Ok(
        WalRetentionAnalyzedTransactionPageStorageRestartCheckpointReplay {
            completed,
            analysis,
        },
    )
}

fn restart_checkpoint_completeness_baseline_matches_owned_observation(
    expected: &DurableTransactionRestartCheckpointCompletenessBaseline,
    actual: &OwnedDurableTransactionRestartCheckpointCompletenessBaselineObservation,
) -> bool {
    let transactions = actual.transactions();
    if transactions.persistent_log_id() != expected.persistent_log_id().get()
        || transactions.durable_frontier() != expected.durable_frontier()
        || transactions.transactions().len() != expected.transactions().len()
        || actual.pages().len() != expected.pages().len()
        || !restart_checkpoint_replay_matches_observation(expected.replay_start(), actual.replay())
    {
        return false;
    }
    if !expected
        .transactions()
        .iter()
        .zip(transactions.transactions())
        .all(|(expected, actual)| restart_checkpoint_entry_matches_observation(expected, *actual))
    {
        return false;
    }
    expected
        .pages()
        .iter()
        .zip(actual.pages())
        .all(|(expected, actual)| {
            restart_checkpoint_page_entry_matches_observation(expected, *actual)
        })
}

fn restart_wal_retention_analyses_match(
    expected: &DurableTransactionRestartWalRetentionAnalysis,
    actual: &DurableTransactionRestartWalRetentionAnalysis,
) -> bool {
    expected.persistent_log_id == actual.persistent_log_id
        && expected.lineage.same_lineage(&actual.lineage)
        && expected.durable_frontier == actual.durable_frontier
        && expected.floor.retained_first_record == actual.floor.retained_first_record
        && expected.allocated_epoch_high_water == actual.allocated_epoch_high_water
        && expected.store_page_count == actual.store_page_count
        && expected.unresolved_transaction_count == actual.unresolved_transaction_count
        && expected.requirements.len() == actual.requirements.len()
        && expected
            .requirements
            .iter()
            .zip(&actual.requirements)
            .all(|(expected, actual)| {
                expected.position == actual.position && expected.cause == actual.cause
            })
}

fn restart_wal_reclamation_source_observations_match(
    expected: &DurableTransactionRestartWalReclamationSourceObservation,
    actual: &DurableTransactionRestartWalReclamationSourceObservation,
) -> bool {
    expected.lineage.same_lineage(&actual.lineage)
        && expected.physical_format_version == actual.physical_format_version
        && expected.source_generation == actual.source_generation
        && expected.retained_first_logical_record == actual.retained_first_logical_record
        && expected.logical_position_high_water == actual.logical_position_high_water
        && expected.allocated_epoch_high_water == actual.allocated_epoch_high_water
        && expected.selected_checkpoint_anchor == actual.selected_checkpoint_anchor
}

struct RestartWalReclamationPermitInput {
    persistent_log_id: PersistentLogId,
    lineage: LogLineage,
    durable_frontier: Option<LogSequenceNumber>,
    retained_first_logical_record: Option<LogSequenceNumber>,
    allocated_epoch_high_water: NonZeroU64,
    physical_format_version: NonZeroU16,
    source_generation: u64,
    selected_checkpoint_anchor: DurableTransactionRestartSelectedCheckpointAnchor,
}

fn with_restart_wal_reclamation_permit<Output, Operation>(
    input: RestartWalReclamationPermitInput,
    operation: Operation,
) -> Output
where
    Operation:
        for<'attempt> FnOnce(DurableTransactionRestartWalReclamationPermit<'attempt>) -> Output,
{
    operation(DurableTransactionRestartWalReclamationPermit {
        persistent_log_id: input.persistent_log_id,
        lineage: input.lineage,
        durable_frontier: input.durable_frontier,
        retained_first_logical_record: input.retained_first_logical_record,
        allocated_epoch_high_water: input.allocated_epoch_high_water,
        physical_format_version: input.physical_format_version,
        source_generation: input.source_generation,
        selected_checkpoint_anchor: input.selected_checkpoint_anchor,
        attempt_brand: PhantomData,
    })
}

struct RestartWalReclamationValidatedPreflight<const N: usize> {
    source_physical_format_version: NonZeroU16,
    source_generation: u64,
    selected_checkpoint_anchor: DurableTransactionRestartSelectedCheckpointAnchor,
    retained_logical_record_count: u64,
    retained_observations: Vec<OwnedDurableTransactionRestartReplayObservation<N>>,
}

fn validate_restart_wal_reclamation_source_evidence<Observation, const N: usize>(
    frozen: &DurableTransactionRestartWalRetentionAnalysis,
    source: &DurableTransactionRestartWalReclamationSourceObservation,
    observations: &[Observation],
    selected_checkpoint_anchor: DurableTransactionRestartSelectedCheckpointAnchor,
) -> Result<
    RestartWalReclamationValidatedPreflight<N>,
    DurableTransactionRestartWalReclamationEvidenceError,
>
where
    Observation: DurableTransactionRestartObservationView<N>,
{
    if !frozen.lineage.same_lineage(source.lineage()) {
        return Err(
            DurableTransactionRestartWalReclamationEvidenceError::SourceLineageMismatch {
                expected: frozen.lineage.clone(),
                actual: source.lineage().clone(),
            },
        );
    }
    let Some(physical_format_version) = NonZeroU16::new(source.physical_format_version()) else {
        return Err(
            DurableTransactionRestartWalReclamationEvidenceError::ZeroPhysicalFormatVersion,
        );
    };
    for position in [
        source.retained_first_logical_record(),
        source.logical_position_high_water(),
    ]
    .into_iter()
    .flatten()
    {
        if !frozen.lineage.same_lineage(position.lineage()) {
            return Err(
                DurableTransactionRestartWalReclamationEvidenceError::ForeignSourcePosition {
                    position: position.clone(),
                },
            );
        }
    }
    let expected_high_water = frozen.durable_frontier();
    let actual_high_water = source
        .logical_position_high_water()
        .map(LogSequenceNumber::get);
    if actual_high_water != expected_high_water {
        return Err(
            DurableTransactionRestartWalReclamationEvidenceError::SourceLogicalHighWaterChanged {
                expected: expected_high_water,
                actual: actual_high_water,
            },
        );
    }
    let expected_first = observations
        .first()
        .map(DurableTransactionRestartObservationView::restart_position)
        .map(LogSequenceNumber::get);
    let actual_first = source
        .retained_first_logical_record()
        .map(LogSequenceNumber::get);
    if actual_first != expected_first {
        return Err(
            DurableTransactionRestartWalReclamationEvidenceError::SourceRetainedFirstRecordChanged {
                expected: expected_first,
                actual: actual_first,
            },
        );
    }
    if let (Some(retained_first), Some(floor)) = (
        actual_first,
        frozen
            .floor
            .retained_first_record
            .as_ref()
            .map(LogSequenceNumber::get),
    ) && retained_first > floor
    {
        return Err(
            DurableTransactionRestartWalReclamationEvidenceError::SourceAlreadyPrunedPastFloor {
                retained_first,
                floor,
            },
        );
    }
    if source.allocated_epoch_high_water() != frozen.allocated_epoch_high_water {
        return Err(
            DurableTransactionRestartWalReclamationEvidenceError::SourceAllocatedEpochHighWaterChanged {
                expected: frozen.allocated_epoch_high_water.get(),
                actual: source.allocated_epoch_high_water().get(),
            },
        );
    }
    let anchor_matches = match (
        source.source_generation(),
        source.selected_checkpoint_anchor,
    ) {
        (0, None) => true,
        (0, Some(_)) => false,
        (_, Some(actual)) => actual == selected_checkpoint_anchor,
        (_, None) => false,
    };
    if !anchor_matches {
        return Err(
            DurableTransactionRestartWalReclamationEvidenceError::SelectedCheckpointAnchorChanged {
                expected: selected_checkpoint_anchor,
                actual: source.selected_checkpoint_anchor,
            },
        );
    }
    if source.source_generation() == u64::MAX {
        return Err(
            DurableTransactionRestartWalReclamationEvidenceError::SourceGenerationExhausted {
                generation: source.source_generation(),
            },
        );
    }
    let retained_record_count = match &frozen.floor.retained_first_record {
        None => 0,
        Some(floor) => observations
            .iter()
            .filter(|observation| observation.restart_position().get() >= floor.get())
            .count(),
    };
    let retained_logical_record_count = u64::try_from(retained_record_count).map_err(|_| {
        DurableTransactionRestartWalReclamationEvidenceError::RetainedLogicalRecordCountWidthExceeded {
            record_count: retained_record_count,
        }
    })?;
    let mut retained_observations = Vec::new();
    retained_observations
        .try_reserve_exact(retained_record_count)
        .map_err(|_| {
            DurableTransactionRestartWalReclamationEvidenceError::RetainedObservationCapacityExhausted {
                record_count: retained_record_count,
            }
        })?;
    if let Some(floor) = &frozen.floor.retained_first_record {
        retained_observations.extend(
            observations
                .iter()
                .filter(|observation| observation.restart_position().get() >= floor.get())
                .map(
                    OwnedDurableTransactionRestartReplayObservation::from_restart_observation_view,
                ),
        );
    }
    Ok(RestartWalReclamationValidatedPreflight {
        source_physical_format_version: physical_format_version,
        source_generation: source.source_generation(),
        selected_checkpoint_anchor,
        retained_logical_record_count,
        retained_observations,
    })
}

fn effect_position_value(
    position: Option<&LogSequenceNumber>,
    lineage: &LogLineage,
) -> Result<Option<u64>, DurableTransactionRestartWalReclamationEvidenceError> {
    match position {
        Some(position) if !lineage.same_lineage(position.lineage()) => Err(
            DurableTransactionRestartWalReclamationEvidenceError::ForeignSourcePosition {
                position: position.clone(),
            },
        ),
        Some(position) => Ok(Some(position.get())),
        None => Ok(None),
    }
}

fn validate_restart_wal_reclamation_effect<const N: usize>(
    frozen: &DurableTransactionRestartWalRetentionAnalysis,
    validated: &RestartWalReclamationValidatedPreflight<N>,
    effect: DurableTransactionRestartWalReclamationEffectObservation,
) -> Result<
    DurableTransactionRestartWalReclamationReceipt,
    DurableTransactionRestartWalReclamationEvidenceError,
> {
    let expected_new_generation = validated.source_generation + 1;
    if effect.replacement.old_generation != validated.source_generation
        || effect.replacement.new_generation != expected_new_generation
    {
        return Err(
            DurableTransactionRestartWalReclamationEvidenceError::EffectGenerationChanged {
                expected_old: validated.source_generation,
                actual_old: effect.replacement.old_generation,
                actual_new: effect.replacement.new_generation,
            },
        );
    }
    let Some(replacement_physical_format_version) =
        NonZeroU16::new(effect.replacement.physical_format_version)
    else {
        return Err(
            DurableTransactionRestartWalReclamationEvidenceError::EffectPhysicalFormatVersionZero,
        );
    };
    let actual_first = effect_position_value(
        effect.retained_first_logical_record.as_ref(),
        &frozen.lineage,
    )?;
    let expected_first = frozen
        .floor
        .retained_first_record
        .as_ref()
        .map(LogSequenceNumber::get);
    if actual_first != expected_first {
        return Err(
            DurableTransactionRestartWalReclamationEvidenceError::EffectRetainedFirstRecordChanged {
                expected: expected_first,
                actual: actual_first,
            },
        );
    }
    let actual_high_water =
        effect_position_value(effect.logical_position_high_water.as_ref(), &frozen.lineage)?;
    if actual_high_water != frozen.durable_frontier() {
        return Err(
            DurableTransactionRestartWalReclamationEvidenceError::EffectLogicalHighWaterChanged {
                expected: frozen.durable_frontier(),
                actual: actual_high_water,
            },
        );
    }
    if effect.allocated_epoch_high_water != frozen.allocated_epoch_high_water {
        return Err(
            DurableTransactionRestartWalReclamationEvidenceError::EffectAllocatedEpochHighWaterChanged {
                expected: frozen.allocated_epoch_high_water.get(),
                actual: effect.allocated_epoch_high_water.get(),
            },
        );
    }
    if effect.retained_logical_record_count != validated.retained_logical_record_count {
        return Err(
            DurableTransactionRestartWalReclamationEvidenceError::EffectLogicalRecordCountChanged {
                expected: validated.retained_logical_record_count,
                actual: effect.retained_logical_record_count,
            },
        );
    }
    if effect.retained_logical_record_count != 0 && effect.retained_physical_unit_count == 0 {
        return Err(
            DurableTransactionRestartWalReclamationEvidenceError::EffectPhysicalUnitCountEmpty {
                retained_logical_record_count: effect.retained_logical_record_count,
            },
        );
    }
    Ok(DurableTransactionRestartWalReclamationReceipt {
        persistent_log_id: frozen.persistent_log_id,
        source_physical_format_version: validated.source_physical_format_version,
        replacement_physical_format_version,
        selected_checkpoint_anchor: validated.selected_checkpoint_anchor,
        effect,
    })
}

fn validate_installed_restart_wal_reclamation_source<const N: usize>(
    frozen: &DurableTransactionRestartWalRetentionAnalysis,
    validated: &RestartWalReclamationValidatedPreflight<N>,
    receipt: &DurableTransactionRestartWalReclamationReceipt,
    installed: &DurableTransactionRestartWalReclamationSourceObservation,
) -> Result<(), DurableTransactionRestartWalReclamationEvidenceError> {
    if !frozen.lineage.same_lineage(installed.lineage()) {
        return Err(
            DurableTransactionRestartWalReclamationEvidenceError::SourceLineageMismatch {
                expected: frozen.lineage.clone(),
                actual: installed.lineage().clone(),
            },
        );
    }
    let expected_generation = validated.source_generation + 1;
    if installed.source_generation() != expected_generation {
        return Err(
            DurableTransactionRestartWalReclamationEvidenceError::InstalledGenerationChanged {
                expected: expected_generation,
                actual: installed.source_generation(),
            },
        );
    }
    let expected_format = receipt.replacement_physical_format_version();
    if installed.physical_format_version() != expected_format {
        return Err(
            DurableTransactionRestartWalReclamationEvidenceError::InstalledPhysicalFormatVersionChanged {
                expected: expected_format,
                actual: installed.physical_format_version(),
            },
        );
    }
    let expected_first = frozen
        .floor
        .retained_first_record
        .as_ref()
        .map(LogSequenceNumber::get);
    let actual_first =
        effect_position_value(installed.retained_first_logical_record(), &frozen.lineage)?;
    if actual_first != expected_first {
        return Err(
            DurableTransactionRestartWalReclamationEvidenceError::SourceRetainedFirstRecordChanged {
                expected: expected_first,
                actual: actual_first,
            },
        );
    }
    let expected_high_water = frozen.durable_frontier();
    let actual_high_water =
        effect_position_value(installed.logical_position_high_water(), &frozen.lineage)?;
    if actual_high_water != expected_high_water {
        return Err(
            DurableTransactionRestartWalReclamationEvidenceError::SourceLogicalHighWaterChanged {
                expected: expected_high_water,
                actual: actual_high_water,
            },
        );
    }
    if installed.allocated_epoch_high_water() != frozen.allocated_epoch_high_water {
        return Err(
            DurableTransactionRestartWalReclamationEvidenceError::SourceAllocatedEpochHighWaterChanged {
                expected: frozen.allocated_epoch_high_water.get(),
                actual: installed.allocated_epoch_high_water().get(),
            },
        );
    }
    if installed.selected_checkpoint_anchor != Some(validated.selected_checkpoint_anchor) {
        return Err(
            DurableTransactionRestartWalReclamationEvidenceError::SelectedCheckpointAnchorChanged {
                expected: validated.selected_checkpoint_anchor,
                actual: installed.selected_checkpoint_anchor,
            },
        );
    }
    Ok(())
}

fn validate_installed_restart_wal_retained_observations<const N: usize>(
    expected: &[OwnedDurableTransactionRestartReplayObservation<N>],
    actual: &[DurableTransactionRestartObservation<N>],
) -> Result<(), DurableTransactionRestartWalReclamationEvidenceError> {
    if actual.len() != expected.len() {
        return Err(
            DurableTransactionRestartWalReclamationEvidenceError::InstalledRetainedRecordCountChanged {
                expected: expected.len(),
                actual: actual.len(),
            },
        );
    }
    for (index, (expected, actual)) in expected.iter().zip(actual).enumerate() {
        let actual = OwnedDurableTransactionRestartReplayObservation::from(actual);
        if *expected != actual {
            return Err(
                DurableTransactionRestartWalReclamationEvidenceError::InstalledRetainedRecordChanged {
                    index,
                    expected_position: owned_replay_observation_position(expected).get(),
                    actual_position: owned_replay_observation_position(&actual).get(),
                },
            );
        }
    }
    Ok(())
}

fn reclaim_analyzed_transaction_restart_wal_prefix<
    Source,
    Store,
    CheckpointSource,
    const N: usize,
>(
    analyzed: WalRetentionAnalyzedTransactionPageStorageRestartCheckpointReplay<
        Source,
        Store,
        CheckpointSource,
        N,
    >,
) -> Result<
    ReclaimedTransactionPageStorageRestartCheckpointReplay<Source, Store, CheckpointSource, N>,
    FailedTransactionPageStorageRestartCheckpointWalReclamation<Source, Store, CheckpointSource, N>,
>
where
    Source: DurableTransactionRestartAnalysisSource<N>
        + DurableTransactionRestartRetentionMetadataSource
        + DurableTransactionRestartPrunedGenerationSource<N>
        + DurableTransactionRestartWalReclamationSource<N>,
    Store: DurablePageStoreInventorySource<N>,
    CheckpointSource: DurableTransactionRestartCheckpointCompletenessBaselineSource
        + DurableTransactionRestartCheckpointCompletenessBaselinePublisher,
{
    let mut analyzed = Box::new(analyzed);
    let checkpoint = match analyzed
        .completed
        .checkpoint_source
        .load_restart_checkpoint_completeness_baseline()
    {
        Ok(Some(checkpoint)) => checkpoint,
        Ok(None) => {
            return Err(FailedTransactionPageStorageRestartCheckpointWalReclamation {
                analyzed,
                error: DurableTransactionRestartWalReclamationError::Preflight(
                    DurableTransactionRestartWalReclamationPreflightError::CurrentCheckpointMissing,
                ),
            });
        }
        Err(source) => {
            return Err(
                FailedTransactionPageStorageRestartCheckpointWalReclamation {
                    analyzed,
                    error: DurableTransactionRestartWalReclamationError::Preflight(
                        DurableTransactionRestartWalReclamationPreflightError::CheckpointSource(
                            source,
                        ),
                    ),
                },
            );
        }
    };
    if !restart_checkpoint_completeness_baseline_matches_owned_observation(
        &analyzed.completed.evidence.selected_baseline,
        &checkpoint,
    ) {
        return Err(FailedTransactionPageStorageRestartCheckpointWalReclamation {
            analyzed,
            error: DurableTransactionRestartWalReclamationError::Preflight(
                DurableTransactionRestartWalReclamationPreflightError::Evidence(Box::new(
                    DurableTransactionRestartWalReclamationEvidenceError::CurrentCheckpointChanged,
                )),
            ),
        });
    }
    let inventory = match analyzed.completed.store.durable_page_store_inventory() {
        Ok(inventory) => inventory,
        Err(source) => {
            return Err(
                FailedTransactionPageStorageRestartCheckpointWalReclamation {
                    analyzed,
                    error: DurableTransactionRestartWalReclamationError::Preflight(
                        DurableTransactionRestartWalReclamationPreflightError::StoreInventory(
                            source,
                        ),
                    ),
                },
            );
        }
    };
    let store_lineage = analyzed.completed.store.lineage().clone();
    let metadata =
        match analyzed
            .completed
            .source
            .observe_restart_retention_metadata()
        {
            Ok(metadata) => metadata,
            Err(source) => {
                return Err(FailedTransactionPageStorageRestartCheckpointWalReclamation {
                analyzed,
                error: DurableTransactionRestartWalReclamationError::Preflight(
                    DurableTransactionRestartWalReclamationPreflightError::RetentionMetadata(
                        source,
                    ),
                ),
            });
            }
        };
    let reclamation_source =
        match analyzed
            .completed
            .source
            .observe_restart_wal_reclamation_source()
        {
            Ok(observation) => observation,
            Err(source) => {
                return Err(FailedTransactionPageStorageRestartCheckpointWalReclamation {
                analyzed,
                error: DurableTransactionRestartWalReclamationError::Preflight(
                    DurableTransactionRestartWalReclamationPreflightError::ReclamationSource(
                        source,
                    ),
                ),
            });
            }
        };
    let lineage = analyzed.completed.source.lineage().clone();
    let selected_checkpoint_anchor =
        selected_restart_checkpoint_anchor(&analyzed.completed.evidence.selected_baseline);
    if reclamation_source.source_generation() == u64::MAX {
        return Err(FailedTransactionPageStorageRestartCheckpointWalReclamation {
            analyzed,
            error: DurableTransactionRestartWalReclamationError::Preflight(
                DurableTransactionRestartWalReclamationPreflightError::Evidence(Box::new(
                    DurableTransactionRestartWalReclamationEvidenceError::SourceGenerationExhausted {
                        generation: u64::MAX,
                    },
                )),
            ),
        });
    }
    let validated = match &analyzed.completed.validation {
        SelectedRestartCheckpointValidation::CompletePrefix => {
            let validation = analyzed
                .completed
                .source
                .with_durable_transaction_restart_observations(
                    |durable_frontier, observations| {
                        let fresh = analyze_completed_transaction_restart_wal_retention_evidence(
                            CompletedTransactionRestartWalRetentionEvidenceInput {
                                coordinator: &analyzed.completed.coordinator,
                                completion: &analyzed.completed.evidence,
                                lineage: &lineage,
                                store_lineage: &store_lineage,
                                durable_frontier,
                                observations,
                                inventory: &inventory,
                                metadata: &metadata,
                            },
                        )
                        .map_err(|source| {
                            DurableTransactionRestartWalReclamationEvidenceError::FreshRetention(
                                Box::new(source),
                            )
                        })?;
                        if !restart_wal_retention_analyses_match(&analyzed.analysis, &fresh) {
                            return Err(
                                DurableTransactionRestartWalReclamationEvidenceError::FrozenRetentionAnalysisChanged,
                            );
                        }
                        validate_restart_wal_reclamation_source_evidence(
                            &analyzed.analysis,
                            &reclamation_source,
                            observations,
                            selected_checkpoint_anchor,
                        )
                    },
                );
            match validation {
                Ok(Ok(validated)) => validated,
                Ok(Err(source)) => {
                    return Err(
                        FailedTransactionPageStorageRestartCheckpointWalReclamation {
                            analyzed,
                            error: DurableTransactionRestartWalReclamationError::Preflight(
                                DurableTransactionRestartWalReclamationPreflightError::Evidence(
                                    Box::new(source),
                                ),
                            ),
                        },
                    );
                }
                Err(source) => {
                    return Err(
                        FailedTransactionPageStorageRestartCheckpointWalReclamation {
                            analyzed,
                            error: DurableTransactionRestartWalReclamationError::Preflight(
                                DurableTransactionRestartWalReclamationPreflightError::WalSource(
                                    source,
                                ),
                            ),
                        },
                    );
                }
            }
        }
        SelectedRestartCheckpointValidation::Anchored { planner } => {
            let materialized = match planner(
                &mut analyzed.completed.source,
                &analyzed.completed.store,
                &analyzed.completed.evidence.selected_baseline,
            ) {
                Ok(materialized) => materialized,
                Err(source) => {
                    return Err(
                        FailedTransactionPageStorageRestartCheckpointWalReclamation {
                            analyzed,
                            error: DurableTransactionRestartWalReclamationError::Preflight(
                                DurableTransactionRestartWalReclamationPreflightError::ReplayPlanning(
                                    Box::new(source),
                                ),
                            ),
                        },
                    );
                }
            };
            let fresh = match derive_completed_transaction_restart_wal_retention_evidence(
                CompletedTransactionRestartWalRetentionEvidenceInput {
                    coordinator: &analyzed.completed.coordinator,
                    completion: &analyzed.completed.evidence,
                    lineage: &lineage,
                    store_lineage: &store_lineage,
                    durable_frontier: materialized.current_analysis.durable_frontier(),
                    observations: &materialized.retained_observations,
                    inventory: &inventory,
                    metadata: &metadata,
                },
                &materialized.current_analysis,
            ) {
                Ok(fresh) => fresh,
                Err(source) => {
                    return Err(
                        FailedTransactionPageStorageRestartCheckpointWalReclamation {
                            analyzed,
                            error: DurableTransactionRestartWalReclamationError::Preflight(
                                DurableTransactionRestartWalReclamationPreflightError::Evidence(
                                    Box::new(
                                        DurableTransactionRestartWalReclamationEvidenceError::FreshRetention(
                                            Box::new(source),
                                        ),
                                    ),
                                ),
                            ),
                        },
                    );
                }
            };
            if !restart_wal_retention_analyses_match(&analyzed.analysis, &fresh) {
                return Err(
                    FailedTransactionPageStorageRestartCheckpointWalReclamation {
                        analyzed,
                        error: DurableTransactionRestartWalReclamationError::Preflight(
                            DurableTransactionRestartWalReclamationPreflightError::Evidence(
                                Box::new(
                                    DurableTransactionRestartWalReclamationEvidenceError::FrozenRetentionAnalysisChanged,
                                ),
                            ),
                        ),
                    },
                );
            }
            match validate_restart_wal_reclamation_source_evidence(
                &analyzed.analysis,
                &reclamation_source,
                &materialized.retained_observations,
                selected_checkpoint_anchor,
            ) {
                Ok(validated) => validated,
                Err(source) => {
                    return Err(
                        FailedTransactionPageStorageRestartCheckpointWalReclamation {
                            analyzed,
                            error: DurableTransactionRestartWalReclamationError::Preflight(
                                DurableTransactionRestartWalReclamationPreflightError::Evidence(
                                    Box::new(source),
                                ),
                            ),
                        },
                    );
                }
            }
        }
    };
    let reobserved_source =
        match analyzed
            .completed
            .source
            .observe_restart_wal_reclamation_source()
        {
            Ok(observation) => observation,
            Err(source) => {
                return Err(FailedTransactionPageStorageRestartCheckpointWalReclamation {
                analyzed,
                error: DurableTransactionRestartWalReclamationError::Preflight(
                    DurableTransactionRestartWalReclamationPreflightError::ReclamationSource(
                        source,
                    ),
                ),
            });
            }
        };
    if !restart_wal_reclamation_source_observations_match(&reclamation_source, &reobserved_source) {
        return Err(FailedTransactionPageStorageRestartCheckpointWalReclamation {
            analyzed,
            error: DurableTransactionRestartWalReclamationError::Preflight(
                DurableTransactionRestartWalReclamationPreflightError::Evidence(Box::new(
                    DurableTransactionRestartWalReclamationEvidenceError::SourceObservationChanged {
                        expected_generation: reclamation_source.source_generation(),
                        actual_generation: reobserved_source.source_generation(),
                    },
                )),
            ),
        });
    }

    let permit_input = RestartWalReclamationPermitInput {
        persistent_log_id: analyzed.analysis.persistent_log_id,
        lineage: analyzed.analysis.lineage.clone(),
        durable_frontier: analyzed.analysis.durable_frontier.clone(),
        retained_first_logical_record: analyzed.analysis.floor.retained_first_record.clone(),
        allocated_epoch_high_water: analyzed.analysis.allocated_epoch_high_water,
        physical_format_version: validated.source_physical_format_version,
        source_generation: validated.source_generation,
        selected_checkpoint_anchor: validated.selected_checkpoint_anchor,
    };
    let effect = with_restart_wal_reclamation_permit(permit_input, |permit| {
        analyzed.completed.source.reclaim_restart_wal_prefix(permit)
    });
    let effect =
        match effect {
            Ok(effect) => effect,
            Err(source) => {
                return Err(FailedTransactionPageStorageRestartCheckpointWalReclamation {
                analyzed,
                error: DurableTransactionRestartWalReclamationError::OutcomeIndeterminate(
                    DurableTransactionRestartWalReclamationOutcomeIndeterminateError::Effect(
                        source,
                    ),
                ),
            });
            }
        };
    let receipt =
        match validate_restart_wal_reclamation_effect(&analyzed.analysis, &validated, effect) {
            Ok(receipt) => receipt,
            Err(source) => {
                return Err(FailedTransactionPageStorageRestartCheckpointWalReclamation {
                    analyzed,
                    error: DurableTransactionRestartWalReclamationError::OutcomeIndeterminate(
                        DurableTransactionRestartWalReclamationOutcomeIndeterminateError::Receipt(
                            source,
                        ),
                    ),
                });
            }
        };
    let installed_source = match analyzed
        .completed
        .source
        .observe_restart_wal_reclamation_source()
    {
        Ok(source) => source,
        Err(source) => {
            return Err(FailedTransactionPageStorageRestartCheckpointWalReclamation {
                    analyzed,
                    error: DurableTransactionRestartWalReclamationError::OutcomeIndeterminate(
                        DurableTransactionRestartWalReclamationOutcomeIndeterminateError::InstalledSource(
                            source,
                        ),
                    ),
                });
        }
    };
    if let Err(source) = validate_installed_restart_wal_reclamation_source(
        &analyzed.analysis,
        &validated,
        &receipt,
        &installed_source,
    ) {
        return Err(
            FailedTransactionPageStorageRestartCheckpointWalReclamation {
                analyzed,
                error: DurableTransactionRestartWalReclamationError::OutcomeIndeterminate(
                    DurableTransactionRestartWalReclamationOutcomeIndeterminateError::InstalledEvidence(
                        source,
                    ),
                ),
            },
        );
    }
    let installed_records = analyzed
        .completed
        .source
        .with_durable_transaction_restart_retained_observations(|observations| {
            validate_installed_restart_wal_retained_observations(
                &validated.retained_observations,
                observations,
            )
        });
    match installed_records {
        Ok(Ok(())) => {}
        Ok(Err(source)) => {
            return Err(
                FailedTransactionPageStorageRestartCheckpointWalReclamation {
                    analyzed,
                    error: DurableTransactionRestartWalReclamationError::OutcomeIndeterminate(
                        DurableTransactionRestartWalReclamationOutcomeIndeterminateError::InstalledEvidence(
                            source,
                        ),
                    ),
                },
            );
        }
        Err(source) => {
            return Err(
                FailedTransactionPageStorageRestartCheckpointWalReclamation {
                    analyzed,
                    error: DurableTransactionRestartWalReclamationError::OutcomeIndeterminate(
                        DurableTransactionRestartWalReclamationOutcomeIndeterminateError::InstalledWal(
                            source,
                        ),
                    ),
                },
            );
        }
    }
    let reobserved_installed_source = match analyzed
        .completed
        .source
        .observe_restart_wal_reclamation_source()
    {
        Ok(source) => source,
        Err(source) => {
            return Err(FailedTransactionPageStorageRestartCheckpointWalReclamation {
                    analyzed,
                    error: DurableTransactionRestartWalReclamationError::OutcomeIndeterminate(
                        DurableTransactionRestartWalReclamationOutcomeIndeterminateError::InstalledSource(
                            source,
                        ),
                    ),
                });
        }
    };
    if !restart_wal_reclamation_source_observations_match(
        &installed_source,
        &reobserved_installed_source,
    ) {
        return Err(
            FailedTransactionPageStorageRestartCheckpointWalReclamation {
                analyzed,
                error: DurableTransactionRestartWalReclamationError::OutcomeIndeterminate(
                    DurableTransactionRestartWalReclamationOutcomeIndeterminateError::InstalledEvidence(
                        DurableTransactionRestartWalReclamationEvidenceError::SourceObservationChanged {
                            expected_generation: installed_source.source_generation(),
                            actual_generation: reobserved_installed_source.source_generation(),
                        },
                    ),
                ),
            },
        );
    }
    Ok(ReclaimedTransactionPageStorageRestartCheckpointReplay {
        analyzed: *analyzed,
        receipt,
    })
}

fn validate_restart_checkpoint_completeness_baseline_against_current_prefix<
    Source,
    Store,
    const N: usize,
>(
    source: &mut Source,
    store: &Store,
    checkpoint: &DurableTransactionRestartCheckpointCompletenessBaselineObservation<'_>,
) -> Result<
    DurableTransactionRestartCheckpointCompletenessBaseline,
    DurableTransactionRestartCheckpointCompletenessBaselineValidationError<
        Source::Error,
        Store::ObservationError,
    >,
>
where
    Source: DurableTransactionRestartAnalysisSource<N>,
    Store: DurablePageStoreSnapshotSource<N>,
{
    let lineage = source.lineage().clone();
    let store_lineage = store.lineage().clone();
    if !lineage.same_lineage(&store_lineage) {
        return Err(
            DurableTransactionRestartCheckpointCompletenessBaselineValidationError::LineageMismatch {
                source_lineage: lineage,
                store_lineage,
            },
        );
    }
    let Some(expected_id) = lineage.persistent_id() else {
        return Err(
            DurableTransactionRestartCheckpointCompletenessBaselineValidationError::Evidence(
                Box::new(
                    DurableTransactionRestartCheckpointCompletenessBaselineValidationEvidenceError::Baseline(
                        Box::new(
                            DurableTransactionRestartCheckpointBaselineValidationEvidenceError::CurrentPersistentLineageRequired,
                        ),
                    ),
                ),
            ),
        );
    };
    let transactions = checkpoint.transactions();
    let Some(actual_id) = PersistentLogId::new(transactions.persistent_log_id()) else {
        return Err(
            DurableTransactionRestartCheckpointCompletenessBaselineValidationError::Evidence(
                Box::new(
                    DurableTransactionRestartCheckpointCompletenessBaselineValidationEvidenceError::Baseline(
                        Box::new(
                            DurableTransactionRestartCheckpointBaselineValidationEvidenceError::ZeroPersistentLogId {
                                persistent_log_id: transactions.persistent_log_id(),
                            },
                        ),
                    ),
                ),
            ),
        );
    };
    if actual_id != expected_id {
        return Err(
            DurableTransactionRestartCheckpointCompletenessBaselineValidationError::Evidence(
                Box::new(
                    DurableTransactionRestartCheckpointCompletenessBaselineValidationEvidenceError::Baseline(
                        Box::new(
                            DurableTransactionRestartCheckpointBaselineValidationEvidenceError::ForeignPersistentLogId {
                                expected: expected_id,
                                actual: actual_id,
                            },
                        ),
                    ),
                ),
            ),
        );
    }
    if transactions.durable_frontier() == Some(0) {
        return Err(
            DurableTransactionRestartCheckpointCompletenessBaselineValidationError::Evidence(
                Box::new(
                    DurableTransactionRestartCheckpointCompletenessBaselineValidationEvidenceError::Baseline(
                        Box::new(
                            DurableTransactionRestartCheckpointBaselineValidationEvidenceError::ZeroCheckpointFrontier {
                                checkpoint_frontier: 0,
                            },
                        ),
                    ),
                ),
            ),
        );
    }

    match source.with_durable_transaction_restart_observations(|current_frontier, observations| {
        validate_restart_checkpoint_completeness_baseline_evidence::<Source::Error, Store, N>(
            &lineage,
            current_frontier,
            observations,
            store,
            checkpoint,
        )
    }) {
        Ok(Ok(baseline)) => Ok(baseline),
        Ok(Err(source)) => Err(
            DurableTransactionRestartCheckpointCompletenessBaselineValidationError::Evidence(
                Box::new(source),
            ),
        ),
        Err(source) => Err(
            DurableTransactionRestartCheckpointCompletenessBaselineValidationError::Source(source),
        ),
    }
}

/// Invalid decoded completeness evidence or current-prefix relationship.
///
/// `Baseline` reuses the exact ADR 0039 pre-callback identity/frontier checks
/// and shared selected-prefix rejection variants unchanged. `NestedTransaction`
/// separately reuses the same evidence type for a post-selection mismatch
/// between the decoded nested transaction observation and the authoritative
/// transaction baseline recomputed for the same selected prefix.
#[derive(Debug)]
pub enum DurableTransactionRestartCheckpointCompletenessBaselineValidationEvidenceError<
    SourceError,
    StoreError,
> {
    /// Reused ADR 0039 pre-callback identity/frontier or selected-prefix evidence.
    Baseline(Box<DurableTransactionRestartCheckpointBaselineValidationEvidenceError>),
    /// The selected-prefix completeness analysis or a page-store observation failed.
    CompletenessEvidence(Box<DurableTransactionRestartCompletenessError<SourceError, StoreError>>),
    /// The authoritative selected-prefix completeness baseline could not be prepared.
    BaselinePreparation(DurableTransactionRestartCheckpointBaselineError),
    /// The decoded nested transaction observation differs from authoritative evidence.
    NestedTransaction(Box<DurableTransactionRestartCheckpointBaselineValidationEvidenceError>),
    /// The decoded page table has a different length.
    PageCountMismatch {
        /// Number of pages recomputed from authoritative WAL and store evidence.
        expected: usize,
        /// Number of decoded page entries.
        actual: usize,
    },
    /// One decoded page entry differs from the authoritative entry at the same index.
    PageEntryMismatch {
        /// Zero-based page-number-sorted entry index.
        index: usize,
        /// Entry recomputed from authoritative WAL and store evidence.
        expected: Box<DurableTransactionRestartPageEntry>,
        /// Exact untrusted decoded page entry.
        actual: DurableTransactionRestartCheckpointCompletenessBaselinePageObservation,
    },
    /// The decoded replay-lower-bound fields differ from authoritative evidence.
    ReplayMismatch {
        /// Replay lower bound recomputed from authoritative WAL and store evidence.
        expected: Box<DurableTransactionRestartReplayStart>,
        /// Exact untrusted decoded replay fields.
        actual: DurableTransactionRestartCheckpointCompletenessBaselineReplayObservation,
    },
}

impl<SourceError: fmt::Display, StoreError: fmt::Display> fmt::Display
    for DurableTransactionRestartCheckpointCompletenessBaselineValidationEvidenceError<
        SourceError,
        StoreError,
    >
{
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::Baseline(source) => {
                write!(
                    formatter,
                    "restart checkpoint completeness baseline evidence is invalid: {source}"
                )
            }
            Self::CompletenessEvidence(source) => write!(
                formatter,
                "restart checkpoint completeness evidence is invalid: {source}"
            ),
            Self::BaselinePreparation(source) => write!(
                formatter,
                "authoritative restart checkpoint completeness baseline preparation failed: {source}"
            ),
            Self::NestedTransaction(source) => write!(
                formatter,
                "decoded restart checkpoint completeness transaction fields do not match authoritative evidence: {source}"
            ),
            Self::PageCountMismatch { expected, actual } => write!(
                formatter,
                "decoded restart checkpoint completeness has {actual} page entries, expected {expected}"
            ),
            Self::PageEntryMismatch {
                index,
                expected,
                actual,
            } => write!(
                formatter,
                "decoded restart checkpoint completeness page entry {index} (page {}) does not match authoritative page {}",
                actual.page_number(),
                expected.page_number().get()
            ),
            Self::ReplayMismatch { expected, actual } => write!(
                formatter,
                "decoded restart checkpoint completeness replay fields {actual:?} do not match authoritative replay {expected:?}"
            ),
        }
    }
}

impl<SourceError, StoreError> Error
    for DurableTransactionRestartCheckpointCompletenessBaselineValidationEvidenceError<
        SourceError,
        StoreError,
    >
where
    SourceError: Error + 'static,
    StoreError: Error + 'static,
{
    fn source(&self) -> Option<&(dyn Error + 'static)> {
        match self {
            Self::Baseline(source) => Some(source.as_ref()),
            Self::CompletenessEvidence(source) => Some(source.as_ref()),
            Self::BaselinePreparation(source) => Some(source),
            Self::NestedTransaction(source) => Some(source.as_ref()),
            Self::PageCountMismatch { .. }
            | Self::PageEntryMismatch { .. }
            | Self::ReplayMismatch { .. } => None,
        }
    }
}

/// Failure to read the current prefix or validate decoded completeness evidence.
///
/// A post-callback source error is authoritative even when the callback itself
/// already computed a candidate result: `Ok(Err(_))` from the source's own
/// method call is only possible when the callback ran and returned normally,
/// so `Source` and `Evidence` cannot both describe the same attempt.
#[derive(Debug)]
pub enum DurableTransactionRestartCheckpointCompletenessBaselineValidationError<
    SourceError,
    StoreError,
> {
    /// WAL and page-store sources do not protect one lineage; neither is observed.
    LineageMismatch {
        /// Durable restart source lineage.
        source_lineage: LogLineage,
        /// Page-store lineage.
        store_lineage: LogLineage,
    },
    /// The current durable-prefix source failed authoritatively.
    Source(SourceError),
    /// Decoded or source-relative completeness evidence was invalid.
    Evidence(
        Box<
            DurableTransactionRestartCheckpointCompletenessBaselineValidationEvidenceError<
                SourceError,
                StoreError,
            >,
        >,
    ),
}

impl<SourceError: fmt::Display, StoreError: fmt::Display> fmt::Display
    for DurableTransactionRestartCheckpointCompletenessBaselineValidationError<
        SourceError,
        StoreError,
    >
{
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::LineageMismatch { .. } => formatter.write_str(
                "restart-analysis source and page snapshot source belong to different lineages",
            ),
            Self::Source(source) => {
                write!(
                    formatter,
                    "restart checkpoint completeness validation source failed: {source}"
                )
            }
            Self::Evidence(source) => {
                write!(
                    formatter,
                    "restart checkpoint completeness validation failed: {source}"
                )
            }
        }
    }
}

impl<SourceError, StoreError> Error
    for DurableTransactionRestartCheckpointCompletenessBaselineValidationError<
        SourceError,
        StoreError,
    >
where
    SourceError: Error + 'static,
    StoreError: Error + 'static,
{
    fn source(&self) -> Option<&(dyn Error + 'static)> {
        match self {
            Self::Source(source) => Some(source),
            Self::Evidence(source) => Some(source.as_ref()),
            Self::LineageMismatch { .. } => None,
        }
    }
}

/// Invalid complete-prefix evidence supplied to restart analysis.
#[derive(Clone, Debug, Eq, PartialEq)]
pub enum DurableTransactionRestartAnalysisEvidenceError {
    /// A nonempty observation stream omitted its durable frontier.
    FrontierMissing {
        /// Number of supplied logical observations.
        record_count: usize,
    },
    /// A durable frontier was supplied for an empty logical-record stream.
    FrontierWithoutRecords {
        /// Unexpected supplied frontier.
        frontier: LogSequenceNumber,
    },
    /// The durable frontier belongs to another WAL lineage.
    ForeignFrontier {
        /// Rejected foreign frontier.
        frontier: LogSequenceNumber,
    },
    /// The nonempty durable frontier used the reserved zero position.
    ZeroFrontier {
        /// Rejected zero frontier.
        frontier: LogSequenceNumber,
    },
    /// One logical observation belongs to another WAL lineage.
    ForeignRecordLineage {
        /// Zero-based observation index.
        index: usize,
        /// Kind of the rejected observation.
        kind: DurableTransactionRestartObservationKind,
        /// Rejected foreign position.
        position: LogSequenceNumber,
    },
    /// Two identical adjacent observations claim one physical position.
    DuplicateRecordPosition {
        /// Zero-based index of the first observation.
        previous_index: usize,
        /// Zero-based index of the repeated observation.
        actual_index: usize,
        /// Kind shared by the identical observations.
        kind: DurableTransactionRestartObservationKind,
        /// Duplicated physical position.
        position: LogSequenceNumber,
    },
    /// Two different adjacent observations claim one physical position.
    ContradictoryRecordPosition {
        /// Zero-based index of the prior observation.
        previous_index: usize,
        /// Kind of the prior observation.
        previous_kind: DurableTransactionRestartObservationKind,
        /// Zero-based index of the contradictory observation.
        actual_index: usize,
        /// Kind of the contradictory observation.
        actual_kind: DurableTransactionRestartObservationKind,
        /// Contradictory physical position.
        position: LogSequenceNumber,
    },
    /// A later observation has a numerically lower physical position.
    NonAdvancingRecordPosition {
        /// Zero-based index of the prior observation.
        previous_index: usize,
        /// Prior physical position.
        previous: LogSequenceNumber,
        /// Zero-based index of the decreasing observation.
        actual_index: usize,
        /// Decreasing physical position.
        actual: LogSequenceNumber,
    },
    /// The last projected record does not equal the supplied durable frontier.
    TailFrontierMismatch {
        /// Supplied durable frontier.
        frontier: LogSequenceNumber,
        /// Actual final observation position.
        tail: LogSequenceNumber,
    },
    /// The owned transaction table could not reserve its complete upper bound.
    TransactionCapacityExhausted {
        /// Durable record count used as the transaction-count upper bound.
        record_count: usize,
    },
    /// One persisted identity has more than one durable commit.
    DuplicateCommit {
        /// Identity with contradictory commit records.
        transaction: DurableTransactionIdentityObservation,
        /// First durable commit position.
        first_commit_position: LogSequenceNumber,
        /// Later duplicate commit position.
        duplicate_commit_position: LogSequenceNumber,
    },
    /// A transaction-owned page occurs after the same identity's commit.
    PageAfterCommit {
        /// Identity whose post-commit page is invalid.
        transaction: DurableTransactionIdentityObservation,
        /// Earlier durable commit position.
        commit_position: LogSequenceNumber,
        /// Invalid later page position.
        page_position: LogSequenceNumber,
    },
    /// Counting one identity's owned pages exceeded `usize`.
    OwnedPageCountExhausted {
        /// Identity whose record count could not advance.
        transaction: DurableTransactionIdentityObservation,
    },
}

impl fmt::Display for DurableTransactionRestartAnalysisEvidenceError {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::FrontierMissing { record_count } => write!(
                formatter,
                "nonempty durable restart stream with {record_count} records has no frontier"
            ),
            Self::FrontierWithoutRecords { frontier } => write!(
                formatter,
                "durable restart frontier {} has no logical records",
                frontier.get()
            ),
            Self::ForeignFrontier { frontier } => write!(
                formatter,
                "durable restart frontier {} belongs to another lineage",
                frontier.get()
            ),
            Self::ZeroFrontier { .. } => {
                formatter.write_str("nonempty durable restart frontier must be nonzero")
            }
            Self::ForeignRecordLineage {
                index,
                kind,
                position,
            } => write!(
                formatter,
                "durable restart record {index} ({kind:?}) at position {} belongs to another lineage",
                position.get()
            ),
            Self::DuplicateRecordPosition {
                previous_index,
                actual_index,
                position,
                ..
            } => write!(
                formatter,
                "durable restart records {previous_index} and {actual_index} duplicate position {}",
                position.get()
            ),
            Self::ContradictoryRecordPosition {
                previous_index,
                actual_index,
                position,
                ..
            } => write!(
                formatter,
                "durable restart records {previous_index} and {actual_index} contradict at position {}",
                position.get()
            ),
            Self::NonAdvancingRecordPosition {
                previous_index,
                previous,
                actual_index,
                actual,
            } => write!(
                formatter,
                "durable restart record {actual_index} position {} does not advance beyond record {previous_index} position {}",
                actual.get(),
                previous.get()
            ),
            Self::TailFrontierMismatch { frontier, tail } => write!(
                formatter,
                "durable restart tail position {} does not equal frontier {}",
                tail.get(),
                frontier.get()
            ),
            Self::TransactionCapacityExhausted { record_count } => write!(
                formatter,
                "durable restart transaction capacity is exhausted for {record_count} records"
            ),
            Self::DuplicateCommit {
                transaction,
                first_commit_position,
                duplicate_commit_position,
            } => write!(
                formatter,
                "transaction {transaction} has duplicate commits at positions {} and {}",
                first_commit_position.get(),
                duplicate_commit_position.get()
            ),
            Self::PageAfterCommit {
                transaction,
                commit_position,
                page_position,
            } => write!(
                formatter,
                "transaction {transaction} page at position {} follows commit at position {}",
                page_position.get(),
                commit_position.get()
            ),
            Self::OwnedPageCountExhausted { transaction } => write!(
                formatter,
                "transaction {transaction} owned-page record count is exhausted"
            ),
        }
    }
}

impl Error for DurableTransactionRestartAnalysisEvidenceError {}

/// Failure to obtain or analyze one complete durable restart prefix.
#[derive(Debug)]
pub enum DurableTransactionRestartAnalysisError<SourceError> {
    /// The source failed before returning authoritative stable-prefix evidence.
    Source(SourceError),
    /// The projected complete-prefix evidence was invalid.
    Evidence(Box<DurableTransactionRestartAnalysisEvidenceError>),
}

impl<SourceError: fmt::Display> fmt::Display
    for DurableTransactionRestartAnalysisError<SourceError>
{
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::Source(source) => write!(formatter, "restart-analysis source failed: {source}"),
            Self::Evidence(source) => write!(formatter, "restart analysis failed: {source}"),
        }
    }
}

impl<SourceError> Error for DurableTransactionRestartAnalysisError<SourceError>
where
    SourceError: Error + 'static,
{
    fn source(&self) -> Option<&(dyn Error + 'static)> {
        match self {
            Self::Source(source) => Some(source),
            Self::Evidence(source) => Some(source.as_ref()),
        }
    }
}

fn analyze_durable_transaction_restart_evidence<const N: usize>(
    lineage: &LogLineage,
    durable_frontier: Option<&LogSequenceNumber>,
    observations: &[DurableTransactionRestartObservation<N>],
) -> Result<DurableTransactionRestartAnalysis, DurableTransactionRestartAnalysisEvidenceError> {
    if let Some(frontier) = durable_frontier {
        if !lineage.same_lineage(frontier.lineage()) {
            return Err(
                DurableTransactionRestartAnalysisEvidenceError::ForeignFrontier {
                    frontier: frontier.clone(),
                },
            );
        }
        if frontier.get() == 0 {
            return Err(
                DurableTransactionRestartAnalysisEvidenceError::ZeroFrontier {
                    frontier: frontier.clone(),
                },
            );
        }
    }

    match (durable_frontier, observations.is_empty()) {
        (None, false) => {
            return Err(
                DurableTransactionRestartAnalysisEvidenceError::FrontierMissing {
                    record_count: observations.len(),
                },
            );
        }
        (Some(frontier), true) => {
            return Err(
                DurableTransactionRestartAnalysisEvidenceError::FrontierWithoutRecords {
                    frontier: frontier.clone(),
                },
            );
        }
        (None, true) => {
            return Ok(DurableTransactionRestartAnalysis {
                lineage: lineage.clone(),
                durable_frontier: None,
                transactions: Vec::new(),
            });
        }
        (Some(_), false) => {}
    }

    let mut previous: Option<(usize, &DurableTransactionRestartObservation<N>)> = None;
    for (index, observation) in observations.iter().enumerate() {
        let position = observation.position();
        if !lineage.same_lineage(position.lineage()) {
            return Err(
                DurableTransactionRestartAnalysisEvidenceError::ForeignRecordLineage {
                    index,
                    kind: observation.kind(),
                    position: position.clone(),
                },
            );
        }
        if let Some((previous_index, previous_observation)) = previous {
            let previous_position = previous_observation.position();
            if position.get() == previous_position.get() {
                if observation == previous_observation {
                    return Err(
                        DurableTransactionRestartAnalysisEvidenceError::DuplicateRecordPosition {
                            previous_index,
                            actual_index: index,
                            kind: observation.kind(),
                            position: position.clone(),
                        },
                    );
                }
                return Err(
                    DurableTransactionRestartAnalysisEvidenceError::ContradictoryRecordPosition {
                        previous_index,
                        previous_kind: previous_observation.kind(),
                        actual_index: index,
                        actual_kind: observation.kind(),
                        position: position.clone(),
                    },
                );
            }
            if position.get() < previous_position.get() {
                return Err(
                    DurableTransactionRestartAnalysisEvidenceError::NonAdvancingRecordPosition {
                        previous_index,
                        previous: previous_position.clone(),
                        actual_index: index,
                        actual: position.clone(),
                    },
                );
            }
        }
        previous = Some((index, observation));
    }

    let frontier = durable_frontier.ok_or(
        DurableTransactionRestartAnalysisEvidenceError::FrontierMissing {
            record_count: observations.len(),
        },
    )?;
    let tail = observations
        .last()
        .map(DurableTransactionRestartObservation::position);
    let Some(tail) = tail else {
        return Err(
            DurableTransactionRestartAnalysisEvidenceError::FrontierWithoutRecords {
                frontier: frontier.clone(),
            },
        );
    };
    if tail != frontier {
        return Err(
            DurableTransactionRestartAnalysisEvidenceError::TailFrontierMismatch {
                frontier: frontier.clone(),
                tail: tail.clone(),
            },
        );
    }

    let mut transactions: Vec<DurableTransactionRestartEntry> = Vec::new();
    transactions.try_reserve(observations.len()).map_err(|_| {
        DurableTransactionRestartAnalysisEvidenceError::TransactionCapacityExhausted {
            record_count: observations.len(),
        }
    })?;

    for observation in observations {
        match observation {
            DurableTransactionRestartObservation::Page(_) => {}
            DurableTransactionRestartObservation::TransactionPage(observation) => {
                let transaction = observation.owner();
                let page_position = observation.position();
                match transactions.binary_search_by_key(&transaction, |entry| entry.transaction) {
                    Ok(index) => {
                        let entry = &mut transactions[index];
                        if let DurableTransactionRestartState::Committed { commit_position } =
                            &entry.state
                        {
                            return Err(
                                DurableTransactionRestartAnalysisEvidenceError::PageAfterCommit {
                                    transaction,
                                    commit_position: commit_position.clone(),
                                    page_position: page_position.clone(),
                                },
                            );
                        }
                        entry.owned_page_record_count = entry
                            .owned_page_record_count
                            .checked_add(1)
                            .ok_or(
                                DurableTransactionRestartAnalysisEvidenceError::OwnedPageCountExhausted {
                                    transaction,
                                },
                            )?;
                        entry.last_owned_page_position = Some(page_position.clone());
                    }
                    Err(index) => transactions.insert(
                        index,
                        DurableTransactionRestartEntry {
                            transaction,
                            first_owned_page_position: Some(page_position.clone()),
                            last_owned_page_position: Some(page_position.clone()),
                            owned_page_record_count: 1,
                            state: DurableTransactionRestartState::Uncommitted,
                        },
                    ),
                }
            }
            DurableTransactionRestartObservation::Commit(observation) => {
                let transaction = observation.transaction();
                let commit_position = observation.position();
                match transactions.binary_search_by_key(&transaction, |entry| entry.transaction) {
                    Ok(index) => {
                        let entry = &mut transactions[index];
                        match &entry.state {
                            DurableTransactionRestartState::Uncommitted => {
                                entry.state = DurableTransactionRestartState::Committed {
                                    commit_position: commit_position.clone(),
                                };
                            }
                            DurableTransactionRestartState::Committed {
                                commit_position: first_commit_position,
                            } => {
                                return Err(
                                    DurableTransactionRestartAnalysisEvidenceError::DuplicateCommit {
                                        transaction,
                                        first_commit_position: first_commit_position.clone(),
                                        duplicate_commit_position: commit_position.clone(),
                                    },
                                );
                            }
                        }
                    }
                    Err(index) => transactions.insert(
                        index,
                        DurableTransactionRestartEntry {
                            transaction,
                            first_owned_page_position: None,
                            last_owned_page_position: None,
                            owned_page_record_count: 0,
                            state: DurableTransactionRestartState::Committed {
                                commit_position: commit_position.clone(),
                            },
                        },
                    ),
                }
            }
        }
    }

    Ok(DurableTransactionRestartAnalysis {
        lineage: lineage.clone(),
        durable_frontier: Some(frontier.clone()),
        transactions,
    })
}

/// Reconstructs one deterministic transaction table from a complete durable prefix.
///
/// The source callback is invoked at most once. Its complete unified stream is
/// validated before table allocation or transaction-specific classification.
pub fn analyze_durable_transaction_restart<Source, const N: usize>(
    source: &mut Source,
) -> Result<DurableTransactionRestartAnalysis, DurableTransactionRestartAnalysisError<Source::Error>>
where
    Source: DurableTransactionRestartAnalysisSource<N>,
{
    let lineage = source.lineage().clone();
    match source.with_durable_transaction_restart_observations(|durable_frontier, observations| {
        analyze_durable_transaction_restart_evidence(&lineage, durable_frontier, observations)
    }) {
        Ok(Ok(analysis)) => Ok(analysis),
        Ok(Err(source)) => Err(DurableTransactionRestartAnalysisError::Evidence(Box::new(
            source,
        ))),
        Err(source) => Err(DurableTransactionRestartAnalysisError::Source(source)),
    }
}

fn restart_transaction_entry(
    analysis: &DurableTransactionRestartAnalysis,
    page_number: PageNumber,
    transaction: DurableTransactionIdentityObservation,
    page_position: u64,
) -> Result<&DurableTransactionRestartEntry, DurableTransactionRestartCompletenessEvidenceError> {
    analysis
        .transactions
        .binary_search_by_key(&transaction, |entry| entry.transaction)
        .map(|index| &analysis.transactions[index])
        .map_err(|_| {
            DurableTransactionRestartCompletenessEvidenceError::OwnedPageTransactionMissing {
                page_number,
                transaction,
                page_position,
            }
        })
}

fn latest_required_restart_page_image<Observation, const N: usize>(
    analysis: &DurableTransactionRestartAnalysis,
    page_number: PageNumber,
    observations: &[Observation],
) -> Result<
    Option<DurableTransactionRestartRequiredPageImage>,
    DurableTransactionRestartCompletenessEvidenceError,
>
where
    Observation: DurableTransactionRestartObservationView<N>,
{
    let mut required = None;
    for observation in observations {
        match observation.as_restart_observation_ref() {
            DurableTransactionRestartObservationRef::Page {
                page_number: actual_page,
                position,
                ..
            } if actual_page == page_number => {
                required = Some(DurableTransactionRestartRequiredPageImage::Raw {
                    page_position: position.get(),
                });
            }
            DurableTransactionRestartObservationRef::TransactionPage {
                transaction,
                page_number: actual_page,
                position,
                ..
            } if actual_page == page_number => {
                let page_position = position.get();
                let entry =
                    restart_transaction_entry(analysis, page_number, transaction, page_position)?;
                if let DurableTransactionRestartState::Committed { commit_position } = entry.state()
                {
                    required = Some(
                        DurableTransactionRestartRequiredPageImage::CommittedTransaction {
                            transaction,
                            page_position,
                            commit_position: commit_position.get(),
                        },
                    );
                }
            }
            DurableTransactionRestartObservationRef::Page { .. }
            | DurableTransactionRestartObservationRef::TransactionPage { .. }
            | DurableTransactionRestartObservationRef::Commit { .. } => {}
        }
    }
    Ok(required)
}

fn snapshot_payload_matches<const N: usize>(
    snapshot: &StoredPageSnapshotObservation<N>,
    page_version: PageVersion,
    bytes: &[u8; N],
) -> bool {
    snapshot.page_version() == page_version && snapshot.image().bytes() == bytes
}

fn validate_restart_page_snapshot<Observation, const N: usize>(
    lineage: &LogLineage,
    analysis: &DurableTransactionRestartAnalysis,
    observations: &[Observation],
    page_number: PageNumber,
    snapshot: &StoredPageSnapshotObservation<N>,
) -> Result<u64, DurableTransactionRestartCompletenessEvidenceError>
where
    Observation: DurableTransactionRestartObservationView<N>,
{
    if snapshot.page_number() != page_number {
        return Err(
            DurableTransactionRestartCompletenessEvidenceError::UnexpectedSnapshotPage {
                expected: page_number,
                actual: snapshot.page_number(),
            },
        );
    }
    if !lineage.same_lineage(snapshot.required_position().lineage()) {
        return Err(
            DurableTransactionRestartCompletenessEvidenceError::ForeignSnapshotLineage {
                page_number,
                position: snapshot.required_position().clone(),
            },
        );
    }

    let Some(frontier) = analysis.durable_frontier() else {
        return Err(
            DurableTransactionRestartCompletenessEvidenceError::AnalyzedPageFrontierMissing {
                page_number,
            },
        );
    };
    let position = snapshot.required_position().get();
    if position > frontier.get() {
        return Err(
            DurableTransactionRestartCompletenessEvidenceError::SnapshotBeyondFrontier {
                page_number,
                position,
                frontier: frontier.get(),
            },
        );
    }

    let Ok(index) = observations.binary_search_by_key(&position, |observation| {
        observation.restart_position().get()
    }) else {
        return Err(
            DurableTransactionRestartCompletenessEvidenceError::SnapshotPositionUnbacked {
                page_number,
                position,
            },
        );
    };
    match observations[index].as_restart_observation_ref() {
        DurableTransactionRestartObservationRef::Page {
            page_number: actual_page,
            page_version,
            bytes,
            ..
        } if actual_page == page_number => {
            if !snapshot_payload_matches(snapshot, page_version, bytes) {
                return Err(
                    DurableTransactionRestartCompletenessEvidenceError::SnapshotPayloadContradiction {
                        page_number,
                        position,
                    },
                );
            }
        }
        DurableTransactionRestartObservationRef::TransactionPage {
            transaction,
            page_number: actual_page,
            page_version,
            bytes,
            ..
        } if actual_page == page_number => {
            if !snapshot_payload_matches(snapshot, page_version, bytes) {
                return Err(
                    DurableTransactionRestartCompletenessEvidenceError::SnapshotPayloadContradiction {
                        page_number,
                        position,
                    },
                );
            }
            let entry = restart_transaction_entry(analysis, page_number, transaction, position)?;
            if matches!(entry.state(), DurableTransactionRestartState::Uncommitted) {
                return Err(
                    DurableTransactionRestartCompletenessEvidenceError::SnapshotBackedByUncommittedTransactionPage {
                        page_number,
                        transaction,
                        page_position: position,
                    },
                );
            }
        }
        DurableTransactionRestartObservationRef::Page { .. }
        | DurableTransactionRestartObservationRef::TransactionPage { .. }
        | DurableTransactionRestartObservationRef::Commit { .. } => {
            return Err(
                DurableTransactionRestartCompletenessEvidenceError::SnapshotPositionUnbacked {
                    page_number,
                    position,
                },
            );
        }
    }
    Ok(position)
}

fn lower_restart_replay_start(
    current: &mut Option<(u64, DurableTransactionRestartReplayStartCause)>,
    position: u64,
    cause: DurableTransactionRestartReplayStartCause,
) {
    match current {
        Some((current_position, _)) if *current_position <= position => {}
        Some((current_position, current_cause)) => {
            *current_position = position;
            *current_cause = cause;
        }
        None => *current = Some((position, cause)),
    }
}

fn analyze_durable_transaction_restart_completeness_evidence<SourceError, Store, const N: usize>(
    lineage: &LogLineage,
    durable_frontier: Option<&LogSequenceNumber>,
    observations: &[DurableTransactionRestartObservation<N>],
    store: &Store,
) -> Result<
    DurableTransactionRestartCompletenessAnalysis,
    DurableTransactionRestartCompletenessError<SourceError, Store::ObservationError>,
>
where
    Store: DurablePageStoreSnapshotSource<N>,
{
    let transaction_analysis =
        analyze_durable_transaction_restart_evidence(lineage, durable_frontier, observations)
            .map_err(|source| {
                DurableTransactionRestartCompletenessError::Evidence(Box::new(
                    DurableTransactionRestartCompletenessEvidenceError::RestartAnalysis {
                        source: Box::new(source),
                    },
                ))
            })?;

    let mut page_numbers = Vec::new();
    page_numbers.try_reserve(observations.len()).map_err(|_| {
        DurableTransactionRestartCompletenessError::Evidence(Box::new(
            DurableTransactionRestartCompletenessEvidenceError::PageInventoryCapacityExhausted {
                record_count: observations.len(),
            },
        ))
    })?;
    for observation in observations {
        match observation {
            DurableTransactionRestartObservation::Page(observation) => {
                page_numbers.push(observation.page_number());
            }
            DurableTransactionRestartObservation::TransactionPage(observation) => {
                page_numbers.push(observation.page().page_number());
            }
            DurableTransactionRestartObservation::Commit(_) => {}
        }
    }
    page_numbers.sort_unstable();
    page_numbers.dedup();

    let mut pages = Vec::new();
    pages.try_reserve_exact(page_numbers.len()).map_err(|_| {
        DurableTransactionRestartCompletenessError::Evidence(Box::new(
            DurableTransactionRestartCompletenessEvidenceError::PageTableCapacityExhausted {
                page_count: page_numbers.len(),
            },
        ))
    })?;

    let mut replay_floor = None;
    for transaction in transaction_analysis.transactions() {
        if matches!(
            transaction.state(),
            DurableTransactionRestartState::Uncommitted
        ) {
            let Some(first_position) = transaction.first_owned_page_position() else {
                return Err(DurableTransactionRestartCompletenessError::Evidence(
                    Box::new(
                        DurableTransactionRestartCompletenessEvidenceError::UncommittedTransactionPageRangeMissing {
                            transaction: transaction.transaction(),
                        },
                    ),
                ));
            };
            lower_restart_replay_start(
                &mut replay_floor,
                first_position.get(),
                DurableTransactionRestartReplayStartCause::UncommittedTransaction {
                    transaction: transaction.transaction(),
                },
            );
        }
    }

    for page_number in page_numbers {
        let required =
            latest_required_restart_page_image(&transaction_analysis, page_number, observations)
                .map_err(|source| {
                    DurableTransactionRestartCompletenessError::Evidence(Box::new(source))
                })?;
        let snapshot = store.observe_page(page_number).map_err(|source| {
            DurableTransactionRestartCompletenessError::StoreObservation {
                page_number,
                source,
            }
        })?;
        let stored_position = snapshot
            .as_ref()
            .map(|snapshot| {
                validate_restart_page_snapshot(
                    lineage,
                    &transaction_analysis,
                    observations,
                    page_number,
                    snapshot,
                )
            })
            .transpose()
            .map_err(|source| {
                DurableTransactionRestartCompletenessError::Evidence(Box::new(source))
            })?;

        let state = match (required, stored_position) {
            (None, None) => DurableTransactionRestartPageState::NoRequiredImage,
            (None, Some(stored_position)) => {
                return Err(DurableTransactionRestartCompletenessError::Evidence(
                    Box::new(
                        DurableTransactionRestartCompletenessEvidenceError::RequiredPageImageMissing {
                            page_number,
                            stored_position,
                        },
                    ),
                ));
            }
            (Some(required), None) => {
                lower_restart_replay_start(
                    &mut replay_floor,
                    required.page_position(),
                    DurableTransactionRestartReplayStartCause::StoreMissing { page_number },
                );
                DurableTransactionRestartPageState::StoreMissing { required }
            }
            (Some(required), Some(stored_position))
                if stored_position == required.page_position() =>
            {
                DurableTransactionRestartPageState::StoreCurrent {
                    required,
                    stored_position,
                }
            }
            (Some(required), Some(stored_position))
                if stored_position < required.page_position() =>
            {
                lower_restart_replay_start(
                    &mut replay_floor,
                    required.page_position(),
                    DurableTransactionRestartReplayStartCause::StoreBehind { page_number },
                );
                DurableTransactionRestartPageState::StoreBehind {
                    stored_position,
                    required,
                }
            }
            (Some(required), Some(stored_position)) => {
                return Err(DurableTransactionRestartCompletenessError::Evidence(
                    Box::new(
                        DurableTransactionRestartCompletenessEvidenceError::SnapshotBeyondRequiredImage {
                            page_number,
                            stored_position,
                            required_position: required.page_position(),
                        },
                    ),
                ));
            }
        };
        pages.push(DurableTransactionRestartPageEntry { page_number, state });
    }

    let replay_start = match replay_floor {
        Some((position, cause)) => {
            DurableTransactionRestartReplayStart::AtPosition { position, cause }
        }
        None => DurableTransactionRestartReplayStart::AfterFrontier {
            frontier: transaction_analysis
                .durable_frontier()
                .map(LogSequenceNumber::get),
        },
    };
    Ok(DurableTransactionRestartCompletenessAnalysis {
        transaction_analysis,
        pages,
        replay_start,
    })
}

/// Read-only in-process lifecycle phase recorded by the coordinator.
///
/// This phase is not persistent recovery evidence and deliberately carries no
/// log position or client-visible transaction state.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum TransactionLifecycleStatus {
    /// The coordinator issued an active transaction token.
    Active,
    /// The token was consumed and WAL work may have begun.
    CommitAttempted,
    /// The exact WAL durability fence completed successfully.
    Committed,
    /// The WAL port failed after the commit attempt began.
    Indeterminate,
    /// A transaction-owned page WAL append was attempted but valid append
    /// evidence was not established.
    ///
    /// This phase is distinct from [`Self::Indeterminate`]. Commit and
    /// commit-outcome resolution gate strictly on [`Self::Indeterminate`] and
    /// never reinterpret this page-append phase as a commit attempt.
    PageAppendIndeterminate,
    /// Authoritative recovery found no durable commit record.
    NoDurableCommitRecord,
}

/// Failure to issue a fresh in-process transaction identity.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum TransactionIssueError {
    /// Every nonzero numeric identity has already been issued.
    IdentitySpaceExhausted,
    /// The lifecycle registry already contains the next identity.
    IdentityAlreadyIssued(TransactionId),
}

impl fmt::Display for TransactionIssueError {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::IdentitySpaceExhausted => {
                formatter.write_str("transaction identity space is exhausted")
            }
            Self::IdentityAlreadyIssued(transaction_id) => write!(
                formatter,
                "transaction identity {transaction_id} was already issued"
            ),
        }
    }
}

impl Error for TransactionIssueError {}

/// Coordinator-owned transaction issuance and commit-attempt registry.
///
/// The private runtime identity binds active tokens to one coordinator without
/// global state. Registry entries are retained for the coordinator lifetime so
/// issued identities cannot be reused by this in-process model.
///
/// ```compile_fail
/// use ntsql_transaction::TransactionCoordinator;
///
/// fn cannot_clone(coordinator: TransactionCoordinator) {
/// let duplicate = coordinator.clone();
/// }
/// ```
///
/// ```compile_fail
/// use ntsql_transaction::TransactionCoordinator;
///
/// let bypass = TransactionCoordinator::new();
/// ```
#[derive(Debug)]
pub struct TransactionCoordinator {
    epoch: TransactionEpoch,
    identity: Arc<()>,
    log_lineage: LogLineage,
    next_transaction_id: Option<NonZeroU64>,
    lifecycles: BTreeMap<TransactionId, TransactionLifecycleStatus>,
    staged_pages: BTreeSet<(TransactionId, ntsql_page::PageNumber)>,
}

impl TransactionCoordinator {
    /// Opens an empty coordinator with one source-assigned lineage epoch.
    pub fn open<Source>(source: &mut Source) -> Result<Self, Source::Error>
    where
        Source: TransactionEpochSource + ?Sized,
    {
        let (epoch, log_lineage) = source.allocate_transaction_epoch()?;
        Ok(Self::from_allocated_epoch(epoch, log_lineage))
    }

    fn from_allocated_epoch(epoch: NonZeroU64, log_lineage: LogLineage) -> Self {
        Self {
            epoch: TransactionEpoch(epoch),
            identity: Arc::new(()),
            log_lineage,
            next_transaction_id: Some(NonZeroU64::MIN),
            lifecycles: BTreeMap::new(),
            staged_pages: BTreeSet::new(),
        }
    }

    /// Returns this coordinator's persistence-lineage epoch.
    #[must_use]
    pub const fn epoch(&self) -> TransactionEpoch {
        self.epoch
    }

    /// Issues one fresh active transaction token.
    pub fn begin(&mut self) -> Result<ActiveTransaction, TransactionIssueError> {
        let Some(next_transaction_id) = self.next_transaction_id else {
            return Err(TransactionIssueError::IdentitySpaceExhausted);
        };
        let transaction_id = TransactionId {
            epoch: self.epoch,
            sequence: next_transaction_id,
        };
        match self.lifecycles.entry(transaction_id) {
            Entry::Vacant(entry) => {
                entry.insert(TransactionLifecycleStatus::Active);
            }
            Entry::Occupied(_) => {
                return Err(TransactionIssueError::IdentityAlreadyIssued(transaction_id));
            }
        }
        self.next_transaction_id = next_transaction_id
            .get()
            .checked_add(1)
            .and_then(NonZeroU64::new);

        Ok(ActiveTransaction {
            transaction_id,
            coordinator_identity: Arc::clone(&self.identity),
        })
    }

    /// Returns whether this coordinator issued the active token.
    #[must_use]
    pub fn owns(&self, transaction: &ActiveTransaction) -> bool {
        Arc::ptr_eq(&self.identity, &transaction.coordinator_identity)
    }

    /// Returns whether this coordinator issued the indeterminate token.
    #[must_use]
    pub fn owns_indeterminate(&self, transaction: &IndeterminateTransaction) -> bool {
        Arc::ptr_eq(&self.identity, &transaction.coordinator_identity)
    }

    /// Returns the in-process lifecycle phase for an issued identity.
    #[must_use]
    pub fn status(&self, transaction_id: TransactionId) -> Option<TransactionLifecycleStatus> {
        self.lifecycles.get(&transaction_id).copied()
    }

    /// Starts one commit attempt for an active token issued by this coordinator.
    ///
    /// Rejections occur before the WAL port is called and retain the active
    /// token. Once WAL work starts, any port failure is terminally
    /// indeterminate for this in-process coordinator.
    pub fn commit<L>(
        &mut self,
        transaction: ActiveTransaction,
        log: &mut L,
    ) -> Result<CommittedTransaction, CoordinatedCommitError<L::Error>>
    where
        L: CommitLog<TransactionCommitRecord>,
    {
        if !self.owns(&transaction) {
            return Err(CoordinatedCommitError::Rejected(
                TransactionCommitRejection {
                    transaction,
                    reason: TransactionCommitRejectionReason::ForeignCoordinator,
                },
            ));
        }
        if !self.log_lineage.same_lineage(log.lineage()) {
            return Err(CoordinatedCommitError::Rejected(
                TransactionCommitRejection {
                    transaction,
                    reason: TransactionCommitRejectionReason::ForeignLogLineage,
                },
            ));
        }

        let log_lineage = self.log_lineage.clone();
        let transaction_id = transaction.transaction_id();
        let status = match self.lifecycles.get_mut(&transaction_id) {
            Some(status) if *status == TransactionLifecycleStatus::Active => status,
            Some(status) => {
                return Err(CoordinatedCommitError::Rejected(
                    TransactionCommitRejection {
                        transaction,
                        reason: TransactionCommitRejectionReason::LifecycleMismatch {
                            actual: Some(*status),
                        },
                    },
                ));
            }
            None => {
                return Err(CoordinatedCommitError::Rejected(
                    TransactionCommitRejection {
                        transaction,
                        reason: TransactionCommitRejectionReason::LifecycleMismatch {
                            actual: None,
                        },
                    },
                ));
            }
        };

        *status = TransactionLifecycleStatus::CommitAttempted;
        match transaction.commit(log, log_lineage) {
            Ok(committed) => {
                *status = TransactionLifecycleStatus::Committed;
                Ok(committed)
            }
            Err(error) => {
                *status = TransactionLifecycleStatus::Indeterminate;
                Err(CoordinatedCommitError::Indeterminate(error))
            }
        }
    }

    /// Resolves one indeterminate token from authoritative durable-log evidence.
    ///
    /// Ownership and lifecycle mismatches are rejected before consulting the
    /// source. Source failures and lineage mismatches retain the same token and
    /// leave the lifecycle indeterminate. Authoritative absence is terminal but
    /// does not recreate active state or define a retry or rollback rule.
    pub fn resolve<Source>(
        &mut self,
        transaction: IndeterminateTransaction,
        source: &mut Source,
    ) -> Result<TransactionCommitResolution, TransactionResolutionError<Source::Error>>
    where
        Source: TransactionRecoverySource + ?Sized,
    {
        if !self.owns_indeterminate(&transaction) {
            return Err(TransactionResolutionError {
                transaction,
                failure: TransactionResolutionFailure::ForeignCoordinator,
            });
        }

        let transaction_id = transaction.transaction_id();
        let actual = self.status(transaction_id);
        if actual != Some(TransactionLifecycleStatus::Indeterminate) {
            return Err(TransactionResolutionError {
                transaction,
                failure: TransactionResolutionFailure::LifecycleMismatch { actual },
            });
        }

        let (lineage, lookup) = match source.lookup_durable_commit(transaction_id) {
            Ok(result) => result,
            Err(source) => {
                return Err(TransactionResolutionError {
                    transaction,
                    failure: TransactionResolutionFailure::Source(source),
                });
            }
        };
        if !transaction.log_lineage.same_lineage(&lineage) {
            return Err(TransactionResolutionError {
                transaction,
                failure: TransactionResolutionFailure::ForeignLogLineage,
            });
        }
        if let DurableCommitLookup::Found { position } = &lookup
            && !lineage.same_lineage(position.lineage())
        {
            return Err(TransactionResolutionError {
                transaction,
                failure: TransactionResolutionFailure::ForeignLogLineage,
            });
        }

        let Some(status) = self.lifecycles.get_mut(&transaction_id) else {
            return Err(TransactionResolutionError {
                transaction,
                failure: TransactionResolutionFailure::LifecycleMismatch { actual: None },
            });
        };
        match lookup {
            DurableCommitLookup::Found { position } => {
                *status = TransactionLifecycleStatus::Committed;
                Ok(TransactionCommitResolution::Committed(
                    CommittedTransaction {
                        transaction_id,
                        log_position: position,
                    },
                ))
            }
            DurableCommitLookup::Absent => {
                *status = TransactionLifecycleStatus::NoDurableCommitRecord;
                Ok(TransactionCommitResolution::NoDurableCommitRecord(
                    NoDurableCommitRecord { transaction_id },
                ))
            }
        }
    }

    /// Stages one transaction-owned page write for an active token issued by
    /// this coordinator.
    ///
    /// Ownership, coordinator/log lineage, page/log lineage, the retained
    /// `Active` phase, and the one-image-per-page limit are validated before the
    /// transaction-page WAL port is called. Every pre-append rejection retains
    /// the unchanged active token and the exact unlogged page and never calls
    /// the append port.
    ///
    /// Once the append port is invoked, an adapter error or invalid lineage
    /// evidence is terminal: the coordinator records
    /// [`TransactionLifecycleStatus::PageAppendIndeterminate`], returns terminal
    /// page evidence with no path back to [`ActiveTransaction`], and blocks
    /// commit and commit-outcome resolution for that identity. Success returns
    /// the same active token plus one [`TransactionDirtyPage`] and leaves the
    /// coordinator lifecycle `Active`; the page store is never called here.
    pub fn stage_page_write<L, const N: usize>(
        &mut self,
        transaction: ActiveTransaction,
        page: UnloggedPage<N>,
        log: &mut L,
    ) -> Result<(ActiveTransaction, TransactionDirtyPage<N>), TransactionPageStageError<L::Error, N>>
    where
        L: TransactionPageLog<N>,
    {
        if !self.owns(&transaction) {
            return Err(TransactionPageStageError::Rejected(
                TransactionPageStageRejection {
                    transaction,
                    page,
                    reason: TransactionPageStageRejectionReason::ForeignCoordinator,
                },
            ));
        }
        if !self.log_lineage.same_lineage(log.lineage()) {
            return Err(TransactionPageStageError::Rejected(
                TransactionPageStageRejection {
                    transaction,
                    page,
                    reason: TransactionPageStageRejectionReason::ForeignLogLineage,
                },
            ));
        }
        if !page.address().lineage().same_lineage(log.lineage()) {
            return Err(TransactionPageStageError::Rejected(
                TransactionPageStageRejection {
                    transaction,
                    page,
                    reason: TransactionPageStageRejectionReason::ForeignPageLineage,
                },
            ));
        }
        let transaction_id = transaction.transaction_id();
        match self.lifecycles.get(&transaction_id).copied() {
            Some(TransactionLifecycleStatus::Active) => {}
            actual => {
                return Err(TransactionPageStageError::Rejected(
                    TransactionPageStageRejection {
                        transaction,
                        page,
                        reason: TransactionPageStageRejectionReason::LifecycleMismatch { actual },
                    },
                ));
            }
        }
        let page_number = page.address().number();
        if !self.staged_pages.insert((transaction_id, page_number)) {
            return Err(TransactionPageStageError::Rejected(
                TransactionPageStageRejection {
                    transaction,
                    page,
                    reason: TransactionPageStageRejectionReason::PageAlreadyStaged,
                },
            ));
        }

        let mut bridge = TransactionPageAppendBridge {
            transaction_id,
            log,
        };
        match stage_page_write(&mut bridge, page) {
            Ok(dirty) => Ok((
                transaction,
                TransactionDirtyPage {
                    transaction_id,
                    dirty,
                },
            )),
            Err(StagePageWriteError::Rejected(rejection)) => {
                // The domain page port re-rejected after this coordinator had
                // already validated the shared lineage. This never invoked the
                // append effect, so the token stays active without poisoning
                // the lifecycle.
                let _ = self.staged_pages.remove(&(transaction_id, page_number));
                Err(TransactionPageStageError::Rejected(
                    TransactionPageStageRejection {
                        transaction,
                        page: rejection.into_page(),
                        reason: TransactionPageStageRejectionReason::InternalPageLogRejection,
                    },
                ))
            }
            Err(StagePageWriteError::Append(error)) => {
                self.mark_page_append_indeterminate(transaction_id);
                let (page, source) = error.into_parts();
                Err(TransactionPageStageError::Append(
                    TransactionPageAppendError {
                        transaction_id,
                        page,
                        source,
                    },
                ))
            }
            Err(StagePageWriteError::InvalidEvidence(error)) => {
                self.mark_page_append_indeterminate(transaction_id);
                let reason = error.reason();
                Err(TransactionPageStageError::InvalidEvidence(
                    TransactionPageEvidenceError {
                        transaction_id,
                        page: error.into_page(),
                        reason,
                    },
                ))
            }
        }
    }

    fn mark_page_append_indeterminate(&mut self, transaction_id: TransactionId) {
        if let Some(status) = self.lifecycles.get_mut(&transaction_id) {
            *status = TransactionLifecycleStatus::PageAppendIndeterminate;
        }
    }
}

/// Caller-owned WAL record for one internal transaction commit attempt.
///
/// Only [`TransactionCoordinator::commit`] constructs this value. Persistence
/// adapters may inspect the identity but do not own transaction state.
#[derive(Debug, Eq, PartialEq)]
pub struct TransactionCommitRecord {
    transaction_id: TransactionId,
}

impl TransactionCommitRecord {
    /// Returns the transaction whose commit attempt this record identifies.
    #[must_use]
    pub const fn transaction_id(&self) -> TransactionId {
        self.transaction_id
    }
}

/// Transaction state that may begin one coordinator-owned commit attempt.
///
/// ```compile_fail
/// use ntsql_transaction::ActiveTransaction;
///
/// fn cannot_clone(transaction: ActiveTransaction) {
///     let duplicate = transaction.clone();
/// }
/// ```
///
/// ```compile_fail
/// use ntsql_transaction::{ActiveTransaction, TransactionCommitRecord, TransactionCoordinator};
/// use ntsql_wal::CommitLog;
///
/// fn cannot_commit_twice<L>(
///     coordinator: &mut TransactionCoordinator,
///     transaction: ActiveTransaction,
///     log: &mut L,
/// )
/// where
///     L: CommitLog<TransactionCommitRecord>,
/// {
///     let _first = coordinator.commit(transaction, log);
///     let _second = coordinator.commit(transaction, log);
/// }
/// ```
#[derive(Debug)]
pub struct ActiveTransaction {
    transaction_id: TransactionId,
    coordinator_identity: Arc<()>,
}

impl ActiveTransaction {
    /// Returns the transaction identity without changing state.
    #[must_use]
    pub const fn transaction_id(&self) -> TransactionId {
        self.transaction_id
    }

    fn commit<L>(
        self,
        log: &mut L,
        log_lineage: LogLineage,
    ) -> Result<CommittedTransaction, TransactionCommitError<L::Error>>
    where
        L: CommitLog<TransactionCommitRecord>,
    {
        let Self {
            transaction_id,
            coordinator_identity,
        } = self;
        let record = TransactionCommitRecord { transaction_id };

        match commit_durability(log, &record, |acknowledgement| CommittedTransaction {
            transaction_id,
            log_position: acknowledgement.position().clone(),
        }) {
            Ok(committed) => Ok(committed),
            Err(source) => Err(TransactionCommitError {
                transaction: IndeterminateTransaction {
                    transaction_id,
                    coordinator_identity,
                    log_lineage,
                },
                source,
            }),
        }
    }
}

/// Reason an active token was rejected before the WAL port was called.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum TransactionCommitRejectionReason {
    /// The active token belongs to another coordinator runtime identity.
    ForeignCoordinator,
    /// The commit-log port does not match the epoch source lineage.
    ForeignLogLineage,
    /// The issuing coordinator did not retain the expected active phase.
    LifecycleMismatch {
        /// Recorded phase, or `None` when the registry entry is absent.
        actual: Option<TransactionLifecycleStatus>,
    },
}

/// Pre-WAL commit rejection that retains the still-active token.
#[derive(Debug)]
pub struct TransactionCommitRejection {
    transaction: ActiveTransaction,
    reason: TransactionCommitRejectionReason,
}

impl TransactionCommitRejection {
    /// Returns why the coordinator rejected the token.
    #[must_use]
    pub const fn reason(&self) -> TransactionCommitRejectionReason {
        self.reason
    }

    /// Returns the rejected token's transaction identity.
    #[must_use]
    pub const fn transaction_id(&self) -> TransactionId {
        self.transaction.transaction_id()
    }

    /// Returns the active token for routing back to its issuing coordinator.
    #[must_use]
    pub fn into_transaction(self) -> ActiveTransaction {
        self.transaction
    }
}

impl fmt::Display for TransactionCommitRejection {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self.reason {
            TransactionCommitRejectionReason::ForeignCoordinator => write!(
                formatter,
                "transaction {} belongs to another coordinator",
                self.transaction_id()
            ),
            TransactionCommitRejectionReason::ForeignLogLineage => write!(
                formatter,
                "transaction {} belongs to another commit-log lineage",
                self.transaction_id()
            ),
            TransactionCommitRejectionReason::LifecycleMismatch { actual } => write!(
                formatter,
                "transaction {} is not active in its coordinator registry: {actual:?}",
                self.transaction_id()
            ),
        }
    }
}

impl Error for TransactionCommitRejection {}

/// Coordinator commit failure before or after the WAL attempt boundary.
#[derive(Debug)]
pub enum CoordinatedCommitError<E> {
    /// The WAL port was not called and the active token is retained.
    Rejected(TransactionCommitRejection),
    /// WAL work began and the transaction outcome is indeterminate.
    Indeterminate(TransactionCommitError<E>),
}

impl<E: fmt::Display> fmt::Display for CoordinatedCommitError<E> {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::Rejected(rejection) => rejection.fmt(formatter),
            Self::Indeterminate(error) => error.fmt(formatter),
        }
    }
}

impl<E> Error for CoordinatedCommitError<E>
where
    E: Error + 'static,
{
    fn source(&self) -> Option<&(dyn Error + 'static)> {
        match self {
            Self::Rejected(rejection) => Some(rejection),
            Self::Indeterminate(error) => Some(error),
        }
    }
}

/// Transaction whose commit record is confirmed durable by the WAL port.
#[derive(Debug, Eq, PartialEq)]
pub struct CommittedTransaction {
    transaction_id: TransactionId,
    log_position: LogSequenceNumber,
}

impl CommittedTransaction {
    /// Returns the committed transaction identity.
    #[must_use]
    pub const fn transaction_id(&self) -> TransactionId {
        self.transaction_id
    }

    /// Returns the exact internal log position confirmed durable.
    #[must_use]
    pub const fn log_position(&self) -> &LogSequenceNumber {
        &self.log_position
    }
}

/// Terminal transaction state for authoritative absence of a durable record.
///
/// This state offers no active, retry, rollback, or client-visible transition.
///
/// ```compile_fail
/// use ntsql_transaction::{NoDurableCommitRecord, TransactionId};
///
/// fn cannot_construct(transaction_id: TransactionId) {
///     let forged = NoDurableCommitRecord { transaction_id };
/// }
/// ```
#[derive(Debug, Eq, PartialEq)]
pub struct NoDurableCommitRecord {
    transaction_id: TransactionId,
}

impl NoDurableCommitRecord {
    /// Returns the transaction identity absent from the durable view.
    #[must_use]
    pub const fn transaction_id(&self) -> TransactionId {
        self.transaction_id
    }
}

/// Terminal result of resolving an indeterminate commit attempt.
#[derive(Debug, Eq, PartialEq)]
pub enum TransactionCommitResolution {
    /// The exact commit record is present in the durable view.
    Committed(CommittedTransaction),
    /// The complete durable view contains no commit record.
    NoDurableCommitRecord(NoDurableCommitRecord),
}

impl TransactionCommitResolution {
    /// Returns the resolved transaction identity.
    #[must_use]
    pub const fn transaction_id(&self) -> TransactionId {
        match self {
            Self::Committed(transaction) => transaction.transaction_id(),
            Self::NoDurableCommitRecord(transaction) => transaction.transaction_id(),
        }
    }
}

/// Transaction whose durable commit outcome cannot be established safely.
///
/// This state deliberately offers no commit or rollback operation.
///
/// ```compile_fail
/// use ntsql_transaction::{
///     IndeterminateTransaction, TransactionCommitRecord, TransactionCoordinator,
/// };
/// use ntsql_wal::CommitLog;
///
/// fn cannot_retry<L>(
///     coordinator: &mut TransactionCoordinator,
///     transaction: IndeterminateTransaction,
///     log: &mut L,
/// )
/// where
///     L: CommitLog<TransactionCommitRecord>,
/// {
///     coordinator.commit(transaction, log);
/// }
/// ```
#[derive(Debug)]
pub struct IndeterminateTransaction {
    transaction_id: TransactionId,
    coordinator_identity: Arc<()>,
    log_lineage: LogLineage,
}

impl IndeterminateTransaction {
    /// Returns the transaction identity requiring later outcome resolution.
    #[must_use]
    pub const fn transaction_id(&self) -> TransactionId {
        self.transaction_id
    }
}

/// Reason authoritative resolution did not produce terminal transaction state.
#[derive(Debug, Eq, PartialEq)]
pub enum TransactionResolutionFailure<E> {
    /// The token belongs to another coordinator runtime identity.
    ForeignCoordinator,
    /// The recovery source searched a different log lineage.
    ForeignLogLineage,
    /// The issuing coordinator did not retain the expected indeterminate phase.
    LifecycleMismatch {
        /// Recorded phase, or `None` when the registry entry is absent.
        actual: Option<TransactionLifecycleStatus>,
    },
    /// The recovery source could not establish an authoritative result.
    Source(E),
}

/// Failed resolution that retains the consumed indeterminate token.
#[derive(Debug)]
pub struct TransactionResolutionError<E> {
    transaction: IndeterminateTransaction,
    failure: TransactionResolutionFailure<E>,
}

impl<E> TransactionResolutionError<E> {
    /// Returns the transaction identity that remains indeterminate.
    #[must_use]
    pub const fn transaction_id(&self) -> TransactionId {
        self.transaction.transaction_id()
    }

    /// Borrows the token retained after failed resolution.
    #[must_use]
    pub const fn transaction(&self) -> &IndeterminateTransaction {
        &self.transaction
    }

    /// Borrows the exact resolution failure.
    #[must_use]
    pub const fn failure(&self) -> &TransactionResolutionFailure<E> {
        &self.failure
    }

    /// Returns the retained token for another authoritative resolution attempt.
    #[must_use]
    pub fn into_transaction(self) -> IndeterminateTransaction {
        self.transaction
    }

    /// Returns the retained token and exact resolution failure.
    #[must_use]
    pub fn into_parts(self) -> (IndeterminateTransaction, TransactionResolutionFailure<E>) {
        (self.transaction, self.failure)
    }
}

impl<E: fmt::Display> fmt::Display for TransactionResolutionError<E> {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        match &self.failure {
            TransactionResolutionFailure::ForeignCoordinator => write!(
                formatter,
                "transaction {} belongs to another coordinator",
                self.transaction_id()
            ),
            TransactionResolutionFailure::ForeignLogLineage => write!(
                formatter,
                "transaction {} recovery source belongs to another log lineage",
                self.transaction_id()
            ),
            TransactionResolutionFailure::LifecycleMismatch { actual } => write!(
                formatter,
                "transaction {} is not indeterminate in its coordinator registry: {actual:?}",
                self.transaction_id()
            ),
            TransactionResolutionFailure::Source(source) => write!(
                formatter,
                "transaction {} durable commit lookup failed: {source}",
                self.transaction_id()
            ),
        }
    }
}

impl<E> Error for TransactionResolutionError<E>
where
    E: Error + 'static,
{
    fn source(&self) -> Option<&(dyn Error + 'static)> {
        match &self.failure {
            TransactionResolutionFailure::Source(source) => Some(source),
            TransactionResolutionFailure::ForeignCoordinator
            | TransactionResolutionFailure::ForeignLogLineage
            | TransactionResolutionFailure::LifecycleMismatch { .. } => None,
        }
    }
}

/// WAL failure paired with the consumed transaction's fail-closed state.
#[derive(Debug)]
pub struct TransactionCommitError<E> {
    transaction: IndeterminateTransaction,
    source: CommitError<E>,
}

impl<E> TransactionCommitError<E> {
    /// Borrows the transaction that cannot be retried as active.
    #[must_use]
    pub const fn transaction(&self) -> &IndeterminateTransaction {
        &self.transaction
    }

    /// Borrows the original append- or flush-specific WAL failure.
    #[must_use]
    pub const fn cause(&self) -> &CommitError<E> {
        &self.source
    }

    /// Returns the fail-closed transaction state and original WAL failure.
    #[must_use]
    pub fn into_parts(self) -> (IndeterminateTransaction, CommitError<E>) {
        (self.transaction, self.source)
    }
}

impl<E: fmt::Display> fmt::Display for TransactionCommitError<E> {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(
            formatter,
            "transaction {} commit outcome is indeterminate: {}",
            self.transaction.transaction_id(),
            self.source
        )
    }
}

impl<E> Error for TransactionCommitError<E>
where
    E: Error + 'static,
{
    fn source(&self) -> Option<&(dyn Error + 'static)> {
        Some(&self.source)
    }
}

/// Caller-borrowed WAL record for one transaction-owned page write.
///
/// Only the coordinator's private append bridge constructs this value, so safe
/// downstream code cannot forge a transaction-owned page record. Persistence
/// adapters may inspect the identity and borrowed page but do not own the
/// transaction lifecycle.
///
/// ```compile_fail
/// use ntsql_page::UnloggedPage;
/// use ntsql_transaction::{TransactionId, TransactionPageWriteRecord};
///
/// fn cannot_construct<const N: usize>(
///     transaction_id: TransactionId,
///     page: &UnloggedPage<N>,
/// ) {
///     let _forged = TransactionPageWriteRecord {
///         transaction_id,
///         page,
///     };
/// }
/// ```
#[derive(Debug)]
pub struct TransactionPageWriteRecord<'page, const N: usize> {
    transaction_id: TransactionId,
    page: &'page UnloggedPage<N>,
}

impl<const N: usize> TransactionPageWriteRecord<'_, N> {
    /// Returns the transaction identity that owns this page write.
    #[must_use]
    pub const fn transaction_id(&self) -> TransactionId {
        self.transaction_id
    }

    /// Returns the borrowed unlogged page image being appended.
    #[must_use]
    pub const fn page(&self) -> &UnloggedPage<N> {
        self.page
    }
}

/// WAL append port for one transaction-owned full page image.
///
/// Hard adapter obligation: transaction-page appends and transaction commit
/// appends for one lineage must share exactly one monotonic position space and
/// one durable frontier, so a later commit flush also makes every prior
/// transaction-page record durable. The domain validates that the returned
/// position is lineage-bound; it cannot prove the adapter honors this shared
/// frontier. Extending [`CommitLog<TransactionCommitRecord>`] requires one
/// adapter surface to provide both append operations. An adapter that assigns
/// handles sharing a lineage to independent spaces or frontiers still violates
/// this port even if each record is individually well formed.
pub trait TransactionPageLog<const N: usize>: CommitLog<TransactionCommitRecord> {
    /// Appends one transaction-owned page image and returns its exact
    /// lineage-bound WAL position.
    ///
    /// Success means the record was appended, not made durable. An error does
    /// not specify whether the physical append occurred.
    fn append_transaction_page(
        &mut self,
        record: &TransactionPageWriteRecord<'_, N>,
    ) -> Result<LogSequenceNumber, Self::Error>;
}

/// Private adapter that presents a [`TransactionPageLog`] as a [`PageLog`] so
/// the domain page-staging evidence checks can run unchanged while every append
/// carries the owning [`TransactionId`].
struct TransactionPageAppendBridge<'log, L, const N: usize>
where
    L: TransactionPageLog<N>,
{
    transaction_id: TransactionId,
    log: &'log mut L,
}

impl<L, const N: usize> LogDurability for TransactionPageAppendBridge<'_, L, N>
where
    L: TransactionPageLog<N>,
{
    type Error = L::Error;

    fn lineage(&self) -> &LogLineage {
        self.log.lineage()
    }

    fn flush_through(&mut self, position: &LogSequenceNumber) -> Result<(), Self::Error> {
        self.log.flush_through(position)
    }
}

impl<L, const N: usize> PageLog<N> for TransactionPageAppendBridge<'_, L, N>
where
    L: TransactionPageLog<N>,
{
    fn append_page(&mut self, page: &UnloggedPage<N>) -> Result<LogSequenceNumber, Self::Error> {
        let record = TransactionPageWriteRecord {
            transaction_id: self.transaction_id,
            page,
        };
        self.log.append_transaction_page(&record)
    }
}

/// Transaction-owned dirty page whose exact WAL position was appended under one
/// transaction identity but which cannot reach the page store until the same
/// transaction is durably committed.
///
/// This wrapper is not cloneable, exposes no raw [`DirtyPage`],
/// `PageWritePermit`, or store capability, and provides only read-only owner and
/// page inspection. The local no-steal rule is enforced structurally: a
/// transaction-owned image cannot be flushed except through
/// [`flush_committed_page`], which requires a [`CommittedTransaction`].
///
/// ```compile_fail
/// use ntsql_transaction::{TransactionDirtyPage, TransactionId};
/// use ntsql_page::DirtyPage;
///
/// fn cannot_construct<const N: usize>(transaction_id: TransactionId, dirty: DirtyPage<N>) {
///     let _forged = TransactionDirtyPage {
///         transaction_id,
///         dirty,
///     };
/// }
/// ```
///
/// ```compile_fail
/// use ntsql_transaction::TransactionDirtyPage;
///
/// fn cannot_clone<const N: usize>(page: TransactionDirtyPage<N>) {
///     let _duplicate = page.clone();
/// }
/// ```
///
/// ```compile_fail
/// use ntsql_transaction::TransactionDirtyPage;
/// use ntsql_page::DirtyPage;
///
/// fn cannot_extract_raw_dirty<const N: usize>(page: TransactionDirtyPage<N>) -> DirtyPage<N> {
///     page.into_dirty_page()
/// }
/// ```
#[derive(Debug, Eq, PartialEq)]
pub struct TransactionDirtyPage<const N: usize> {
    transaction_id: TransactionId,
    dirty: DirtyPage<N>,
}

impl<const N: usize> TransactionDirtyPage<N> {
    /// Returns the owning transaction identity.
    #[must_use]
    pub const fn transaction_id(&self) -> TransactionId {
        self.transaction_id
    }

    /// Returns the adapter-assigned page version.
    #[must_use]
    pub const fn version(&self) -> ntsql_page::PageVersion {
        self.dirty.version()
    }

    /// Returns the internal page address.
    #[must_use]
    pub const fn address(&self) -> &ntsql_page::PageAddress {
        self.dirty.address()
    }

    /// Returns the borrowed dirty image bytes.
    #[must_use]
    pub const fn image(&self) -> &ntsql_page::PageImage<N> {
        self.dirty.image()
    }

    /// Returns the exact WAL position that must be durable before a committed
    /// flush may store this image.
    #[must_use]
    pub const fn required_position(&self) -> &LogSequenceNumber {
        self.dirty.required_position()
    }
}

/// Transaction-owned clean page whose required WAL position and durable page
/// write both reported success for the owning committed transaction.
///
/// ```compile_fail
/// use ntsql_transaction::{TransactionCleanPage, TransactionId};
/// use ntsql_page::CleanPage;
///
/// fn cannot_construct<const N: usize>(transaction_id: TransactionId, clean: CleanPage<N>) {
///     let _forged = TransactionCleanPage {
///         transaction_id,
///         clean,
///     };
/// }
/// ```
#[derive(Debug, Eq, PartialEq)]
pub struct TransactionCleanPage<const N: usize> {
    transaction_id: TransactionId,
    clean: CleanPage<N>,
}

impl<const N: usize> TransactionCleanPage<N> {
    /// Returns the owning transaction identity.
    #[must_use]
    pub const fn transaction_id(&self) -> TransactionId {
        self.transaction_id
    }

    /// Returns the internal page address.
    #[must_use]
    pub const fn address(&self) -> &ntsql_page::PageAddress {
        self.clean.address()
    }

    /// Returns the adapter-assigned page version.
    #[must_use]
    pub const fn version(&self) -> ntsql_page::PageVersion {
        self.clean.version()
    }

    /// Returns the borrowed clean image bytes.
    #[must_use]
    pub const fn image(&self) -> &ntsql_page::PageImage<N> {
        self.clean.image()
    }

    /// Returns the exact WAL position that was durable before durable page
    /// completion was reported.
    #[must_use]
    pub const fn required_position(&self) -> &LogSequenceNumber {
        self.clean.required_position()
    }

    /// Returns the owning identity and the terminal clean page.
    #[must_use]
    pub fn into_parts(self) -> (TransactionId, CleanPage<N>) {
        (self.transaction_id, self.clean)
    }
}

/// Reason a transaction-owned page write was rejected before the append port
/// was called.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum TransactionPageStageRejectionReason {
    /// The active token belongs to another coordinator runtime identity.
    ForeignCoordinator,
    /// The transaction-page log does not match the coordinator lineage.
    ForeignLogLineage,
    /// The page address belongs to another lineage than the log.
    ForeignPageLineage,
    /// The issuing coordinator did not retain the expected active phase.
    LifecycleMismatch {
        /// Recorded phase, or `None` when the registry entry is absent.
        actual: Option<TransactionLifecycleStatus>,
    },
    /// This transaction already staged an image for the same page.
    PageAlreadyStaged,
    /// The domain page port re-rejected the composition before invoking the
    /// append effect. This is retryable and did not poison the lifecycle.
    InternalPageLogRejection,
}

/// Pre-append page-stage rejection that retains the still-active token and the
/// exact unlogged page.
#[derive(Debug)]
pub struct TransactionPageStageRejection<const N: usize> {
    transaction: ActiveTransaction,
    page: UnloggedPage<N>,
    reason: TransactionPageStageRejectionReason,
}

impl<const N: usize> TransactionPageStageRejection<N> {
    /// Returns the rejected token's transaction identity.
    #[must_use]
    pub const fn transaction_id(&self) -> TransactionId {
        self.transaction.transaction_id()
    }

    /// Returns the exact rejection reason.
    #[must_use]
    pub const fn reason(&self) -> TransactionPageStageRejectionReason {
        self.reason
    }

    /// Borrows the retained still-active token.
    #[must_use]
    pub const fn transaction(&self) -> &ActiveTransaction {
        &self.transaction
    }

    /// Borrows the retained unchanged unlogged page.
    #[must_use]
    pub const fn page(&self) -> &UnloggedPage<N> {
        &self.page
    }

    /// Returns the retained active token and unchanged unlogged page for a
    /// corrected composition.
    #[must_use]
    pub fn into_parts(self) -> (ActiveTransaction, UnloggedPage<N>) {
        (self.transaction, self.page)
    }
}

impl<const N: usize> fmt::Display for TransactionPageStageRejection<N> {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self.reason {
            TransactionPageStageRejectionReason::ForeignCoordinator => write!(
                formatter,
                "transaction {} belongs to another coordinator",
                self.transaction_id()
            ),
            TransactionPageStageRejectionReason::ForeignLogLineage => write!(
                formatter,
                "transaction {} belongs to another transaction-page log lineage",
                self.transaction_id()
            ),
            TransactionPageStageRejectionReason::ForeignPageLineage => write!(
                formatter,
                "transaction {} page belongs to another log lineage",
                self.transaction_id()
            ),
            TransactionPageStageRejectionReason::LifecycleMismatch { actual } => write!(
                formatter,
                "transaction {} is not active in its coordinator registry: {actual:?}",
                self.transaction_id()
            ),
            TransactionPageStageRejectionReason::PageAlreadyStaged => write!(
                formatter,
                "transaction {} already staged page {}",
                self.transaction_id(),
                self.page.address().number().get()
            ),
            TransactionPageStageRejectionReason::InternalPageLogRejection => write!(
                formatter,
                "transaction {} page composition was rejected before append",
                self.transaction_id()
            ),
        }
    }
}

impl<const N: usize> Error for TransactionPageStageRejection<N> {}

/// Terminal transaction-owned page state after an append port error.
///
/// This value offers no path back to [`ActiveTransaction`].
#[derive(Debug)]
pub struct TransactionPageAppendError<E, const N: usize> {
    transaction_id: TransactionId,
    page: IndeterminatePageLogAppend<N>,
    source: E,
}

impl<E, const N: usize> TransactionPageAppendError<E, N> {
    /// Returns the owning transaction identity that is now page-indeterminate.
    #[must_use]
    pub const fn transaction_id(&self) -> TransactionId {
        self.transaction_id
    }

    /// Returns the terminal page state.
    #[must_use]
    pub const fn page(&self) -> &IndeterminatePageLogAppend<N> {
        &self.page
    }

    /// Returns the exact WAL append failure.
    #[must_use]
    pub const fn cause(&self) -> &E {
        &self.source
    }

    /// Returns the owning identity, terminal page state, and exact WAL cause.
    #[must_use]
    pub fn into_parts(self) -> (TransactionId, IndeterminatePageLogAppend<N>, E) {
        (self.transaction_id, self.page, self.source)
    }
}

impl<E: fmt::Display, const N: usize> fmt::Display for TransactionPageAppendError<E, N> {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(
            formatter,
            "transaction {} page {} WAL append failed: {}",
            self.transaction_id,
            self.page.address().number().get(),
            self.source
        )
    }
}

impl<E, const N: usize> Error for TransactionPageAppendError<E, N>
where
    E: Error + 'static,
{
    fn source(&self) -> Option<&(dyn Error + 'static)> {
        Some(&self.source)
    }
}

