    #[test]
    fn pre_recovery_completeness_selection_requires_decline_and_retains_source_through_retry()
    -> Result<(), TestError> {
        let persistent_log_id =
            PersistentLogId::new(0x1590).ok_or(TestError("selection persistent log id"))?;
        let lineage = LogLineage::persistent(persistent_log_id);
        let first_page = PageNumber::new(81).ok_or(TestError("selection first page"))?;
        let mut owner = batch_restart_analyzed_checkpoint_owner(&lineage, &[81])?;
        owner.parts_mut().1.current.clear();
        let baseline = owner
            .prepare_restart_checkpoint_completeness_baseline_from_current_prefix()
            .map_err(|_| TestError("selection baseline preparation"))?;
        assert_eq!(baseline.pages().len(), 1);
        assert!(baseline.pages().iter().all(|entry| matches!(
            entry.state(),
            DurableTransactionRestartPageState::StoreMissing { .. }
        )));

        let events = Rc::new(RefCell::new(Vec::new()));
        owner.parts_mut().0.restart_events = Some(Rc::clone(&events));
        let callbacks_before = owner.parts().0.restart_callbacks;
        let observations_before = owner.parts().1.observations.borrow().len();
        let attempts_before = owner.parts().1.attempts.len();
        owner.parts_mut().1.write_fault = Some((
            first_page,
            FakeRecoveryWriteFault::Before(FakeFault("batch write")),
        ));
        let (source, store, _, _) = owner.into_parts();
        let mut checkpoint = FakeCompletenessCheckpointPublisher::new(Some(
            owned_decoded_completeness_checkpoint(&baseline),
        ));
        checkpoint.events = Some(Rc::clone(&events));

        let selection = UnrecoveredTransactionPageStorage::new(source, store)
            .select_restart_checkpoint_completeness(checkpoint);
        let TransactionPageStorageRestartCheckpointCompletenessSelection::Selected(selected) =
            selection
        else {
            return Err(TestError("exact pre-recovery checkpoint was not selected"));
        };
        assert_eq!(selected.persistent_log_id(), persistent_log_id);
        assert_eq!(selected.durable_frontier(), baseline.durable_frontier());
        assert_eq!(selected.transaction_count(), baseline.transactions().len());
        assert_eq!(selected.page_count(), baseline.pages().len());
        assert!(
            format!("{selected:?}").contains("SelectedTransactionPageStorage"),
            "selected debug output lost its state name"
        );
        assert_eq!(
            events.borrow().as_slice(),
            ["completeness-checkpoint-read", "wal"]
        );

        let failure = selected
            .decline_checkpoint()
            .map_err(|_| TestError("complete-prefix checkpoint decline was rejected"))?
            .recover()
            .err()
            .ok_or(TestError("armed full recovery unexpectedly succeeded"))?;
        assert!(matches!(
            failure.error(),
            CommittedTransactionPagesRecoveryError::Page {
                page_number,
                source: CommittedTransactionPageRecoveryError::StoreWrite { state },
                ..
            } if *page_number == first_page
                && state.as_ref().cause() == &FakeFault("batch write")
        ));

        let recovered = failure
            .retry()
            .map_err(|_| TestError("selection fallback retry failed"))?;
        assert_eq!(recovered.recovery_report().pages().len(), 1);
        let mut analyzed = recovered
            .analyze_restart()
            .map_err(|_| TestError("selection fallback restart analysis failed"))?;
        assert_eq!(
            analyzed.restart_analysis().durable_frontier(),
            Some(&lineage.position(2))
        );
        let receipt = analyzed
            .publish_restart_checkpoint_completeness_baseline_from_current_prefix()
            .map_err(|_| TestError("retained completeness source did not publish"))?;
        assert_eq!(receipt.persistent_log_id(), persistent_log_id);
        assert_eq!(receipt.page_count(), 1);

        let (source, store, report, analysis, checkpoint) = analyzed.into_parts();
        assert_eq!(report.pages().len(), 1);
        assert_eq!(analysis.transactions().len(), 1);
        assert_eq!(checkpoint.load_calls, 1);
        assert_eq!(checkpoint.publication_calls, 1);
        assert_eq!(source.restart_callbacks, callbacks_before + 3);
        assert_eq!(store.observations.borrow().len(), observations_before + 4);
        assert_eq!(store.attempts.len(), attempts_before + 2);
        assert_eq!(store.attempts[attempts_before..], [first_page, first_page]);
        assert_eq!(
            events.borrow().as_slice(),
            [
                "completeness-checkpoint-read",
                "wal",
                "wal",
                "wal",
                "completeness-checkpoint-publish",
            ]
        );
        Ok(())
    }

    #[test]
    fn pre_recovery_completeness_selection_accepts_unchanged_store_behind_evidence()
    -> Result<(), TestError> {
        let persistent_log_id =
            PersistentLogId::new(0x1593).ok_or(TestError("behind persistent log id"))?;
        let lineage = LogLineage::persistent(persistent_log_id);
        let page_number = PageNumber::new(93).ok_or(TestError("behind page number"))?;
        let mut owner = restart_analyzed_checkpoint_owner(
            &lineage,
            Some(lineage.position(3)),
            vec![
                restart_raw_page(&lineage, page_number.get(), 1)?,
                restart_raw_page(&lineage, page_number.get(), 3)?,
            ],
        )?;
        owner.parts_mut().1.current.push(FakeRecoverySnapshot {
            page_number,
            page_version: PageVersion::new(1),
            byte: u8::try_from(page_number.get()).map_err(|_| TestError("behind page byte"))?,
            page_position: lineage.position(1),
        });
        let baseline = owner
            .prepare_restart_checkpoint_completeness_baseline_from_current_prefix()
            .map_err(|_| TestError("behind baseline preparation"))?;
        assert!(matches!(
            baseline.pages(),
            [entry]
                if matches!(
                    entry.state(),
                    DurableTransactionRestartPageState::StoreBehind {
                        stored_position: 1,
                        required: DurableTransactionRestartRequiredPageImage::Raw {
                            page_position: 3,
                        },
                    }
                )
        ));

        let checkpoint = FakeCompletenessCheckpointPublisher::new(Some(
            owned_decoded_completeness_checkpoint(&baseline),
        ));
        let (source, store, _, _) = owner.into_parts();
        let selection = UnrecoveredTransactionPageStorage::new(source, store)
            .select_restart_checkpoint_completeness(checkpoint);
        let TransactionPageStorageRestartCheckpointCompletenessSelection::Selected(selected) =
            selection
        else {
            return Err(TestError(
                "unchanged store-behind checkpoint was not selected",
            ));
        };
        assert_eq!(selected.persistent_log_id(), persistent_log_id);
        assert_eq!(selected.durable_frontier(), Some(3));
        assert_eq!(selected.page_count(), 1);

        let analyzed = selected
            .decline_checkpoint()
            .map_err(|_| TestError("behind complete-prefix checkpoint decline was rejected"))?
            .recover()
            .map_err(|_| TestError("behind full recovery failed"))?
            .analyze_restart()
            .map_err(|_| TestError("behind restart analysis failed"))?;
        let (_, store, report, _, checkpoint) = analyzed.into_parts();
        assert!(report.pages().is_empty());
        assert!(store.attempts.is_empty());
        assert_eq!(checkpoint.load_calls, 1);
        assert_eq!(checkpoint.publication_calls, 0);
        Ok(())
    }

    #[test]
    fn pre_recovery_completeness_absence_and_source_rejection_do_not_observe_storage()
    -> Result<(), TestError> {
        let persistent_log_id =
            PersistentLogId::new(0x1591).ok_or(TestError("absence persistent log id"))?;
        let lineage = LogLineage::persistent(persistent_log_id);
        let source =
            FakeDurablePageRecoverySource::new(lineage.clone(), Vec::new(), Vec::new(), Vec::new());
        let store = FakeBatchCommittedPageRecoveryStore::new(lineage.clone());
        let events = Rc::new(RefCell::new(Vec::new()));
        let mut checkpoint = FakeCompletenessCheckpointPublisher::new(None);
        checkpoint.events = Some(Rc::clone(&events));

        let selection = UnrecoveredTransactionPageStorage::new(source, store)
            .select_restart_checkpoint_completeness(checkpoint);
        let TransactionPageStorageRestartCheckpointCompletenessSelection::Absent(absent) =
            selection
        else {
            return Err(TestError("empty completeness slot was not absent"));
        };
        assert_eq!(events.borrow().as_slice(), ["completeness-checkpoint-read"]);
        let mut analyzed = absent
            .continue_with_full_recovery()
            .recover()
            .map_err(|_| TestError("absent full recovery failed"))?
            .analyze_restart()
            .map_err(|_| TestError("absent restart analysis failed"))?;
        let receipt = analyzed
            .publish_restart_checkpoint_completeness_baseline_from_current_prefix()
            .map_err(|_| TestError("absent retained source publication failed"))?;
        assert_eq!(receipt.persistent_log_id(), persistent_log_id);
        assert_eq!(receipt.durable_frontier(), None);
        assert_eq!(receipt.transaction_count(), 0);
        assert_eq!(receipt.page_count(), 0);
        let (source, store, _, _, checkpoint) = analyzed.into_parts();
        assert_eq!(checkpoint.load_calls, 1);
        assert_eq!(checkpoint.publication_calls, 1);
        assert_eq!(source.restart_callbacks, 2);
        assert!(store.observations.borrow().is_empty());
        assert!(store.attempts.is_empty());

        let mut source =
            FakeDurablePageRecoverySource::new(lineage.clone(), Vec::new(), Vec::new(), Vec::new());
        let events = Rc::new(RefCell::new(Vec::new()));
        source.restart_events = Some(Rc::clone(&events));
        let store = FakeBatchCommittedPageRecoveryStore::new(lineage);
        let mut checkpoint = FakeCompletenessCheckpointSource::new(None);
        checkpoint.fault = Some(FakeFault("selection checkpoint source"));
        checkpoint.events = Some(Rc::clone(&events));

        let selection = UnrecoveredTransactionPageStorage::new(source, store)
            .select_restart_checkpoint_completeness(checkpoint);
        let TransactionPageStorageRestartCheckpointCompletenessSelection::Rejected(rejected) =
            selection
        else {
            return Err(TestError("checkpoint source failure was not rejected"));
        };
        assert_eq!(
            rejected.to_string(),
            "restart checkpoint completeness selection rejected: restart checkpoint completeness source failed: selection checkpoint source"
        );
        assert_eq!(
            Error::source(&rejected).map(ToString::to_string),
            Some(String::from(
                "restart checkpoint completeness source failed: selection checkpoint source"
            ))
        );
        assert!(matches!(
            rejected.error(),
            DurableTransactionRestartCheckpointCompletenessBaselineSourceValidationError::CheckpointSource(
                FakeFault("selection checkpoint source")
            )
        ));
        assert_eq!(events.borrow().as_slice(), ["completeness-checkpoint"]);

        let (uncheckpointed, rejection) = rejected
            .continue_with_full_recovery()
            .map_err(|_| TestError("legacy checkpoint rejection denied fallback"))?;
        assert!(matches!(
            rejection,
            DurableTransactionRestartCheckpointCompletenessBaselineSourceValidationError::CheckpointSource(
                FakeFault("selection checkpoint source")
            )
        ));
        let analyzed = uncheckpointed
            .recover()
            .map_err(|_| TestError("source-rejected full recovery failed"))?
            .analyze_restart()
            .map_err(|_| TestError("source-rejected restart analysis failed"))?;
        let (source, store, _, _, checkpoint) = analyzed.into_parts();
        assert_eq!(checkpoint.calls, 1);
        assert_eq!(source.restart_callbacks, 1);
        assert!(store.observations.borrow().is_empty());
        assert!(store.attempts.is_empty());
        assert_eq!(
            events.borrow().as_slice(),
            ["completeness-checkpoint", "wal"]
        );
        Ok(())
    }

    #[test]
    fn pre_recovery_completeness_rejects_early_identity_and_advanced_snapshot_then_falls_back()
    -> Result<(), TestError> {
        let persistent_log_id =
            PersistentLogId::new(0x1592).ok_or(TestError("rejection persistent log id"))?;
        let foreign_log_id =
            PersistentLogId::new(0x2592).ok_or(TestError("foreign persistent log id"))?;
        let lineage = LogLineage::persistent(persistent_log_id);

        for actual in [0, foreign_log_id.get()] {
            let source = FakeDurablePageRecoverySource::new(
                lineage.clone(),
                Vec::new(),
                Vec::new(),
                Vec::new(),
            );
            let store = FakeBatchCommittedPageRecoveryStore::new(lineage.clone());
            let checkpoint =
                OwnedDurableTransactionRestartCheckpointCompletenessBaselineObservation::new(
                    OwnedDurableTransactionRestartCheckpointBaselineObservation::new(
                        actual,
                        None,
                        Vec::new(),
                    ),
                    Vec::new(),
                    DurableTransactionRestartCheckpointCompletenessBaselineReplayObservation::new(
                        DurableTransactionRestartCheckpointCompletenessBaselineReplayKindObservation::AfterFrontier,
                        None,
                        None,
                        None,
                    ),
                );
            let checkpoint = FakeCompletenessCheckpointSource::new(Some(checkpoint));

            let selection = UnrecoveredTransactionPageStorage::new(source, store)
                .select_restart_checkpoint_completeness(checkpoint);
            let TransactionPageStorageRestartCheckpointCompletenessSelection::Rejected(rejected) =
                selection
            else {
                return Err(TestError("invalid checkpoint identity was not rejected"));
            };
            assert!(matches!(
                rejected.error(),
                DurableTransactionRestartCheckpointCompletenessBaselineSourceValidationError::BaselineValidation(
                    source
                ) if matches!(
                    source.as_ref(),
                    DurableTransactionRestartCheckpointCompletenessBaselineValidationError::Evidence(
                        evidence
                    ) if matches!(
                        evidence.as_ref(),
                        DurableTransactionRestartCheckpointCompletenessBaselineValidationEvidenceError::Baseline(
                            baseline
                        ) if (actual == 0
                            && matches!(
                                baseline.as_ref(),
                                DurableTransactionRestartCheckpointBaselineValidationEvidenceError::ZeroPersistentLogId {
                                    persistent_log_id: 0
                                }
                            ))
                            || (actual == foreign_log_id.get()
                                && matches!(
                                    baseline.as_ref(),
                                    DurableTransactionRestartCheckpointBaselineValidationEvidenceError::ForeignPersistentLogId {
                                        expected,
                                        actual: rejected_actual,
                                    } if *expected == persistent_log_id
                                        && *rejected_actual == foreign_log_id
                                ))
                    )
                )
            ));
            let (uncheckpointed, _) = rejected
                .continue_with_full_recovery()
                .map_err(|_| TestError("legacy source rejection denied fallback"))?;
            let analyzed = uncheckpointed
                .recover()
                .map_err(|_| TestError("identity-rejected full recovery failed"))?
                .analyze_restart()
                .map_err(|_| TestError("identity-rejected restart analysis failed"))?;
            let (source, store, _, _, checkpoint) = analyzed.into_parts();
            assert_eq!(checkpoint.calls, 1);
            assert_eq!(source.restart_callbacks, 1);
            assert!(store.observations.borrow().is_empty());
            assert!(store.attempts.is_empty());
        }

        let source =
            FakeDurablePageRecoverySource::new(lineage.clone(), Vec::new(), Vec::new(), Vec::new());
        let store = FakeBatchCommittedPageRecoveryStore::new(lineage.clone());
        let checkpoint =
            OwnedDurableTransactionRestartCheckpointCompletenessBaselineObservation::new(
                OwnedDurableTransactionRestartCheckpointBaselineObservation::new(
                    persistent_log_id.get(),
                    None,
                    Vec::new(),
                ),
                vec![
                    DurableTransactionRestartCheckpointCompletenessBaselinePageObservation::new(
                        91,
                        DurableTransactionRestartCheckpointCompletenessBaselinePageStateObservation::StoreCurrent,
                        Some(
                            DurableTransactionRestartCheckpointCompletenessBaselineRequiredImageObservation::Raw {
                                page_position: 1,
                            },
                        ),
                        Some(1),
                    ),
                ],
                DurableTransactionRestartCheckpointCompletenessBaselineReplayObservation::new(
                    DurableTransactionRestartCheckpointCompletenessBaselineReplayKindObservation::AfterFrontier,
                    None,
                    None,
                    None,
                ),
            );
        let checkpoint = FakeCompletenessCheckpointSource::new(Some(checkpoint));
        let selection = UnrecoveredTransactionPageStorage::new(source, store)
            .select_restart_checkpoint_completeness(checkpoint);
        let TransactionPageStorageRestartCheckpointCompletenessSelection::Rejected(rejected) =
            selection
        else {
            return Err(TestError(
                "empty-frontier checkpoint with a stored page was not rejected",
            ));
        };
        assert!(matches!(
            rejected.error(),
            DurableTransactionRestartCheckpointCompletenessBaselineSourceValidationError::BaselineValidation(
                validation
            ) if matches!(
                validation.as_ref(),
                DurableTransactionRestartCheckpointCompletenessBaselineValidationError::Evidence(
                    evidence
                ) if matches!(
                    evidence.as_ref(),
                    DurableTransactionRestartCheckpointCompletenessBaselineValidationEvidenceError::PageCountMismatch {
                        expected: 0,
                        actual: 1,
                    }
                )
            )
        ));
        let (uncheckpointed, _) = rejected
            .continue_with_full_recovery()
            .map_err(|_| TestError("legacy baseline rejection denied fallback"))?;
        let analyzed = uncheckpointed
            .recover()
            .map_err(|_| TestError("empty-frontier full recovery failed"))?
            .analyze_restart()
            .map_err(|_| TestError("empty-frontier restart analysis failed"))?;
        let (source, store, _, _, checkpoint) = analyzed.into_parts();
        assert_eq!(checkpoint.calls, 1);
        assert_eq!(source.restart_callbacks, 2);
        assert!(store.observations.borrow().is_empty());
        assert!(store.attempts.is_empty());

        let page_number = PageNumber::new(91).ok_or(TestError("advanced selected page"))?;
        let page_byte =
            u8::try_from(page_number.get()).map_err(|_| TestError("advanced page byte"))?;
        let first_owner = durable_identity(159, 1)?;
        let second_owner = durable_identity(159, 2)?;
        let old_observations = vec![
            restart_owned_page(&lineage, first_owner, page_number.get(), 1)?,
            restart_commit(&lineage, first_owner, 2)?,
        ];
        let mut old_owner = restart_analyzed_checkpoint_owner(
            &lineage,
            Some(lineage.position(2)),
            old_observations,
        )?;
        old_owner.parts_mut().1.current.push(FakeRecoverySnapshot {
            page_number,
            page_version: PageVersion::new(1),
            byte: page_byte,
            page_position: lineage.position(1),
        });
        let old_baseline = old_owner
            .prepare_restart_checkpoint_completeness_baseline_from_current_prefix()
            .map_err(|_| TestError("old selection baseline"))?;
        let checkpoint = FakeCompletenessCheckpointSource::new(Some(
            owned_decoded_completeness_checkpoint(&old_baseline),
        ));

        let mut source = FakeDurablePageRecoverySource::new(
            lineage.clone(),
            vec![
                physical_page_observation(&lineage, page_number.get(), 1, page_byte, 1)?,
                physical_page_observation(&lineage, page_number.get(), 3, page_byte, 3)?,
            ],
            vec![
                durable_page_observation(
                    &lineage,
                    first_owner,
                    page_number.get(),
                    1,
                    page_byte,
                    1,
                )?,
                durable_page_observation(
                    &lineage,
                    second_owner,
                    page_number.get(),
                    3,
                    page_byte,
                    3,
                )?,
            ],
            vec![
                durable_commit_observation(&lineage, first_owner, 2)?,
                durable_commit_observation(&lineage, second_owner, 4)?,
            ],
        );
        source.restart_frontier = Some(lineage.position(4));
        source.restart_observations = vec![
            restart_owned_page(&lineage, first_owner, page_number.get(), 1)?,
            restart_commit(&lineage, first_owner, 2)?,
            restart_owned_page(&lineage, second_owner, page_number.get(), 3)?,
            restart_commit(&lineage, second_owner, 4)?,
        ];
        let mut store = FakeBatchCommittedPageRecoveryStore::new(lineage.clone());
        store.current.push(FakeRecoverySnapshot {
            page_number,
            page_version: PageVersion::new(3),
            byte: page_byte,
            page_position: lineage.position(3),
        });

        let selection = UnrecoveredTransactionPageStorage::new(source, store)
            .select_restart_checkpoint_completeness(checkpoint);
        let TransactionPageStorageRestartCheckpointCompletenessSelection::Rejected(rejected) =
            selection
        else {
            return Err(TestError(
                "advanced selected page checkpoint was not rejected",
            ));
        };
        assert!(matches!(
            rejected.error(),
            DurableTransactionRestartCheckpointCompletenessBaselineSourceValidationError::BaselineValidation(
                validation
            ) if matches!(
                validation.as_ref(),
                DurableTransactionRestartCheckpointCompletenessBaselineValidationError::Evidence(
                    evidence
                ) if matches!(
                    evidence.as_ref(),
                    DurableTransactionRestartCheckpointCompletenessBaselineValidationEvidenceError::CompletenessEvidence(
                        completeness
                    ) if matches!(
                        completeness.as_ref(),
                        DurableTransactionRestartCompletenessError::Evidence(completeness)
                            if matches!(
                                completeness.as_ref(),
                                DurableTransactionRestartCompletenessEvidenceError::SnapshotBeyondFrontier {
                                    page_number: actual_page,
                                    position: 3,
                                    frontier: 2,
                                } if *actual_page == page_number
                            )
                    )
                )
            )
        ));

        let (uncheckpointed, rejection) = rejected
            .continue_with_full_recovery()
            .map_err(|_| TestError("legacy checkpoint source rejection denied fallback"))?;
        assert!(matches!(
            rejection,
            DurableTransactionRestartCheckpointCompletenessBaselineSourceValidationError::BaselineValidation(_)
        ));
        let recovered = uncheckpointed
            .recover()
            .map_err(|_| TestError("advanced-checkpoint full recovery failed"))?;
        assert!(matches!(
            recovered.recovery_report().pages(),
            [CommittedTransactionPageRecoveryOutcome::AlreadyCurrent { .. }]
        ));
        let analyzed = recovered
            .analyze_restart()
            .map_err(|_| TestError("advanced-checkpoint restart analysis failed"))?;
        let (source, store, _, analysis, checkpoint) = analyzed.into_parts();
        assert_eq!(checkpoint.calls, 1);
        assert_eq!(source.restart_callbacks, 2);
        assert_eq!(analysis.durable_frontier(), Some(&lineage.position(4)));
        assert!(store.attempts.is_empty());
        Ok(())
    }

    #[test]
    fn selected_checkpoint_replay_planning_materializes_every_start_shape() -> Result<(), TestError>
    {
        let persistent_log_id =
            PersistentLogId::new(0x1610).ok_or(TestError("replay persistent log id"))?;
        let lineage = LogLineage::persistent(persistent_log_id);
        let empty_baseline = fake_completeness_baseline(&lineage, None, Vec::new(), Vec::new())?;

        let empty_selected = select_fake_restart_checkpoint(
            fake_restart_source(&lineage, None, Vec::new()),
            FakeBatchCommittedPageRecoveryStore::new(lineage.clone()),
            &empty_baseline,
        )?;
        let empty = empty_selected
            .plan_replay_window()
            .map_err(|_| TestError("empty replay planning failed"))?;
        assert_eq!(empty.checkpoint_frontier(), None);
        assert_eq!(empty.current_frontier(), None);
        assert_eq!(empty.inclusive_replay_start(), None);
        assert_eq!(empty.replay_record_count(), 0);
        assert_eq!(empty.current_transaction_count(), 0);
        assert!(empty.replay_observations.is_empty());

        let transaction = durable_identity(161, 1)?;
        let full_stream = vec![
            restart_raw_page(&lineage, 91, 1)?,
            restart_owned_page(&lineage, transaction, 92, 3)?,
            restart_commit(&lineage, transaction, 4)?,
        ];
        let expected_full_stream = full_stream
            .iter()
            .map(OwnedDurableTransactionRestartReplayObservation::from)
            .collect::<Vec<_>>();
        let full_selected = select_fake_restart_checkpoint(
            fake_restart_source(&lineage, Some(lineage.position(4)), full_stream),
            FakeBatchCommittedPageRecoveryStore::new(lineage.clone()),
            &empty_baseline,
        )?;
        let full = full_selected
            .plan_replay_window()
            .map_err(|_| TestError("full-stream replay planning failed"))?;
        assert_eq!(full.checkpoint_frontier(), None);
        assert_eq!(full.current_frontier(), Some(4));
        assert_eq!(full.replay_record_count(), 3);
        assert_eq!(full.current_transaction_count(), 1);
        assert_eq!(full.replay_observations, expected_full_stream);
        assert_eq!(full.selected.storage.source.restart_callbacks, 2);
        assert_eq!(full.selected.checkpoint_source.calls, 1);
        let analyzed = full
            .decline_replay_plan()
            .map_err(|_| TestError("full-stream complete-prefix plan decline was rejected"))?
            .recover()
            .map_err(|_| TestError("full-stream fallback recovery failed"))?
            .analyze_restart()
            .map_err(|_| TestError("full-stream fallback analysis failed"))?;
        let (source, store, _, analysis, checkpoint) = analyzed.into_parts();
        assert_eq!(source.restart_callbacks, 3);
        assert_eq!(analysis.durable_frontier(), Some(&lineage.position(4)));
        assert!(store.attempts.is_empty());
        assert_eq!(checkpoint.calls, 1);

        let committed = durable_identity(161, 2)?;
        let committed_page =
            PageNumber::new(93).ok_or(TestError("committed replay page number"))?;
        let committed_snapshot = FakeRecoverySnapshot {
            page_number: committed_page,
            page_version: PageVersion::new(1),
            byte: 93,
            page_position: lineage.position(1),
        };
        let committed_baseline = fake_completeness_baseline(
            &lineage,
            Some(lineage.position(2)),
            vec![
                restart_owned_page(&lineage, committed, committed_page.get(), 1)?,
                restart_commit(&lineage, committed, 2)?,
            ],
            vec![committed_snapshot.clone()],
        )?;
        assert_eq!(
            committed_baseline.replay_start(),
            &DurableTransactionRestartReplayStart::AfterFrontier { frontier: Some(2) }
        );

        let exact_selected = select_fake_restart_checkpoint(
            fake_restart_source(
                &lineage,
                Some(lineage.position(2)),
                vec![
                    restart_owned_page(&lineage, committed, committed_page.get(), 1)?,
                    restart_commit(&lineage, committed, 2)?,
                ],
            ),
            {
                let mut store = FakeBatchCommittedPageRecoveryStore::new(lineage.clone());
                store.current.push(committed_snapshot.clone());
                store
            },
            &committed_baseline,
        )?;
        let exact = exact_selected
            .plan_replay_window()
            .map_err(|_| TestError("exact-frontier replay planning failed"))?;
        assert_eq!(exact.checkpoint_frontier(), Some(2));
        assert_eq!(exact.current_frontier(), Some(2));
        assert_eq!(exact.replay_record_count(), 0);
        assert!(exact.replay_observations.is_empty());

        let suffix = restart_raw_page(&lineage, 94, 4)?;
        let expected_suffix = OwnedDurableTransactionRestartReplayObservation::from(&suffix);
        let suffix_selected = select_fake_restart_checkpoint(
            fake_restart_source(
                &lineage,
                Some(lineage.position(4)),
                vec![
                    restart_owned_page(&lineage, committed, committed_page.get(), 1)?,
                    restart_commit(&lineage, committed, 2)?,
                    suffix,
                ],
            ),
            {
                let mut store = FakeBatchCommittedPageRecoveryStore::new(lineage.clone());
                store.current.push(committed_snapshot);
                store
            },
            &committed_baseline,
        )?;
        let suffix = suffix_selected
            .plan_replay_window()
            .map_err(|_| TestError("suffix replay planning failed"))?;
        assert_eq!(suffix.checkpoint_frontier(), Some(2));
        assert_eq!(suffix.current_frontier(), Some(4));
        assert_eq!(suffix.inclusive_replay_start(), None);
        assert_eq!(suffix.replay_observations, [expected_suffix]);
        assert_eq!(
            suffix
                .selected
                .storage
                .store
                .observations
                .borrow()
                .as_slice(),
            [committed_page, committed_page]
        );
        assert!(suffix.selected.storage.store.attempts.is_empty());

        let uncommitted = durable_identity(161, 3)?;
        let inclusive_baseline = fake_completeness_baseline(
            &lineage,
            Some(lineage.position(2)),
            vec![
                restart_owned_page(&lineage, uncommitted, 95, 1)?,
                restart_raw_page(&lineage, 96, 2)?,
            ],
            Vec::new(),
        )?;
        assert_eq!(inclusive_baseline.replay_start().position(), Some(1));
        let inclusive_stream = vec![
            restart_owned_page(&lineage, uncommitted, 95, 1)?,
            restart_raw_page(&lineage, 96, 2)?,
            restart_commit(&lineage, uncommitted, 4)?,
        ];
        let expected_inclusive = inclusive_stream
            .iter()
            .map(OwnedDurableTransactionRestartReplayObservation::from)
            .collect::<Vec<_>>();
        let inclusive_selected = select_fake_restart_checkpoint(
            fake_restart_source(&lineage, Some(lineage.position(4)), inclusive_stream),
            FakeBatchCommittedPageRecoveryStore::new(lineage.clone()),
            &inclusive_baseline,
        )?;
        let inclusive = inclusive_selected
            .plan_replay_window()
            .map_err(|_| TestError("inclusive replay planning failed"))?;
        assert_eq!(inclusive.checkpoint_frontier(), Some(2));
        assert_eq!(inclusive.current_frontier(), Some(4));
        assert_eq!(inclusive.inclusive_replay_start(), Some(1));
        assert_eq!(inclusive.replay_record_count(), 3);
        assert_eq!(inclusive.current_transaction_count(), 1);
        assert_eq!(inclusive.replay_observations, expected_inclusive);
        assert_eq!(inclusive.selected.storage.source.restart_callbacks, 2);
        assert_eq!(inclusive.selected.checkpoint_source.calls, 1);
        assert_eq!(
            inclusive.selected.storage.store.observations.borrow().len(),
            4
        );
        assert!(inclusive.selected.storage.store.attempts.is_empty());
        Ok(())
    }

    #[test]
    fn selected_checkpoint_replay_planning_fails_closed_by_exact_stage() -> Result<(), TestError> {
        let persistent_log_id =
            PersistentLogId::new(0x1611).ok_or(TestError("failure persistent log id"))?;
        let lineage = LogLineage::persistent(persistent_log_id);
        let committed = durable_identity(162, 1)?;
        let page_number = PageNumber::new(97).ok_or(TestError("failure page number"))?;
        let snapshot = FakeRecoverySnapshot {
            page_number,
            page_version: PageVersion::new(1),
            byte: 97,
            page_position: lineage.position(1),
        };
        let baseline = fake_completeness_baseline(
            &lineage,
            Some(lineage.position(2)),
            vec![
                restart_owned_page(&lineage, committed, page_number.get(), 1)?,
                restart_commit(&lineage, committed, 2)?,
            ],
            vec![snapshot.clone()],
        )?;

        let malformed_selected = select_fake_restart_checkpoint(
            fake_restart_source(
                &lineage,
                Some(lineage.position(4)),
                vec![
                    restart_owned_page(&lineage, committed, page_number.get(), 1)?,
                    restart_commit(&lineage, committed, 2)?,
                    restart_commit(&lineage, committed, 4)?,
                ],
            ),
            {
                let mut store = FakeBatchCommittedPageRecoveryStore::new(lineage.clone());
                store.current.push(snapshot.clone());
                store
            },
            &baseline,
        )?;
        let malformed = malformed_selected
            .plan_replay_window()
            .err()
            .ok_or(TestError("malformed suffix produced a replay plan"))?;
        assert!(matches!(
            malformed.error(),
            DurableTransactionRestartCheckpointReplayPlanningError::Evidence(source)
                if matches!(
                    source.as_ref(),
                    DurableTransactionRestartCheckpointReplayPlanningEvidenceError::CurrentAnalysis(
                        current
                    ) if matches!(
                        current.as_ref(),
                        DurableTransactionRestartAnalysisEvidenceError::DuplicateCommit {
                            transaction,
                            first_commit_position,
                            duplicate_commit_position,
                        } if *transaction == committed
                            && first_commit_position == &lineage.position(2)
                            && duplicate_commit_position == &lineage.position(4)
                    )
                )
        ));
        assert_eq!(
            Error::source(&malformed).map(ToString::to_string),
            Some(String::from(
                "restart replay planning failed: complete current restart analysis failed: transaction 162:1 has duplicate commits at positions 2 and 4"
            ))
        );
        let (uncheckpointed, malformed_error) = malformed
            .continue_with_full_recovery()
            .map_err(|_| TestError("malformed complete-prefix fallback was rejected"))?;
        assert!(matches!(
            malformed_error,
            DurableTransactionRestartCheckpointReplayPlanningError::Evidence(_)
        ));
        let recovered = uncheckpointed
            .recover()
            .map_err(|_| TestError("malformed fallback recovery failed"))?;
        assert!(matches!(
            recovered.analyze_restart().err(),
            Some(
                FailedTransactionPageStorageRestartAnalysisWithCompletenessCheckpoint {
                    storage: FailedTransactionPageStorageRestartAnalysis {
                        error: DurableTransactionRestartAnalysisError::Evidence(_),
                        ..
                    },
                    ..
                }
            )
        ));

        let raw_baseline = fake_completeness_baseline(
            &lineage,
            Some(lineage.position(1)),
            vec![restart_raw_page(&lineage, 98, 1)?],
            Vec::new(),
        )?;
        let mut changing_source = fake_restart_source(
            &lineage,
            Some(lineage.position(1)),
            vec![restart_raw_page(&lineage, 98, 1)?],
        );
        changing_source.restart_replacement_after_callback = Some((
            Some(lineage.position(1)),
            vec![restart_raw_page(&lineage, 99, 1)?],
        ));
        let changed_selected = select_fake_restart_checkpoint(
            changing_source,
            FakeBatchCommittedPageRecoveryStore::new(lineage.clone()),
            &raw_baseline,
        )?;
        let changed = changed_selected
            .plan_replay_window()
            .err()
            .ok_or(TestError("changed selected prefix produced a replay plan"))?;
        assert!(matches!(
            changed.error(),
            DurableTransactionRestartCheckpointReplayPlanningError::Evidence(source)
                if matches!(
                    source.as_ref(),
                    DurableTransactionRestartCheckpointReplayPlanningEvidenceError::SelectedBaselineMismatch(
                        mismatch
                    ) if mismatch.durable_frontier() == Some(1)
                        && mismatch.page_count() == 1
                        && mismatch.inclusive_replay_start() == Some(1)
                )
        ));
        assert_eq!(changed.selected.storage.source.restart_callbacks, 2);
        assert_eq!(changed.selected.checkpoint_source.calls, 1);

        let mut store_fault_source = fake_restart_source(
            &lineage,
            Some(lineage.position(1)),
            vec![restart_raw_page(&lineage, 98, 1)?],
        );
        store_fault_source.restart_events = Some(Rc::new(RefCell::new(Vec::new())));
        let mut store_fault = FakeBatchCommittedPageRecoveryStore::new(lineage.clone());
        let raw_page = PageNumber::new(98).ok_or(TestError("raw failure page"))?;
        store_fault.observation_fault_on_attempt =
            Some((2, raw_page, FakeFault("planned store observation")));
        let store_selected =
            select_fake_restart_checkpoint(store_fault_source, store_fault, &raw_baseline)?;
        let store_failed = store_selected
            .plan_replay_window()
            .err()
            .ok_or(TestError("planned store failure produced success"))?;
        assert!(matches!(
            store_failed.error(),
            DurableTransactionRestartCheckpointReplayPlanningError::Evidence(source)
                if matches!(
                    source.as_ref(),
                    DurableTransactionRestartCheckpointReplayPlanningEvidenceError::CheckpointRevalidation(
                        revalidation
                    ) if matches!(
                        revalidation.as_ref(),
                        DurableTransactionRestartCheckpointCompletenessBaselineValidationEvidenceError::CompletenessEvidence(
                            completeness
                        ) if matches!(
                            completeness.as_ref(),
                            DurableTransactionRestartCompletenessError::StoreObservation {
                                page_number,
                                source: FakeFault("planned store observation"),
                            } if *page_number == raw_page
                        )
                    )
                )
        ));
        assert_eq!(
            store_failed
                .selected
                .storage
                .store
                .observations
                .borrow()
                .as_slice(),
            [raw_page, raw_page]
        );
        assert!(store_failed.selected.storage.store.attempts.is_empty());
        Ok(())
    }

    #[test]
    fn selected_checkpoint_replay_planning_preserves_callback_source_failures_and_fallback()
    -> Result<(), TestError> {
        let persistent_log_id =
            PersistentLogId::new(0x1612).ok_or(TestError("source persistent log id"))?;
        let lineage = LogLineage::persistent(persistent_log_id);
        let baseline = fake_completeness_baseline(&lineage, None, Vec::new(), Vec::new())?;

        for (after_callback, expected_callbacks) in [(false, 1), (true, 2)] {
            let mut source = fake_restart_source(&lineage, None, Vec::new());
            if after_callback {
                source.restart_after_callback_error_on_callback =
                    Some((2, FakeFault("planning source after callback")));
            } else {
                source.restart_before_callback_error_on_callback =
                    Some((2, FakeFault("planning source before callback")));
            }
            let selected = select_fake_restart_checkpoint(
                source,
                FakeBatchCommittedPageRecoveryStore::new(lineage.clone()),
                &baseline,
            )?;
            let failed = selected.plan_replay_window().err().ok_or(TestError(
                "scheduled planning source failure became success",
            ))?;
            let expected = if after_callback {
                FakeFault("planning source after callback")
            } else {
                FakeFault("planning source before callback")
            };
            assert!(matches!(
                failed.error(),
                DurableTransactionRestartCheckpointReplayPlanningError::Source(actual)
                    if *actual == expected
            ));
            assert_eq!(
                Error::source(&failed).map(ToString::to_string),
                Some(format!("restart replay planning source failed: {expected}"))
            );
            assert_eq!(
                failed.selected.storage.source.restart_callbacks,
                expected_callbacks
            );
            assert_eq!(failed.selected.checkpoint_source.calls, 1);

            let (uncheckpointed, error) = failed
                .continue_with_full_recovery()
                .map_err(|_| TestError("source-failed complete-prefix fallback was rejected"))?;
            assert!(matches!(
                error,
                DurableTransactionRestartCheckpointReplayPlanningError::Source(actual)
                    if actual == expected
            ));
            let analyzed = uncheckpointed
                .recover()
                .map_err(|_| TestError("source-failed fallback recovery failed"))?
                .analyze_restart()
                .map_err(|_| TestError("source-failed fallback analysis failed"))?;
            let (source, store, report, analysis, checkpoint) = analyzed.into_parts();
            assert_eq!(source.restart_callbacks, expected_callbacks + 1);
            assert!(store.attempts.is_empty());
            assert!(report.pages().is_empty());
            assert_eq!(analysis.durable_frontier(), None);
            assert_eq!(checkpoint.calls, 1);
        }
        Ok(())
    }

    #[test]
    fn replay_page_repair_preparation_classifies_checkpoint_and_suffix_pages()
    -> Result<(), TestError> {
        let persistent_log_id =
            PersistentLogId::new(0x1630).ok_or(TestError("repair persistent log id"))?;
        let lineage = LogLineage::persistent(persistent_log_id);
        let checkpoint_committed = durable_identity(163, 1)?;
        let checkpoint_uncommitted = durable_identity(163, 2)?;
        let later_uncommitted = durable_identity(163, 3)?;
        let suffix_uncommitted = durable_identity(163, 4)?;
        let suffix_committed = durable_identity(163, 5)?;
        let checkpoint_current =
            PageNumber::new(171).ok_or(TestError("checkpoint current page"))?;
        let checkpoint_missing =
            PageNumber::new(172).ok_or(TestError("checkpoint missing page"))?;
        let checkpoint_behind = PageNumber::new(173).ok_or(TestError("checkpoint behind page"))?;
        let checkpoint_later_commit =
            PageNumber::new(174).ok_or(TestError("checkpoint later commit page"))?;
        let suffix_current = PageNumber::new(175).ok_or(TestError("suffix current page"))?;
        let suffix_no_required =
            PageNumber::new(176).ok_or(TestError("suffix no-required page"))?;
        let suffix_behind = PageNumber::new(177).ok_or(TestError("suffix behind page"))?;

        let checkpoint_stream = vec![
            restart_raw_page(&lineage, checkpoint_current.get(), 1)?,
            restart_owned_page(&lineage, checkpoint_committed, checkpoint_missing.get(), 2)?,
            restart_commit(&lineage, checkpoint_committed, 3)?,
            restart_raw_page(&lineage, checkpoint_behind.get(), 4)?,
            restart_raw_page(&lineage, checkpoint_behind.get(), 5)?,
            restart_owned_page(
                &lineage,
                checkpoint_uncommitted,
                checkpoint_later_commit.get(),
                6,
            )?,
        ];
        let current_snapshot = FakeRecoverySnapshot {
            page_number: checkpoint_current,
            page_version: PageVersion::new(1),
            byte: u8::try_from(checkpoint_current.get())
                .map_err(|_| TestError("checkpoint current byte"))?,
            page_position: lineage.position(1),
        };
        let behind_snapshot = FakeRecoverySnapshot {
            page_number: checkpoint_behind,
            page_version: PageVersion::new(4),
            byte: u8::try_from(checkpoint_behind.get())
                .map_err(|_| TestError("checkpoint behind byte"))?,
            page_position: lineage.position(4),
        };
        let baseline = fake_completeness_baseline(
            &lineage,
            Some(lineage.position(6)),
            checkpoint_stream,
            vec![current_snapshot.clone(), behind_snapshot.clone()],
        )?;
        assert_eq!(baseline.replay_start().position(), Some(2));

        let current_stream = vec![
            restart_raw_page(&lineage, checkpoint_current.get(), 1)?,
            restart_owned_page(&lineage, checkpoint_committed, checkpoint_missing.get(), 2)?,
            restart_commit(&lineage, checkpoint_committed, 3)?,
            restart_raw_page(&lineage, checkpoint_behind.get(), 4)?,
            restart_raw_page(&lineage, checkpoint_behind.get(), 5)?,
            restart_owned_page(
                &lineage,
                checkpoint_uncommitted,
                checkpoint_later_commit.get(),
                6,
            )?,
            restart_owned_page(&lineage, later_uncommitted, checkpoint_current.get(), 7)?,
            restart_commit(&lineage, checkpoint_uncommitted, 8)?,
            restart_raw_page(&lineage, suffix_current.get(), 9)?,
            restart_owned_page(&lineage, suffix_uncommitted, suffix_no_required.get(), 10)?,
            restart_raw_page(&lineage, suffix_behind.get(), 11)?,
            restart_owned_page(&lineage, suffix_committed, suffix_behind.get(), 12)?,
            restart_commit(&lineage, suffix_committed, 13)?,
        ];
        let suffix_current_snapshot = FakeRecoverySnapshot {
            page_number: suffix_current,
            page_version: PageVersion::new(9),
            byte: u8::try_from(suffix_current.get())
                .map_err(|_| TestError("suffix current byte"))?,
            page_position: lineage.position(9),
        };
        let suffix_behind_snapshot = FakeRecoverySnapshot {
            page_number: suffix_behind,
            page_version: PageVersion::new(11),
            byte: u8::try_from(suffix_behind.get()).map_err(|_| TestError("suffix behind byte"))?,
            page_position: lineage.position(11),
        };
        let mut store = FakeBatchCommittedPageRecoveryStore::new(lineage.clone());
        store.current = vec![
            current_snapshot,
            behind_snapshot,
            suffix_current_snapshot,
            suffix_behind_snapshot,
        ];
        let selected = select_fake_restart_checkpoint(
            fake_restart_source(&lineage, Some(lineage.position(13)), current_stream),
            store,
            &baseline,
        )?;
        let planned = selected
            .plan_replay_window()
            .map_err(|_| TestError("repair replay planning"))?;
        assert_eq!(planned.replay_record_count(), 12);
        assert_eq!(planned.selected.storage.source.restart_callbacks, 2);
        assert_eq!(
            planned.selected.storage.store.observations.borrow().len(),
            8
        );

        let preparation = planned.prepare_page_repairs();
        let TransactionPageStorageRestartCheckpointRepairPreparation::Prepared(prepared) =
            preparation
        else {
            return Err(TestError("repair preparation unexpectedly failed"));
        };
        assert_eq!(prepared.persistent_log_id(), persistent_log_id);
        assert_eq!(prepared.checkpoint_frontier(), Some(6));
        assert_eq!(prepared.current_frontier(), Some(13));
        assert_eq!(prepared.page_count(), 7);
        assert_eq!(prepared.no_required_image_count(), 1);
        assert_eq!(prepared.unchanged_checkpoint_current_count(), 1);
        assert_eq!(prepared.already_current_count(), 1);
        assert_eq!(prepared.repair_candidate_count(), 4);
        assert_eq!(
            prepared
                .page_repairs
                .iter()
                .map(|repair| repair.page_number)
                .collect::<Vec<_>>(),
            [
                checkpoint_current,
                checkpoint_missing,
                checkpoint_behind,
                checkpoint_later_commit,
                suffix_current,
                suffix_no_required,
                suffix_behind,
            ]
        );
        assert!(matches!(
            prepared.page_repairs[0].resolution,
            PreparedTransactionRestartCheckpointPageRepairResolution::CheckpointCurrent(_)
        ));
        assert!(matches!(
            &prepared.page_repairs[1],
            PreparedTransactionRestartCheckpointPageRepair {
                target: Some(DurableTransactionRestartCheckpointPageRepairTarget {
                    kind:
                        DurableTransactionRestartCheckpointPageRepairTargetKind::CommittedTransaction {
                            transaction,
                            commit_position,
                        },
                    page_position,
                    ..
                }),
                resolution:
                    PreparedTransactionRestartCheckpointPageRepairResolution::Candidate(None),
                ..
            } if *transaction == checkpoint_committed
                && page_position == &lineage.position(2)
                && commit_position == &lineage.position(3)
        ));
        assert!(matches!(
            &prepared.page_repairs[2],
            PreparedTransactionRestartCheckpointPageRepair {
                target: Some(DurableTransactionRestartCheckpointPageRepairTarget {
                    kind: DurableTransactionRestartCheckpointPageRepairTargetKind::Raw,
                    page_position,
                    ..
                }),
                resolution:
                    PreparedTransactionRestartCheckpointPageRepairResolution::Candidate(
                        Some(source)
                    ),
                ..
            } if page_position == &lineage.position(5)
                && source.required_position() == &lineage.position(4)
        ));
        assert!(matches!(
            &prepared.page_repairs[3],
            PreparedTransactionRestartCheckpointPageRepair {
                target: Some(DurableTransactionRestartCheckpointPageRepairTarget {
                    kind:
                        DurableTransactionRestartCheckpointPageRepairTargetKind::CommittedTransaction {
                            transaction,
                            commit_position,
                        },
                    page_position,
                    ..
                }),
                resolution:
                    PreparedTransactionRestartCheckpointPageRepairResolution::Candidate(None),
                ..
            } if *transaction == checkpoint_uncommitted
                && page_position == &lineage.position(6)
                && commit_position == &lineage.position(8)
        ));
        assert!(matches!(
            prepared.page_repairs[4].resolution,
            PreparedTransactionRestartCheckpointPageRepairResolution::AlreadyCurrent(_)
        ));
        assert!(matches!(
            prepared.page_repairs[5].resolution,
            PreparedTransactionRestartCheckpointPageRepairResolution::NoRequiredImage
        ));
        assert!(matches!(
            &prepared.page_repairs[6],
            PreparedTransactionRestartCheckpointPageRepair {
                target: Some(DurableTransactionRestartCheckpointPageRepairTarget {
                    kind:
                        DurableTransactionRestartCheckpointPageRepairTargetKind::CommittedTransaction {
                            transaction,
                            commit_position,
                        },
                    page_position,
                    ..
                }),
                resolution:
                    PreparedTransactionRestartCheckpointPageRepairResolution::Candidate(
                        Some(source)
                    ),
                ..
            } if *transaction == suffix_committed
                && page_position == &lineage.position(12)
                && commit_position == &lineage.position(13)
                && source.required_position() == &lineage.position(11)
        ));
        assert_eq!(
            prepared
                .planned
                .selected
                .storage
                .store
                .observations
                .borrow()
                .as_slice(),
            [
                checkpoint_current,
                checkpoint_missing,
                checkpoint_behind,
                checkpoint_later_commit,
                checkpoint_current,
                checkpoint_missing,
                checkpoint_behind,
                checkpoint_later_commit,
                checkpoint_current,
                checkpoint_missing,
                checkpoint_behind,
                checkpoint_later_commit,
                suffix_current,
                suffix_no_required,
                suffix_behind,
            ]
        );
        assert_eq!(
            prepared.planned.selected.storage.source.restart_callbacks,
            2
        );
        assert!(prepared.planned.selected.storage.store.attempts.is_empty());
        assert_eq!(prepared.planned.selected.checkpoint_source.calls, 1);

        let analyzed = prepared
            .decline_page_repairs()
            .map_err(|_| TestError("prepared complete-prefix repairs decline was rejected"))?
            .recover()
            .map_err(|_| TestError("prepared repair fallback recovery"))?
            .analyze_restart()
            .map_err(|_| TestError("prepared repair fallback analysis"))?;
        let (source, store, _, analysis, checkpoint) = analyzed.into_parts();
        assert_eq!(source.restart_callbacks, 3);
        assert_eq!(analysis.durable_frontier(), Some(&lineage.position(13)));
        assert!(store.attempts.is_empty());
        assert_eq!(checkpoint.calls, 1);
        Ok(())
    }

    fn suffix_repair_preparation_error(
        lineage: &LogLineage,
        observations: Vec<DurableTransactionRestartObservation<1>>,
        snapshot_page: PageNumber,
        snapshot: FakeRecoverySnapshot,
    ) -> Result<DurableTransactionRestartCheckpointRepairPreparationError<FakeFault>, TestError>
    {
        let frontier = observations
            .last()
            .map(DurableTransactionRestartObservation::position)
            .cloned();
        let baseline = fake_completeness_baseline(lineage, None, Vec::new(), Vec::new())?;
        let mut store = FakeBatchCommittedPageRecoveryStore::new(lineage.clone());
        store.observation_override = Some((snapshot_page, snapshot));
        let selected = select_fake_restart_checkpoint(
            fake_restart_source(lineage, frontier, observations),
            store,
            &baseline,
        )?;
        let planned = selected
            .plan_replay_window()
            .map_err(|_| TestError("suffix failure replay planning"))?;
        let preparation = planned.prepare_page_repairs();
        let TransactionPageStorageRestartCheckpointRepairPreparation::Failed(failed) = preparation
        else {
            return Err(TestError("suffix repair contradiction prepared"));
        };
        assert_eq!(
            failed
                .planned
                .selected
                .storage
                .store
                .observations
                .borrow()
                .as_slice(),
            [snapshot_page]
        );
        assert_eq!(failed.planned.selected.storage.source.restart_callbacks, 2);
        assert!(failed.planned.selected.storage.store.attempts.is_empty());
        let (_uncheckpointed, error) = failed
            .continue_with_full_recovery()
            .map_err(|_| TestError("complete-prefix repair fallback was rejected"))?;
        Ok(error)
    }

    #[test]
    fn replay_page_repair_preparation_handles_empty_replay_and_physical_recency()
    -> Result<(), TestError> {
        let persistent_log_id =
            PersistentLogId::new(0x1635).ok_or(TestError("edge persistent log id"))?;
        let lineage = LogLineage::persistent(persistent_log_id);
        let store_only_page = PageNumber::new(184).ok_or(TestError("store-only page"))?;
        let baseline = fake_completeness_baseline(&lineage, None, Vec::new(), Vec::new())?;
        let mut store = FakeBatchCommittedPageRecoveryStore::new(lineage.clone());
        store.current.push(FakeRecoverySnapshot {
            page_number: store_only_page,
            page_version: PageVersion::new(1),
            byte: u8::try_from(store_only_page.get())
                .map_err(|_| TestError("store-only page byte"))?,
            page_position: lineage.position(1),
        });
        let selected = select_fake_restart_checkpoint(
            fake_restart_source(&lineage, None, Vec::new()),
            store,
            &baseline,
        )?;
        let planned = selected
            .plan_replay_window()
            .map_err(|_| TestError("empty repair replay planning"))?;
        assert_eq!(planned.replay_record_count(), 0);
        let TransactionPageStorageRestartCheckpointRepairPreparation::Prepared(empty) =
            planned.prepare_page_repairs()
        else {
            return Err(TestError("empty repair preparation failed"));
        };
        assert_eq!(empty.page_count(), 0);
        assert_eq!(empty.no_required_image_count(), 0);
        assert_eq!(empty.unchanged_checkpoint_current_count(), 0);
        assert_eq!(empty.already_current_count(), 0);
        assert_eq!(empty.repair_candidate_count(), 0);
        assert!(
            empty
                .planned
                .selected
                .storage
                .store
                .observations
                .borrow()
                .is_empty()
        );
        assert_eq!(empty.planned.selected.storage.source.restart_callbacks, 2);
        let TransactionPageStorageRestartCheckpointPageRepairExecution::Repaired(empty) =
            empty.execute_page_repairs()
        else {
            return Err(TestError("empty repair execution failed"));
        };
        assert!(empty.page_outcomes().is_empty());

        let transaction = durable_identity(163, 9)?;
        let replay_page = PageNumber::new(185).ok_or(TestError("physical recency page"))?;
        let replay = vec![
            DurableTransactionRestartObservation::TransactionPage(durable_page_observation(
                &lineage,
                transaction,
                replay_page.get(),
                200,
                0xA5,
                1,
            )?),
            restart_commit(&lineage, transaction, 2)?,
            DurableTransactionRestartObservation::Page(physical_page_observation(
                &lineage,
                replay_page.get(),
                1,
                0x5A,
                3,
            )?),
        ];
        let selected = select_fake_restart_checkpoint(
            fake_restart_source(&lineage, Some(lineage.position(3)), replay),
            FakeBatchCommittedPageRecoveryStore::new(lineage.clone()),
            &baseline,
        )?;
        let planned = selected
            .plan_replay_window()
            .map_err(|_| TestError("physical recency replay planning"))?;
        let TransactionPageStorageRestartCheckpointRepairPreparation::Prepared(prepared) =
            planned.prepare_page_repairs()
        else {
            return Err(TestError("physical recency repair preparation failed"));
        };
        assert_eq!(prepared.page_count(), 1);
        assert_eq!(prepared.repair_candidate_count(), 1);
        assert!(matches!(
            &prepared.page_repairs[0],
            PreparedTransactionRestartCheckpointPageRepair {
                target: Some(DurableTransactionRestartCheckpointPageRepairTarget {
                    kind: DurableTransactionRestartCheckpointPageRepairTargetKind::Raw,
                    page_version,
                    bytes,
                    page_position,
                    ..
                }),
                resolution:
                    PreparedTransactionRestartCheckpointPageRepairResolution::Candidate(None),
                ..
            } if *page_version == PageVersion::new(1)
                && *bytes == [0x5A]
                && page_position == &lineage.position(3)
        ));
        assert_eq!(
            prepared
                .planned
                .selected
                .storage
                .store
                .observations
                .borrow()
                .as_slice(),
            [replay_page]
        );
        assert_eq!(
            prepared.planned.selected.storage.source.restart_callbacks,
            2
        );
        Ok(())
    }

