    #[test]
    fn replay_page_repair_preparation_rejects_snapshot_contradictions() -> Result<(), TestError> {
        let persistent_log_id =
            PersistentLogId::new(0x1631).ok_or(TestError("contradiction persistent log id"))?;
        let lineage = LogLineage::persistent(persistent_log_id);
        let page_number = PageNumber::new(180).ok_or(TestError("contradiction page"))?;
        let other_page = PageNumber::new(181).ok_or(TestError("unexpected page"))?;

        let unexpected = suffix_repair_preparation_error(
            &lineage,
            vec![restart_raw_page(&lineage, page_number.get(), 1)?],
            page_number,
            FakeRecoverySnapshot {
                page_number: other_page,
                page_version: PageVersion::new(1),
                byte: u8::try_from(other_page.get())
                    .map_err(|_| TestError("unexpected page byte"))?,
                page_position: lineage.position(1),
            },
        )?;
        assert!(matches!(
            unexpected,
            DurableTransactionRestartCheckpointRepairPreparationError::Evidence(source)
                if matches!(
                    source.as_ref(),
                    DurableTransactionRestartCheckpointRepairPreparationEvidenceError::UnexpectedSnapshotPage {
                        expected,
                        actual,
                        ..
                    } if *expected == page_number && *actual == other_page
                )
        ));

        let foreign = LogLineage::persistent(
            PersistentLogId::new(0x1632).ok_or(TestError("foreign persistent log id"))?,
        );
        let foreign_error = suffix_repair_preparation_error(
            &lineage,
            vec![restart_raw_page(&lineage, page_number.get(), 1)?],
            page_number,
            FakeRecoverySnapshot {
                page_number,
                page_version: PageVersion::new(1),
                byte: u8::try_from(page_number.get())
                    .map_err(|_| TestError("foreign page byte"))?,
                page_position: foreign.position(1),
            },
        )?;
        assert!(matches!(
            foreign_error,
            DurableTransactionRestartCheckpointRepairPreparationError::Evidence(source)
                if matches!(
                    source.as_ref(),
                    DurableTransactionRestartCheckpointRepairPreparationEvidenceError::ForeignSnapshotLineage {
                        page_number: actual,
                        ..
                    } if *actual == page_number
                )
        ));

        let payload_error = suffix_repair_preparation_error(
            &lineage,
            vec![restart_raw_page(&lineage, page_number.get(), 1)?],
            page_number,
            FakeRecoverySnapshot {
                page_number,
                page_version: PageVersion::new(1),
                byte: 0,
                page_position: lineage.position(1),
            },
        )?;
        assert!(matches!(
            payload_error,
            DurableTransactionRestartCheckpointRepairPreparationError::Evidence(source)
                if matches!(
                    source.as_ref(),
                    DurableTransactionRestartCheckpointRepairPreparationEvidenceError::SnapshotPayloadContradiction {
                        page_number: actual,
                        ..
                    } if *actual == page_number
                )
        ));

        let unbacked_error = suffix_repair_preparation_error(
            &lineage,
            vec![
                restart_raw_page(&lineage, page_number.get(), 1)?,
                restart_raw_page(&lineage, page_number.get(), 3)?,
            ],
            page_number,
            FakeRecoverySnapshot {
                page_number,
                page_version: PageVersion::new(2),
                byte: u8::try_from(page_number.get())
                    .map_err(|_| TestError("unbacked page byte"))?,
                page_position: lineage.position(2),
            },
        )?;
        assert!(matches!(
            unbacked_error,
            DurableTransactionRestartCheckpointRepairPreparationError::Evidence(source)
                if matches!(
                    source.as_ref(),
                    DurableTransactionRestartCheckpointRepairPreparationEvidenceError::SuffixSnapshotRecordMissing {
                        page_number: actual,
                        ..
                    } if *actual == page_number
                )
        ));

        let after_error = suffix_repair_preparation_error(
            &lineage,
            vec![restart_raw_page(&lineage, page_number.get(), 1)?],
            page_number,
            FakeRecoverySnapshot {
                page_number,
                page_version: PageVersion::new(2),
                byte: u8::try_from(page_number.get()).map_err(|_| TestError("later page byte"))?,
                page_position: lineage.position(2),
            },
        )?;
        assert!(matches!(
            after_error,
            DurableTransactionRestartCheckpointRepairPreparationError::Evidence(source)
                if matches!(
                    source.as_ref(),
                    DurableTransactionRestartCheckpointRepairPreparationEvidenceError::SnapshotAfterTarget {
                        page_number: actual,
                        ..
                    } if *actual == page_number
                )
        ));

        let uncommitted = durable_identity(163, 6)?;
        let uncommitted_error = suffix_repair_preparation_error(
            &lineage,
            vec![restart_owned_page(
                &lineage,
                uncommitted,
                page_number.get(),
                1,
            )?],
            page_number,
            FakeRecoverySnapshot {
                page_number,
                page_version: PageVersion::new(1),
                byte: u8::try_from(page_number.get())
                    .map_err(|_| TestError("uncommitted page byte"))?,
                page_position: lineage.position(1),
            },
        )?;
        assert!(matches!(
            uncommitted_error,
            DurableTransactionRestartCheckpointRepairPreparationError::Evidence(source)
                if matches!(
                    source.as_ref(),
                    DurableTransactionRestartCheckpointRepairPreparationEvidenceError::SnapshotBackedByUncommittedTransaction {
                        page_number: actual_page,
                        transaction,
                        ..
                    } if *actual_page == page_number && *transaction == uncommitted
                )
        ));
        Ok(())
    }

    #[test]
    fn replay_page_repair_preparation_fails_before_store_for_retained_evidence_errors()
    -> Result<(), TestError> {
        let persistent_log_id =
            PersistentLogId::new(0x1633).ok_or(TestError("evidence persistent log id"))?;
        let lineage = LogLineage::persistent(persistent_log_id);
        let transaction = durable_identity(163, 7)?;
        let page_number = PageNumber::new(182).ok_or(TestError("evidence page"))?;
        let baseline = fake_completeness_baseline(
            &lineage,
            Some(lineage.position(2)),
            vec![
                restart_owned_page(&lineage, transaction, page_number.get(), 1)?,
                restart_commit(&lineage, transaction, 2)?,
            ],
            Vec::new(),
        )?;

        let selected = select_fake_restart_checkpoint(
            fake_restart_source(
                &lineage,
                Some(lineage.position(2)),
                vec![
                    restart_owned_page(&lineage, transaction, page_number.get(), 1)?,
                    restart_commit(&lineage, transaction, 2)?,
                ],
            ),
            FakeBatchCommittedPageRecoveryStore::new(lineage.clone()),
            &baseline,
        )?;
        let mut missing_dirty = selected
            .plan_replay_window()
            .map_err(|_| TestError("missing dirty replay planning"))?;
        missing_dirty.replay_observations.clear();
        let TransactionPageStorageRestartCheckpointRepairPreparation::Failed(missing_dirty) =
            missing_dirty.prepare_page_repairs()
        else {
            return Err(TestError("missing dirty image prepared"));
        };
        assert!(matches!(
            missing_dirty.error(),
            DurableTransactionRestartCheckpointRepairPreparationError::Evidence(source)
                if matches!(
                    source.as_ref(),
                    DurableTransactionRestartCheckpointRepairPreparationEvidenceError::DirtyCheckpointRequiredImageMissing {
                        page_number: actual,
                        page_position: 1,
                    } if *actual == page_number
                )
        ));
        assert_eq!(
            missing_dirty
                .planned
                .selected
                .storage
                .store
                .observations
                .borrow()
                .as_slice(),
            [page_number, page_number]
        );

        let selected = select_fake_restart_checkpoint(
            fake_restart_source(
                &lineage,
                Some(lineage.position(2)),
                vec![
                    restart_owned_page(&lineage, transaction, page_number.get(), 1)?,
                    restart_commit(&lineage, transaction, 2)?,
                ],
            ),
            FakeBatchCommittedPageRecoveryStore::new(lineage.clone()),
            &baseline,
        )?;
        let mut missing_transaction = selected
            .plan_replay_window()
            .map_err(|_| TestError("missing transaction replay planning"))?;
        missing_transaction.current_analysis.transactions.clear();
        let TransactionPageStorageRestartCheckpointRepairPreparation::Failed(missing_transaction) =
            missing_transaction.prepare_page_repairs()
        else {
            return Err(TestError("missing transaction entry prepared"));
        };
        assert!(matches!(
            missing_transaction.error(),
            DurableTransactionRestartCheckpointRepairPreparationError::Evidence(source)
                if matches!(
                    source.as_ref(),
                    DurableTransactionRestartCheckpointRepairPreparationEvidenceError::CurrentTransactionMissing {
                        transaction: actual,
                        ..
                    } if *actual == transaction
                )
        ));
        assert_eq!(
            missing_transaction
                .planned
                .selected
                .storage
                .store
                .observations
                .borrow()
                .as_slice(),
            [page_number, page_number]
        );

        let selected = select_fake_restart_checkpoint(
            fake_restart_source(
                &lineage,
                Some(lineage.position(2)),
                vec![
                    restart_owned_page(&lineage, transaction, page_number.get(), 1)?,
                    restart_commit(&lineage, transaction, 2)?,
                ],
            ),
            FakeBatchCommittedPageRecoveryStore::new(lineage.clone()),
            &baseline,
        )?;
        let mut missing_commit = selected
            .plan_replay_window()
            .map_err(|_| TestError("missing commit replay planning"))?;
        drop(missing_commit.replay_observations.pop());
        let TransactionPageStorageRestartCheckpointRepairPreparation::Failed(missing_commit) =
            missing_commit.prepare_page_repairs()
        else {
            return Err(TestError("missing commit record prepared"));
        };
        assert!(matches!(
            missing_commit.error(),
            DurableTransactionRestartCheckpointRepairPreparationError::Evidence(source)
                if matches!(
                    source.as_ref(),
                    DurableTransactionRestartCheckpointRepairPreparationEvidenceError::CommittedReplayRecordMissing {
                        transaction: actual,
                        ..
                    } if *actual == transaction
                )
        ));
        assert_eq!(
            missing_commit
                .planned
                .selected
                .storage
                .store
                .observations
                .borrow()
                .as_slice(),
            [page_number, page_number]
        );
        Ok(())
    }

    #[test]
    fn replay_page_repair_preparation_preserves_store_errors_and_source_changes()
    -> Result<(), TestError> {
        let persistent_log_id =
            PersistentLogId::new(0x1634).ok_or(TestError("store failure persistent log id"))?;
        let lineage = LogLineage::persistent(persistent_log_id);
        let page_number = PageNumber::new(183).ok_or(TestError("store failure page"))?;
        let baseline = fake_completeness_baseline(&lineage, None, Vec::new(), Vec::new())?;
        let mut fault_store = FakeBatchCommittedPageRecoveryStore::new(lineage.clone());
        fault_store.observation_fault = Some((page_number, FakeFault("repair observation")));
        let selected = select_fake_restart_checkpoint(
            fake_restart_source(
                &lineage,
                Some(lineage.position(1)),
                vec![restart_raw_page(&lineage, page_number.get(), 1)?],
            ),
            fault_store,
            &baseline,
        )?;
        let planned = selected
            .plan_replay_window()
            .map_err(|_| TestError("store failure replay planning"))?;
        let TransactionPageStorageRestartCheckpointRepairPreparation::Failed(failed) =
            planned.prepare_page_repairs()
        else {
            return Err(TestError("store observation failure prepared"));
        };
        assert!(matches!(
            failed.error(),
            DurableTransactionRestartCheckpointRepairPreparationError::StoreObservation {
                page_number: actual,
                source: FakeFault("repair observation"),
            } if *actual == page_number
        ));
        let preparation_source =
            Error::source(&failed).ok_or(TestError("repair preparation source missing"))?;
        assert_eq!(
            preparation_source.to_string(),
            String::from(
                "restart checkpoint repair source observation failed for page 183: repair observation"
            )
        );
        assert_eq!(
            preparation_source.source().map(ToString::to_string),
            Some(String::from("repair observation"))
        );
        let (uncheckpointed, error) = failed
            .continue_with_full_recovery()
            .map_err(|_| TestError("store-failed complete-prefix fallback was rejected"))?;
        assert!(matches!(
            error,
            DurableTransactionRestartCheckpointRepairPreparationError::StoreObservation { .. }
        ));
        let recovered = uncheckpointed
            .recover()
            .map_err(|_| TestError("store failure fallback recovery"))?;
        assert!(recovered.recovery_report().pages().is_empty());

        let current_snapshot = FakeRecoverySnapshot {
            page_number,
            page_version: PageVersion::new(1),
            byte: u8::try_from(page_number.get())
                .map_err(|_| TestError("source change page byte"))?,
            page_position: lineage.position(1),
        };
        let current_baseline = fake_completeness_baseline(
            &lineage,
            Some(lineage.position(1)),
            vec![restart_raw_page(&lineage, page_number.get(), 1)?],
            vec![current_snapshot.clone()],
        )?;
        let transaction = durable_identity(163, 8)?;
        let mut store = FakeBatchCommittedPageRecoveryStore::new(lineage.clone());
        store.current.push(current_snapshot);
        let selected = select_fake_restart_checkpoint(
            fake_restart_source(
                &lineage,
                Some(lineage.position(2)),
                vec![
                    restart_raw_page(&lineage, page_number.get(), 1)?,
                    restart_owned_page(&lineage, transaction, page_number.get(), 2)?,
                ],
            ),
            store,
            &current_baseline,
        )?;
        let mut planned = selected
            .plan_replay_window()
            .map_err(|_| TestError("source change replay planning"))?;
        planned.selected.storage.store.current.clear();
        let TransactionPageStorageRestartCheckpointRepairPreparation::Failed(changed) =
            planned.prepare_page_repairs()
        else {
            return Err(TestError("changed checkpoint source prepared"));
        };
        assert!(matches!(
            changed.error(),
            DurableTransactionRestartCheckpointRepairPreparationError::Evidence(source)
                if matches!(
                    source.as_ref(),
                    DurableTransactionRestartCheckpointRepairPreparationEvidenceError::CheckpointSourceChanged {
                        page_number: actual,
                        expected_position: Some(1),
                        actual_position: None,
                    } if *actual == page_number
                )
        ));
        assert_eq!(changed.planned.selected.storage.source.restart_callbacks, 2);
        assert!(changed.planned.selected.storage.store.attempts.is_empty());
        Ok(())
    }

    #[test]
    fn prepared_replay_page_repairs_execute_raw_committed_and_inert_decisions_in_order()
    -> Result<(), TestError> {
        let persistent_log_id =
            PersistentLogId::new(0x1660).ok_or(TestError("execution persistent log id"))?;
        let lineage = LogLineage::persistent(persistent_log_id);
        let checkpoint_current =
            PageNumber::new(191).ok_or(TestError("execution checkpoint page"))?;
        let raw_page = PageNumber::new(192).ok_or(TestError("execution raw page"))?;
        let committed_page = PageNumber::new(193).ok_or(TestError("execution committed page"))?;
        let no_required_page =
            PageNumber::new(194).ok_or(TestError("execution no-required page"))?;
        let already_current_page =
            PageNumber::new(195).ok_or(TestError("execution current target page"))?;
        let uncommitted = durable_identity(166, 1)?;
        let committed = durable_identity(166, 2)?;

        let checkpoint_snapshot = FakeRecoverySnapshot {
            page_number: checkpoint_current,
            page_version: PageVersion::new(1),
            byte: 191,
            page_position: lineage.position(1),
        };
        let baseline = fake_completeness_baseline(
            &lineage,
            Some(lineage.position(1)),
            vec![restart_raw_page(&lineage, checkpoint_current.get(), 1)?],
            vec![checkpoint_snapshot.clone()],
        )?;
        let current_stream = vec![
            restart_raw_page(&lineage, checkpoint_current.get(), 1)?,
            restart_owned_page(&lineage, uncommitted, checkpoint_current.get(), 2)?,
            restart_raw_page(&lineage, raw_page.get(), 3)?,
            restart_owned_page(&lineage, committed, committed_page.get(), 4)?,
            restart_commit(&lineage, committed, 5)?,
            restart_owned_page(&lineage, uncommitted, no_required_page.get(), 6)?,
            restart_raw_page(&lineage, already_current_page.get(), 7)?,
        ];
        let already_current_snapshot = FakeRecoverySnapshot {
            page_number: already_current_page,
            page_version: PageVersion::new(7),
            byte: 195,
            page_position: lineage.position(7),
        };
        let mut store = FakeBatchCommittedPageRecoveryStore::new(lineage.clone());
        store.current = vec![checkpoint_snapshot, already_current_snapshot];
        let prepared = prepare_fake_restart_checkpoint_page_repairs(
            fake_restart_source(&lineage, Some(lineage.position(7)), current_stream),
            store,
            &baseline,
        )?;
        assert_eq!(prepared.page_count(), 5);
        assert_eq!(prepared.unchanged_checkpoint_current_count(), 1);
        assert_eq!(prepared.repair_candidate_count(), 2);
        assert_eq!(prepared.no_required_image_count(), 1);
        assert_eq!(prepared.already_current_count(), 1);

        let TransactionPageStorageRestartCheckpointPageRepairExecution::Repaired(repaired) =
            prepared.execute_page_repairs()
        else {
            return Err(TestError("complete repair execution failed"));
        };
        assert_eq!(
            repaired.page_outcomes(),
            [
                TransactionRestartCheckpointPageRepairOutcome::CheckpointCurrent {
                    page_number: checkpoint_current,
                },
                TransactionRestartCheckpointPageRepairOutcome::Repaired {
                    page_number: raw_page,
                },
                TransactionRestartCheckpointPageRepairOutcome::Repaired {
                    page_number: committed_page,
                },
                TransactionRestartCheckpointPageRepairOutcome::NoRequiredImage {
                    page_number: no_required_page,
                },
                TransactionRestartCheckpointPageRepairOutcome::AlreadyCurrent {
                    page_number: already_current_page,
                },
            ]
        );
        let store = &repaired.prepared.planned.selected.storage.store;
        assert_eq!(store.attempts, [raw_page, committed_page]);
        assert!(matches!(
            store
                .current_observation(raw_page)
                .map_err(|_| TestError("raw repair observation"))?,
            Some(snapshot) if snapshot.required_position() == &lineage.position(3)
                && snapshot.image().bytes() == &[192]
        ));
        assert!(matches!(
            store
                .current_observation(committed_page)
                .map_err(|_| TestError("committed repair observation"))?,
            Some(snapshot) if snapshot.required_position() == &lineage.position(4)
                && snapshot.image().bytes() == &[193]
        ));
        let TransactionPageStorageRestartCheckpointRestoration::Restored(restored) =
            repaired.restore_transaction_state()
        else {
            return Err(TestError("complete repair transaction restoration failed"));
        };
        let callbacks_before_completion = restored
            .repaired
            .prepared
            .planned
            .selected
            .storage
            .source
            .restart_callbacks;
        let observations_before_completion = restored
            .repaired
            .prepared
            .planned
            .selected
            .storage
            .store
            .observations
            .borrow()
            .len();
        let summary = restored.transaction_summary();
        assert_eq!(summary.transaction_count(), 2);
        assert_eq!(summary.committed_count(), 1);
        assert_eq!(summary.unresolved_count(), 1);
        assert_eq!(summary.coordinator_epoch().get(), 167);

        let completed = restored
            .complete_restart()
            .map_err(|_| TestError("selected restart completion failed"))?;
        let evidence = completed.completion_evidence();
        assert_eq!(evidence.persistent_log_id(), persistent_log_id);
        assert_eq!(evidence.checkpoint_frontier(), Some(1));
        assert_eq!(evidence.current_frontier(), Some(7));
        assert_eq!(evidence.page_outcomes().len(), 5);
        assert_eq!(evidence.transaction_summary(), summary);
        assert_eq!(
            completed.parts().1.restart_callbacks,
            callbacks_before_completion + 1
        );
        assert_eq!(
            completed.parts().2.observations.borrow().len(),
            observations_before_completion + 5
        );
        assert_eq!(completed.evidence.replay_observations.len(), 6);
        assert_eq!(completed.evidence.page_repairs.len(), 5);

        let mut retained = completed
            .analyze_wal_retention()
            .map_err(|_| TestError("selected restart retention analysis failed"))?;
        let analysis = retained.retention_analysis();
        assert_eq!(analysis.persistent_log_id(), persistent_log_id);
        assert!(analysis.lineage().same_lineage(&lineage));
        assert_eq!(analysis.durable_frontier(), Some(7));
        assert_eq!(analysis.allocated_epoch_high_water(), 167);
        assert_eq!(analysis.floor().retained_first_record(), Some(1));
        assert_eq!(analysis.store_page_count(), 4);
        assert_eq!(analysis.unresolved_transaction_count(), 1);
        assert_eq!(analysis.requirements().len(), 6);
        assert_eq!(
            analysis.requirements()[0].cause(),
            DurableTransactionRestartWalRetentionRequirementCause::SelectedCheckpointFrontier
        );
        assert_eq!(
            analysis.requirements()[5].cause(),
            DurableTransactionRestartWalRetentionRequirementCause::UnresolvedTransaction {
                transaction: uncommitted,
            }
        );

        let live = retained.parts_mut().0.begin()?;
        assert_eq!(live.transaction_id().epoch().get(), 167);
        assert_eq!(live.transaction_id().sequence(), 1);
        assert_eq!(retained.completion_evidence().current_frontier(), Some(7));
        assert_eq!(
            retained
                .retention_analysis()
                .floor()
                .retained_first_record(),
            Some(1)
        );
        Ok(())
    }

    #[test]
    fn selected_restart_completion_revalidates_every_live_release_boundary() -> Result<(), TestError>
    {
        let persistent_log_id =
            PersistentLogId::new(0x1680).ok_or(TestError("completion persistent log id"))?;
        let lineage = LogLineage::persistent(persistent_log_id);
        let baseline = fake_completeness_baseline(&lineage, None, Vec::new(), Vec::new())?;
        let page_number = PageNumber::new(218).ok_or(TestError("completion page"))?;

        let mut source_failed = restore_fake_raw_restart_page(&lineage, &baseline, page_number)?;
        source_failed
            .repaired
            .prepared
            .planned
            .selected
            .storage
            .source
            .restart_before_callback_error = Some(FakeFault("final WAL source"));
        let source_failed = source_failed
            .complete_restart()
            .err()
            .ok_or(TestError("final WAL source failure was accepted"))?;
        assert!(matches!(
            source_failed.error(),
            DurableTransactionRestartCheckpointCompletionError::RestartAnalysis(
                DurableTransactionRestartAnalysisError::Source(FakeFault("final WAL source"))
            )
        ));
        assert_eq!(
            source_failed
                .transaction_summary()
                .coordinator_epoch()
                .get(),
            1
        );

        let mut frontier_changed = restore_fake_raw_restart_page(&lineage, &baseline, page_number)?;
        let observations_before = frontier_changed
            .repaired
            .prepared
            .planned
            .selected
            .storage
            .store
            .observations
            .borrow()
            .len();
        let advanced_page = PageNumber::new(219).ok_or(TestError("advanced completion page"))?;
        frontier_changed
            .repaired
            .prepared
            .planned
            .selected
            .storage
            .source
            .restart_frontier = Some(lineage.position(2));
        frontier_changed
            .repaired
            .prepared
            .planned
            .selected
            .storage
            .source
            .restart_observations
            .push(restart_raw_page(&lineage, advanced_page.get(), 2)?);
        let frontier_changed = frontier_changed
            .complete_restart()
            .err()
            .ok_or(TestError("advanced final WAL frontier was accepted"))?;
        assert!(matches!(
            frontier_changed.error(),
            DurableTransactionRestartCheckpointCompletionError::Evidence(source)
                if matches!(
                    source.as_ref(),
                    DurableTransactionRestartCheckpointCompletionEvidenceError::CurrentFrontierChanged {
                        expected: Some(1),
                        actual: Some(2),
                    }
                )
        ));
        assert_eq!(
            frontier_changed
                .restored
                .repaired
                .prepared
                .planned
                .selected
                .storage
                .store
                .observations
                .borrow()
                .len(),
            observations_before
        );

        let mut table_changed = restore_fake_raw_restart_page(&lineage, &baseline, page_number)?;
        let unexpected_transaction = durable_identity(168, 1)?;
        table_changed
            .repaired
            .prepared
            .planned
            .selected
            .storage
            .source
            .restart_observations = vec![restart_commit(&lineage, unexpected_transaction, 1)?];
        let table_changed = table_changed
            .complete_restart()
            .err()
            .ok_or(TestError("changed final transaction table was accepted"))?;
        assert!(matches!(
            table_changed.error(),
            DurableTransactionRestartCheckpointCompletionError::Evidence(source)
                if matches!(
                    source.as_ref(),
                    DurableTransactionRestartCheckpointCompletionEvidenceError::CurrentTransactionCountChanged {
                        expected: 0,
                        actual: 1,
                    }
                )
        ));

        let mut observation_failed =
            restore_fake_raw_restart_page(&lineage, &baseline, page_number)?;
        observation_failed
            .repaired
            .prepared
            .planned
            .selected
            .storage
            .store
            .observation_fault = Some((page_number, FakeFault("final page observation")));
        let observation_failed = observation_failed
            .complete_restart()
            .err()
            .ok_or(TestError("final page observation failure was accepted"))?;
        assert!(matches!(
            observation_failed.error(),
            DurableTransactionRestartCheckpointCompletionError::StoreObservation {
                page_number: actual,
                source: FakeFault("final page observation"),
            } if *actual == page_number
        ));

        let mut target_missing = restore_fake_raw_restart_page(&lineage, &baseline, page_number)?;
        target_missing
            .repaired
            .prepared
            .planned
            .selected
            .storage
            .store
            .current
            .clear();
        let target_missing = target_missing
            .complete_restart()
            .err()
            .ok_or(TestError("missing final repair target was accepted"))?;
        assert!(matches!(
            target_missing.error(),
            DurableTransactionRestartCheckpointCompletionError::Evidence(source)
                if matches!(
                    source.as_ref(),
                    DurableTransactionRestartCheckpointCompletionEvidenceError::FinalPageTargetMissing {
                        page_number: actual,
                    } if *actual == page_number
                )
        ));

        let mut outcome_changed = restore_fake_raw_restart_page(&lineage, &baseline, page_number)?;
        outcome_changed.repaired.page_outcomes[0] =
            TransactionRestartCheckpointPageRepairOutcome::NoRequiredImage { page_number };
        let outcome_changed = outcome_changed
            .complete_restart()
            .err()
            .ok_or(TestError("changed final page outcome was accepted"))?;
        assert!(matches!(
            outcome_changed.error(),
            DurableTransactionRestartCheckpointCompletionError::Evidence(source)
                if matches!(
                    source.as_ref(),
                    DurableTransactionRestartCheckpointCompletionEvidenceError::PageOutcomeChanged {
                        index: 0,
                        expected_page,
                        actual: TransactionRestartCheckpointPageRepairOutcome::NoRequiredImage {
                            page_number: actual,
                        },
                    } if *expected_page == page_number && *actual == page_number
                )
        ));

        let mut store_foreign = restore_fake_raw_restart_page(&lineage, &baseline, page_number)?;
        let foreign_lineage = LogLineage::persistent(
            PersistentLogId::new(0x168f).ok_or(TestError("completion foreign lineage"))?,
        );
        store_foreign
            .repaired
            .prepared
            .planned
            .selected
            .storage
            .store
            .lineage = foreign_lineage.clone();
        let store_foreign = store_foreign
            .complete_restart()
            .err()
            .ok_or(TestError("foreign final page store was accepted"))?;
        assert!(matches!(
            store_foreign.error(),
            DurableTransactionRestartCheckpointCompletionError::Evidence(source)
                if matches!(
                    source.as_ref(),
                    DurableTransactionRestartCheckpointCompletionEvidenceError::StoreLineageMismatch {
                        expected,
                        actual,
                    } if expected.same_lineage(&lineage)
                        && actual.same_lineage(&foreign_lineage)
                )
        ));

        let mut coordinator_used = restore_fake_raw_restart_page(&lineage, &baseline, page_number)?;
        let issued = coordinator_used.coordinator.begin()?;
        assert_eq!(issued.transaction_id().epoch().get(), 1);
        let coordinator_used = coordinator_used
            .complete_restart()
            .err()
            .ok_or(TestError("used restored coordinator was accepted"))?;
        assert!(matches!(
            coordinator_used.error(),
            DurableTransactionRestartCheckpointCompletionError::Evidence(source)
                if matches!(
                    source.as_ref(),
                    DurableTransactionRestartCheckpointCompletionEvidenceError::CoordinatorStateChanged {
                        next_sequence: Some(2),
                        lifecycle_count: 1,
                        staged_page_count: 0,
                    }
                )
        ));
        Ok(())
    }

    #[test]
    fn wal_retention_analysis_preserves_empty_maximum_and_source_constraints()
    -> Result<(), TestError> {
        let persistent_log_id =
            PersistentLogId::new(0x1690).ok_or(TestError("retention persistent log id"))?;
        let lineage = LogLineage::persistent(persistent_log_id);
        let baseline = fake_completeness_baseline(&lineage, None, Vec::new(), Vec::new())?;

        let empty = complete_fake_restart_checkpoint(
            fake_restart_source(&lineage, None, Vec::new()),
            FakeBatchCommittedPageRecoveryStore::new(lineage.clone()),
            &baseline,
        )?
        .analyze_wal_retention()
        .map_err(|_| TestError("empty retention analysis failed"))?;
        assert_eq!(
            empty.retention_analysis().persistent_log_id(),
            persistent_log_id
        );
        assert_eq!(empty.retention_analysis().durable_frontier(), None);
        assert_eq!(
            empty.retention_analysis().floor().retained_first_record(),
            None
        );
        assert_eq!(empty.retention_analysis().allocated_epoch_high_water(), 1);
        assert_eq!(empty.retention_analysis().store_page_count(), 0);
        assert!(empty.retention_analysis().requirements().is_empty());

        let page_number = PageNumber::new(220).ok_or(TestError("maximum retention page"))?;
        let mut maximum = complete_fake_raw_restart_page_positions(
            &lineage,
            &baseline,
            page_number,
            &[u64::MAX],
        )?;
        maximum.source.retention_source_constraint = Some(lineage.position(u64::MAX));
        let maximum = maximum
            .analyze_wal_retention()
            .map_err(|_| TestError("maximum retention analysis failed"))?;
        assert_eq!(
            maximum.retention_analysis().durable_frontier(),
            Some(u64::MAX)
        );
        assert_eq!(
            maximum.retention_analysis().floor().retained_first_record(),
            Some(u64::MAX)
        );
        assert_eq!(maximum.retention_analysis().requirements().len(), 2);
        assert_eq!(
            maximum.retention_analysis().requirements()[0].cause(),
            DurableTransactionRestartWalRetentionRequirementCause::StoredPage { page_number }
        );
        assert_eq!(
            maximum.retention_analysis().requirements()[1].cause(),
            DurableTransactionRestartWalRetentionRequirementCause::SourceConstraint
        );
        Ok(())
    }

    #[test]
    fn wal_retention_analysis_retains_completed_owner_on_source_and_staleness_failures()
    -> Result<(), TestError> {
        let persistent_log_id =
            PersistentLogId::new(0x1691).ok_or(TestError("retention failure persistent id"))?;
        let lineage = LogLineage::persistent(persistent_log_id);
        let baseline = fake_completeness_baseline(&lineage, None, Vec::new(), Vec::new())?;
        let page_number = PageNumber::new(221).ok_or(TestError("retention failure page"))?;

        let mut inventory_failed =
            complete_fake_raw_restart_page_positions(&lineage, &baseline, page_number, &[1])?;
        inventory_failed.store.inventory_error = Some(FakeFault("retention inventory"));
        let inventory_failed = inventory_failed
            .analyze_wal_retention()
            .err()
            .ok_or(TestError("retention inventory failure was accepted"))?;
        assert!(matches!(
            inventory_failed.error(),
            DurableTransactionRestartWalRetentionAnalysisError::StoreInventory(FakeFault(
                "retention inventory"
            ))
        ));
        assert_eq!(
            inventory_failed
                .transaction_summary()
                .coordinator_epoch()
                .get(),
            1
        );

        let mut metadata_failed =
            complete_fake_raw_restart_page_positions(&lineage, &baseline, page_number, &[1])?;
        metadata_failed.source.retention_metadata_error = Some(FakeFault("retention metadata"));
        let metadata_failed = metadata_failed
            .analyze_wal_retention()
            .err()
            .ok_or(TestError("retention metadata failure was accepted"))?;
        assert!(matches!(
            metadata_failed.error(),
            DurableTransactionRestartWalRetentionAnalysisError::MetadataSource(FakeFault(
                "retention metadata"
            ))
        ));

        let mut wal_failed =
            complete_fake_raw_restart_page_positions(&lineage, &baseline, page_number, &[1])?;
        wal_failed.source.restart_before_callback_error = Some(FakeFault("retention WAL"));
        let wal_failed = wal_failed
            .analyze_wal_retention()
            .err()
            .ok_or(TestError("retention WAL failure was accepted"))?;
        assert!(matches!(
            wal_failed.error(),
            DurableTransactionRestartWalRetentionAnalysisError::WalSource(FakeFault(
                "retention WAL"
            ))
        ));

        let mut allocator_stale =
            complete_fake_raw_restart_page_positions(&lineage, &baseline, page_number, &[1])?;
        allocator_stale.source.retention_metadata_epoch_override = NonZeroU64::new(2);
        let allocator_stale = allocator_stale
            .analyze_wal_retention()
            .err()
            .ok_or(TestError("stale allocator metadata was accepted"))?;
        assert!(matches!(
            allocator_stale.error(),
            DurableTransactionRestartWalRetentionAnalysisError::Evidence(source)
                if matches!(
                    source.as_ref(),
                    DurableTransactionRestartWalRetentionEvidenceError::AllocatedEpochHighWaterChanged {
                        expected: 1,
                        actual: 2,
                    }
                )
        ));

        let foreign_lineage = LogLineage::persistent(
            PersistentLogId::new(0x169F).ok_or(TestError("foreign retention lineage"))?,
        );
        let mut store_foreign =
            complete_fake_raw_restart_page_positions(&lineage, &baseline, page_number, &[1])?;
        store_foreign.store.lineage = foreign_lineage.clone();
        let store_foreign = store_foreign
            .analyze_wal_retention()
            .err()
            .ok_or(TestError("foreign inventory lineage was accepted"))?;
        assert!(matches!(
            store_foreign.error(),
            DurableTransactionRestartWalRetentionAnalysisError::Evidence(source)
                if matches!(
                    source.as_ref(),
                    DurableTransactionRestartWalRetentionEvidenceError::StoreLineageMismatch {
                        expected,
                        actual,
                    } if expected.same_lineage(&lineage)
                        && actual.same_lineage(&foreign_lineage)
                )
        ));

        let mut metadata_foreign =
            complete_fake_raw_restart_page_positions(&lineage, &baseline, page_number, &[1])?;
        metadata_foreign.source.retention_metadata_lineage_override = Some(foreign_lineage.clone());
        let metadata_foreign = metadata_foreign
            .analyze_wal_retention()
            .err()
            .ok_or(TestError("foreign retention metadata was accepted"))?;
        assert!(matches!(
            metadata_foreign.error(),
            DurableTransactionRestartWalRetentionAnalysisError::Evidence(source)
                if matches!(
                    source.as_ref(),
                    DurableTransactionRestartWalRetentionEvidenceError::MetadataLineageMismatch {
                        expected,
                        actual,
                    } if expected.same_lineage(&lineage)
                        && actual.same_lineage(&foreign_lineage)
                )
        ));

        let mut source_constraint_foreign =
            complete_fake_raw_restart_page_positions(&lineage, &baseline, page_number, &[1])?;
        source_constraint_foreign.source.retention_source_constraint =
            Some(foreign_lineage.position(1));
        let source_constraint_foreign = source_constraint_foreign
            .analyze_wal_retention()
            .err()
            .ok_or(TestError("foreign source constraint was accepted"))?;
        assert!(matches!(
            source_constraint_foreign.error(),
            DurableTransactionRestartWalRetentionAnalysisError::Evidence(source)
                if matches!(
                    source.as_ref(),
                    DurableTransactionRestartWalRetentionEvidenceError::ForeignSourceConstraint {
                        position,
                    } if position.lineage().same_lineage(&foreign_lineage)
                )
        ));

        let mut coordinator_used =
            complete_fake_raw_restart_page_positions(&lineage, &baseline, page_number, &[1])?;
        let active = coordinator_used.parts_mut().0.begin()?;
        assert_eq!(active.transaction_id().sequence(), 1);
        let coordinator_used = coordinator_used
            .analyze_wal_retention()
            .err()
            .ok_or(TestError(
                "used coordinator retention analysis was accepted",
            ))?;
        assert!(matches!(
            coordinator_used.error(),
            DurableTransactionRestartWalRetentionAnalysisError::Evidence(source)
                if matches!(
                    source.as_ref(),
                    DurableTransactionRestartWalRetentionEvidenceError::Completion {
                        source
                    } if matches!(
                        source.as_ref(),
                        DurableTransactionRestartCheckpointCompletionEvidenceError::CoordinatorStateChanged {
                            next_sequence: Some(2),
                            lifecycle_count: 1,
                            staged_page_count: 0,
                        }
                    )
                )
        ));
        Ok(())
    }

    #[test]
    fn wal_retention_analysis_rejects_incomplete_or_contradictory_page_inventory()
    -> Result<(), TestError> {
        let persistent_log_id =
            PersistentLogId::new(0x1692).ok_or(TestError("inventory rejection persistent id"))?;
        let lineage = LogLineage::persistent(persistent_log_id);
        let baseline = fake_completeness_baseline(&lineage, None, Vec::new(), Vec::new())?;
        let page_number = PageNumber::new(222).ok_or(TestError("inventory rejection page"))?;

        let mut duplicate =
            complete_fake_raw_restart_page_positions(&lineage, &baseline, page_number, &[1])?;
        let duplicate_snapshot = duplicate.store.current[0].clone();
        duplicate.store.inventory_override =
            Some(vec![duplicate_snapshot.clone(), duplicate_snapshot]);
        let duplicate = duplicate
            .analyze_wal_retention()
            .err()
            .ok_or(TestError("duplicate page inventory was accepted"))?;
        assert!(matches!(
            duplicate.error(),
            DurableTransactionRestartWalRetentionAnalysisError::Evidence(source)
                if matches!(
                    source.as_ref(),
                    DurableTransactionRestartWalRetentionEvidenceError::PageInventoryNotStrictlyIncreasing {
                        index: 1,
                        previous,
                        actual,
                    } if *previous == page_number && *actual == page_number
                )
        ));

        let mut missing =
            complete_fake_raw_restart_page_positions(&lineage, &baseline, page_number, &[1])?;
        missing.store.current.clear();
        let missing = missing
            .analyze_wal_retention()
            .err()
            .ok_or(TestError("missing page inventory was accepted"))?;
        assert!(matches!(
            missing.error(),
            DurableTransactionRestartWalRetentionAnalysisError::Evidence(source)
                if matches!(
                    source.as_ref(),
                    DurableTransactionRestartWalRetentionEvidenceError::RequiredPageSnapshotMissing {
                        page_number: actual,
                        required_position: 1,
                    } if *actual == page_number
                )
        ));

        let mut behind =
            complete_fake_raw_restart_page_positions(&lineage, &baseline, page_number, &[1, 2])?;
        behind.store.current[0].page_version = PageVersion::new(1);
        behind.store.current[0].page_position = lineage.position(1);
        let behind = behind
            .analyze_wal_retention()
            .err()
            .ok_or(TestError("behind page inventory was accepted"))?;
        assert!(matches!(
            behind.error(),
            DurableTransactionRestartWalRetentionAnalysisError::Evidence(source)
                if matches!(
                    source.as_ref(),
                    DurableTransactionRestartWalRetentionEvidenceError::RequiredPageSnapshotBehind {
                        page_number: actual,
                        stored_position: 1,
                        required_position: 2,
                    } if *actual == page_number
                )
        ));

        let mut contradictory =
            complete_fake_raw_restart_page_positions(&lineage, &baseline, page_number, &[1])?;
        contradictory.store.current[0].byte ^= 0xFF;
        let contradictory = contradictory
            .analyze_wal_retention()
            .err()
            .ok_or(TestError("contradictory page inventory was accepted"))?;
        assert!(matches!(
            contradictory.error(),
            DurableTransactionRestartWalRetentionAnalysisError::Evidence(source)
                if matches!(
                    source.as_ref(),
                    DurableTransactionRestartWalRetentionEvidenceError::PageInventorySnapshot {
                        page_number: actual,
                        source,
                    } if *actual == page_number
                        && matches!(
                            source.as_ref(),
                            DurableTransactionRestartCompletenessEvidenceError::SnapshotPayloadContradiction {
                                page_number: nested,
                                position: 1,
                            } if *nested == page_number
                        )
                )
        ));

        let foreign_lineage = LogLineage::persistent(
            PersistentLogId::new(0x169E).ok_or(TestError("foreign snapshot lineage"))?,
        );
        let mut foreign =
            complete_fake_raw_restart_page_positions(&lineage, &baseline, page_number, &[1])?;
        foreign.store.current[0].page_position = foreign_lineage.position(1);
        let foreign = foreign
            .analyze_wal_retention()
            .err()
            .ok_or(TestError("foreign snapshot inventory was accepted"))?;
        assert!(matches!(
            foreign.error(),
            DurableTransactionRestartWalRetentionAnalysisError::Evidence(source)
                if matches!(
                    source.as_ref(),
                    DurableTransactionRestartWalRetentionEvidenceError::PageInventorySnapshot {
                        page_number: actual,
                        source,
                    } if *actual == page_number
                        && matches!(
                            source.as_ref(),
                            DurableTransactionRestartCompletenessEvidenceError::ForeignSnapshotLineage {
                                page_number: nested,
                                position,
                            } if *nested == page_number
                                && position.lineage().same_lineage(&foreign_lineage)
                        )
                )
        ));

        let store_only_page = PageNumber::new(223).ok_or(TestError("store-only inventory page"))?;
        let mut store_only =
            complete_fake_raw_restart_page_positions(&lineage, &baseline, page_number, &[1])?;
        store_only.store.current.push(FakeRecoverySnapshot {
            page_number: store_only_page,
            page_version: PageVersion::new(1),
            byte: u8::try_from(store_only_page.get())
                .map_err(|_| TestError("store-only page byte"))?,
            page_position: lineage.position(1),
        });
        let store_only = store_only
            .analyze_wal_retention()
            .err()
            .ok_or(TestError("store-only page inventory was accepted"))?;
        assert!(matches!(
            store_only.error(),
            DurableTransactionRestartWalRetentionAnalysisError::Evidence(source)
                if matches!(
                    source.as_ref(),
                    DurableTransactionRestartWalRetentionEvidenceError::PageInventorySnapshot {
                        page_number: actual,
                        source,
                    } if *actual == store_only_page
                        && matches!(
                            source.as_ref(),
                            DurableTransactionRestartCompletenessEvidenceError::SnapshotPositionUnbacked {
                                page_number: nested,
                                position: 1,
                            } if *nested == store_only_page
                        )
                )
        ));

        let uncommitted = durable_identity(169, 1)?;
        let unresolved_page = PageNumber::new(224).ok_or(TestError("unresolved inventory page"))?;
        let mut unresolved = complete_fake_restart_checkpoint(
            fake_restart_source(
                &lineage,
                Some(lineage.position(1)),
                vec![restart_owned_page(
                    &lineage,
                    uncommitted,
                    unresolved_page.get(),
                    1,
                )?],
            ),
            FakeBatchCommittedPageRecoveryStore::new(lineage.clone()),
            &baseline,
        )?;
        unresolved.store.current.push(FakeRecoverySnapshot {
            page_number: unresolved_page,
            page_version: PageVersion::new(1),
            byte: u8::try_from(unresolved_page.get())
                .map_err(|_| TestError("unresolved page byte"))?,
            page_position: lineage.position(1),
        });
        let unresolved = unresolved
            .analyze_wal_retention()
            .err()
            .ok_or(TestError("unresolved-backed inventory was accepted"))?;
        assert!(matches!(
            unresolved.error(),
            DurableTransactionRestartWalRetentionAnalysisError::Evidence(source)
                if matches!(
                    source.as_ref(),
                    DurableTransactionRestartWalRetentionEvidenceError::PageInventorySnapshot {
                        page_number: actual,
                        source,
                    } if *actual == unresolved_page
                        && matches!(
                            source.as_ref(),
                            DurableTransactionRestartCompletenessEvidenceError::SnapshotBackedByUncommittedTransactionPage {
                                page_number: nested,
                                transaction,
                                page_position: 1,
                            } if *nested == unresolved_page && *transaction == uncommitted
                        )
                )
        ));
        Ok(())
    }

    #[test]
    fn selected_checkpoint_anchor_covers_every_authoritative_field_and_order()
    -> Result<(), TestError> {
        let persistent_log_id =
            PersistentLogId::new(0x1700).ok_or(TestError("anchor persistent id"))?;
        let first_transaction = durable_identity(170, 1)?;
        let second_transaction = durable_identity(170, 2)?;
        let first_page = PageNumber::new(230).ok_or(TestError("anchor first page"))?;
        let second_page = PageNumber::new(231).ok_or(TestError("anchor second page"))?;
        let baseline = DurableTransactionRestartCheckpointCompletenessBaseline {
            transaction_baseline: DurableTransactionRestartCheckpointBaseline {
                persistent_log_id,
                durable_frontier: Some(19),
                transactions: vec![
                    DurableTransactionRestartCheckpointBaselineEntry {
                        transaction: first_transaction,
                        first_owned_page_position: Some(2),
                        last_owned_page_position: Some(7),
                        owned_page_record_count: 2,
                        state: DurableTransactionRestartCheckpointBaselineState::Committed {
                            commit_position: 9,
                        },
                    },
                    DurableTransactionRestartCheckpointBaselineEntry {
                        transaction: second_transaction,
                        first_owned_page_position: Some(11),
                        last_owned_page_position: Some(11),
                        owned_page_record_count: 1,
                        state: DurableTransactionRestartCheckpointBaselineState::Uncommitted,
                    },
                ],
            },
            pages: vec![
                DurableTransactionRestartPageEntry {
                    page_number: first_page,
                    state: DurableTransactionRestartPageState::StoreCurrent {
                        required:
                            DurableTransactionRestartRequiredPageImage::CommittedTransaction {
                                transaction: first_transaction,
                                page_position: 7,
                                commit_position: 9,
                            },
                        stored_position: 7,
                    },
                },
                DurableTransactionRestartPageEntry {
                    page_number: second_page,
                    state: DurableTransactionRestartPageState::StoreBehind {
                        stored_position: 3,
                        required: DurableTransactionRestartRequiredPageImage::Raw {
                            page_position: 13,
                        },
                    },
                },
            ],
            replay_start: DurableTransactionRestartReplayStart::AtPosition {
                position: 11,
                cause: DurableTransactionRestartReplayStartCause::UncommittedTransaction {
                    transaction: second_transaction,
                },
            },
        };
        let anchor = selected_restart_checkpoint_anchor(&baseline);
        assert_eq!(anchor.version(), 1);
        assert_eq!(anchor.value(), 0x2d4b_6d2a_34bd_3e9e_bfbc_3090_213f_7548);

        let mut mutations = Vec::new();
        mutations
            .try_reserve_exact(22)
            .map_err(|_| TestError("anchor mutations"))?;
        let mut mutated = baseline.clone();
        mutated.transaction_baseline.persistent_log_id =
            PersistentLogId::new(0x1701).ok_or(TestError("mutated anchor id"))?;
        mutations.push(mutated);
        let mut mutated = baseline.clone();
        mutated.transaction_baseline.durable_frontier = None;
        mutations.push(mutated);
        let mut mutated = baseline.clone();
        mutated.transaction_baseline.transactions[0].transaction = second_transaction;
        mutations.push(mutated);
        let mut mutated = baseline.clone();
        mutated.transaction_baseline.transactions[0].first_owned_page_position = Some(3);
        mutations.push(mutated);
        let mut mutated = baseline.clone();
        mutated.transaction_baseline.transactions[0].last_owned_page_position = Some(8);
        mutations.push(mutated);
        let mut mutated = baseline.clone();
        mutated.transaction_baseline.transactions[0].owned_page_record_count = 3;
        mutations.push(mutated);
        let mut mutated = baseline.clone();
        mutated.transaction_baseline.transactions[0].state =
            DurableTransactionRestartCheckpointBaselineState::Uncommitted;
        mutations.push(mutated);
        let mut mutated = baseline.clone();
        mutated.transaction_baseline.transactions[0].state =
            DurableTransactionRestartCheckpointBaselineState::Committed {
                commit_position: 10,
            };
        mutations.push(mutated);
        let mut mutated = baseline.clone();
        mutated.transaction_baseline.transactions.swap(0, 1);
        mutations.push(mutated);
        let mut mutated = baseline.clone();
        mutated.pages[0].page_number = second_page;
        mutations.push(mutated);
        let mut mutated = baseline.clone();
        mutated.pages[0].state = DurableTransactionRestartPageState::StoreMissing {
            required: DurableTransactionRestartRequiredPageImage::CommittedTransaction {
                transaction: first_transaction,
                page_position: 7,
                commit_position: 9,
            },
        };
        mutations.push(mutated);
        let mut mutated = baseline.clone();
        if let DurableTransactionRestartPageState::StoreCurrent { required, .. } =
            &mut mutated.pages[0].state
        {
            *required = DurableTransactionRestartRequiredPageImage::Raw { page_position: 7 };
        }
        mutations.push(mutated);
        let mut mutated = baseline.clone();
        if let DurableTransactionRestartPageState::StoreCurrent {
            required:
                DurableTransactionRestartRequiredPageImage::CommittedTransaction { transaction, .. },
            ..
        } = &mut mutated.pages[0].state
        {
            *transaction = second_transaction;
        }
        mutations.push(mutated);
        let mut mutated = baseline.clone();
        if let DurableTransactionRestartPageState::StoreCurrent {
            required:
                DurableTransactionRestartRequiredPageImage::CommittedTransaction {
                    page_position, ..
                },
            ..
        } = &mut mutated.pages[0].state
        {
            *page_position = 8;
        }
        mutations.push(mutated);
        let mut mutated = baseline.clone();
        if let DurableTransactionRestartPageState::StoreCurrent {
            required:
                DurableTransactionRestartRequiredPageImage::CommittedTransaction {
                    commit_position, ..
                },
            ..
        } = &mut mutated.pages[0].state
        {
            *commit_position = 10;
        }
        mutations.push(mutated);
        let mut mutated = baseline.clone();
        if let DurableTransactionRestartPageState::StoreCurrent {
            stored_position, ..
        } = &mut mutated.pages[0].state
        {
            *stored_position = 6;
        }
        mutations.push(mutated);
        let mut mutated = baseline.clone();
        if let DurableTransactionRestartPageState::StoreBehind {
            required: DurableTransactionRestartRequiredPageImage::Raw { page_position },
            ..
        } = &mut mutated.pages[1].state
        {
            *page_position = 14;
        }
        mutations.push(mutated);
        let mut mutated = baseline.clone();
        mutated.pages.swap(0, 1);
        mutations.push(mutated);
        let mut mutated = baseline.clone();
        mutated.replay_start =
            DurableTransactionRestartReplayStart::AfterFrontier { frontier: Some(19) };
        mutations.push(mutated);
        let mut mutated = baseline.clone();
        mutated.replay_start = DurableTransactionRestartReplayStart::AtPosition {
            position: 12,
            cause: DurableTransactionRestartReplayStartCause::UncommittedTransaction {
                transaction: second_transaction,
            },
        };
        mutations.push(mutated);
        let mut mutated = baseline.clone();
        mutated.replay_start = DurableTransactionRestartReplayStart::AtPosition {
            position: 11,
            cause: DurableTransactionRestartReplayStartCause::StoreBehind {
                page_number: second_page,
            },
        };
        mutations.push(mutated);
        let mut mutated = baseline.clone();
        mutated.replay_start = DurableTransactionRestartReplayStart::AtPosition {
            position: 11,
            cause: DurableTransactionRestartReplayStartCause::UncommittedTransaction {
                transaction: first_transaction,
            },
        };
        mutations.push(mutated);

        for mutation in &mutations {
            assert_ne!(selected_restart_checkpoint_anchor(mutation), anchor);
        }
        let mut after_frontier = baseline.clone();
        after_frontier.replay_start =
            DurableTransactionRestartReplayStart::AfterFrontier { frontier: Some(19) };
        let after_frontier_anchor = selected_restart_checkpoint_anchor(&after_frontier);
        after_frontier.replay_start =
            DurableTransactionRestartReplayStart::AfterFrontier { frontier: Some(18) };
        assert_ne!(
            selected_restart_checkpoint_anchor(&after_frontier),
            after_frontier_anchor
        );
        let mut store_cause = baseline.clone();
        store_cause.replay_start = DurableTransactionRestartReplayStart::AtPosition {
            position: 11,
            cause: DurableTransactionRestartReplayStartCause::StoreMissing {
                page_number: first_page,
            },
        };
        let store_cause_anchor = selected_restart_checkpoint_anchor(&store_cause);
        store_cause.replay_start = DurableTransactionRestartReplayStart::AtPosition {
            position: 11,
            cause: DurableTransactionRestartReplayStartCause::StoreMissing {
                page_number: second_page,
            },
        };
        assert_ne!(
            selected_restart_checkpoint_anchor(&store_cause),
            store_cause_anchor
        );
        Ok(())
    }

    #[test]
    fn wal_reclamation_revalidates_in_order_and_returns_one_exact_receipt() -> Result<(), TestError>
    {
        let persistent_log_id =
            PersistentLogId::new(0x1702).ok_or(TestError("reclamation persistent id"))?;
        let lineage = LogLineage::persistent(persistent_log_id);
        let baseline = fake_completeness_baseline(&lineage, None, Vec::new(), Vec::new())?;
        let page_number = PageNumber::new(232).ok_or(TestError("reclamation page"))?;
        let mut analyzed = prepare_fake_raw_wal_reclamation(&lineage, &baseline, page_number)?;
        analyzed
            .completed
            .source
            .reclamation_replacement_format_version = Some(2);
        let events = Rc::new(RefCell::new(Vec::new()));
        analyzed.completed.checkpoint_source.events = Some(Rc::clone(&events));
        analyzed.completed.store.inventory_events = Some(Rc::clone(&events));
        analyzed.completed.source.restart_events = Some(Rc::clone(&events));
        analyzed.completed.source.reclamation_events = Some(Rc::clone(&events));
        assert_eq!(analyzed.completed.source.reclamation_generation, 0);
        assert_eq!(analyzed.completed.source.reclamation_anchor, None);

        let reclaimed = analyzed
            .reclaim_wal_prefix()
            .map_err(|_| TestError("valid WAL reclamation failed"))?;
        assert_eq!(
            events.borrow().as_slice(),
            [
                "completeness-checkpoint",
                "store-inventory",
                "retention-metadata",
                "reclamation-observe",
                "wal",
                "reclamation-observe",
                "reclamation-effect",
                "reclamation-observe",
                "reclamation-observe",
            ]
        );
        let receipt = reclaimed.reclamation_receipt();
        assert_eq!(receipt.persistent_log_id(), persistent_log_id);
        assert_eq!(receipt.source_physical_format_version(), 1);
        assert_eq!(receipt.replacement_physical_format_version(), 2);
        assert_eq!(receipt.old_generation(), 0);
        assert_eq!(receipt.new_generation(), 1);
        assert_eq!(receipt.retained_first_logical_record(), Some(1));
        assert_eq!(receipt.logical_position_high_water(), Some(1));
        assert_eq!(receipt.retained_logical_record_count(), 1);
        assert_eq!(receipt.retained_physical_unit_count(), 1);
        assert_eq!(receipt.allocated_epoch_high_water(), 1);
        let (_, source, _, evidence) = reclaimed.into_parts();
        assert_eq!(source.reclamation_effect_calls, 1);
        assert_eq!(
            source.reclamation_anchor,
            Some(evidence.receipt().selected_checkpoint_anchor())
        );
        assert_eq!(evidence.receipt().new_generation(), 1);
        assert_eq!(evidence.retention().durable_frontier(), Some(1));
        assert_eq!(evidence.completion().current_frontier(), Some(1));
        Ok(())
    }

    #[test]
    fn wal_reclamation_rejects_every_stale_preflight_class_before_effect() -> Result<(), TestError>
    {
        let persistent_log_id =
            PersistentLogId::new(0x1703).ok_or(TestError("stale reclamation persistent id"))?;
        let lineage = LogLineage::persistent(persistent_log_id);
        let baseline = fake_completeness_baseline(&lineage, None, Vec::new(), Vec::new())?;
        let page_number = PageNumber::new(233).ok_or(TestError("stale reclamation page"))?;

        let mut stale = prepare_fake_raw_wal_reclamation(&lineage, &baseline, page_number)?;
        stale.completed.checkpoint_source.checkpoint = None;
        require_fake_reclamation_preflight_failure(stale)?;

        let mut stale = prepare_fake_raw_wal_reclamation(&lineage, &baseline, page_number)?;
        if let Some(checkpoint) = &mut stale.completed.checkpoint_source.checkpoint {
            checkpoint.transactions.durable_frontier = Some(1);
        }
        require_fake_reclamation_preflight_failure(stale)?;

        let mut stale = prepare_fake_raw_wal_reclamation(&lineage, &baseline, page_number)?;
        stale.completed.store.inventory_error = Some(FakeFault("stale inventory"));
        require_fake_reclamation_preflight_failure(stale)?;

        let mut stale = prepare_fake_raw_wal_reclamation(&lineage, &baseline, page_number)?;
        stale.completed.source.retention_metadata_error =
            Some(FakeFault("stale retention metadata"));
        require_fake_reclamation_preflight_failure(stale)?;

        let mut stale = prepare_fake_raw_wal_reclamation(&lineage, &baseline, page_number)?;
        stale.completed.source.reclamation_observation_error =
            Some(FakeFault("stale reclamation metadata"));
        require_fake_reclamation_preflight_failure(stale)?;

        let mut stale = prepare_fake_raw_wal_reclamation(&lineage, &baseline, page_number)?;
        stale.completed.source.restart_before_callback_error = Some(FakeFault("stale WAL"));
        require_fake_reclamation_preflight_failure(stale)?;

        let mut stale = prepare_fake_raw_wal_reclamation(&lineage, &baseline, page_number)?;
        stale.completed.source.restart_frontier = Some(lineage.position(2));
        stale
            .completed
            .source
            .restart_observations
            .push(restart_raw_page(&lineage, page_number.get(), 2)?);
        require_fake_reclamation_preflight_failure(stale)?;

        let mut stale = prepare_fake_raw_wal_reclamation(&lineage, &baseline, page_number)?;
        stale.completed.store.current[0].byte ^= 0xff;
        require_fake_reclamation_preflight_failure(stale)?;

        let mut stale = prepare_fake_raw_wal_reclamation(&lineage, &baseline, page_number)?;
        stale.completed.source.retention_metadata_epoch_override = NonZeroU64::new(2);
        require_fake_reclamation_preflight_failure(stale)?;

        let mut stale = prepare_fake_raw_wal_reclamation(&lineage, &baseline, page_number)?;
        stale.completed.source.reclamation_format_version = 0;
        require_fake_reclamation_preflight_failure(stale)?;

        let foreign_lineage = LogLineage::persistent(
            PersistentLogId::new(0x170f).ok_or(TestError("foreign reclamation lineage"))?,
        );
        let mut stale = prepare_fake_raw_wal_reclamation(&lineage, &baseline, page_number)?;
        stale.completed.source.reclamation_lineage_override = Some(foreign_lineage.clone());
        require_fake_reclamation_preflight_failure(stale)?;

        let mut stale = prepare_fake_raw_wal_reclamation(&lineage, &baseline, page_number)?;
        stale.completed.source.reclamation_frontier_override =
            Some(Some(foreign_lineage.position(1)));
        require_fake_reclamation_preflight_failure(stale)?;

        let mut stale = prepare_fake_raw_wal_reclamation(&lineage, &baseline, page_number)?;
        stale.completed.source.reclamation_frontier_override = Some(None);
        require_fake_reclamation_preflight_failure(stale)?;

        let mut stale = prepare_fake_raw_wal_reclamation(&lineage, &baseline, page_number)?;
        stale.completed.source.reclamation_retained_first_override = Some(None);
        require_fake_reclamation_preflight_failure(stale)?;

        let mut stale = prepare_fake_raw_wal_reclamation(&lineage, &baseline, page_number)?;
        stale.completed.source.reclamation_epoch_override = NonZeroU64::new(2);
        require_fake_reclamation_preflight_failure(stale)?;

        let mut stale = prepare_fake_raw_wal_reclamation(&lineage, &baseline, page_number)?;
        stale.completed.source.reclamation_anchor = Some(selected_restart_checkpoint_anchor(
            &stale.completed.evidence.selected_baseline,
        ));
        require_fake_reclamation_preflight_failure(stale)?;

        let mut stale = prepare_fake_raw_wal_reclamation(&lineage, &baseline, page_number)?;
        stale.completed.source.reclamation_generation = 1;
        require_fake_reclamation_preflight_failure(stale)?;

        let mut stale = prepare_fake_raw_wal_reclamation(&lineage, &baseline, page_number)?;
        stale.completed.source.reclamation_generation = 1;
        let expected_anchor =
            selected_restart_checkpoint_anchor(&stale.completed.evidence.selected_baseline);
        stale.completed.source.reclamation_anchor =
            Some(DurableTransactionRestartSelectedCheckpointAnchor {
                version: expected_anchor.version(),
                value: expected_anchor.value() ^ 1,
            });
        require_fake_reclamation_preflight_failure(stale)?;

        let mut stale = prepare_fake_raw_wal_reclamation(&lineage, &baseline, page_number)?;
        stale.completed.source.reclamation_generation = u64::MAX;
        stale.completed.source.reclamation_anchor = Some(selected_restart_checkpoint_anchor(
            &stale.completed.evidence.selected_baseline,
        ));
        let stale = stale
            .reclaim_wal_prefix()
            .err()
            .ok_or(TestError("exhausted reclamation generation was accepted"))?;
        assert!(matches!(
            stale.error(),
            DurableTransactionRestartWalReclamationError::Preflight(
                DurableTransactionRestartWalReclamationPreflightError::Evidence(source)
            ) if matches!(
                source.as_ref(),
                DurableTransactionRestartWalReclamationEvidenceError::SourceGenerationExhausted {
                    generation: u64::MAX,
                }
            )
        ));
        assert_eq!(stale.analyzed.completed.source.reclamation_effect_calls, 0);

        let mut stale = prepare_fake_raw_wal_reclamation(&lineage, &baseline, page_number)?;
        stale
            .completed
            .source
            .reclamation_generation_after_first_observation = Some(1);
        require_fake_reclamation_preflight_failure(stale)?;

        let mut stale = prepare_fake_raw_wal_reclamation(&lineage, &baseline, page_number)?;
        stale.analysis.store_page_count = 2;
        require_fake_reclamation_preflight_failure(stale)?;

        let mut stale = prepare_fake_raw_wal_reclamation(&lineage, &baseline, page_number)?;
        stale.completed.source.retention_source_constraint = Some(lineage.position(1));
        require_fake_reclamation_preflight_failure(stale)?;

        let mut stale = prepare_fake_raw_wal_reclamation(&lineage, &baseline, page_number)?;
        let _active = stale.completed.coordinator.begin()?;
        require_fake_reclamation_preflight_failure(stale)?;
        Ok(())
    }

    #[test]
    fn wal_reclamation_effect_failures_and_bad_receipts_are_terminal() -> Result<(), TestError> {
        let persistent_log_id =
            PersistentLogId::new(0x1704).ok_or(TestError("terminal reclamation persistent id"))?;
        let lineage = LogLineage::persistent(persistent_log_id);
        let baseline = fake_completeness_baseline(&lineage, None, Vec::new(), Vec::new())?;
        let page_number = PageNumber::new(234).ok_or(TestError("terminal reclamation page"))?;

        let mut failed = prepare_fake_raw_wal_reclamation(&lineage, &baseline, page_number)?;
        failed.completed.source.reclamation_effect_error =
            Some(FakeFault("indeterminate reclamation"));
        let failed = failed
            .reclaim_wal_prefix()
            .err()
            .ok_or(TestError("effect failure was accepted"))?;
        assert!(matches!(
            failed.error(),
            DurableTransactionRestartWalReclamationError::OutcomeIndeterminate(
                DurableTransactionRestartWalReclamationOutcomeIndeterminateError::Effect(
                    FakeFault("indeterminate reclamation")
                )
            )
        ));
        assert_eq!(failed.analyzed.completed.source.reclamation_effect_calls, 1);

        let mut uninstalled = prepare_fake_raw_wal_reclamation(&lineage, &baseline, page_number)?;
        uninstalled.completed.source.reclamation_effect_override = Some(
            DurableTransactionRestartWalReclamationEffectObservation::new(
                DurableTransactionRestartWalReclamationReplacementObservation::new(0, 1, 1),
                Some(lineage.position(1)),
                Some(lineage.position(1)),
                1,
                1,
                NonZeroU64::MIN,
            ),
        );
        let uninstalled = uninstalled
            .reclaim_wal_prefix()
            .err()
            .ok_or(TestError("uninstalled replacement report was accepted"))?;
        assert!(matches!(
            uninstalled.error(),
            DurableTransactionRestartWalReclamationError::OutcomeIndeterminate(
                DurableTransactionRestartWalReclamationOutcomeIndeterminateError::InstalledEvidence(
                    DurableTransactionRestartWalReclamationEvidenceError::InstalledGenerationChanged {
                        expected: 1,
                        actual: 0,
                    }
                )
            )
        ));
        assert_eq!(
            uninstalled
                .analyzed
                .completed
                .source
                .reclamation_effect_calls,
            1
        );

        let mut installed_source_failure =
            prepare_fake_raw_wal_reclamation(&lineage, &baseline, page_number)?;
        installed_source_failure
            .completed
            .source
            .reclamation_observation_error_after_effect =
            Some(FakeFault("installed source observation"));
        let installed_source_failure = installed_source_failure
            .reclaim_wal_prefix()
            .err()
            .ok_or(TestError("installed source failure was accepted"))?;
        assert!(matches!(
            installed_source_failure.error(),
            DurableTransactionRestartWalReclamationError::OutcomeIndeterminate(
                DurableTransactionRestartWalReclamationOutcomeIndeterminateError::InstalledSource(
                    FakeFault("installed source observation")
                )
            )
        ));

        let mut installed_wal_failure =
            prepare_fake_raw_wal_reclamation(&lineage, &baseline, page_number)?;
        installed_wal_failure
            .completed
            .source
            .retained_restart_before_callback_error_after_effect =
            Some(FakeFault("installed retained suffix"));
        let installed_wal_failure = installed_wal_failure
            .reclaim_wal_prefix()
            .err()
            .ok_or(TestError("installed WAL failure was accepted"))?;
        assert!(matches!(
            installed_wal_failure.error(),
            DurableTransactionRestartWalReclamationError::OutcomeIndeterminate(
                DurableTransactionRestartWalReclamationOutcomeIndeterminateError::InstalledWal(
                    FakeFault("installed retained suffix")
                )
            )
        ));

        let mut installed_record_failure =
            prepare_fake_raw_wal_reclamation(&lineage, &baseline, page_number)?;
        installed_record_failure
            .completed
            .source
            .reclamation_retained_first_override = Some(Some(lineage.position(1)));
        installed_record_failure
            .completed
            .source
            .reclamation_drop_last_retained_after_effect = true;
        let installed_record_failure = installed_record_failure
            .reclaim_wal_prefix()
            .err()
            .ok_or(TestError("installed record loss was accepted"))?;
        assert!(matches!(
            installed_record_failure.error(),
            DurableTransactionRestartWalReclamationError::OutcomeIndeterminate(
                DurableTransactionRestartWalReclamationOutcomeIndeterminateError::InstalledEvidence(
                    DurableTransactionRestartWalReclamationEvidenceError::InstalledRetainedRecordCountChanged {
                        expected: 1,
                        actual: 0,
                    }
                )
            )
        ));

        let mut installed_payload_failure =
            prepare_fake_raw_wal_reclamation(&lineage, &baseline, page_number)?;
        installed_payload_failure
            .completed
            .source
            .reclamation_replace_last_retained_after_effect =
            Some(restart_raw_page(&lineage, page_number.get() - 1, 1)?);
        let installed_payload_failure = installed_payload_failure
            .reclaim_wal_prefix()
            .err()
            .ok_or(TestError("installed payload change was accepted"))?;
        assert!(matches!(
            installed_payload_failure.error(),
            DurableTransactionRestartWalReclamationError::OutcomeIndeterminate(
                DurableTransactionRestartWalReclamationOutcomeIndeterminateError::InstalledEvidence(
                    DurableTransactionRestartWalReclamationEvidenceError::InstalledRetainedRecordChanged {
                        index: 0,
                        expected_position: 1,
                        actual_position: 1,
                    }
                )
            )
        ));

        let mut invalid = prepare_fake_raw_wal_reclamation(&lineage, &baseline, page_number)?;
        invalid.completed.source.reclamation_effect_override = Some(
            DurableTransactionRestartWalReclamationEffectObservation::new(
                DurableTransactionRestartWalReclamationReplacementObservation::new(0, 1, 1),
                Some(lineage.position(1)),
                Some(lineage.position(1)),
                2,
                1,
                NonZeroU64::MIN,
            ),
        );
        let invalid = invalid
            .reclaim_wal_prefix()
            .err()
            .ok_or(TestError("invalid reclamation receipt was accepted"))?;
        assert!(matches!(
            invalid.error(),
            DurableTransactionRestartWalReclamationError::OutcomeIndeterminate(
                DurableTransactionRestartWalReclamationOutcomeIndeterminateError::Receipt(source)
            ) if matches!(
                source,
                DurableTransactionRestartWalReclamationEvidenceError::EffectLogicalRecordCountChanged {
                    expected: 1,
                    actual: 2,
                }
            )
        ));
        assert_eq!(
            invalid.analyzed.completed.source.reclamation_effect_calls,
            1
        );

        let mut invalid = prepare_fake_raw_wal_reclamation(&lineage, &baseline, page_number)?;
        invalid.completed.source.reclamation_effect_override = Some(
            DurableTransactionRestartWalReclamationEffectObservation::new(
                DurableTransactionRestartWalReclamationReplacementObservation::new(0, 2, 1),
                Some(lineage.position(1)),
                Some(lineage.position(1)),
                1,
                1,
                NonZeroU64::MIN,
            ),
        );
        let invalid = invalid
            .reclaim_wal_prefix()
            .err()
            .ok_or(TestError("skipped reclamation generation was accepted"))?;
        assert!(matches!(
            invalid.error(),
            DurableTransactionRestartWalReclamationError::OutcomeIndeterminate(
                DurableTransactionRestartWalReclamationOutcomeIndeterminateError::Receipt(source)
            ) if matches!(
                source,
                DurableTransactionRestartWalReclamationEvidenceError::EffectGenerationChanged {
                    expected_old: 0,
                    actual_old: 0,
                    actual_new: 2,
                }
            )
        ));

        let mut invalid = prepare_fake_raw_wal_reclamation(&lineage, &baseline, page_number)?;
        invalid.completed.source.reclamation_effect_override = Some(
            DurableTransactionRestartWalReclamationEffectObservation::new(
                DurableTransactionRestartWalReclamationReplacementObservation::new(0, 1, 0),
                Some(lineage.position(1)),
                Some(lineage.position(1)),
                1,
                1,
                NonZeroU64::MIN,
            ),
        );
        let invalid = invalid
            .reclaim_wal_prefix()
            .err()
            .ok_or(TestError("zero replacement format was accepted"))?;
        assert!(matches!(
            invalid.error(),
            DurableTransactionRestartWalReclamationError::OutcomeIndeterminate(
                DurableTransactionRestartWalReclamationOutcomeIndeterminateError::Receipt(
                    DurableTransactionRestartWalReclamationEvidenceError::EffectPhysicalFormatVersionZero
                )
            )
        ));
        Ok(())
    }

    #[test]
    fn failed_replay_page_repair_retries_the_whole_plan_after_before_and_after_faults()
    -> Result<(), TestError> {
        let persistent_log_id =
            PersistentLogId::new(0x1661).ok_or(TestError("retry persistent log id"))?;
        let lineage = LogLineage::persistent(persistent_log_id);
        let baseline = fake_completeness_baseline(&lineage, None, Vec::new(), Vec::new())?;
        let first = PageNumber::new(196).ok_or(TestError("retry first page"))?;
        let second = PageNumber::new(197).ok_or(TestError("retry second page"))?;
        let mut prepared = prepare_fake_restart_checkpoint_page_repairs(
            fake_restart_source(
                &lineage,
                Some(lineage.position(2)),
                vec![
                    restart_raw_page(&lineage, first.get(), 1)?,
                    restart_raw_page(&lineage, second.get(), 2)?,
                ],
            ),
            FakeBatchCommittedPageRecoveryStore::new(lineage.clone()),
            &baseline,
        )?;
        prepared.planned.selected.storage.store.write_fault = Some((
            second,
            FakeRecoveryWriteFault::After(FakeFault("repair write")),
        ));

        let TransactionPageStorageRestartCheckpointPageRepairExecution::Failed(failed) =
            prepared.execute_page_repairs()
        else {
            return Err(TestError("after-write fault did not fail execution"));
        };
        assert_eq!(
            failed.completed_prefix(),
            [TransactionRestartCheckpointPageRepairOutcome::Repaired { page_number: first }]
        );
        assert!(failed.has_indeterminate_result());
        assert!(matches!(
            failed.cause(),
            TransactionRestartCheckpointPageRepairFailureCause::StoreWrite {
                page_number,
                source: FakeFault("repair write"),
            } if *page_number == second
        ));
        assert_eq!(
            failed.prepared.planned.selected.storage.store.attempts,
            [first, second]
        );
        assert_eq!(
            failed.prepared.planned.selected.storage.store.current.len(),
            2
        );

        let TransactionPageStorageRestartCheckpointPageRepairExecution::Repaired(repaired) =
            failed.retry()
        else {
            return Err(TestError("after-write whole-plan retry failed"));
        };
        assert_eq!(
            repaired.page_outcomes(),
            [
                TransactionRestartCheckpointPageRepairOutcome::TargetAlreadyPresent {
                    page_number: first,
                },
                TransactionRestartCheckpointPageRepairOutcome::TargetAlreadyPresent {
                    page_number: second,
                },
            ]
        );
        assert_eq!(
            repaired.prepared.planned.selected.storage.store.attempts,
            [first, second]
        );

        let before_page = PageNumber::new(198).ok_or(TestError("before-write page"))?;
        let mut prepared = prepare_fake_restart_checkpoint_page_repairs(
            fake_restart_source(
                &lineage,
                Some(lineage.position(1)),
                vec![restart_raw_page(&lineage, before_page.get(), 1)?],
            ),
            FakeBatchCommittedPageRecoveryStore::new(lineage.clone()),
            &baseline,
        )?;
        prepared.planned.selected.storage.store.write_fault = Some((
            before_page,
            FakeRecoveryWriteFault::Before(FakeFault("repair write")),
        ));
        let TransactionPageStorageRestartCheckpointPageRepairExecution::Failed(failed) =
            prepared.execute_page_repairs()
        else {
            return Err(TestError("before-write fault did not fail execution"));
        };
        assert!(failed.completed_prefix().is_empty());
        assert!(failed.has_indeterminate_result());
        assert!(
            failed
                .prepared
                .planned
                .selected
                .storage
                .store
                .current
                .is_empty()
        );
        let TransactionPageStorageRestartCheckpointPageRepairExecution::Repaired(repaired) =
            failed.retry()
        else {
            return Err(TestError("before-write whole-plan retry failed"));
        };
        assert_eq!(
            repaired.page_outcomes(),
            [TransactionRestartCheckpointPageRepairOutcome::Repaired {
                page_number: before_page,
            }]
        );
        assert_eq!(
            repaired.prepared.planned.selected.storage.store.attempts,
            [before_page, before_page]
        );
        Ok(())
    }

    #[test]
    fn replay_page_repair_fails_closed_on_changed_sources_and_mid_plan_observation_errors()
    -> Result<(), TestError> {
        let persistent_log_id =
            PersistentLogId::new(0x1662).ok_or(TestError("failure persistent log id"))?;
        let lineage = LogLineage::persistent(persistent_log_id);
        let baseline = fake_completeness_baseline(&lineage, None, Vec::new(), Vec::new())?;
        let changed_page = PageNumber::new(199).ok_or(TestError("changed repair page"))?;
        let mut prepared = prepare_fake_restart_checkpoint_page_repairs(
            fake_restart_source(
                &lineage,
                Some(lineage.position(1)),
                vec![restart_raw_page(&lineage, changed_page.get(), 1)?],
            ),
            FakeBatchCommittedPageRecoveryStore::new(lineage.clone()),
            &baseline,
        )?;
        prepared
            .planned
            .selected
            .storage
            .store
            .current
            .push(FakeRecoverySnapshot {
                page_number: changed_page,
                page_version: PageVersion::new(2),
                byte: 0xFF,
                page_position: lineage.position(2),
            });
        let TransactionPageStorageRestartCheckpointPageRepairExecution::Failed(changed) =
            prepared.execute_page_repairs()
        else {
            return Err(TestError("changed repair source was accepted"));
        };
        assert!(changed.completed_prefix().is_empty());
        assert!(!changed.has_indeterminate_result());
        assert!(matches!(
            changed.cause(),
            TransactionRestartCheckpointPageRepairFailureCause::SourceComparison {
                page_number,
                source:
                    DurableTransactionRestartCheckpointPageRepairComparisonError::StoreChanged {
                        expected_source_position: None,
                        actual_position: Some(actual),
                        ..
                    },
            } if *page_number == changed_page && actual == &lineage.position(2)
        ));
        assert!(
            changed
                .prepared
                .planned
                .selected
                .storage
                .store
                .attempts
                .is_empty()
        );

        let first = PageNumber::new(200).ok_or(TestError("observation first page"))?;
        let second = PageNumber::new(201).ok_or(TestError("observation second page"))?;
        let mut prepared = prepare_fake_restart_checkpoint_page_repairs(
            fake_restart_source(
                &lineage,
                Some(lineage.position(2)),
                vec![
                    restart_raw_page(&lineage, first.get(), 1)?,
                    restart_raw_page(&lineage, second.get(), 2)?,
                ],
            ),
            FakeBatchCommittedPageRecoveryStore::new(lineage.clone()),
            &baseline,
        )?;
        let prior_observations = prepared
            .planned
            .selected
            .storage
            .store
            .observations
            .borrow()
            .len();
        prepared
            .planned
            .selected
            .storage
            .store
            .observation_fault_on_attempt = Some((
            prior_observations + 2,
            second,
            FakeFault("execution observation"),
        ));
        let TransactionPageStorageRestartCheckpointPageRepairExecution::Failed(failed) =
            prepared.execute_page_repairs()
        else {
            return Err(TestError("mid-plan observation fault did not fail"));
        };
        assert_eq!(
            failed.completed_prefix(),
            [TransactionRestartCheckpointPageRepairOutcome::Repaired { page_number: first }]
        );
        assert!(!failed.has_indeterminate_result());
        assert!(matches!(
            failed.cause(),
            TransactionRestartCheckpointPageRepairFailureCause::StoreObservation {
                page_number,
                source: FakeFault("execution observation"),
            } if *page_number == second
        ));
        let TransactionPageStorageRestartCheckpointPageRepairExecution::Repaired(repaired) =
            failed.retry()
        else {
            return Err(TestError("observation-failed whole-plan retry failed"));
        };
        assert_eq!(
            repaired.page_outcomes(),
            [
                TransactionRestartCheckpointPageRepairOutcome::TargetAlreadyPresent {
                    page_number: first,
                },
                TransactionRestartCheckpointPageRepairOutcome::Repaired {
                    page_number: second,
                },
            ]
        );
        assert_eq!(
            repaired.prepared.planned.selected.storage.store.attempts,
            [first, second]
        );
        Ok(())
    }

    #[test]
    fn repaired_restart_restores_empty_committed_unresolved_and_mixed_transaction_state()
    -> Result<(), TestError> {
        let persistent_log_id =
            PersistentLogId::new(0x1670).ok_or(TestError("restoration persistent log id"))?;
        let lineage = LogLineage::persistent(persistent_log_id);
        let empty_baseline = fake_completeness_baseline(&lineage, None, Vec::new(), Vec::new())?;
        let empty = repair_fake_restart_checkpoint(
            fake_restart_source(&lineage, None, Vec::new()),
            FakeBatchCommittedPageRecoveryStore::new(lineage.clone()),
            &empty_baseline,
        )?;
        let TransactionPageStorageRestartCheckpointRestoration::Restored(mut empty) =
            empty.restore_transaction_state()
        else {
            return Err(TestError("empty transaction restoration failed"));
        };
        assert_eq!(
            empty.transaction_summary(),
            TransactionRestartRestorationSummary {
                transaction_count: 0,
                committed_count: 0,
                unresolved_count: 0,
                highest_persisted_transaction: None,
                coordinator_epoch: TransactionEpoch(NonZeroU64::MIN),
                indeterminate_allocation_attempt_count: 0,
            }
        );
        let first = empty.coordinator.begin()?;
        assert_eq!(first.transaction_id().epoch().get(), 1);
        assert_eq!(first.transaction_id().sequence(), 1);

        let committed_only = durable_identity(3, 1)?;
        let committed_stream = vec![restart_commit(&lineage, committed_only, 1)?];
        let committed = repair_fake_restart_checkpoint(
            fake_restart_source(&lineage, Some(lineage.position(1)), committed_stream),
            FakeBatchCommittedPageRecoveryStore::new(lineage.clone()),
            &empty_baseline,
        )?;
        let TransactionPageStorageRestartCheckpointRestoration::Restored(committed) =
            committed.restore_transaction_state()
        else {
            return Err(TestError("committed-only transaction restoration failed"));
        };
        let summary = committed.transaction_summary();
        assert_eq!(summary.transaction_count(), 1);
        assert_eq!(summary.committed_count(), 1);
        assert_eq!(summary.unresolved_count(), 0);
        assert_eq!(
            summary.highest_persisted_transaction(),
            Some(committed_only)
        );
        assert_eq!(summary.coordinator_epoch().get(), 4);
        let committed_entry = &committed
            .repaired
            .prepared
            .planned
            .current_analysis
            .transactions()[0];
        assert_eq!(committed_entry.first_owned_page_position(), None);
        assert_eq!(committed_entry.last_owned_page_position(), None);
        assert_eq!(committed_entry.owned_page_record_count(), 0);
        assert_eq!(
            committed_entry
                .state()
                .commit_position()
                .map(LogSequenceNumber::get),
            Some(1)
        );

        let unresolved_only = durable_identity(5, 1)?;
        let unresolved_page =
            PageNumber::new(209).ok_or(TestError("unresolved restoration page"))?;
        let unresolved_stream = vec![restart_owned_page(
            &lineage,
            unresolved_only,
            unresolved_page.get(),
            1,
        )?];
        let unresolved = repair_fake_restart_checkpoint(
            fake_restart_source(&lineage, Some(lineage.position(1)), unresolved_stream),
            FakeBatchCommittedPageRecoveryStore::new(lineage.clone()),
            &empty_baseline,
        )?;
        let TransactionPageStorageRestartCheckpointRestoration::Restored(unresolved) =
            unresolved.restore_transaction_state()
        else {
            return Err(TestError("unresolved-only transaction restoration failed"));
        };
        let summary = unresolved.transaction_summary();
        assert_eq!(summary.transaction_count(), 1);
        assert_eq!(summary.committed_count(), 0);
        assert_eq!(summary.unresolved_count(), 1);
        assert_eq!(summary.coordinator_epoch().get(), 6);

        let checkpoint_unresolved = durable_identity(6, 1)?;
        let current_unresolved = durable_identity(7, 2)?;
        let checkpoint_page = PageNumber::new(210).ok_or(TestError("mixed checkpoint page"))?;
        let unresolved_first =
            PageNumber::new(211).ok_or(TestError("mixed unresolved first page"))?;
        let unresolved_last =
            PageNumber::new(212).ok_or(TestError("mixed unresolved last page"))?;
        let mixed_baseline = fake_completeness_baseline(
            &lineage,
            Some(lineage.position(1)),
            vec![restart_owned_page(
                &lineage,
                checkpoint_unresolved,
                checkpoint_page.get(),
                1,
            )?],
            Vec::new(),
        )?;
        let mixed_stream = vec![
            restart_owned_page(&lineage, checkpoint_unresolved, checkpoint_page.get(), 1)?,
            restart_owned_page(&lineage, checkpoint_unresolved, checkpoint_page.get(), 2)?,
            restart_commit(&lineage, checkpoint_unresolved, 3)?,
            restart_owned_page(&lineage, current_unresolved, unresolved_first.get(), 4)?,
            restart_owned_page(&lineage, current_unresolved, unresolved_last.get(), 5)?,
        ];
        let mixed = repair_fake_restart_checkpoint(
            fake_restart_source(&lineage, Some(lineage.position(5)), mixed_stream),
            FakeBatchCommittedPageRecoveryStore::new(lineage.clone()),
            &mixed_baseline,
        )?;
        let TransactionPageStorageRestartCheckpointRestoration::Restored(mut mixed) =
            mixed.restore_transaction_state()
        else {
            return Err(TestError("mixed transaction restoration failed"));
        };
        let summary = mixed.transaction_summary();
        assert_eq!(summary.transaction_count(), 2);
        assert_eq!(summary.committed_count(), 1);
        assert_eq!(summary.unresolved_count(), 1);
        assert_eq!(
            summary.highest_persisted_transaction(),
            Some(current_unresolved)
        );
        assert_eq!(summary.coordinator_epoch().get(), 8);
        let entries = mixed
            .repaired
            .prepared
            .planned
            .current_analysis
            .transactions();
        assert_eq!(entries.len(), 2);
        assert_eq!(
            entries[0]
                .state()
                .commit_position()
                .map(LogSequenceNumber::get),
            Some(3)
        );
        assert_eq!(
            entries[0]
                .first_owned_page_position()
                .map(LogSequenceNumber::get),
            Some(1)
        );
        assert_eq!(
            entries[0]
                .last_owned_page_position()
                .map(LogSequenceNumber::get),
            Some(2)
        );
        assert_eq!(entries[0].owned_page_record_count(), 2);
        assert_eq!(
            entries[1]
                .first_owned_page_position()
                .map(LogSequenceNumber::get),
            Some(4)
        );
        assert_eq!(
            entries[1]
                .last_owned_page_position()
                .map(LogSequenceNumber::get),
            Some(5)
        );
        assert_eq!(entries[1].owned_page_record_count(), 2);
        assert_eq!(
            entries[1].state(),
            &DurableTransactionRestartState::Uncommitted
        );
        let fresh = mixed.coordinator.begin()?;
        assert_eq!(fresh.transaction_id().epoch().get(), 8);
        assert_eq!(fresh.transaction_id().sequence(), 1);
        Ok(())
    }

    #[test]
    fn transaction_restoration_rejects_unresolved_page_changes_inside_selected_prefix()
    -> Result<(), TestError> {
        let persistent_log_id =
            PersistentLogId::new(0x1675).ok_or(TestError("prefix change persistent log id"))?;
        let lineage = LogLineage::persistent(persistent_log_id);
        let transaction = durable_identity(8, 1)?;
        let owned_page = PageNumber::new(215).ok_or(TestError("prefix owned page"))?;
        let raw_page = PageNumber::new(216).ok_or(TestError("prefix raw page"))?;
        let observations = || -> Result<Vec<DurableTransactionRestartObservation<1>>, TestError> {
            Ok(vec![
                restart_owned_page(&lineage, transaction, owned_page.get(), 1)?,
                restart_raw_page(&lineage, raw_page.get(), 5)?,
            ])
        };
        let baseline = fake_completeness_baseline(
            &lineage,
            Some(lineage.position(5)),
            observations()?,
            Vec::new(),
        )?;

        let mut growth = repair_fake_restart_checkpoint(
            fake_restart_source(&lineage, Some(lineage.position(5)), observations()?),
            FakeBatchCommittedPageRecoveryStore::new(lineage.clone()),
            &baseline,
        )?;
        let growth_entry = &mut growth.prepared.planned.current_analysis.transactions[0];
        growth_entry.last_owned_page_position = Some(lineage.position(3));
        growth_entry.owned_page_record_count = 2;
        let TransactionPageStorageRestartCheckpointRestoration::Rejected(growth) =
            growth.restore_transaction_state()
        else {
            return Err(TestError(
                "inside-prefix unresolved page growth was accepted",
            ));
        };
        assert!(matches!(
            growth.cause(),
            TransactionRestartRestorationRejection::Evidence(source)
                if matches!(
                    source.as_ref(),
                    TransactionRestartRestorationEvidenceError::SelectedUnresolvedOwnedPageEvidenceContradiction {
                        transaction: actual,
                        selected_frontier: 5,
                        selected_last_position: Some(1),
                        current_last_position: Some(3),
                        selected_record_count: 1,
                        current_record_count: 2,
                    } if *actual == transaction
                )
        ));
        assert!(
            growth
                .repaired
                .prepared
                .planned
                .selected
                .storage
                .source
                .restart_epoch_allocations
                .is_empty()
        );

        let mut moved_without_growth = repair_fake_restart_checkpoint(
            fake_restart_source(&lineage, Some(lineage.position(5)), observations()?),
            FakeBatchCommittedPageRecoveryStore::new(lineage.clone()),
            &baseline,
        )?;
        moved_without_growth
            .prepared
            .planned
            .current_analysis
            .transactions[0]
            .last_owned_page_position = Some(lineage.position(3));
        let TransactionPageStorageRestartCheckpointRestoration::Rejected(moved_without_growth) =
            moved_without_growth.restore_transaction_state()
        else {
            return Err(TestError(
                "inside-prefix unresolved last-page movement was accepted",
            ));
        };
        assert!(matches!(
            moved_without_growth.cause(),
            TransactionRestartRestorationRejection::Evidence(source)
                if matches!(
                    source.as_ref(),
                    TransactionRestartRestorationEvidenceError::SelectedUnresolvedOwnedPageEvidenceContradiction {
                        transaction: actual,
                        selected_frontier: 5,
                        selected_last_position: Some(1),
                        current_last_position: Some(3),
                        selected_record_count: 1,
                        current_record_count: 1,
                    } if *actual == transaction
                )
        ));
        Ok(())
    }

    #[test]
    fn transaction_restoration_rejects_contradictions_stale_high_water_and_exhaustion()
    -> Result<(), TestError> {
        let persistent_log_id =
            PersistentLogId::new(0x1671).ok_or(TestError("rejection persistent log id"))?;
        let lineage = LogLineage::persistent(persistent_log_id);
        let transaction = durable_identity(9, 1)?;
        let page_number = PageNumber::new(213).ok_or(TestError("rejection page"))?;
        let stream = vec![restart_owned_page(
            &lineage,
            transaction,
            page_number.get(),
            1,
        )?];
        let baseline = fake_completeness_baseline(
            &lineage,
            Some(lineage.position(1)),
            vec![restart_owned_page(
                &lineage,
                transaction,
                page_number.get(),
                1,
            )?],
            Vec::new(),
        )?;

        let mut contradictory = repair_fake_restart_checkpoint(
            fake_restart_source(&lineage, Some(lineage.position(1)), stream),
            FakeBatchCommittedPageRecoveryStore::new(lineage.clone()),
            &baseline,
        )?;
        contradictory
            .prepared
            .planned
            .current_analysis
            .transactions
            .clear();
        let TransactionPageStorageRestartCheckpointRestoration::Rejected(rejected) =
            contradictory.restore_transaction_state()
        else {
            return Err(TestError("contradictory restoration was accepted"));
        };
        assert!(matches!(
            rejected.cause(),
            TransactionRestartRestorationRejection::Evidence(source)
                if matches!(
                    source.as_ref(),
                    TransactionRestartRestorationEvidenceError::SelectedTransactionMissing {
                        transaction: actual,
                    } if *actual == transaction
                )
        ));
        assert_eq!(rejected.indeterminate_allocation_attempt_count(), 0);
        assert!(
            rejected
                .repaired
                .prepared
                .planned
                .selected
                .storage
                .source
                .restart_epoch_allocations
                .is_empty()
        );

        let empty_baseline = fake_completeness_baseline(&lineage, None, Vec::new(), Vec::new())?;
        let mut stale = repair_fake_restart_checkpoint(
            fake_restart_source(
                &lineage,
                Some(lineage.position(1)),
                vec![restart_owned_page(
                    &lineage,
                    transaction,
                    page_number.get(),
                    1,
                )?],
            ),
            FakeBatchCommittedPageRecoveryStore::new(lineage.clone()),
            &empty_baseline,
        )?;
        stale
            .prepared
            .planned
            .selected
            .storage
            .source
            .restart_next_epoch = NonZeroU64::new(transaction.epoch());
        let TransactionPageStorageRestartCheckpointRestoration::Rejected(stale) =
            stale.restore_transaction_state()
        else {
            return Err(TestError("stale restoration epoch was accepted"));
        };
        assert!(matches!(
            stale.cause(),
            TransactionRestartRestorationRejection::PersistedEpochHighWaterNotAdvanced {
                persisted_epoch_high_water: 9,
                next_epoch: 9,
            }
        ));

        let mut dishonest = repair_fake_restart_checkpoint(
            fake_restart_source(
                &lineage,
                Some(lineage.position(1)),
                vec![restart_owned_page(
                    &lineage,
                    transaction,
                    page_number.get(),
                    1,
                )?],
            ),
            FakeBatchCommittedPageRecoveryStore::new(lineage.clone()),
            &empty_baseline,
        )?;
        dishonest
            .prepared
            .planned
            .selected
            .storage
            .source
            .restart_epoch_result_override = NonZeroU64::new(transaction.epoch());
        let TransactionPageStorageRestartCheckpointRestoration::Rejected(dishonest) =
            dishonest.restore_transaction_state()
        else {
            return Err(TestError("dishonest allocated epoch was accepted"));
        };
        assert!(matches!(
            dishonest.cause(),
            TransactionRestartRestorationRejection::AllocatedEpochNotAbovePersistedHighWater {
                persisted_epoch_high_water: 9,
                allocated_epoch: 9,
            }
        ));

        let mut foreign = repair_fake_restart_checkpoint(
            fake_restart_source(&lineage, None, Vec::new()),
            FakeBatchCommittedPageRecoveryStore::new(lineage.clone()),
            &empty_baseline,
        )?;
        let foreign_lineage = LogLineage::persistent(
            PersistentLogId::new(0x167f).ok_or(TestError("foreign restoration lineage"))?,
        );
        foreign
            .prepared
            .planned
            .selected
            .storage
            .source
            .restart_epoch_lineage_override = Some(foreign_lineage.clone());
        let TransactionPageStorageRestartCheckpointRestoration::Rejected(foreign) =
            foreign.restore_transaction_state()
        else {
            return Err(TestError("foreign allocated epoch lineage was accepted"));
        };
        assert!(matches!(
            foreign.cause(),
            TransactionRestartRestorationRejection::AllocatedEpochLineageMismatch {
                expected,
                actual,
                allocated_epoch: 1,
            } if expected.same_lineage(&lineage) && actual.same_lineage(&foreign_lineage)
        ));

        let maximum = durable_identity(u64::MAX, 1)?;
        let maximum_page = PageNumber::new(214).ok_or(TestError("maximum epoch page"))?;
        let exhausted = repair_fake_restart_checkpoint(
            fake_restart_source(
                &lineage,
                Some(lineage.position(1)),
                vec![restart_owned_page(
                    &lineage,
                    maximum,
                    maximum_page.get(),
                    1,
                )?],
            ),
            FakeBatchCommittedPageRecoveryStore::new(lineage.clone()),
            &empty_baseline,
        )?;
        let TransactionPageStorageRestartCheckpointRestoration::Rejected(exhausted) =
            exhausted.restore_transaction_state()
        else {
            return Err(TestError("maximum transaction epoch was accepted"));
        };
        assert!(matches!(
            exhausted.cause(),
            TransactionRestartRestorationRejection::IdentitySpaceExhausted {
                persisted_epoch_high_water: Some(u64::MAX),
            }
        ));
        Ok(())
    }

    #[test]
    fn transaction_restoration_retries_only_indeterminate_epoch_allocation() -> Result<(), TestError>
    {
        let persistent_log_id =
            PersistentLogId::new(0x1672).ok_or(TestError("retry persistent log id"))?;
        let lineage = LogLineage::persistent(persistent_log_id);
        let baseline = fake_completeness_baseline(&lineage, None, Vec::new(), Vec::new())?;

        let mut before = repair_fake_restart_checkpoint(
            fake_restart_source(&lineage, None, Vec::new()),
            FakeBatchCommittedPageRecoveryStore::new(lineage.clone()),
            &baseline,
        )?;
        before
            .prepared
            .planned
            .selected
            .storage
            .source
            .restart_epoch_before_error = Some(FakeFault("before restart epoch"));
        let TransactionPageStorageRestartCheckpointRestoration::Failed(failed) =
            before.restore_transaction_state()
        else {
            return Err(TestError("before-allocation fault did not fail"));
        };
        assert_eq!(failed.cause(), &FakeFault("before restart epoch"));
        assert_eq!(failed.indeterminate_allocation_attempt_count(), 1);
        let TransactionPageStorageRestartCheckpointRestoration::Restored(before) = failed.retry()
        else {
            return Err(TestError("before-allocation restoration retry failed"));
        };
        assert_eq!(before.transaction_summary().coordinator_epoch().get(), 1);
        assert_eq!(
            before
                .transaction_summary()
                .indeterminate_allocation_attempt_count(),
            1
        );
        assert_eq!(
            before
                .repaired
                .prepared
                .planned
                .selected
                .storage
                .source
                .restart_epoch_allocations,
            [1]
        );

        let mut after = repair_fake_restart_checkpoint(
            fake_restart_source(&lineage, None, Vec::new()),
            FakeBatchCommittedPageRecoveryStore::new(lineage.clone()),
            &baseline,
        )?;
        after
            .prepared
            .planned
            .selected
            .storage
            .source
            .restart_epoch_after_error = Some(FakeFault("after restart epoch"));
        let TransactionPageStorageRestartCheckpointRestoration::Failed(failed) =
            after.restore_transaction_state()
        else {
            return Err(TestError("after-allocation fault did not fail"));
        };
        assert_eq!(failed.cause(), &FakeFault("after restart epoch"));
        assert_eq!(failed.indeterminate_allocation_attempt_count(), 1);
        assert_eq!(
            failed
                .repaired
                .prepared
                .planned
                .selected
                .storage
                .source
                .restart_epoch_allocations,
            [1]
        );
        let TransactionPageStorageRestartCheckpointRestoration::Restored(after) = failed.retry()
        else {
            return Err(TestError("after-allocation restoration retry failed"));
        };
        assert_eq!(after.transaction_summary().coordinator_epoch().get(), 2);
        assert_eq!(
            after
                .transaction_summary()
                .indeterminate_allocation_attempt_count(),
            1
        );
        assert_eq!(
            after
                .repaired
                .prepared
                .planned
                .selected
                .storage
                .source
                .restart_epoch_allocations,
            [1, 2]
        );

        let exhausted_count = repair_fake_restart_checkpoint(
            fake_restart_source(&lineage, None, Vec::new()),
            FakeBatchCommittedPageRecoveryStore::new(lineage.clone()),
            &baseline,
        )?;
        let TransactionPageStorageRestartCheckpointRestoration::Rejected(exhausted_count) =
            restore_transaction_restart_state(exhausted_count, usize::MAX)
        else {
            return Err(TestError("exhausted allocation attempt count was accepted"));
        };
        assert!(matches!(
            exhausted_count.cause(),
            TransactionRestartRestorationRejection::AllocationAttemptCountExhausted
        ));
        assert_eq!(
            exhausted_count.indeterminate_allocation_attempt_count(),
            usize::MAX
        );
        assert!(
            exhausted_count
                .repaired
                .prepared
                .planned
                .selected
                .storage
                .source
                .restart_epoch_allocations
                .is_empty()
        );
        Ok(())
    }

